CFG = Config()
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
def _cfg_path(name: str) -> str:
    """Return an absolute path near the bot file unless path is already absolute."""
    if not name:
        return BASE_DIR
    return name if os.path.isabs(name) else os.path.join(BASE_DIR, name)
# Persistent state (prevents trading after restart if daily SAFE/LOCK was reached)
