logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s | %(message)s",
    handlers=[
        logging.FileHandler(_cfg_path(CFG.LOG_FILE), encoding="utf-8"),
        logging.StreamHandler()
    ]
)
def log(msg: str):
    logging.info(msg)
# ==================
# BYBIT CLIENT
# Создаётся внутри Engine.__init__, а не при импорте модуля —
# это позволяет безопасно импортировать файл без немедленного
# подключения к бирже, и корректно работает при тестировании.
# ==================
client: Optional[HTTP] = None  # инициализируется в Engine.__init__
# ==================
# UTILS: decimal rounding
# ==================
def _dec(x) -> Decimal:
    return Decimal(str(x))
def floor_to_step(value: float, step: float) -> float:
    v = _dec(value)
    s = _dec(step)
    if s <= 0:
        return float(v)
    q = (v / s).to_integral_value(rounding=ROUND_DOWN) * s
    # [FIX-19] Для integer steps (step=1, step=10 etc) возвращаем int
    # чтобы избежать float precision: 1239669 не превращался в 1239669.4
    s_norm = s.normalize()
    if s_norm.as_tuple().exponent >= 0:  # step целое (1, 10, 100...)
        return float(int(q))  # гарантированно целое
    return float(q)
def ceil_to_step(value: float, step: float) -> float:
    """Округление ВВЕРХ до шага tick_size — используется для SELL-цен,
    чтобы лимитный ордер не оказался ниже рынка и не был отклонён биржей."""
    v = _dec(value)
    s = _dec(step)
    if s <= 0:
        return float(v)
    q = (v / s).to_integral_value(rounding=ROUND_UP) * s
    return float(q)
def fmt_by_step(value: float, step: float) -> str:
    v = _dec(floor_to_step(value, step))
    # [FIX-19] .normalize() убирает trailing zeros: Decimal('1.0') → Decimal('1')
    # Без normalize: step=1.0 → exponent=-1 → places=1 → qty='1239669.0' → ErrCode 170137
    s = _dec(step).normalize()
    places = max(0, -s.as_tuple().exponent)
    return f"{v:.{places}f}"
def fmt_by_step_ceil(value: float, step: float) -> str:
    """fmt_by_step с округлением вверх — для SELL-ордеров."""
    v = _dec(ceil_to_step(value, step))
    s = _dec(step).normalize()  # [FIX-19] normalize убирает trailing zeros
    places = max(0, -s.as_tuple().exponent)
    return f"{v:.{places}f}"
def now_ms() -> int:
    return int(time.time() * 1000)
def _now_local_dt() -> datetime:
    """Unified local time source for reports/state, tied to CFG.DAILY_TZ."""
    try:
        return datetime.now(ZoneInfo(getattr(CFG, "DAILY_TZ", "Europe/Chisinau")))
    except Exception:
        return datetime.now()
def ts_str() -> str:
    return _now_local_dt().strftime("%Y-%m-%d %H:%M:%S")
def today_ymd() -> str:
    """Return current local date as YYYY-MM-DD (same TZ as daily lock)."""
    return _now_local_dt().strftime("%Y-%m-%d")
def cap_amp_pct(value: float, cap: float) -> float:
    try:
        v = float(value or 0.0)
        c = max(0.0, float(cap or 0.0))
        if c <= 0.0:
            return max(0.0, v)
        return max(0.0, min(v, c))
    except Exception:
        return 0.0
# ==================
# RETRY WRAPPER
# ==================
def new_order_link_id(prefix: str = "bot") -> str:
    """[FIX-v297-BUG] Идемпотентный ключ ордера (Bybit orderLinkId).

    call_with_retry() ретраит place_order при сетевых таймаутах/ошибках. Если ордер на самом
    деле уже исполнился на бирже, а ответ потерялся — retry без orderLinkId создавал ВТОРОЙ,
    дублирующий живой ордер. orderLinkId генерируется ОДИН раз ДО вызова call_with_retry и
    передаётся одинаковым на каждой попытке — Bybit распознаёт повтор по этому ключу и не
    создаёт дубликат. Префикс ограничен коротким тегом (buy/sell/emg/avg), max ~36 символов.
    """
    return f"{prefix[:8]}-{now_ms()}-{uuid.uuid4().hex[:10]}"
def call_with_retry(fn, *args, **kwargs):
    # [FIX-v144-R3] Постоянные ошибки Bybit — retry не поможет, сразу raise.
    # 10001=params error, 110007=insufficient balance, 110013=symbol not found,
    # 110014=invalid qty, 12201=invalid symbol, 10006=IP banned
    # [FIX-v220-1] 170131=insufficient balance — постоянная ошибка, retry не поможет.
    # По логам v219: 6 retry × ~1с = 6 сек потери при каждой нехватке баланса.
    _NO_RETRY_CODES = {10001, 110007, 110013, 110014, 12201, 10006, 110055, 170131}
    delay = 0.6
    last = None
    for i in range(CFG.RETRY_ATTEMPTS):
        try:
            resp = fn(*args, **kwargs)
            # Bybit API: treat non-zero retCode as error (prevents false 'BUY placed' messages)
            if isinstance(resp, dict) and 'retCode' in resp and resp.get('retCode') not in (0, '0', None):
                rc = resp.get('retCode')
                # [FIX-v144-R3] Постоянная ошибка — сразу raise без retry
                try:
                    if int(rc) in _NO_RETRY_CODES:
                        raise RuntimeError(f"Bybit permanent error retCode={rc} retMsg={resp.get('retMsg')}")
                except (TypeError, ValueError):  # [v145-silent]
                    pass
                raise RuntimeError(f"Bybit retCode={rc} retMsg={resp.get('retMsg')}")
            return resp
        except RuntimeError as e:
            # Если это постоянная ошибка — сразу пробрасываем
            if "permanent error" in str(e):
                raise
            last = e
            log(f"⚠️ NET/API error: {e} | retry {i+1}/{CFG.RETRY_ATTEMPTS}")
            time.sleep(delay)
            delay = min(delay * CFG.RETRY_BACKOFF, 15.0)
        except Exception as e:
            last = e
            # [FIX-v234-1] КРИТИЧНО: Bybit SDK бросает Exception (не dict retCode)
            # для ошибок типа "Insufficient balance (ErrCode: 170131)".
            # Раньше: except Exception → log → retry 1..6 → 6 лишних запросов!
            # Теперь: если в тексте ошибки есть код из NO_RETRY_CODES → сразу raise.
            _e_str = str(e)
            _no_retry_texts = ['170131', '110007', '110013', '110014', '12201', '10006', '110055', 'permanent error']
            if any(code in _e_str for code in _no_retry_texts):
                raise  # немедленно — retry не поможет при нехватке баланса
            log(f"⚠️ NET/API error: {e} | retry {i+1}/{CFG.RETRY_ATTEMPTS}")
            time.sleep(delay)
            delay = min(delay * CFG.RETRY_BACKOFF, 15.0)
    raise last
