@dataclass
class SymbolFilters:
    tick_size: float
    qty_step: float
    min_qty: float
    min_amt: float
@dataclass
class PositionState:
    base_qty: float = 0.0
    entry_price: Optional[float] = None   # средневзвешенная цена входа
    entry_cost: float = 0.0              # суммарный USDT потраченный на покупки
    entry_time_ms: Optional[int] = None
    peak_price: Optional[float] = None  # for trailing — максимальная цена с момента входа
    # [FIX-v148-1] peak_pnl_pct: максимальный PnL% достигнутый с момента входа.
    # Нужен для no-progress time_stop (FIX-v147-6).
    # Обновляется в run() при каждой итерации если pnl > текущего peak_pnl_pct.
    peak_pnl_pct: float = 0.0           # [FIX-v148-1] максимальный достигнутый PnL %
    # [FIX-v148-1] filled_orders_count: сколько BUY ордеров сетки исполнено.
    # Нужен для full_grid_early_stop и аналитики.
    filled_orders_count: int = 0        # [FIX-v148-1] кол-во исполненных BUY ордеров
    trailing_active: bool = False
    tp1_done: bool = False
    tp2_done: bool = False
    be_activated: bool = False
    tp1_order_active: bool = False
    tp2_order_active: bool = False
    be_order_active: bool = False
@dataclass
class PnLState:
    realized_usdt: float = 0.0   # net (gross - fees)
    fees_usdt: float = 0.0       # суммарные комиссии
    fee_buy_usdt: float = 0.0    # комиссии с BUY ордеров
    fee_sell_usdt: float = 0.0   # комиссии с SELL ордеров
    gross_usdt: float = 0.0      # gross PnL до вычета комиссий
    realized_partial_usdt: float = 0.0  # net PnL от частичных SELL (не завершённых сделок)
    realized_final_usdt: float = 0.0    # net PnL от финальных закрытий сделок
    position_remaining_qty: float = 0.0 # live remainder qty after partial close
    position_remaining_cost: float = 0.0 # carry cost for remainder
    trades_count: int = 0        # всего с запуска
    profitable_trades: int = 0   # прибыльных сделок
    loss_trades: int = 0         # убыточных сделок
    # window tracking
    hour_start_ts: float = field(default_factory=time.time)
    hour_realized: float = 0.0
    hour_gross: float = 0.0
    hour_fees: float = 0.0
    hour_trades: int = 0   # сделок за текущий час
    hour_wins: int = 0     # [FIX-v144-P2] прибыльных за час (для hourly winrate)
    hour_losses: int = 0   # [FIX-v144-P2] убыточных за час
    day_start_date: str = field(default_factory=today_ymd)
    day_realized: float = 0.0
    day_gross: float = 0.0
    day_fees: float = 0.0
    day_fee_buy: float = 0.0
    day_fee_sell: float = 0.0
    day_trades: int = 0    # сделок за текущий день
# ==================
# [FIX-BUG18] apply_trade_activity_mode перенесена ПЕРЕД class Engine —
# она вызывается внутри Engine._activity_profile() и /activity handler,
# поэтому должна быть определена до класса.
# ==================
def apply_trade_activity_mode(mode_name: str) -> str:
    mode = str(mode_name or 'balanced').strip().lower()
    if mode not in ('conservative', 'balanced', 'active'):
        mode = 'balanced'
    CFG.TRADE_ACTIVITY_MODE = mode
    profiles = {
        'conservative': {
            'ema_mult': 0.88,
            'spread_mult': 0.90,
            'tradeability_threshold': 0.40,
            'switch_improvement_pct': max(12.0, float(getattr(CFG, 'SWITCH_IMPROVEMENT_PCT', 10.0) or 10.0)),
            'no_trade_relax_after_min': max(35.0, float(getattr(CFG, 'NO_TRADE_RELAX_AFTER_MIN', 45) or 45)),
            'scanner_precheck_top_n': max(3, int(getattr(CFG, 'SCANNER_PRECHECK_TOP_N', 5) or 5)),
            # [FIX-v298-BUG] Было max(1, min(2,...)) — при ORDER_COUNT=1 (например, из-за
            # другого не-заклампленного места) cap схлопывался до 1 → dynamic_order_count()
            # мог вернуть 1 ордер в "conservative" профиле. Пол поднят до 2 (стратегия
            # требует строго >=2 ордеров для усреднения).
            'order_count_cap': max(2, min(2, int(getattr(CFG, 'ORDER_COUNT', 2) or 2))),
            'ai_min_adj': 0.30,
            'entry_threshold': float(getattr(CFG, 'ENTRY_THRESHOLD_CONSERVATIVE', 5.0) or 5.0),
        },
        'balanced': {
            'ema_mult': 1.00,
            'spread_mult': 1.00,
            'tradeability_threshold': float(getattr(CFG, 'SCANNER_MIN_TRADEABILITY_SCORE', 0.25) or 0.25),
            'switch_improvement_pct': float(getattr(CFG, 'SWITCH_IMPROVEMENT_PCT', 10.0) or 10.0),
            'no_trade_relax_after_min': float(getattr(CFG, 'NO_TRADE_RELAX_AFTER_MIN', 45) or 45),
            'scanner_precheck_top_n': int(getattr(CFG, 'SCANNER_PRECHECK_TOP_N', 5) or 5),
            # [FIX-v298-BUG] Было max(1, min(3,...)) — floor поднят до 2, см. комментарий
            # в 'conservative' профиле выше.
            'order_count_cap': max(2, min(3, int(getattr(CFG, 'ORDER_COUNT', 2) or 2))),
            'ai_min_adj': 0.0,
            'entry_threshold': float(getattr(CFG, 'ENTRY_THRESHOLD_BALANCED', 3.5) or 3.5),
        },
        'active': {
            'ema_mult': 1.25,
            'spread_mult': 1.25,
            'tradeability_threshold': 0.15,
            'switch_improvement_pct': min(8.0, float(getattr(CFG, 'SWITCH_IMPROVEMENT_PCT', 10.0) or 10.0)),
            'no_trade_relax_after_min': min(25.0, float(getattr(CFG, 'NO_TRADE_RELAX_AFTER_MIN', 45) or 45)),
            'scanner_precheck_top_n': max(5, int(getattr(CFG, 'SCANNER_PRECHECK_TOP_N', 5) or 5)),
            'order_count_cap': 3,
            'ai_min_adj': -0.45,
            'entry_threshold': float(getattr(CFG, 'ENTRY_THRESHOLD_ACTIVE', 2.5) or 2.5),
        },
    }
    p = profiles[mode]
    CFG.SCANNER_MIN_TRADEABILITY_SCORE = p['tradeability_threshold']
    CFG.SWITCH_IMPROVEMENT_PCT = p['switch_improvement_pct']
    CFG.NO_TRADE_RELAX_AFTER_MIN = p['no_trade_relax_after_min']
    CFG.SCANNER_PRECHECK_TOP_N = p['scanner_precheck_top_n']
    CFG.ORDER_COUNT = 2   # [FIX-v275-3] строго 2 ордера (усреднение, не давать активности раздуть)
    CFG._TRADE_ACTIVITY_PROFILE = p
    return mode

# ══════════════════════════════════════════════════════════════════════════════
# [FIX-v167-2] БАЗА ЗНАНИЙ — bot_knowledge.json
# ══════════════════════════════════════════════════════════════════════════════
class BotKnowledge:
    """Самообучающаяся база знаний. Анализирует результаты сделок."""
    def __init__(self, base_dir: str):
        self.path = os.path.join(base_dir, "bot_knowledge.json")
        self._data = self._load()
        self._cur: dict = {}
        # [FIX-v314-BUG] self._data мутируется не только из главного торгового потока,
        # но и из фоновых потоков ai_brain_advisor_v4.py (_apply_loss_analysis,
        # _run_nightly_report, _run_blacklist_review — все три запускаются через
        # threading.Thread(daemon=True) и напрямую пишут в self.knowledge._data / зовут
        # self.knowledge._save()). Без блокировки _save() может итерировать (json.dump)
        # тот же dict/list, который в этот момент мутирует другой поток — CPython в этом
        # случае может бросить "RuntimeError: dictionary changed size during iteration"
        # прямо во время сохранения (тихо проглатывается в _save(), см. там же — save
        # просто пропускается) либо потерять часть записи. Лок используется в _save() и
        # в фоновых мутаторах ai_brain_advisor_v4.py — см. FIX-v314-BUG там же.
        self._lock = threading.RLock()
        # [FIX-v181-1] Создаём файл при старте даже без сделок.
        # Раньше файл появлялся только после первой завершённой сделки.
        # Теперь создаётся пустой при запуске → мозг сразу виден в папке.
        if not os.path.exists(self.path):
            self._save()
            log("[knowledge] bot_knowledge.json создан при старте")

    def _load(self) -> dict:
        try:
            if os.path.exists(self.path):
                with open(self.path, 'r', encoding='utf-8') as f:
                    return json.load(f)
        except Exception as _e:
            log(f"[knowledge] load err: {_e}")
        return {"version": "1.0", "trades": [], "insights": [],
                "filter_stats": {}, "hour_stats": {}, "weekday_stats": {},
                "problems": [], "manual_changes": []}

    def _save(self):
        try:
            # [FIX-v314-BUG] см. лок в __init__ — сериализация (json.dump ниже) итерирует
            # self._data и вложенные списки/словари; если фоновый ИИ-поток в этот момент
            # мутирует то же самое (например .append() в ai_learning_log), итерация может
            # упасть с RuntimeError прямо посреди сохранения. Лок сериализует save() с теми
            # же фоновыми мутаторами, которые тоже его берут (ai_brain_advisor_v4.py).
            with self._lock:
                self._data["updated"] = datetime.now().isoformat()
                # [FIX-v262-2] Исключаем несериализуемые объекты (Engine ref) из JSON
                _skip_keys = ('_engine_ref',)
                _clean = {k: v for k, v in self._data.items() if k not in _skip_keys}
                with open(self.path, 'w', encoding='utf-8') as f:
                    json.dump(_clean, f, ensure_ascii=False, indent=2)
        except Exception as _e:
            log(f"[knowledge] save err: {_e}")


    # ─────────────────────────────────────────────────────────────────
    # [v213] СИСТЕМА ДОВЕРИЯ БОТАМ
    # Мозг помнит: SMC дал сигнал → сделка прибыльная/убыточная
    # Каждый бот получает вес 0.3-1.5 по своему историческому WR
    # ─────────────────────────────────────────────────────────────────

    def update_bot_trust(self, bot_name: str, outcome: str,
                          pnl_pct: float = 0.0) -> None:
        """Обновить доверие боту после сделки.
        bot_name : 'smc','funding','volume','news','corr','base','none'
        outcome  : 'profit'|'loss'
        pnl_pct  : реальный PnL% этой сделки (для avg_pnl расчёта)
        """
        try:
            trust = self._data.setdefault("bot_trust", {})
            b = trust.setdefault(bot_name, {
                "trades":0,"wins":0,"wr":0.5,"weight":1.0,
                "total_pnl":0.0,"avg_pnl":0.0,           # [v217-P1] avg_pnl_pct
                "sum_win_pnl":0.0,"sum_loss_pnl":0.0,    # avg по прибылям/убыткам
                "win_count":0,"loss_count":0,
            })
            b["trades"] += 1
            b["total_pnl"] = round(b.get("total_pnl",0.0) + pnl_pct, 4)
            b["avg_pnl"]   = round(b["total_pnl"] / b["trades"], 4)
            if outcome == "profit":
                b["wins"] += 1
                b["win_count"]   = b.get("win_count",0)+1
                b["sum_win_pnl"] = round(b.get("sum_win_pnl",0.0)+abs(pnl_pct),4)
            else:
                b["loss_count"]   = b.get("loss_count",0)+1
                b["sum_loss_pnl"] = round(b.get("sum_loss_pnl",0.0)+abs(pnl_pct),4)
            n   = b["trades"]
            wr  = b["wins"] / n
            b["wr"] = round(wr, 3)

            # avg_win и avg_loss для расчёта реального Profit Factor
            wn = b.get("win_count",0); ln = b.get("loss_count",0)
            avg_win  = b.get("sum_win_pnl",0)/wn  if wn>0 else 0.0
            avg_loss = b.get("sum_loss_pnl",0)/ln if ln>0 else 0.0
            b["avg_win_pnl"]  = round(avg_win, 4)
            b["avg_loss_pnl"] = round(avg_loss, 4)

            # [v217-P1] Profit Factor = avg_win / avg_loss
            # PF>1 + WR>50% → доверяем | PF<1 → бот реально убыточный
            pf = avg_win/avg_loss if avg_loss>0 else (2.0 if wn>0 else 1.0)
            b["profit_factor"] = round(pf, 3)

            # Вес = f(WR, PF, avg_pnl) — не только WR!
            if n >= 5:
                # Реально прибыльный бот: WR≥50% И PF≥1 И avg_pnl>0
                truly_profitable = (wr >= 0.50 and pf >= 1.0 and b["avg_pnl"] >= 0)
                if   wr >= 0.70 and pf >= 1.5 and truly_profitable: b["weight"] = 1.5
                elif wr >= 0.60 and pf >= 1.2 and truly_profitable: b["weight"] = 1.2
                elif wr >= 0.50 and pf >= 1.0 and truly_profitable: b["weight"] = 1.0
                elif wr >= 0.40 or not truly_profitable:             b["weight"] = 0.7
                else:                                                 b["weight"] = 0.3
            trust[bot_name] = b
            self._data["bot_trust"] = trust
            self._save()
            log(f"🤝 [v217-trust] {bot_name}: WR={wr:.0%} PF={pf:.2f} "
                f"avg={b['avg_pnl']:+.3f}% w={b['weight']} ({n})")
        except Exception as _e:
            log(f"⚠️ [trust] {_e}")

    def get_bot_weight(self, bot_name: str) -> float:
        """Вернуть вес бота (0.3-1.5). По умолчанию 1.0."""
        try:
            return float(self._data.get("bot_trust",{}).get(bot_name,{}).get("weight",1.0))
        except Exception:
            return 1.0

    def get_rotation_report(self, engine) -> str:
        """[v217-P2] Краткий отчёт почему монеты отклонялись в базовом режиме."""
        try:
            if not hasattr(engine,'_base_mode_reject_log'):
                return "нет данных"
            log_data = getattr(engine,'_base_mode_reject_log',{})
            if not log_data: return "нет отклонений"
            parts=[]
            for sym,reasons in list(log_data.items())[-5:]:  # последние 5
                last=reasons[-1] if reasons else "?"
                parts.append(f"{sym}:{last}")
            return " | ".join(parts)
        except Exception: return "ошибка"

    def get_best_bot(self) -> str:
        """Лучший бот по WR (≥5 сделок)."""
        try:
            best, best_wr = "none", 0.0
            for bot, d in self._data.get("bot_trust",{}).items():
                if d.get("trades",0) >= 5 and d.get("wr",0) > best_wr:
                    best_wr = d["wr"]; best = bot
            return best
        except Exception:
            return "none"

    def get_trust_summary(self) -> str:
        """Краткий текст для TG /status."""
        try:
            trust = self._data.get("bot_trust", {})
            if not trust:
                return "нет данных"
            parts = []
            for bot, d in sorted(trust.items(), key=lambda x: -x[1].get("wr",0)):
                t = d.get("trades",0)
                if t > 0:
                    pf = d.get("profit_factor",1.0)
                    parts.append(f"{bot}:{d.get('wr',0):.0%}PF{pf:.1f}×{t}")
            return " | ".join(parts) if parts else "нет данных"
        except Exception:
            return "ошибка"

    # ──────────────────────────────────────────────────────────────
    # [v218-SNAPSHOT] Снимок сигналов ботов ПЕРЕД сделкой
    # ──────────────────────────────────────────────────────────────

    def save_pre_trade_snapshot(self, symbol: str, bot_signals: dict) -> None:
        """Сохраняет что говорили все боты прямо перед входом в сделку.
        
        bot_signals: {
            'smc':         {'score':4, 'trend':'bullish', 'fvg':True},
            'funding':     {'signal':'positive', 'rate':0.01},
            'volume':      {'anomaly':True, 'mult':2.3},
            'news':        {'sentiment':'neutral', 'blocked':False},
            'corr':        {'buy_blocked':False, 'regime':'trending'},
            'liquidation': {'signal':'neutral'},
            'chart':       {'trend':'up','score':6.5,'hh':True,'hl':True},
            'timestamp':   1234567890.0,
        }
        """
        try:
            snap = {
                "symbol":    symbol,
                "timestamp": bot_signals.get("timestamp", __import__("time").time()),
                "signals":   {k:v for k,v in bot_signals.items() if k != "timestamp"},
            }
            snaps = self._data.setdefault("pre_trade_snapshots", [])
            snaps.append(snap)
            # Храним последние 50 снимков
            if len(snaps) > 50:
                snaps.pop(0)
            self._data["pre_trade_snapshots"] = snaps
            log(f"📸 [v218] Pre-trade snapshot: {symbol} | {len(bot_signals)-1} сигналов")
        except Exception as _e:
            log(f"⚠️ [snapshot] {_e}")

    def get_last_trade_context(self, symbol: str = "") -> str:
        """Возвращает текст: что говорили боты перед последней сделкой."""
        try:
            snaps = self._data.get("pre_trade_snapshots", [])
            if not snaps:
                return "нет данных"
            # Фильтруем по символу если задан
            if symbol:
                snaps = [s for s in snaps if s.get("symbol") == symbol]
            if not snaps:
                return f"нет снимков для {symbol}"
            last = snaps[-1]
            sigs = last.get("signals", {})
            sym  = last.get("symbol","?")
            ts   = last.get("timestamp",0)
            lines = [f"📸 Снимок перед {sym}:"]
            for bot, data in sigs.items():
                if isinstance(data, dict):
                    brief = " ".join(f"{k}={v}" for k,v in list(data.items())[:3])
                    lines.append(f"  • {bot}: {brief}")
                else:
                    lines.append(f"  • {bot}: {data}")
            return "\n".join(lines)
        except Exception as _e:
            return f"ошибка: {_e}"

    # [v219-ACCURACY] Точность бота по конкретной монете
    def get_bot_accuracy_by_symbol(self, bot_name: str = "") -> str:
        """Показывает точность сигналов каждого бота по монетам.
        
        Пример: "SMC: MNTUSDT=80%(5) XLMUSDT=40%(5) FETUSDT=60%(3)"
        """
        try:
            snaps = self._data.get("pre_trade_snapshots", [])
            trades = self._data.get("trades", [])
            if not snaps or not trades: return "нет данных"

            # {bot: {symbol: [wins, total]}}
            acc: dict = {}
            for snap in snaps:
                sym = snap.get("symbol","")
                ts  = snap.get("timestamp",0)
                matched = next(
                    (t for t in reversed(trades)
                     if t.get("symbol")==sym and abs(t.get("entry_ts",0)-ts)<600),
                    None)
                if not matched: continue
                outcome = matched.get("outcome","")
                for bot, data in snap.get("signals",{}).items():
                    if bot_name and bot != bot_name: continue
                    bot_data = acc.setdefault(bot,{})
                    sym_data = bot_data.setdefault(sym,[0,0])
                    sym_data[1]+=1  # total
                    # Бот "угадал" если: bullish+profit или bearish+loss
                    was_bullish=False
                    if isinstance(data,dict):
                        was_bullish=(data.get("trend") in ("up","bullish") or
                                     data.get("signal") in ("positive","buy") or
                                     data.get("buy_blocked") is False)
                    if (was_bullish and outcome=="profit") or (not was_bullish and outcome=="loss"):
                        sym_data[0]+=1  # win

            if not acc: return "нет сопоставлений"
            lines_out=[]
            for bot, sym_data in sorted(acc.items()):
                parts=[]
                for sym,(wins,total) in sorted(sym_data.items(),key=lambda x:-x[1][0]/max(x[1][1],1)):
                    if total>=2:  # минимум 2 сделки
                        wr=wins/total
                        parts.append(f"{sym}={wr:.0%}({total})")
                if parts:
                    lines_out.append(f"• {bot}: {' '.join(parts[:4])}")
            return "\n".join(lines_out) if lines_out else "мало данных (нужно ≥2 сделки на монету)"
        except Exception as _e:
            return f"ошибка: {_e}"

    def get_all_snapshots_report(self) -> str:
        """Полный отчёт по всем снимкам — какие боты были правы."""
        try:
            snaps = self._data.get("pre_trade_snapshots", [])
            trades = self._data.get("trades", [])
            if not snaps or not trades:
                return "нет данных"
            # Сопоставляем снимки и итоги сделок
            correct_by_bot: dict = {}
            total_by_bot:   dict = {}
            for snap in snaps:
                sym = snap.get("symbol","")
                ts  = snap.get("timestamp",0)
                # Ищем ближайшую сделку по этой монете
                matched = next(
                    (t for t in reversed(trades)
                     if t.get("symbol")==sym and abs(t.get("entry_ts",0)-ts)<600),
                    None
                )
                if not matched:
                    continue
                outcome = matched.get("outcome","")
                for bot, data in snap.get("signals",{}).items():
                    total_by_bot[bot] = total_by_bot.get(bot,0) + 1
                    # Считаем "правым" если:
                    # smc→bullish + profit, funding→positive + profit, т.д.
                    was_bullish = False
                    if isinstance(data, dict):
                        was_bullish = (data.get("trend") in ("up","bullish") or
                                       data.get("signal") in ("positive","buy") or
                                       data.get("anomaly") is True or
                                       data.get("buy_blocked") is False)
                    if was_bullish and outcome == "profit":
                        correct_by_bot[bot] = correct_by_bot.get(bot,0) + 1
                    elif not was_bullish and outcome == "loss":
                        correct_by_bot[bot] = correct_by_bot.get(bot,0) + 1
            if not total_by_bot:
                return "нет сопоставлений"
            parts = []
            for bot, total in sorted(total_by_bot.items()):
                correct = correct_by_bot.get(bot,0)
                acc = correct/total if total>0 else 0
                parts.append(f"{bot}:{acc:.0%}({total})")
            return "Точность сигналов: " + " | ".join(parts)
        except Exception as _e:
            return f"ошибка: {_e}"

    def log_trade_entry(self, symbol, entry_price, adx=0.0, rsi=0.0,
                        score=0.0, turnover=0.0, tier=1, mode="SNIPER", stakan=0.0):
        now = datetime.now()
        self._last_known_symbol = symbol  # [FIX-v183-3] для синтетического _cur
        # [FIX-v190-NOTRADE] обновляем время последней сделки
        # Используется для детекции 12/24/48ч без сделок
        try:
            if hasattr(self, '_engine_ref') and self._engine_ref:
                self._engine_ref._last_trade_ts = time.time()
        except Exception: pass
        self._cur = {
            "id": f"{symbol}_{int(time.time())}",
            "symbol": symbol, "mode": mode, "entry_price": entry_price,
            "entry_ts": time.time(), "entry_time": now.isoformat(),
            "hour": now.hour, "weekday": now.weekday(),
            # [FIX-v297-BUG] "hour" выше — ЛОКАЛЬНОЕ время сервера, и это корректно для
            # hour_stats/bad_hours/is_good_hour_for_trading (та цепочка вся локальная).
            # НО per-symbol "шпаргалка" (symbol_stats best_hours/worst_hours, см.
            # BotKnowledge._update_stats) читается сканером через datetime.utcnow().hour
            # (scan_market_top, get_tg_report и др.) — если сервер не в UTC, бонус/штраф
            # "золотого часа" применялся не в тот час. Пишем отдельное UTC-поле для
            # per-symbol статистики, не трогая уже корректную локальную цепочку.
            "hour_utc": datetime.utcnow().hour,
            "weekday_name": ["Пн","Вт","Ср","Чт","Пт","Сб","Вс"][now.weekday()],
            "adx": round(adx, 1), "rsi": round(rsi, 1), "score": round(score, 2),
            "turnover_m": round(turnover / 1_000_000, 2), "stakan": stakan,
            "adaptive_tier": tier, "outcome": "open",
            "exit_price": 0.0, "pnl_usdt": 0.0, "pnl_pct": 0.0,
            "exit_reason": "", "duration_h": 0.0,
            # [FIX-v222-2] Сохраняем сигнал бота в каждом трейде для анализа.
            # Раньше _last_signal_bot хранился отдельно и перезаписывался → нельзя
            # было анализировать "какой бот лучше работает в какой час/режим".
            "signal_bot": str(self._data.get("_last_signal_bot", "none")),
            "market_regime": str(self._data.get("_last_market_regime", "normal")),
            # [v232-ADVISOR] Советы ботов при входе — сохранены в _data временно
            "bot_advisory": dict(self._data.get("_pending_bot_advisory", {})),
            # [FIX-v326-BUG2] Уровень ослабления фильтров, на котором сканер сейчас находится
            # (строгое/мягкое/среднее/сильное/максимальное/ЭКСТРЕННЫЙ) — записываем при КАЖДОМ
            # входе, чтобы позже накопить статистику "какой уровень ослабления реально даёт
            # прибыль, а какой только минус" (relax_level_stats, см. _update_stats).
            "relax_level": str(getattr(self._engine_ref, '_current_relax_step', 'строгое')
                                if hasattr(self, '_engine_ref') and self._engine_ref else 'unknown'),
        }
        log(f"[knowledge] Вход: {symbol} ADX={adx:.0f} RSI={rsi:.0f} T{tier} bot={self._cur['signal_bot']}")

    def log_trade_exit(self, exit_price: float, pnl_usdt: float, exit_reason: str = ""):
        # [FIX-v183-3] Создаём синтетический _cur для аварийных выходов
        # Раньше: если log_trade_entry не вызывался (перезапуск бота) → _cur пустой → return → мозг молчит
        # Теперь: при аварийных exit создаём _cur из текущих данных позиции
        if not self._cur:
            _emergency_exits = ("dump_exit","stop_loss","full_grid_early_stop","falling_grid")
            if any(ex in exit_reason for ex in _emergency_exits):
                try:
                    _sym = getattr(self, '_last_known_symbol', 'UNKNOWN')
                    _ep  = float(exit_price or 0)
                    self._cur = {
                        "id": f"{_sym}_{int(time.time())}_emergency",
                        "symbol": _sym, "mode": "UNKNOWN",
                        "entry_price": _ep, "entry_ts": time.time()-3600,
                        "entry_time": datetime.now().isoformat(),
                        "hour": datetime.now().hour,
                        "hour_utc": datetime.utcnow().hour,  # [FIX-v297-BUG] см. log_trade_entry
                        "weekday": datetime.now().weekday(),
                        "weekday_name": ["Пн","Вт","Ср","Чт","Пт","Сб","Вс"][datetime.now().weekday()],
                        "adx": 0.0, "rsi": 0.0, "score": 0.0,
                        "source": "emergency_synthetic",
                    }
                    log(f"📝 [brain] Синтетический _cur для {exit_reason}")
                except Exception as _syn_ex:
                    log(f"⚠️ [brain synthetic_cur] {_syn_ex}")
                    return
            else:
                return
        try:
            t = self._cur
            dur = (time.time() - t.get("entry_ts", time.time())) / 3600.0
            ep = t.get("entry_price", exit_price) or exit_price
            pnl_pct = (exit_price - ep) / max(ep, 1e-9) * 100.0
            outcome = "profit" if pnl_usdt > 0.005 else ("loss" if pnl_usdt < -0.005 else "breakeven")
            t.update({"exit_price": exit_price, "pnl_usdt": round(pnl_usdt, 6),
                      "pnl_pct": round(pnl_pct, 3), "exit_reason": exit_reason,
                      "duration_h": round(dur, 2), "outcome": outcome})
            self._data["trades"].append(dict(t))
            self._update_stats(t)
            if outcome == "loss":
                self._log_problem(t)
                # [FIX-v185-2] Аварийная продажа → TG отчёт с анализом и мерами
                _emergency_reasons = ("dump_exit","stop_loss","full_grid_early_stop","falling_grid")
                if any(ex in exit_reason for ex in _emergency_reasons):
                    try:
                        self._send_emergency_tg_report(
                            symbol=t.get('symbol','?'),
                            pnl_usdt=pnl_usdt,
                            exit_reason=exit_reason,
                            hour=t.get('hour', 0),
                            adx=t.get('adx', 0.0)
                        )
                    except Exception as _etg:
                        log(f"⚠️ [emergency_tg_call] {_etg}")
            if len(self._data["trades"]) % 10 == 0:
                self._analyze_patterns()
            # [v216-TRUST-ALL] Trust update после КАЖДОГО выхода: TP/SL/dump/time_stop
            try:
                _sig_bot = str(self._data.get("_last_signal_bot","none"))
                _t_out = outcome
                _er_str = str(exit_reason or "")
                if any(x in _er_str for x in ["TP_fill","BE_fill"]):
                    _t_out = "profit"
                elif any(x in _er_str for x in ["stop_loss","dump_exit","full_grid_early"]):
                    _t_out = "loss"
                # [FIX-v308-BUG2] "time_stop"/"ext_time_stop" убраны из этого списка.
                # Причина: run() шлёт reason="time_stop {h}h loss={pct}%" из ОДНОГО блока кода
                # и для настоящего убыточного time_stop/hard_exit, И для _long_hold_profit_trigger
                # ("💰 Забираю прибыль" — штатный ПРИБЫЛЬНЫЙ выход по времени+профиту, см. run()).
                # Текст всегда начинается с "time_stop" независимо от знака результата —
                # substring-проверкой их не различить. outcome, пришедший в эту функцию, уже
                # корректно посчитан из реального pnl_usdt (видно в строке "[knowledge] Выход:
                # ... profit +0.0582" чуть ниже) — доверяем ему, а не тексту причины.
                # Раньше это ломало доверие к сигнальным ботам: прибыльная сделка SLXUSDT
                # (+0.0582 USDT) считалась убытком pnl=-98.3% → smc-бот получал weight=0.3
                # принудительно ЗА ПРИБЫЛЬНУЮ сделку.
                # [FIX-v308-BUG3] БЫЛО: self._last_entry_cost — атрибут, который нигде в файле
                # не устанавливается, всегда падал в fallback getattr(...,pnl_usdt+0.001) —
                # то есть знаменатель ВСЕГДА был "прибыль ± копейка", а не реальная стоимость
                # входа. Итог: _t_pnl_pct почти всегда получался около ±100% независимо от
                # реального размера сделки (видно по всему боту: "avg=-48.525%", "pnl=-102.099%"
                # и т.п. — это не реальные проценты). Чуть выше в этой же функции (строка ~4010)
                # уже правильно посчитан pnl_pct = (exit_price-entry_price)/entry_price*100 —
                # берём его вместо сломанной формулы.
                _t_pnl_pct = float(t.get('pnl_pct', 0.0) or 0.0)
                if _t_out == "loss": _t_pnl_pct = -abs(_t_pnl_pct)
                elif _t_out == "profit": _t_pnl_pct = abs(_t_pnl_pct)
                self.update_bot_trust(_sig_bot, _t_out, pnl_pct=_t_pnl_pct)
                log(f"🤝 [v217-trust] {_sig_bot}→{_t_out} pnl={_t_pnl_pct:+.3f}% reason={_er_str[:30]}")
                # При WR<35% после 5+ сделок → принудительный weight=0.3
                # [FIX-v297-STAT] Было >=3 — жёсткий немедленный оверрайд поверх более
                # аккуратной n>=5 логики в update_bot_trust() (строка ~3482 выше), то есть при
                # 3 сделках (1 победа/2 поражения, WR=33%) доверие к сигнальному боту резалось
                # до минимума одной убыточной сделкой на очень маленькой выборке. Синхронизировано
                # с тем же порогом n>=5, что использует update_bot_trust().
                if _t_out == "loss" and _sig_bot != "none":
                    _bt = self._data.get("bot_trust",{}).get(_sig_bot,{})
                    if _bt.get("trades",0) >= 5 and _bt.get("wr",1.0) < 0.35:
                        self._data.setdefault("bot_trust",{}).setdefault(_sig_bot,{})["weight"]=0.3
                        log(f"⚠️ [v216] {_sig_bot} WR<35% → weight=0.3 принудительно")
            except Exception as _tbu:
                log(f"⚠️ [trust_upd] {_tbu}")
            self._save()
            # ── [v250] ИИ объясняет убыток и меняет параметры ───────
            if outcome == 'loss':
                try:
                    _eng = getattr(self, '_engine_ref', None)
                    if _eng and getattr(_eng, 'ai_advisor', None):
                        _eng.ai_advisor.ai_explain_loss(t)
                except Exception as _ai_ex:
                    log(f"⚠️ [v250 ai_explain] {_ai_ex}")
            self._cur = {}
            log(f"[knowledge] Выход: {t['symbol']} {outcome} {pnl_usdt:+.4f} ({exit_reason})")
        except Exception as _e:
            log(f"[knowledge] exit err: {_e}")

    def _update_stats(self, t: dict):
        for bucket_key, stat_key in [(str(t.get("hour", 0)), "hour_stats"),
                                     (str(t.get("weekday", 0)), "weekday_stats")]:
            s = self._data[stat_key].setdefault(bucket_key, {"trades": 0, "wins": 0, "losses": 0, "pnl": 0.0})
            s["trades"] += 1
            if t["outcome"] == "profit":
                s["wins"] += 1
            elif t["outcome"] == "loss":
                s["losses"] += 1
            s["pnl"] = round(s["pnl"] + t["pnl_usdt"], 6)
            if stat_key == "weekday_stats":
                s["name"] = t.get("weekday_name", "?")
        adx = t.get("adx", 0)
        ab = f"ADX_{int(adx // 5) * 5}-{int(adx // 5) * 5 + 5}"
        a = self._data["filter_stats"].setdefault(ab, {"trades": 0, "wins": 0, "pnl": 0.0})
        a["trades"] += 1
        if t["outcome"] == "profit":
            a["wins"] += 1
        a["pnl"] = round(a["pnl"] + t["pnl_usdt"], 6)
        tb = f"Tier_{t.get('adaptive_tier', 1)}"
        b = self._data["filter_stats"].setdefault(tb, {"trades": 0, "wins": 0, "pnl": 0.0})
        b["trades"] += 1
        if t["outcome"] == "profit":
            b["wins"] += 1
        b["pnl"] = round(b["pnl"] + t["pnl_usdt"], 6)
        # [FIX-v326-BUG2] По вашей просьбе: статистика "какой уровень ослабления фильтров
        # реально даёт прибыль, а какой только минус" — используется в scan_market_top()
        # перед фактическим ослаблением до нового уровня (см. _relax_level_quality_gate),
        # чтобы требовать более высокий score от кандидата на уровнях, где раньше было
        # много убытков, вместо того чтобы слепо ослаблять по одной и той же формуле
        # каждый раз. Считается статистикой самого бота (детерминированно, без ИИ/API —
        # не тратим лимит и деньги на запросы ради этого).
        rl = str(t.get("relax_level", "unknown"))
        r = self._data.setdefault("relax_level_stats", {}).setdefault(rl, {"trades": 0, "wins": 0, "pnl": 0.0})
        r["trades"] += 1
        if t["outcome"] == "profit":
            r["wins"] += 1
        r["pnl"] = round(r["pnl"] + t["pnl_usdt"], 6)
        # [FIX-v240-2] Per-symbol статистика
        # KASUSDT ADX=13 убыток → мозг запомнит min_safe_adx для этой монеты
        try:
            _sym_key = str(t.get("symbol", "UNKNOWN"))
            _sym_adx = float(t.get("adx", 0.0))
            sym_s = self._data.setdefault("symbol_stats", {}).setdefault(_sym_key, {
                "trades": 0, "wins": 0, "losses": 0, "pnl": 0.0,
                "adx_losses": [], "min_safe_adx": 0.0,
                "win_hours": [], "loss_hours": [],
                "best_hours": [], "worst_hours": [],
                "last_win_hour": -1, "last_win_ts": 0.0,
                "win_streak": 0, "avg_win_pct": 0.0, "avg_loss_pct": 0.0,
                "best_adx_min": 0.0, "best_adx_max": 0.0,
                "best_rsi_min": 0.0, "best_rsi_max": 0.0,
            })
            sym_s["trades"] += 1
            sym_s["pnl"] = round(sym_s["pnl"] + t["pnl_usdt"], 6)
            # [FIX-v297-BUG] Раньше тут читался t.get("hour", ...) — ЛОКАЛЬНЫЙ час из
            # log_trade_entry, а вся per-symbol шпаргалка (best_hours/worst_hours) читается
            # сканером в UTC (datetime.utcnow().hour). Используем "hour_utc" (см. log_trade_entry),
            # с фолбэком на текущий UTC-час для старых записей без этого поля.
            _entry_hour = int(t.get("hour_utc", __import__("datetime").datetime.utcnow().hour))
            _t_adx = float(t.get("adx", 0.0) or 0.0)
            _t_rsi = float(t.get("rsi", 0.0) or 0.0)
            if t["outcome"] == "profit":
                sym_s["wins"] += 1
                sym_s["win_streak"] = sym_s.get("win_streak", 0) + 1
                sym_s["last_win_hour"] = _entry_hour
                sym_s["last_win_ts"] = __import__("time").time()
                wh = sym_s.setdefault("win_hours", [])
                wh.append(_entry_hour)
                sym_s["win_hours"] = wh[-30:]
                # ADX/RSI диапазон побед
                if _t_adx > 0:
                    _adx_w = [float(tr.get("adx",0)) for tr in self._data.get("trades",[])[-50:]
                              if tr.get("symbol")==_sym_key and tr.get("outcome")=="profit" and float(tr.get("adx",0))>0]
                    if _adx_w:
                        sym_s["best_adx_min"] = round(min(_adx_w), 1)
                        sym_s["best_adx_max"] = round(max(_adx_w), 1)
                if _t_rsi > 0:
                    _rsi_w = [float(tr.get("rsi",0)) for tr in self._data.get("trades",[])[-50:]
                              if tr.get("symbol")==_sym_key and tr.get("outcome")=="profit" and float(tr.get("rsi",0))>0]
                    if _rsi_w:
                        sym_s["best_rsi_min"] = round(min(_rsi_w), 1)
                        sym_s["best_rsi_max"] = round(max(_rsi_w), 1)
                # Средняя прибыль побед
                _wp = [float(tr.get("pnl_pct",0)) for tr in self._data.get("trades",[])[-50:]
                       if tr.get("symbol")==_sym_key and tr.get("outcome")=="profit"]
                if _wp: sym_s["avg_win_pct"] = round(sum(_wp)/len(_wp), 3)
            else:
                sym_s["losses"] += 1
                sym_s["win_streak"] = 0
                lh = sym_s.setdefault("loss_hours", [])
                lh.append(_entry_hour)
                sym_s["loss_hours"] = lh[-30:]
                if _sym_adx > 0:
                    sym_s.setdefault("adx_losses", []).append(round(_sym_adx, 1))
                    sym_s["adx_losses"] = sym_s["adx_losses"][-10:]
                _bad_adx = [a for a in sym_s["adx_losses"] if a < 20]
                # [FIX-v297-STAT] Было >=2 — жёсткий (навсегда, до перезаписи) фильтр монеты
                # выставлялся по 2 убыточным сделкам, статистически ничего не значащей выборке.
                # Подняли до >=5, как и остальные "обучающие" пороги в файле (см. коммент
                # v231 "Минимум 5 сделок... 2 слишком мало для вывода" в apply_learning).
                if len(_bad_adx) >= 5:
                    sym_s["min_safe_adx"] = round(sum(_bad_adx)/len(_bad_adx) + 7.0, 1)
                _lp = [abs(float(tr.get("pnl_pct",0))) for tr in self._data.get("trades",[])[-50:]
                       if tr.get("symbol")==_sym_key and tr.get("outcome")=="loss"]
                if _lp: sym_s["avg_loss_pct"] = round(sum(_lp)/len(_lp), 3)
            # Пересчёт best_hours / worst_hours
            _hr_wr = {}
            for _h in sym_s.get("win_hours", []):
                _x = _hr_wr.setdefault(_h, [0,0]); _x[0]+=1; _x[1]+=1
            for _h in sym_s.get("loss_hours", []):
                _x = _hr_wr.setdefault(_h, [0,0]); _x[1]+=1
            # [FIX-v297-STAT] Было t>=2 — час объявлялся "золотым"/"плохим" по 2 сделкам.
            # Подняли до t>=5 для той же статистической надёжности, что и остальные пороги.
            sym_s["best_hours"]  = [h for h,(w,t) in _hr_wr.items() if t>=5 and w/t>=0.60]
            sym_s["worst_hours"] = [h for h,(w,t) in _hr_wr.items() if t>=5 and w/t<=0.30]
            log(f"📋 [v292-1] {_sym_key} шпаргалка: WR={sym_s['wins']}/{sym_s['trades']} best_h={sym_s['best_hours']} streak={sym_s['win_streak']}")
        except Exception as _ss_ex:
            log(f"⚠️ [symbol_stats] {_ss_ex}")

        # [FIX-v222-3] Добавляем статистику по режиму и сигнал-боту.
        # Раньше мозг не мог ответить: "SMART лучше SAFE?" или "SMC бот полезен в SNIPER?"
        # Теперь: mode_stats["SMART"] = {trades, wins, pnl} → apply_learning использует это.
        _mode_key = str(t.get("mode", "UNKNOWN"))
        ms = self._data.setdefault("mode_stats", {}).setdefault(_mode_key, {"trades": 0, "wins": 0, "pnl": 0.0})
        ms["trades"] += 1
        if t["outcome"] == "profit": ms["wins"] += 1
        ms["pnl"] = round(ms["pnl"] + t["pnl_usdt"], 6)
        # Статистика по сигнал-боту (smc/funding/volume/news/base/none)
        _bot_key = str(t.get("signal_bot", "none"))
        bs = self._data.setdefault("bot_mode_stats", {}).setdefault(_bot_key, {"trades": 0, "wins": 0, "pnl": 0.0})
        bs["trades"] += 1
        if t["outcome"] == "profit": bs["wins"] += 1
        bs["pnl"] = round(bs["pnl"] + t["pnl_usdt"], 6)

    def _log_problem(self, t: dict):
        reasons = []
        adx = t.get("adx", 0); rsi = t.get("rsi", 0)
        tier = t.get("adaptive_tier", 1); reason = t.get("exit_reason", "")
        h = t.get("hour", 12)
        if tier >= 2:
            reasons.append(f"Tier {tier} (ослабл фильтры)")
        if adx < 22:
            reasons.append(f"Слабый тренд ADX={adx:.0f}")
        if rsi > 70:
            reasons.append(f"RSI перекуплен {rsi:.0f}%")
        if "dump" in reason:
            reasons.append("Дамп монеты")
        if "time_stop" in reason:
            reasons.append(f"Боковик {t.get('duration_h', 0):.1f}ч")
        if h in (0, 1, 2, 3, 4):
            reasons.append("Ночь — низкий объём")
        if not reasons:
            reasons.append("Рыночная волатильность")
        self._data["problems"].append({
            "ts": datetime.now().isoformat(),
            "symbol": t.get("symbol"), "pnl_usdt": t.get("pnl_usdt"),
            "analysis": " | ".join(reasons), "adx": adx, "rsi": rsi,
            "hour": h, "tier": tier, "exit_reason": reason,
        })
        self._data["problems"] = self._data["problems"][-100:]


    # ─────────────────────────────────────────────────────────────────
    # [v213] ПРЯМОЕ ЧТЕНИЕ ГРАФИКА
    # Не просто EMA/RSI — мозг видит структуру цены:
    # Higher Highs, Higher Lows, поддержки, импульс, объём
    # ─────────────────────────────────────────────────────────────────

    def analyze_chart_structure(self, closes: list, volumes: list = None) -> dict:
        """Читает структуру графика напрямую.
        
        Returns dict:
          trend     : 'up' | 'down' | 'sideways'
          score     : 0.0-10.0
          hh        : bool  Higher Highs
          hl        : bool  Higher Lows
          momentum  : float % изменение последних 5 vs предыдущих 5
          support   : float уровень поддержки
          resistance: float уровень сопротивления
          near_sup  : bool  цена близко к поддержке
          impulse   : bool  есть импульс вверх
          reason    : str
        """
        try:
            if not closes or len(closes) < 10:
                return {"trend":"unknown","score":0.0,"reason":"мало данных"}

            c = closes[-20:] if len(closes) >= 20 else closes[:]
            n = len(c)
            score = 0.0
            tags = []

            # — Higher Highs: каждый локальный максимум выше предыдущего
            chunk = max(3, n // 4)
            highs = [max(c[i:i+chunk]) for i in range(0, n - chunk + 1, chunk)]
            hh = len(highs) >= 2 and all(highs[k] < highs[k+1] for k in range(len(highs)-1))
            if hh:
                score += 2.5; tags.append("HH")

            # — Higher Lows: каждый локальный минимум выше предыдущего
            lows = [min(c[i:i+chunk]) for i in range(0, n - chunk + 1, chunk)]
            hl = len(lows) >= 2 and all(lows[k] < lows[k+1] for k in range(len(lows)-1))
            if hl:
                score += 2.5; tags.append("HL")

            # — EMA тренд (9/21)
            def _ema(data, p):
                k = 2.0 / (p + 1); v = data[0]
                for x in data[1:]: v = x * k + v * (1 - k)
                return v
            e9 = _ema(c, 9); e21 = _ema(c, 21)
            if e9 > e21 * 1.001:
                score += 1.5; tags.append("EMA↑")
            elif e9 < e21 * 0.999:
                score -= 1.5; tags.append("EMA↓")

            # — Моментум: последние 5 свечей vs предыдущие 5
            if n >= 10:
                r_avg = sum(c[-5:]) / 5
                p_avg = sum(c[-10:-5]) / 5
                mom = (r_avg - p_avg) / p_avg * 100.0 if p_avg > 0 else 0.0
                if mom > 1.0:   score += 2.0; tags.append(f"mom+{mom:.1f}%")
                elif mom > 0.3: score += 1.0; tags.append(f"mom+{mom:.1f}%")
                elif mom < -1.0: score -= 1.5; tags.append(f"mom{mom:.1f}%")
                elif mom < -0.3: score -= 0.5
            else:
                mom = 0.0

            # — Поддержка и сопротивление
            support    = min(c[-10:])
            resistance = max(c[-10:])
            cur = c[-1]
            rng = resistance - support
            if rng > 0:
                pos_pct = (cur - support) / rng * 100
                if pos_pct < 25:
                    score += 1.0; tags.append("near_sup")
                    near_sup = True
                elif pos_pct > 80:
                    score -= 1.0; tags.append("near_res")
                    near_sup = False
                else:
                    near_sup = False
            else:
                near_sup = False; pos_pct = 50

            # — Объём (если передан)
            if volumes and len(volumes) >= 5:
                vol_avg = sum(volumes[-10:]) / max(len(volumes[-10:]), 1)
                vol_now = sum(volumes[-2:]) / 2
                if vol_avg > 0 and vol_now > vol_avg * 1.5:
                    score += 1.0; tags.append("vol↑")

            # — Итог
            score = max(0.0, min(10.0, score))
            if   score >= 6.0: trend = "up"
            elif score >= 3.5: trend = "sideways"
            else:              trend = "down"

            return {
                "trend":      trend,
                "score":      round(score, 2),
                "hh":         hh,
                "hl":         hl,
                "momentum":   round(mom, 3),
                "support":    round(support, 8),
                "resistance": round(resistance, 8),
                "near_sup":   near_sup,
                "impulse":    mom > 0.3,
                "reason":     " ".join(tags) if tags else "нейтрально",
            }
        except Exception as _e:
            log(f"⚠️ [chart_structure] {_e}")
            return {"trend":"unknown","score":0.0,"reason":str(_e)}

    def _analyze_patterns(self):
        trades = self._data["trades"]
        if len(trades) < 5:
            return
        insights = []
        hs = self._data["hour_stats"]
        if len(hs) >= 4:
            bh = max(hs.items(), key=lambda x: x[1]["pnl"])[0]
            wh = min(hs.items(), key=lambda x: x[1]["pnl"])[0]
            insights.append(f"Лучший час: {bh}:00 | Худший: {wh}:00")
        wds = self._data["weekday_stats"]
        if len(wds) >= 3:
            bd = max(wds.items(), key=lambda x: x[1]["pnl"])
            insights.append(f"Лучший день: {bd[1].get('name','?')} PnL={bd[1]['pnl']:+.3f}")
        for tier_key in ["Tier_1", "Tier_2", "Tier_3"]:
            if tier_key in self._data["filter_stats"]:
                fs = self._data["filter_stats"][tier_key]
                if fs["trades"] >= 3:
                    wr = fs["wins"] / fs["trades"] * 100
                    insights.append(f"{tier_key}: WR={wr:.0f}% PnL={fs['pnl']:+.3f}")
        if insights:
            self._data["insights"].append({
                "ts": datetime.now().isoformat(),
                "insights": insights, "count": len(trades),
            })
            self._data["insights"] = self._data["insights"][-50:]
            for ins in insights:
                log(f"[knowledge] {ins}")
            # [FIX-v168-1] После анализа — ПРИМЕНЯЕМ знания!
            self.apply_learning()
            # [FIX-v272] После apply_learning зажимаем фильтры в рамках режима
            try:
                enforce_mode_limits_cfg(str(getattr(CFG, 'TRADING_MODE', 'SMART')))
            except Exception as _eml2: log(f'⚠️ [enforce_mode_limits] {_eml2}')

    # ── ПРИМЕНЕНИЕ ЗНАНИЙ — МОЗГ НАЧИНАЕТ ДЕЙСТВОВАТЬ ─────────────────────
    def _send_emergency_tg_report(self, symbol: str, pnl_usdt: float,
                                   exit_reason: str, hour: int, adx: float):
        """[FIX-v185-1] TG отчёт при аварийной продаже с анализом причин и мерами.

        [FIX-v326-BUG] КРИТИЧНО, найдено по вашему скриншоту (PYTHUSDT, full_grid_early_stop,
        ADX=50, 20:17): текст "Мозг: повысит ADX_MIN" показывался ВСЕГДА для причины
        full_grid_early_stop, но реальный код ниже поднимал ADX_MIN ТОЛЬКО для причины
        stop_loss при ADX<20 — то есть для full_grid_early_stop (а это, по Round 29, САМЫЙ
        частый источник убытка) обещание было пустым текстом, реального действия под ним не
        было вообще. Хуже: через 5 минут после этого сообщения сработал СОВСЕМ ДРУГОЙ, никак
        не связанный механизм (авто-ослабление фильтров по счётчику пустых сканов) и опустил
        ADX_MIN — то есть даже если бы реальное действие сработало, его тут же стёрло бы это
        независимое ослабление. Теперь: (1) реальное действие срабатывает при 2+ убытках за
        этот час НЕЗАВИСИМО от причины и величины ADX (а не только stop_loss+ADX<20) — текст
        сообщения строится по факту того, сработает ли действие, а не по шаблону, зашитому
        под тип причины; (2) поднятие защищено через _ai_adx_floor (см. apply_mode() и
        авто-ослабление ниже по файлу) — независимый механизм ослабления больше не может
        стереть его в первые же минуты.
        """
        try:
            # Что мозг сделает дальше — считаем ДО текста, чтобы текст не врал
            hour_wr = self._data.get('hour_stats', {}).get(str(hour), {})
            h_losses = int(hour_wr.get('losses', 0))
            _will_tighten = (h_losses >= 2) or (adx < 20 and 'stop_loss' in str(exit_reason))

            # Определяем причину на русском
            if 'full_grid_early_stop' in exit_reason:
                причина = "🛑 Полная сетка в убытке — ранний стоп"
                меры = ("Мозг: повысит ADX_MIN и снизит активность в этот час" if _will_tighten
                        else "Мозг: фиксирует случай (пока в пределах нормы, действие не требуется)")
            elif 'falling_grid' in exit_reason:
                причина = "⚡ Падающая сетка — цена резко упала через все ордера"
                меры = "Мозг: проверит EMA тренд строже перед следующим входом"
            elif 'dump_exit' in exit_reason:
                причина = "🚨 Обнаружен дамп — аварийная продажа"
                меры = "Мозг: увеличит дистанцию от входа, добавит час в стоп-лист"
            elif 'stop_loss' in exit_reason:
                причина = "🔴 Стоп-лосс сработал"
                меры = ("Мозг: пересмотрит ADX фильтр для этой монеты" if _will_tighten
                        else "Мозг: фиксирует случай (пока в пределах нормы, действие не требуется)")
            else:
                причина = f"Выход: {exit_reason}"
                меры = "Мозг: анализирует паттерн"

            future_action = ""
            if h_losses >= 2:
                future_action = f"\n🕐 Час {hour}:00 → добавлен в стоп-список (2+ убытков)"
            if adx < 30:
                future_action += f"\n📊 ADX={adx:.0f} слишком слабый"

            # [FIX-v240-1 + FIX-v326-BUG] РЕАЛЬНОЕ действие — мозг не просто пишет в TG.
            # Раньше срабатывало только для (adx<20 and 'stop_loss' in reason). Теперь
            # ЛЮБАЯ причина, если за этот час уже 2+ убытков — независимо от ADX конкретной
            # сделки (ADX=50 у full_grid_early_stop не значит "тренд был слабый", это другой
            # механизм выхода) — плюс сохранён старый узкий случай для stop_loss.
            if _will_tighten:
                try:
                    _cur_adx_sl = float(getattr(CFG, 'SCANNER_ADX_MIN', 20.0))
                    _new_adx_sl = min(_cur_adx_sl + 3.0, 30.0)
                    if _new_adx_sl > _cur_adx_sl:
                        CFG.SCANNER_ADX_MIN = _new_adx_sl
                        # [FIX-v326-BUG] "Пол" от ИИ/мозга — apply_mode() (см. FIX-v325-BUG) и
                        # авто-ослабление фильтров (см. ниже по файлу) теперь не опустят
                        # ADX_MIN ниже этого значения, пока пол не истёк (24ч).
                        CFG._ai_adx_floor = _new_adx_sl
                        CFG._ai_adx_floor_ts = time.time()
                        # Сохраняем в learned_cfg
                        self._data.setdefault("learned_cfg", {})["SCANNER_ADX_MIN"] = _new_adx_sl
                        self._save()
                        log(f"📊 [v326] РЕАЛЬНОЕ действие: ADX_MIN {_cur_adx_sl:.0f}→{_new_adx_sl:.0f} "
                            f"(h_losses={h_losses}, adx={adx:.0f}, reason={exit_reason}), защищено 24ч")
                        future_action += f"\n✅ ADX_MIN уже повышен: {_cur_adx_sl:.0f}→{_new_adx_sl:.0f} (защищено 24ч)"
                except Exception as _fadx: log(f"⚠️ [sl_adx_fix] {_fadx}")

            msg = (
                "🚨 АВАРИЙНАЯ ПРОДАЖА\n"
                + "="*30 + "\n"
                + f"Монета: {symbol}\n"
                + f"Причина: {причина}\n"
                + f"Убыток: {pnl_usdt:+.4f} USDT\n"
                + f"ADX={adx:.0f} | Час={hour}:00\n"
                + "="*30 + "\n"
                + "🧠 ЧТО МОЗГ СДЕЛАЕТ:\n"
                + меры + future_action + "\n"
                + "📚 Мозг учится на этой ошибке"
            )
            if TG.enabled:
                TG.send(msg)
        except Exception as _e:
            log(f"⚠️ [emergency_tg] {_e}")

    # ──────────────────────────────────────────────────────────────
    # [v218-QUIET] Авто-определение тихого рынка
    # ──────────────────────────────────────────────────────────────

    def get_market_regime(self, adx_now: float, rsi_now: float,
                          zero_streak: int) -> str:
        """Определяет режим рынка:
        
        'active'  → торгуем агрессивно, слушаем все боты
        'normal'  → стандартный режим
        'quiet'   → боковик: отключаем liq/corr, слушаем только SMC+volume
        'dead'    → рынок мёртвый: только базовый режим, минимум сигналов
        """
        try:
            if adx_now >= 35 and zero_streak == 0:
                return "active"
            elif adx_now >= 20 and zero_streak <= 5:
                return "normal"
            elif adx_now >= 12 and zero_streak <= 30:
                return "quiet"
            else:
                return "dead"
        except Exception:
            return "normal"

    def get_active_bots_for_regime(self, regime: str) -> dict:
        """Возвращает какие боты слушать в каждом режиме.
        
        Returns: {bot_name: bool}
        True  = слушать (блокирует/разрешает торги)
        False = игнорировать (собираем данные но не блокируем)
        """
        regimes = {
            "active": {
                "smc":True,"funding":True,"volume":True,
                "news":True,"corr":True,"liquidation":True,
            },
            "normal": {
                "smc":True,"funding":True,"volume":True,
                "news":True,"corr":True,"liquidation":False,
            },
            "quiet": {
                # liq и corr не блокируют — только информируют
                "smc":True,"funding":True,"volume":True,
                "news":True,"corr":False,"liquidation":False,
            },
            "dead": {
                # Только news (паника) и базовый режим
                "smc":False,"funding":False,"volume":True,
                "news":True,"corr":False,"liquidation":False,
            },
        }
        return regimes.get(regime, regimes["normal"])

    def apply_learning(self, min_trades: int = 5) -> dict:
        """[FIX-v168-1] КЛЮЧЕВОЙ МЕТОД — применяет накопленные знания к фильтрам.

        Читает статистику из JSON и автоматически корректирует:
        - ADX порог (если низкий ADX исторически убыточен → поднять)
        - Время Adaptive Tier переключения (если Tier 2 убыточен → ждать дольше)
        - Плохие часы суток (WR < 45% за N сделок → добавить в bad_hours)

        Возвращает dict с применёнными изменениями (для логирования).
        """
        applied = {}
        try:
            # [FIX-v272-2] Стабилизация: не менять фильтры чаще раза в FILTER_CHANGE_COOLDOWN_MIN.
            # Без этого мозг дёргал фильтры каждый цикл → "1 плюс → 4 минуса → каша".
            import time as _t272
            _last_change = float(self._data.get('_last_filter_change_ts', 0.0))
            _cooldown_min = float(getattr(CFG, 'FILTER_CHANGE_COOLDOWN_MIN', 30.0))
            if _t272.time() - _last_change < _cooldown_min * 60:
                return {}  # рано менять — даём фильтрам поработать стабильно
            trades = self._data["trades"]
            if len(trades) < min_trades:
                return {}   # мало данных — ничего не менять
            self._data['_last_filter_change_ts'] = _t272.time()

            # ── 1. Анализ ADX диапазонов ─────────────────────────────────
            adx_buckets = {k: v for k, v in self._data["filter_stats"].items()
                           if k.startswith("ADX_") and v["trades"] >= 3}
            if adx_buckets:
                # Находим убыточные ADX диапазоны (WR < 45%)
                bad_adx = []
                for bucket, stats in adx_buckets.items():
                    wr = stats["wins"] / stats["trades"] * 100
                    if wr < 45.0:
                        # Извлекаем нижнюю границу диапазона
                        try:
                            low_adx = int(bucket.split("_")[1].split("-")[0])
                            bad_adx.append(low_adx)
                        except Exception as _px_ex:  # [FIX-v170-2]
                            log(f"⚠️ [brain] ADX bucket parse: {_px_ex}")
                if bad_adx:
                    current_adx = float(getattr(CFG, 'SCANNER_ADX_MIN', 25.0))
                    # Находим минимальный плохой ADX
                    worst_low = min(bad_adx)
                    # [FIX-ADX-DEADLOCK] Ограничиваем максимальный ADX:
                    # Если мало сделок (<5) → не поднимать ADX выше 25 (риск дедлока)
                    # Если много сделок (≥10) → можно до 28
                    _adx_cap = 25.0 if len(trades) < 5 else (28.0 if len(trades) < 15 else 30.0)
                    # Если текущий порог ниже худшего ADX → поднять на 2
                    if current_adx <= worst_low + 5:
                        new_adx = min(worst_low + 3, _adx_cap)
                        if abs(new_adx - current_adx) >= 1.0:
                            # [FIX-v190e-1] НЕ ПОДНИМАТЬ ADX если zero_scan_streak активен!
                            # Мозг снижал ADX через ослабление → apply_learning не должен отменять это
                            _cur_streak = int(getattr(self,'_zero_scan_streak',0)) if hasattr(self,'_zero_scan_streak') else 0
                            if _cur_streak > 5:
                                log(f"⏸️ [brain] ADX НЕ поднят ({current_adx:.0f}→{new_adx:.0f}) — streak={_cur_streak} активен")
                            else:
                                CFG.SCANNER_ADX_MIN = new_adx
                                CFG.ADX_MIN = new_adx
                                applied["adx"] = (current_adx, new_adx)
                                log(f"💡 [brain] ADX {current_adx:.0f}→{new_adx:.0f} (cap={_adx_cap:.0f})")

                    # [FIX-v272] ADX DEADLOCK — порог streak 8→15, floor привязан к режиму
                    _streak_now = int(getattr(self,'_zero_scan_streak',0)) if hasattr(self,'_zero_scan_streak') else 0
                    if current_adx > 25.0 and _streak_now > 15:
                        _mode_profile = MODE_PROFILES.get(str(getattr(CFG,'TRADING_MODE','SMART')), {})
                        _adx_floor = float(_mode_profile.get('ADX_FLOOR', 20.0))
                        _forced_adx = max(_adx_floor, current_adx - 1.5)  # снижаем медленнее: -1.5 вместо -3
                        CFG.SCANNER_ADX_MIN = _forced_adx
                        if hasattr(CFG, 'ADX_MIN'): CFG.ADX_MIN = _forced_adx
                        applied["adx_deadlock_fix"] = (current_adx, _forced_adx)
                        log(f"🔓 [v272] ДЕДЛОК: ADX {current_adx:.0f}→{_forced_adx:.0f} (streak={_streak_now}, floor={_adx_floor:.0f})")
                        if TG.enabled:
                            # [FIX-v312] Было "\\n" (буквальный слэш+n в сообщении вместо
                            # переноса строки) — Telegram показывал текст одной строкой с
                            # видимыми "\n" внутри. Заменено на настоящий перенос "\n".
                            TG.send(
                                f"🔓 Мозг исправил дедлок ADX\n"
                                f"ADX был {current_adx:.0f} → монеты не проходили\n"
                                f"Снижен до {_forced_adx:.0f}\n"
                                f"Пустых сканов было: {_streak_now}"
                            )
                        # Немедленно сохраняем в learned_cfg
                        try:
                            self._data.setdefault("learned_cfg",{})["SCANNER_ADX_MIN"] = _forced_adx
                            self._save()
                        except Exception: pass

            # ── 2. Анализ Adaptive Tier ───────────────────────────────────
            t2_stats = self._data["filter_stats"].get("Tier_2", {})
            # [FIX-v231-1] Минимум 5 сделок в Tier2 (было 3) — слишком мало для вывода
            if t2_stats.get("trades", 0) >= 5:
                t2_wr = t2_stats["wins"] / t2_stats["trades"] * 100
                current_t1h = float(getattr(CFG, 'ADAPTIVE_SNIPER_TIER1_HOURS', 2.0))
                if t2_wr < 40.0 and current_t1h < 4.0:
                    # Tier 2 убыточен → ждём дольше перед переходом
                    new_t1h = min(current_t1h + 0.5, 4.0)
                    CFG.ADAPTIVE_SNIPER_TIER1_HOURS = new_t1h
                    applied["tier1_hours"] = (current_t1h, new_t1h)
                    log(f"💡 [brain] Tier1 ожидание {current_t1h:.1f}→{new_t1h:.1f}ч (Tier2 WR={t2_wr:.0f}%)")
                elif t2_wr >= 60.0 and current_t1h > 1.5:
                    # Tier 2 хорошо работает → переходим раньше
                    new_t1h = max(current_t1h - 0.5, 1.5)
                    CFG.ADAPTIVE_SNIPER_TIER1_HOURS = new_t1h
                    applied["tier1_hours"] = (current_t1h, new_t1h)
                    log(f"💡 [brain] Tier1 ожидание {current_t1h:.1f}→{new_t1h:.1f}ч (Tier2 WR={t2_wr:.0f}% — хорошо!)")

            # ── 2b. [FIX-v272] WR-based mode switch — умное переключение режима ──
            try:
                _recent = [t for t in trades[-20:] if t.get("outcome") in ("profit","loss")]
                if len(_recent) >= 10:
                    _wr_recent = sum(1 for t in _recent if t.get("outcome")=="profit") / len(_recent)
                    _cur_mode = str(getattr(CFG, 'TRADING_MODE', 'SMART'))
                    # [v285-5] deepcopy: передаём КОПИЮ данных, не ссылку!
                    # v284 баг: getattr(self,'_data') → ссылка → apply_mode_with_brain
                    # модифицировала dict по ссылке → мутировала self._data напрямую.
                    # При WR-switch + daily_reset одновременно → data corruption.
                    # [FIX-v321-BUG3] self._data['_engine_ref'] хранит ссылку на весь Engine
                    # (см. [FIX-v262-1]) — а через него достижимы TelegramPolling.lock и
                    # (с v314) BotKnowledge._lock, обычные threading.Lock/RLock. deepcopy()
                    # пытается скопировать ВЕСЬ граф объектов, доходит до лока и падает с
                    # "cannot pickle '_thread.lock' object" — весь блок уходит в except, и
                    # вся функция авто-переключения режима по винрейту (SNIPER↔SAFE↔SMART)
                    # НИ РАЗУ реально не срабатывала (подтверждено логом). apply_mode_with_
                    # brain() читает только learned_cfg — исключаем _engine_ref (тот же ключ,
                    # что уже исключается в _save(), см. _skip_keys там же) перед копированием.
                    import copy as _copy285
                    _kd_wr = _copy285.deepcopy({k: v for k, v in (getattr(self, '_data', None) or {}).items() if k != '_engine_ref'})

                    if _wr_recent < 0.40 and _cur_mode == "SNIPER":
                        # WR < 40% при SNIPER → переключаем в SAFE
                        apply_mode_with_brain("SAFE", _kd_wr)
                        applied["mode_switch"] = ("SNIPER", "SAFE", f"WR={_wr_recent:.0%}")
                        log(f"📉 [v272-WR] SNIPER→SAFE (WR={_wr_recent:.0%} < 40% за 20 сделок)")
                        if TG.enabled:
                            TG.send(f"🛡️ Режим SNIPER→SAFE\nWR упал до {_wr_recent:.0%} (порог 40%)\nМозг снизил риски")

                    elif _wr_recent > 0.60 and _cur_mode == "SAFE":
                        # WR > 60% при SAFE → возвращаем SNIPER
                        apply_mode_with_brain("SNIPER", _kd_wr)
                        applied["mode_switch"] = ("SAFE", "SNIPER", f"WR={_wr_recent:.0%}")
                        log(f"📈 [v272-WR] SAFE→SNIPER (WR={_wr_recent:.0%} > 60% за 20 сделок)")
                        if TG.enabled:
                            TG.send(f"✅ Режим SAFE→SNIPER\nWR вырос до {_wr_recent:.0%} (порог 60%)\nМозг увеличивает активность")

                    elif _wr_recent < 0.40 and _cur_mode == "SMART":
                        # WR < 40% при SMART → переключаем в SAFE
                        apply_mode_with_brain("SAFE", _kd_wr)
                        applied["mode_switch"] = ("SMART", "SAFE", f"WR={_wr_recent:.0%}")
                        log(f"📉 [v272-WR] SMART→SAFE (WR={_wr_recent:.0%} < 40%)")
                        if TG.enabled:
                            TG.send(f"🛡️ Режим SMART→SAFE\nWR={_wr_recent:.0%} < 40%")

                    elif _wr_recent > 0.60 and _cur_mode == "SMART":
                        # WR > 60% при SMART → SNIPER
                        apply_mode_with_brain("SNIPER", _kd_wr)
                        applied["mode_switch"] = ("SMART", "SNIPER", f"WR={_wr_recent:.0%}")
                        log(f"📈 [v272-WR] SMART→SNIPER (WR={_wr_recent:.0%} > 60%)")
                        if TG.enabled:
                            TG.send(f"✅ Режим SMART→SNIPER\nWR={_wr_recent:.0%} > 60%")
            except Exception as _wr_ex:
                log(f"⚠️ [v272-WR-switch] {_wr_ex}")

            # ── 3. Анализ плохих часов суток ─────────────────────────────
            hs = self._data["hour_stats"]
            bad_hours = []
            good_hours = []
            for h_str, stats in hs.items():
                # [FIX-v226-3] Минимум 5 сделок в часе для вывода (было 3).
                # При 3 сделках: 2 убытка = WR=33% → час блокируется.
                # Но 3 сделки — слишком мало. Нужно минимум 5 для надёжности.
                # Математика: при n=5 ±1σ=±22%, при n=3 ±1σ=±29% — слишком неточно.
                _min_h_trades = 5
                if stats["trades"] < _min_h_trades:
                    continue
                wr = stats["wins"] / stats["trades"] * 100
                if wr < 40.0:
                    bad_hours.append(int(h_str))
                elif wr >= 65.0:
                    good_hours.append(int(h_str))
            # [FIX-v169-2] Защита: max 12 часов в bad_hours (не больше половины суток).
            # Если >12 плохих → берём только самые "плохие" по WR
            if len(bad_hours) > 12:
                # Сортируем по WR (от худшего к лучшему) и берём 12
                bad_with_wr = sorted(
                    [(h, hs.get(str(h),{}).get("wins",0) / max(hs.get(str(h),{}).get("trades",1),1))
                     for h in bad_hours],
                    key=lambda x: x[1]  # сортируем по WR (меньше = хуже)
                )
                bad_hours = [h for h,_ in bad_with_wr[:12]]
                log(f"⚠️ [brain] Слишком много плохих часов, ограничен до 12: {sorted(bad_hours)}")
            if bad_hours != self._data.get("bad_hours", []):
                self._data["bad_hours"] = bad_hours
                self._data["good_hours"] = good_hours
                applied["bad_hours"] = bad_hours
                if bad_hours:
                    log(f"💡 [brain] Плохие часы: {bad_hours} (WR<40%) — Tier 2 не применяем")
                if good_hours:
                    log(f"💡 [brain] Хорошие часы: {good_hours} (WR≥65%)")

            # ── 4. RSI оптимизация ────────────────────────────────────────
            # Если есть проблемы (убытки) где RSI был высокий (>68)
            high_rsi_losses = sum(1 for p in self._data.get("problems", [])
                                  if p.get("rsi", 0) > 68 and p.get("pnl_usdt", 0) < -0.05)
            total_losses = len(self._data.get("problems", []))
            if total_losses >= 5 and high_rsi_losses / max(total_losses, 1) > 0.5:
                current_rsi = float(getattr(CFG, 'SCANNER_RSI_MAX', 68.0))
                if current_rsi > 65.0:
                    new_rsi = max(current_rsi - 2.0, 65.0)
                    CFG.SCANNER_RSI_MAX = new_rsi
                    applied["rsi"] = (current_rsi, new_rsi)
                    log(f"💡 [brain] RSI {current_rsi:.0f}→{new_rsi:.0f} ({high_rsi_losses} убытков при RSI>{current_rsi:.0f})")

            # ── 5. [FIX-v222-3b] Анализ mode_stats — какой режим прибыльнее ──
            # Если накопилось достаточно данных → мозг видит какой режим реально лучше
            try:
                _ms = self._data.get("mode_stats", {})
                _mode_insights = []
                for _mn, _mv in _ms.items():
                    if _mv.get("trades", 0) >= 5:
                        _mwr = _mv["wins"] / _mv["trades"] * 100
                        _mode_insights.append((_mn, _mwr, _mv["pnl"]))
                if len(_mode_insights) >= 2:
                    _mode_insights.sort(key=lambda x: x[1], reverse=True)
                    _best_mode = _mode_insights[0]
                    _worst_mode = _mode_insights[-1]
                    if _best_mode[1] - _worst_mode[1] >= 15:  # разница WR >= 15%
                        log(f"💡 [brain v222] Режимы: лучший={_best_mode[0]} WR={_best_mode[1]:.0f}% | "
                            f"худший={_worst_mode[0]} WR={_worst_mode[1]:.0f}%")
                        applied["mode_analysis"] = {
                            "best": _best_mode[0], "best_wr": round(_best_mode[1], 1),
                            "worst": _worst_mode[0], "worst_wr": round(_worst_mode[1], 1),
                        }
            except Exception as _mae:
                log(f"⚠️ [brain mode_stats] {_mae}")

            # ── 6. [FIX-v222-3c] Анализ bot_mode_stats — какой бот реально помогает ──
            try:
                _bs = self._data.get("bot_mode_stats", {})
                _bot_insights = []
                for _bn, _bv in _bs.items():
                    if _bv.get("trades", 0) >= 3 and _bn not in ("none", "base"):
                        _bwr = _bv["wins"] / _bv["trades"] * 100
                        _bot_insights.append((_bn, _bwr, _bv["pnl"], _bv["trades"]))
                if _bot_insights:
                    _bot_insights.sort(key=lambda x: x[1], reverse=True)
                    for _bn, _bwr, _bpnl, _btr in _bot_insights[:3]:
                        log(f"💡 [brain v222] Бот {_bn}: WR={_bwr:.0f}% PnL={_bpnl:+.3f} ({_btr} сделок)")
                    applied["bot_analysis"] = {b[0]: {"wr": round(b[1], 1), "pnl": round(b[2], 4)}
                                               for b in _bot_insights[:3]}
            except Exception as _bae:
                log(f"⚠️ [brain bot_stats] {_bae}")

            # ── [FIX-v240-5] МЕДВЕЖИЙ РЫНОК → автопереключение в SAFE ──────────
            try:
                import os as _os240
                _ms5 = os.path.join(BASE_DIR, "market_state.json")
                if os.path.exists(_ms5) and (time.time() - os.path.getmtime(_ms5)) < 600:
                    with open(_ms5, 'r') as _f5: _state5 = json.load(_f5)
                    _btc5 = float(_state5.get("btc_1h_change", 0.0))
                    _sent5 = str(_state5.get("market_sentiment", "neutral"))
                    _blocked5 = bool(_state5.get("buy_blocked", False))
                    _bear5 = _btc5 < -2.5 or _sent5 == "bearish" or _blocked5

                    if _bear5 and CFG.TRADING_MODE in ("AGGRESSIVE", "SMART"):
                        _bear_trades = [t for t in trades[-5:] if t.get("outcome") == "loss"]
                        if len(_bear_trades) >= 2:
                            # 2+ убытков + медвежий рынок → переключаем в SAFE
                            # [FIX-v272] apply_mode_with_brain вместо apply_mode — не стираем learned_cfg
                            # [FIX-v297-BUG] Было: changes_text.append(...), но `changes_text` в этой
                            # точке функции ещё НЕ существует (она создаётся только внутри отдельной
                            # ветки `if TG.enabled:` намного ниже) → гарантированный NameError,
                            # проглатываемый except ниже. Записываем изменение туда же, куда и
                            # остальные переключения режима — в applied["mode_switch"], как в п.1/п.5.
                            _bear_from_mode = str(CFG.TRADING_MODE)
                            _kd_bear = getattr(self, '_data', None)
                            apply_mode_with_brain("SAFE", _kd_bear)
                            applied["mode_switch"] = (
                                _bear_from_mode, "SAFE",
                                f"медвежий рынок + {len(_bear_trades)} убытка (BTC 1H={_btc5:+.1f}%)"
                            )
                            log(f"📉 [v272] Медвежий рынок + убытки → SAFE режим (BTC={_btc5:+.1f}%)")
                            if TG.enabled:
                                TG.send(
                                    f"🛡️ <b>АВТОПЕРЕХОД В SAFE РЕЖИМ</b>\n"
                                    f"Причина: медвежий рынок + {len(_bear_trades)} убытка\n"
                                    f"BTC 1H: {_btc5:+.1f}%\n"
                                    f"Мозг снижает риски автоматически"
                                )
            except Exception as _bear5_ex:
                log(f"⚠️ [bear_safe] {_bear5_ex}")

            # ── 7. [v232-ADVISOR] Анализ точности советов ботов ──────────────
            # Ключевой раздел новой архитектуры: боты советуют → бот торгует →
            # при выходе сравниваем: совет "паника/avoid/bearish" был верен или нет?
            # Формула: совет "не входи" (score=-1) + сделка в УБЫТОК = совет ВЕРЕН
            #          совет "не входи" (score=-1) + сделка в ПРИБЫЛЬ = совет НЕВЕРЕН
            try:
                _advisory_stats = self._data.setdefault("advisory_accuracy", {})
                # Анализируем сделки с bot_advisory
                _adv_trades = [t for t in trades if t.get("bot_advisory")]
                if len(_adv_trades) >= 3:
                    # Для каждого бота-советника считаем точность
                    _bot_accuracy = {}
                    for _t in _adv_trades:
                        _adv = _t.get("bot_advisory", {})
                        _outcome = _t.get("outcome", "")
                        for _bot_key, _adv_data in _adv.items():
                            if not isinstance(_adv_data, dict): continue
                            _sig_score = int(_adv_data.get("score", 0))
                            if _sig_score == 0: continue
                            _is_profit = _outcome == "profit"
                            # Совет был верен если: score<0 и убыток ИЛИ score>0 и прибыль
                            _correct = (_sig_score < 0 and not _is_profit) or \
                                      (_sig_score > 0 and _is_profit)
                            _s = _bot_accuracy.setdefault(_bot_key, {"correct": 0, "total": 0})
                            _s["total"] += 1
                            if _correct: _s["correct"] += 1

                    # Обновляем advisory_stats и логируем
                    for _bot_key, _stat in _bot_accuracy.items():
                        if _stat["total"] >= 2:
                            _acc = _stat["correct"] / _stat["total"] * 100
                            _advisory_stats[_bot_key] = {
                                "accuracy": round(_acc, 1),
                                "correct": _stat["correct"],
                                "total": _stat["total"],
                            }
                            _verdict = "✅ полезен" if _acc >= 60 else "⚠️ нейтрален" if _acc >= 40 else "❌ мешает"
                            log(f"💡 [v232-ADVISOR] {_bot_key}: точность={_acc:.0f}% "
                                f"({_stat['correct']}/{_stat['total']}) {_verdict}")

                    if _advisory_stats:
                        applied["advisory_accuracy"] = {
                            k: v["accuracy"] for k,v in _advisory_stats.items()
                        }
                        # Боты с точностью < 30% — их советы мешают торговле
                        _harmful = [k for k,v in _advisory_stats.items() if v["accuracy"] < 30 and v["total"] >= 5]
                        if _harmful:
                            log(f"⚠️ [v232-ADVISOR] Боты с низкой точностью (<30%): {_harmful} "
                                f"— их советы НЕ соответствуют реальности рынка")
                            if TG.enabled:
                                TG.send_throttled('advisor_report',
                                    f"🧠 АНАЛИЗ СОВЕТНИКОВ\n"
                                    + "\n".join(f"  {'✅' if v['accuracy']>=60 else '⚠️' if v['accuracy']>=40 else '❌'} "
                                               f"{k}: {v['accuracy']:.0f}% ({v['correct']}/{v['total']})"
                                               for k,v in _advisory_stats.items() if v['total'] >= 2),
                                    cooldown_sec=3600)
            except Exception as _adv_ex:
                log(f"⚠️ [brain advisory] {_adv_ex}")

            if applied:
                # Сохраняем применённые изменения
                self._data.setdefault("learning_log", []).append({
                    "ts": datetime.now().isoformat(),
                    "changes": applied,
                    "trades_count": len(trades),
                })
                self._data["learning_log"] = self._data["learning_log"][-50:]
                # [FIX-v187-7b] Сохраняем learned_cfg — параметры переживут рестарт!
                self._data["learned_cfg"] = {
                    "SCANNER_ADX_MIN":            float(getattr(CFG,"SCANNER_ADX_MIN",25.0)),
                    "SCANNER_RSI_MAX":            float(getattr(CFG,"SCANNER_RSI_MAX",65.0)),
                    "SCANNER_RSI_MIN":            float(getattr(CFG,"SCANNER_RSI_MIN",35.0)),  # [FIX-v227-3] RSI_MIN сохраняется
                    "ADAPTIVE_SNIPER_TIER1_HOURS":float(getattr(CFG,"ADAPTIVE_SNIPER_TIER1_HOURS",2.0)),
                    "SCANNER_MIN_TURNOVER_SCAN":  float(getattr(CFG,"SCANNER_MIN_TURNOVER_SCAN",500000.0)),
                    "MIN_ORDERBOOK_DEPTH_USDT":   float(getattr(CFG,"MIN_ORDERBOOK_DEPTH_USDT",3000.0)),
                    "DEAD_MARKET_SCORE_THRESHOLD":float(getattr(CFG,"DEAD_MARKET_SCORE_THRESHOLD",0.5)),
                    # [FIX-v190b-3] Сохраняем MIN_24H_TURNOVER_USDT в памяти мозга
                    "MIN_24H_TURNOVER_USDT":      float(getattr(CFG,"MIN_24H_TURNOVER_USDT",5_000_000.0)),
                    "AUTO_TURNOVER_BASE":         float(getattr(CFG,"AUTO_TURNOVER_BASE",5_000_000.0)),
                    # [FIX-v190-FINAL] Все торговые параметры сохраняются в памяти мозга
                    "GRID_TP_MIN":               float(getattr(CFG,"GRID_TP_MIN",1.1)),
                    # [FIX-v247-1] Per-symbol и advisory данные — рестарт выживает
                    "symbol_stats":       dict(self._data.get("symbol_stats",{})),
                    "advisory_accuracy":  dict(self._data.get("advisory_accuracy",{})),
                    "STOP_LOSS_PCT":             float(getattr(CFG,"STOP_LOSS_PCT",1.2)),
                    "GRID_STEP_PCT":             float(getattr(CFG,"GRID_STEP_PCT",0.8)),
                    "ORDER_COUNT":               float(getattr(CFG,"ORDER_COUNT",2)),
                    "TIME_STOP_HOURS":           float(getattr(CFG,"TIME_STOP_HOURS",4.0)),
                    # [FIX-v258-1 + FIX-v259-1] Все 15 параметров мозга переживают рестарт
                    "SCANNER_ADX_MIN":           float(getattr(CFG,"SCANNER_ADX_MIN",20)),
                    "ADX_MIN":                   float(getattr(CFG,"ADX_MIN",20)),
                    "SCANNER_RSI_MIN":           float(getattr(CFG,"SCANNER_RSI_MIN",35)),
                    "SCANNER_RSI_MAX":           float(getattr(CFG,"SCANNER_RSI_MAX",65)),
                    "SCANNER_MIN_TURNOVER_SCAN": float(getattr(CFG,"SCANNER_MIN_TURNOVER_SCAN",150000)),
                    "MIN_24H_TURNOVER_USDT":     float(getattr(CFG,"MIN_24H_TURNOVER_USDT",5000000)),
                    "MIN_ORDERBOOK_DEPTH_USDT":  float(getattr(CFG,"MIN_ORDERBOOK_DEPTH_USDT",200)),
                    "AUTO_TURNOVER_BASE":        float(getattr(CFG,"AUTO_TURNOVER_BASE",150000)),
                    "ADAPTIVE_SNIPER_TIER1_HOURS": float(getattr(CFG,"ADAPTIVE_SNIPER_TIER1_HOURS",4.0)),
                    "DEAD_MARKET_SCORE_THRESHOLD": float(getattr(CFG,"DEAD_MARKET_SCORE_THRESHOLD",3.5)),
                    # [FIX-v259-2] Последние 2 из 15 параметров
                    "MIN_24H_TURNOVER_USDT":     float(getattr(CFG,"MIN_24H_TURNOVER_USDT",5000000)),
                    "ADAPTIVE_SNIPER_TIER1_HOURS": float(getattr(CFG,"ADAPTIVE_SNIPER_TIER1_HOURS",4.0)),
                    # [FIX-v260-1] _apply_loss_analysis тоже меняет MIN_SCORE_TO_ENTER
                    "MIN_SCORE_TO_ENTER":        float(getattr(CFG,"MIN_SCORE_TO_ENTER",4.5)),
                }
                self._save()
                # Отправляем в TG если есть значимые изменения
                if TG.enabled:
                    changes_text = []
                    if "adx" in applied:
                        changes_text.append(f"ADX {applied['adx'][0]:.0f}→{applied['adx'][1]:.0f}")
                    if "tier1_hours" in applied:
                        changes_text.append(f"Tier1 ожидание {applied['tier1_hours'][0]:.1f}→{applied['tier1_hours'][1]:.1f}ч")
                    if "rsi" in applied:
                        changes_text.append(f"RSI {applied['rsi'][0]:.0f}→{applied['rsi'][1]:.0f}")
                    if changes_text:
                        _n_trades = len(trades)
                        # [FIX-v226-5] Показываем уверенность мозга на основе числа сделок.
                        # При малой базе (< 20 сделок) изменения ненадёжны.
                        _confidence = "🔴 низкая" if _n_trades < 10 else \
                                      "🟡 средняя" if _n_trades < 30 else \
                                      "🟢 высокая"
                        # [FIX-v229-3] Добавляем ТОП-3 блокировщика в TG отчёт.
                        # Пользователь видит КОНКРЕТНО что мешало торговле.
                        _rj_now = self._data.get("reject_reasons", {})
                        _total_s = max(int(self._data.get("total_scans", 1)), 1)
                        _top_blocks = sorted(
                            [(k, v) for k,v in _rj_now.items() if v > 0],
                            key=lambda x: -x[1]
                        )[:3]
                        _block_text = ""
                        if _top_blocks:
                            _block_text = "\n📊 Топ блокировщиков:\n" + "\n".join(
                                f"  {k}: {v}×/скан ({v/_total_s*100:.0f}%)"
                                for k,v in _top_blocks
                            )
                        TG.send_throttled('brain_learning',
                            f"🧠 МОЗГ ПРИМЕНИЛ ЗНАНИЯ\n"
                            f"📊 База: {_n_trades} сделок | Уверенность: {_confidence}\n"
                            + "\n".join(f"• {c}" for c in changes_text)
                            + _block_text
                            + f"\n\n⚠️ Нужно {max(0, 30-_n_trades)} сделок до высокой уверенности",
                            cooldown_sec=3600)

            # [FIX-v190-5] Диагностика фильтров на основе reject_reasons
            try:
                _fh = self.get_filter_health()
                _fh_changes = []
                _rates = _fh.get("_rates", {})

                # Turnover слишком строгий → снижаем
                if _fh.get("turnover",("ok",""))[0] == "critical":
                    _cur_t = float(getattr(CFG,"SCANNER_MIN_TURNOVER_SCAN",500_000.0))
                    _new_t = max(100_000.0, _cur_t * 0.5)
                    if abs(_new_t-_cur_t)>10000:
                        CFG.SCANNER_MIN_TURNOVER_SCAN = _new_t
                        _fh_changes.append(f"Оборот {_cur_t/1e6:.1f}M→{_new_t/1e6:.1f}M (блокировал {_rates.get('turnover_per_scan',0):.0f}×/скан)")
                        applied["turnover_health"] = (_cur_t, _new_t)
                elif _fh.get("turnover",("ok",""))[0] == "warning":
                    _cur_t = float(getattr(CFG,"SCANNER_MIN_TURNOVER_SCAN",500_000.0))
                    _new_t = max(150_000.0, _cur_t * 0.7)
                    if abs(_new_t-_cur_t)>10000:
                        CFG.SCANNER_MIN_TURNOVER_SCAN = _new_t
                        _fh_changes.append(f"Оборот {_cur_t/1e6:.1f}M→{_new_t/1e6:.1f}M")
                        applied["turnover_health_soft"] = (_cur_t, _new_t)

                # ADX слишком строгий
                if _fh.get("adx",("ok",""))[0] == "warning":
                    _cur_adx = float(getattr(CFG,"SCANNER_ADX_MIN",20.0))
                    _new_adx = max(14.0, _cur_adx - 2.0)
                    # [FIX-v326-BUG] Не опускаем ниже "пола" от ИИ/мозга (см. FIX-v325-BUG,
                    # FIX-v326-BUG в _send_emergency_tg_report) — иначе это ослабление тут же
                    # стирает недавнее целенаправленное ужесточение после серии убытков.
                    _adx_floor_fh = float(getattr(CFG, '_ai_adx_floor', 0.0) or 0.0)
                    _adx_floor_fh_ts = float(getattr(CFG, '_ai_adx_floor_ts', 0.0) or 0.0)
                    if _adx_floor_fh > 0 and (time.time() - _adx_floor_fh_ts) < 24 * 3600:
                        _new_adx = max(_new_adx, _adx_floor_fh)
                    if abs(_new_adx-_cur_adx)>0.5:
                        CFG.SCANNER_ADX_MIN = _new_adx
                        _fh_changes.append(f"ADX {_cur_adx:.0f}→{_new_adx:.0f} (блокировал {_rates.get('adx_per_scan',0):.0f}×/скан)")
                        applied["adx_health"] = (_cur_adx, _new_adx)

                # [FIX-v227-2b] RSI_MIN слишком строгий
                if _fh.get("rsi_min",("ok",""))[0] in ("warning","critical"):
                    _cur_rmin = float(getattr(CFG,"SCANNER_RSI_MIN",35.0))
                    _reduce = 5.0 if _fh["rsi_min"][0] == "critical" else 3.0
                    _new_rmin = max(18.0, _cur_rmin - _reduce)
                    if abs(_new_rmin-_cur_rmin)>0.5:
                        CFG.SCANNER_RSI_MIN = _new_rmin
                        _fh_changes.append(f"RSI_MIN {_cur_rmin:.0f}→{_new_rmin:.0f} (блокировал {_rates.get('rsi_min_per_scan',0):.0f}×/скан)")
                        applied["rsi_min_health"] = (_cur_rmin, _new_rmin)
                        log(f"💡 [brain v227] RSI_MIN снижен: {_cur_rmin:.0f}→{_new_rmin:.0f}")

                # Depth слишком строгий
                if _fh.get("depth",("ok",""))[0] == "warning":
                    _cur_dep = float(getattr(CFG,"MIN_ORDERBOOK_DEPTH_USDT",3000.0))
                    _new_dep = max(600.0, _cur_dep * 0.75)
                    if abs(_new_dep-_cur_dep)>50:
                        CFG.MIN_ORDERBOOK_DEPTH_USDT = _new_dep
                        _fh_changes.append(f"Стакан {_cur_dep:.0f}→{_new_dep:.0f}")
                        applied["depth_health"] = (_cur_dep, _new_dep)

                # [FIX-v190-T24-LEVELS] MIN_24H_TURNOVER_USDT — 10 ступеней
                # Снижается при плохом WR / нет сделок
                # Повышается при хорошем WR / активный рынок (защита от входа на памп)
                # Ступени: 600K → 800K → 1M → 1.5M → 2M → 3M → 5M → 8M → 12M → 20M
                _T24_LEVELS = [600_000, 800_000, 1_000_000, 1_500_000, 2_000_000,
                               3_000_000, 5_000_000, 8_000_000, 12_000_000, 20_000_000]
                _cur_t24 = float(getattr(CFG,"MIN_24H_TURNOVER_USDT",5_000_000.0))
                _cur_t24_idx = min(range(len(_T24_LEVELS)),
                                   key=lambda i: abs(_T24_LEVELS[i]-_cur_t24))

                if len(trades) >= 3:
                    _wins_r = sum(1 for t in trades[-10:] if t.get("outcome")=="profit")
                    _wr_r   = _wins_r / min(len(trades),10)
                    _streak_t24 = int(getattr(self,'_zero_scan_streak',0)) if hasattr(self,'_zero_scan_streak') else 0

                    if _wr_r >= 0.65 and _cur_t24_idx < len(_T24_LEVELS)-1:
                        # WR хороший → повышаем порог (ищем более качественные монеты)
                        _new_t24 = _T24_LEVELS[_cur_t24_idx + 1]
                        if abs(_new_t24 - _cur_t24) > 50_000:
                            CFG.MIN_24H_TURNOVER_USDT = _new_t24
                            CFG.AUTO_TURNOVER_BASE    = _new_t24
                            _fh_changes.append(f"Объём24h↑ {_cur_t24/1e6:.1f}M→{_new_t24/1e6:.1f}M")
                            applied["turnover24h_health"] = (_cur_t24, _new_t24)
                            log(f"📊 [v190] T24↑ {_cur_t24/1e6:.1f}M→{_new_t24/1e6:.1f}M (WR={_wr_r:.0%})")
                    elif (_wr_r < 0.40 or len(trades) < 5 or _streak_t24 > 5) and _cur_t24_idx > 0:
                        # WR плохой или нет монет → снижаем
                        _new_t24 = _T24_LEVELS[_cur_t24_idx - 1]
                        if abs(_new_t24 - _cur_t24) > 50_000:
                            CFG.MIN_24H_TURNOVER_USDT = _new_t24
                            CFG.AUTO_TURNOVER_BASE    = _new_t24
                            _fh_changes.append(f"Объём24h↓ {_cur_t24/1e6:.1f}M→{_new_t24/1e6:.1f}M")
                            applied["turnover24h_health"] = (_cur_t24, _new_t24)
                            log(f"📊 [v190] T24↓ {_cur_t24/1e6:.1f}M→{_new_t24/1e6:.1f}M (WR={_wr_r:.0%})")

                if _fh_changes:
                    log(f"🔧 [v190] Фильтры по статистике: {' | '.join(_fh_changes)}")
                    if TG.enabled:
                        _tg_fh=(
                            "🔧 Мозг оптимизировал фильтры\n"
                            + "\n".join(f"• {c}" for c in _fh_changes)
                            + f"\nОснование: анализ {self._data.get('total_scans',0)} сканов"
                        )
                        TG.send(_tg_fh)
            except Exception as _fh_ex:
                log(f"⚠️ [filter_health_apply] {_fh_ex}")

            # [FIX-v190c-1] АВТО-УПРАВЛЕНИЕ GRID_STEP_PCT
            # Логика: если full_grid_early_stop срабатывает часто →
            # шаг сетки слишком маленький, монета уходит глубже чем мы рассчитываем
            try:
                _fg_exits=[t for t in trades if 'full_grid' in str(t.get("exit_reason",""))]
                _all_exits=len(trades)
                _fg_rate=len(_fg_exits)/_all_exits if _all_exits>0 else 0
                _cur_gs=float(getattr(CFG,"GRID_STEP_PCT",0.8))
                # [v294-C3] ИСПРАВЛЕНИЕ: wr не была определена до этой точки → UnboundLocalError в логе!
                # Вычисляем локально из trades чтобы не зависеть от внешней переменной
                wr = len([t for t in trades if t.get("outcome") == "profit"]) / max(1, len(trades)) * 100 if trades else 0.0

                if _fg_rate > 0.4 and _cur_gs < 1.2:
                    # >40% сделок = full_grid_stop → шаг слишком мал → увеличить
                    _new_gs=min(1.2, round(_cur_gs+0.1, 2))
                    CFG.GRID_STEP_PCT=_new_gs
                    applied["grid_step_up"]=(_cur_gs,_new_gs)
                    log(f"📐 [v190c] GRID_STEP {_cur_gs}%→{_new_gs}% (full_grid_rate={_fg_rate:.0%})")
                    if TG.enabled:
                        TG.send(
                            f"📐 Мозг увеличил шаг сетки\n"
                            f"{_cur_gs}% → {_new_gs}%\n"
                            f"Причина: {len(_fg_exits)}/{_all_exits} сделок = ранний стоп\n"
                            f"Новый шаг даст больше пространства при просадке"
                        )
                elif _fg_rate < 0.1 and _cur_gs > 0.6 and wr >= 60:
                    # <10% full_grid + WR хороший → можно сузить шаг
                    _new_gs=max(0.6, round(_cur_gs-0.1, 2))
                    CFG.GRID_STEP_PCT=_new_gs
                    applied["grid_step_down"]=(_cur_gs,_new_gs)
                    log(f"📐 [v190c] GRID_STEP {_cur_gs}%→{_new_gs}% (WR={wr:.0f}% хороший)")
            except Exception as _gs_ex:
                log(f"⚠️ [auto_grid_step] {_gs_ex}")

            # [FIX-v190c-2] АВТО-УПРАВЛЕНИЕ ORDER_COUNT по балансу
            # Больше ордеров = лучше усреднение, но нужен баланс
            try:
                _bal_now=float(getattr(self,"_last_usdt_bal",0.0) if hasattr(self,"_last_usdt_bal")
                               else 25.0)
                _cur_oc=int(getattr(CFG,"ORDER_COUNT",2))
                _new_oc=_cur_oc
                # [FIX-v279-2] ORDER_COUNT строго 2 — усреднение. Мозг НЕ меняет на 3.
                # Проблема: при балансе>50$ мозг ставил 3 ордера → ломал усреднение.
                _new_oc = 2
                _new_oc = min(2, int(_new_oc))  # [v283-4] HARD GUARD: ORDER_COUNT строго max=2
                if _new_oc!=_cur_oc:
                    CFG.ORDER_COUNT=min(2, int(_new_oc))  # [v288-C2] GUARD: было =_new_oc без ограничения. Мозг мог поставить 3+ ордеров!
                    applied["order_count"]=(_cur_oc,_new_oc)
                    log(f"📊 [v190c] ORDER_COUNT {_cur_oc}→{_new_oc} (баланс={_bal_now:.0f})")
                    if TG.enabled:
                        TG.send(
                            f"📊 Мозг изменил количество ордеров\n"
                            f"{_cur_oc} → {_new_oc} ордеров\n"
                            f"Баланс: {_bal_now:.2f} USDT"
                        )
            except Exception as _oc_ex:
                log(f"⚠️ [auto_order_count] {_oc_ex}")

            # [FIX-v190c-3] АВТО-УПРАВЛЕНИЕ TIME_STOP_HOURS
            # Мозг смотрит среднее время прибыльных сделок
            # TIME_STOP = avg_win_time × 2.5 (с запасом)
            try:
                _win_times=[float(t.get("duration_h",0)) for t in trades
                            if t.get("outcome")=="profit" and float(t.get("duration_h",0))>0]
                if len(_win_times)>=3:
                    _avg_win_h=sum(_win_times)/len(_win_times)
                    _ideal_stop=round(_avg_win_h*2.5, 1)
                    _ideal_stop=max(2.0, min(8.0, _ideal_stop))  # диапазон 2-8 часов
                    _cur_ts=float(getattr(CFG,"TIME_STOP_HOURS",4.0))
                    if abs(_ideal_stop-_cur_ts)>=0.5:
                        CFG.TIME_STOP_HOURS=_ideal_stop
                        applied["time_stop"]=(_cur_ts,_ideal_stop)
                        log(f"⏱️ [v190c] TIME_STOP {_cur_ts}h→{_ideal_stop}h (avg_win={_avg_win_h:.1f}h)")
                        if TG.enabled:
                            TG.send(
                                f"⏱️ Мозг изменил время стопа\n"
                                f"{_cur_ts}ч → {_ideal_stop}ч\n"
                                f"Среднее время прибыльных: {_avg_win_h:.1f}ч\n"
                                f"Формула: {_avg_win_h:.1f}ч × 2.5 = {_ideal_stop}ч"
                            )
            except Exception as _ts_ex:
                log(f"⚠️ [auto_time_stop] {_ts_ex}")

            # [FIX-v190-6] АВТО-УПРАВЛЕНИЕ TP/SL на основе статистики
            # Мозг анализирует: средний PnL прибыльных / средний убыток
            # → корректирует TP и SL для максимизации прибыли
            try:
                _profit_trades=[t for t in trades if t.get("outcome")=="profit" and float(t.get("pnl_pct",0))>0]
                _loss_trades=[t for t in trades if t.get("outcome")=="loss" and float(t.get("pnl_pct",0))<0]

                if len(_profit_trades)>=3:
                    _avg_win_pct=sum(float(t.get("pnl_pct",0)) for t in _profit_trades)/len(_profit_trades)
                    _cur_tp=float(getattr(CFG,"GRID_TP_MIN",1.1))

                    # Если средняя прибыль >> текущий TP → можно поднять TP
                    if _avg_win_pct > _cur_tp * 1.4 and _cur_tp < 1.8:
                        _new_tp=min(1.8, round(_cur_tp+0.1, 2))
                        CFG.GRID_TP_MIN=_new_tp
                        applied["tp_up"]=(_cur_tp,_new_tp)
                        log(f"📈 [v190] TP поднят {_cur_tp}%→{_new_tp}% (avg_win={_avg_win_pct:.2f}%)")
                        if TG.enabled:
                            TG.send(f"📈 Мозг поднял тейк-профит\n{_cur_tp}% → {_new_tp}%\nСредняя прибыль: {_avg_win_pct:.2f}%")

                if len(_loss_trades)>=3:
                    _avg_loss_pct=abs(sum(float(t.get("pnl_pct",0)) for t in _loss_trades)/len(_loss_trades))
                    _cur_sl=float(getattr(CFG,"STOP_LOSS_PCT",1.2))

                    # Если средний убыток > SL → стопы не срабатывают вовремя
                    if _avg_loss_pct > _cur_sl * 1.3 and _cur_sl > 0.8:
                        _new_sl=max(0.8, round(_cur_sl-0.1, 2))
                        CFG.STOP_LOSS_PCT=_new_sl
                        applied["sl_tighten"]=(_cur_sl,_new_sl)
                        log(f"🛡️ [v190] SL ужесточён {_cur_sl}%→{_new_sl}% (avg_loss={_avg_loss_pct:.2f}%)")
                        if TG.enabled:
                            TG.send(f"🛡️ Мозг ужесточил стоп-лосс\n{_cur_sl}% → {_new_sl}%\nСредний убыток был: {_avg_loss_pct:.2f}%")

                    # Если убытки маленькие → можно расслабить SL (больше пространства)
                    elif _avg_loss_pct < _cur_sl * 0.6 and _cur_sl < 1.5:
                        _new_sl=min(1.5, round(_cur_sl+0.1, 2))
                        # [v287-2] SL_MAX GUARD: SL не выше HARD_EXIT-0.05% (порядок DUMP<SL<HARD)
                        _sl_max = round(float(getattr(CFG,"HARD_EXIT_LOSS_PCT", 0.9)) - 0.05, 2)
                        _new_sl = min(_new_sl, _sl_max)  # [v287-2] строгий потолок
                        CFG.STOP_LOSS_PCT=_new_sl
                        applied["sl_relax"]=(_cur_sl,_new_sl)
                        log(f"🛡️ [v190] SL расслаблен {_cur_sl}%→{_new_sl}% (avg_loss мал={_avg_loss_pct:.2f}%)")
            except Exception as _tpsl_ex:
                log(f"⚠️ [auto_tp_sl] {_tpsl_ex}")

            # [FIX-v189-1] АВТО-ПЕРЕКЛЮЧЕНИЕ РЕЖИМА ТОРГОВЛИ
            # Мозг анализирует WR + ADX + внешние сигналы → выбирает режим
            try:
                # Читаем внешние сигналы
                _ms_path = os.path.join(BASE_DIR, "market_state.json")
                _btc_trend = "normal"
                if os.path.exists(_ms_path):
                    with open(_ms_path, 'r') as _fms: _ms = json.load(_fms)
                    _btc_trend = _ms.get("market_sentiment", "neutral")

                _fs_path = os.path.join(BASE_DIR, "funding_signals.json")
                _fund_sig = "normal"
                if os.path.exists(_fs_path):
                    with open(_fs_path, 'r') as _ffs: _fd = json.load(_ffs)
                    _fund_sig = _fd.get("global_signal", "normal")

                _vs_path = os.path.join(BASE_DIR, "volume_signals.json")
                _vol_count = 0
                if os.path.exists(_vs_path):
                    with open(_vs_path, 'r') as _fvs: _vd = json.load(_fvs)
                    _vol_count = len(_vd.get("anomalies", []))

                _cur_mode = str(getattr(CFG, "TRADING_MODE", "SMART"))
                _new_mode, _reason = self.get_recommended_mode(
                    current_mode=_cur_mode,
                    btc_trend=_btc_trend,
                    funding_signal=_fund_sig,
                    volume_anomalies=_vol_count,
                )

                if _new_mode != _cur_mode:
                    # Применяем новый режим
                    try:
                        apply_mode(_new_mode)
                        applied["mode_switch"] = (_cur_mode, _new_mode)
                        log(f"🔄 [brain] Режим: {_cur_mode} → {_new_mode} ({_reason})")
                        if TG.enabled:
                            trades_now = self._data.get("trades", [])
                            recent_wr = 0
                            if len(trades_now) >= 5:
                                recent = trades_now[-10:]
                                recent_wr = sum(1 for t in recent if t.get("outcome")=="profit") / len(recent) * 100
                            TG.send(
                                f"🔄 <b>МОЗГ СМЕНИЛ РЕЖИМ</b>\n"
                                f"{_cur_mode} → {_new_mode}\n"
                                f"Причина: {_reason}\n"
                                f"WR последних сделок: {recent_wr:.0f}%\n"
                                f"BTC тренд: {_btc_trend} | Фандинг: {_fund_sig}"
                            )
                    except Exception as _am_ex:
                        log(f"⚠️ [brain apply_mode] {_am_ex}")
                else:
                    log(f"🔄 [brain] Режим {_cur_mode} оптимален ({_reason})")
            except Exception as _asw_ex:
                log(f"⚠️ [brain auto_switch] {_asw_ex}")
            # ── [FIX-v185-3] РАСШИРЕННОЕ ОБУЧЕНИЕ v185 — на базе реальных данных ─
            # Мозг применяет конкретные выводы из истории торгов
            try:
                total_scans = max(int(self._data.get("total_scans", 1)), 1)
                rj = self._data.get("reject_reasons", {})

                # НОВОЕ: Tier 2 анализ — если WR Tier2 < 40% → увеличить ожидание
                # [FIX-v297-STAT] Было tier2_trades>=2 — тот же вывод, что и в разделе выше
                # (строка ~4337), которая сама себя поправила на ">=5, 2 слишком мало для
                # вывода" (FIX-v231-1), но этот дублирующий блок остался на старом пороге и
                # мог сработать ВТОРОЙ раз за один и тот же apply_learning() по 2 сделкам.
                # Синхронизировано с порогом >=5.
                tier2_st = self._data.get("filter_stats", {}).get("Tier_2", {})
                tier2_trades = int(tier2_st.get("trades", 0))
                tier2_wins = int(tier2_st.get("wins", 0))
                if tier2_trades >= 5 and tier2_wins / tier2_trades < 0.40:
                    cur_t1h = float(getattr(CFG, 'ADAPTIVE_SNIPER_TIER1_HOURS', 2.0))
                    new_t1h = min(cur_t1h + 0.5, 4.0)
                    if abs(new_t1h - cur_t1h) >= 0.4:
                        CFG.ADAPTIVE_SNIPER_TIER1_HOURS = new_t1h
                        applied["tier2_penalty"] = (cur_t1h, new_t1h)
                        log(f"💡 [brain v185] Tier2 WR={tier2_wins}/{tier2_trades} → Tier1 период {cur_t1h:.1f}→{new_t1h:.1f}ч")

                # НОВОЕ: Emergency synthetic trades (ADX=0) = всегда убыток
                # Если их много → ужесточить проверку перед усреднением
                emerg_trades=[t for t in trades if t.get("source")=="emergency_synthetic"]
                if len(emerg_trades) >= 2:
                    log(f"⚠️ [brain v185] {len(emerg_trades)} аварийных синтетических входов — мозг учится их избегать")
                    # [FIX-v229-1] ADX повышение не должно откатывать ослабление мозга.
                    # Если _filter_relaxed_by_brain=True → мозг специально снизил ADX до 10.
                    # Повышать его при 2 emergency trades некорректно — это уничтожает ослабление.
                    _is_relaxed = bool(getattr(CFG, '_filter_relaxed_by_brain', False))
                    if not _is_relaxed:
                        cur_adx = float(getattr(CFG, 'SCANNER_ADX_MIN', 23.0))
                        if cur_adx < 30.0:
                            CFG.SCANNER_ADX_MIN = min(cur_adx + 2.0, 30.0)
                            applied["adx_emergency"] = (cur_adx, CFG.SCANNER_ADX_MIN)
                            log(f"💡 [brain v185] ADX_MIN {cur_adx:.0f}→{CFG.SCANNER_ADX_MIN:.0f} (аварийные входы)")
                    else:
                        log(f"⚡ [v229-1] emergency ADX пропущен: ослабление мозга активно (streak режим)")

                # Оборот: если >60% отсевов из-за turnover → снижаем
                if rj.get("turnover", 0) / total_scans > 0.6:
                    cur_t = float(getattr(CFG, 'SCANNER_MIN_TURNOVER_SCAN', 500_000))
                    new_t = max(cur_t * 0.85, 200_000.0)
                    if abs(new_t - cur_t) > 50_000:
                        CFG.SCANNER_MIN_TURNOVER_SCAN = new_t
                        applied["turnover"] = (cur_t, new_t)
                        log(f"💡 [brain] Turnover {cur_t/1e6:.2f}M→{new_t/1e6:.2f}M")

                # Стакан: если >50% отсевов по depth → снижаем
                if rj.get("depth", 0) / total_scans > 0.5:
                    cur_d = float(getattr(CFG, 'MIN_ORDERBOOK_DEPTH_USDT', 3000))
                    new_d = max(cur_d * 0.8, 500.0)
                    if abs(new_d - cur_d) > 200:
                        CFG.MIN_ORDERBOOK_DEPTH_USDT = new_d
                        applied["depth"] = (cur_d, new_d)
                        log(f"💡 [brain] Stakan {cur_d:.0f}→{new_d:.0f} USDT")

                # RSI: убытки при высоком RSI → снижаем порог
                if "rsi" not in applied:
                    probs = self._data.get("problems", [])
                    hi_rsi = sum(1 for p in probs if float(p.get("rsi", 0)) > 68 and float(p.get("pnl_usdt", 0)) < -0.05)
                    if len(probs) >= 3 and hi_rsi / max(len(probs), 1) > 0.5:
                        cur_r = float(getattr(CFG, 'SCANNER_RSI_MAX', 68.0))
                        new_r = max(cur_r - 2.0, 60.0)
                        if abs(new_r - cur_r) >= 1.0:
                            CFG.SCANNER_RSI_MAX = new_r
                            applied["rsi"] = (cur_r, new_r)
                            log(f"💡 [brain] RSI {cur_r:.0f}→{new_r:.0f}")

                # Dead market: >40% блокировок → ослабляем
                if rj.get("dead_market", 0) / total_scans > 0.4:
                    cur_dm = float(getattr(CFG, 'DEAD_MARKET_SCORE_THRESHOLD', 0.5))
                    new_dm = max(cur_dm * 0.8, 0.1)
                    if abs(new_dm - cur_dm) > 0.05:
                        CFG.DEAD_MARKET_SCORE_THRESHOLD = new_dm
                        applied["dead_market"] = (cur_dm, new_dm)
                        log(f"💡 [brain] DeadMkt {cur_dm:.2f}→{new_dm:.2f}")

                # TG отчёт
                if applied and TG.enabled:
                    labels = {
                        "adx":         lambda v: f"ADX {v[0]:.0f}→{v[1]:.0f}",
                        "rsi":         lambda v: f"RSI {v[0]:.0f}→{v[1]:.0f}",
                        "tier1_hours": lambda v: f"Tier1 {v[0]:.1f}→{v[1]:.1f}ч",
                        "turnover":    lambda v: f"Turnover {v[0]/1e6:.2f}M→{v[1]/1e6:.2f}M",
                        "depth":       lambda v: f"Stakan {v[0]:.0f}→{v[1]:.0f}",
                        "dead_market": lambda v: f"DeadMkt {v[0]:.2f}→{v[1]:.2f}",
                        "bad_hours":   lambda v: f"Плохие часы: {v}",
                    }
                    lines_tg = []
                    for k, fn in labels.items():
                        if k in applied:
                            try: lines_tg.append(fn(applied[k]))
                            except Exception as _lbl_ex:  # [FIX-v179-1]
                                log(f"⚠️ [brain] label: {_lbl_ex}")
                    if lines_tg:
                        TG.send_throttled('brain_learning',
                            "🧠 МОЗГ ПРИМЕНИЛ ЗНАНИЯ\n" + "\n".join(f"• {c}" for c in lines_tg),
                            cooldown_sec=3600)
            except Exception as _ex3:
                log(f"⚠️ [brain] extended_learning: {_ex3}")
        except Exception as _le:
            log(f"⚠️ [brain] apply_learning: {_le}")
        return applied

    def get_smart_tp(self, adx: float, rsi: float, symbol: str = "") -> float:
        """[FIX-v184-2] Умный Take Profit на основе ADX, RSI и истории монеты.
        Мозг знает: при сильном тренде (ADX>50) и не перегретом RSI (<55) → держать дольше.
        При слабом тренде (ADX<35) или перегретом RSI (>65) → выходить быстрее.
        """
        try:
            base_tp = float(getattr(CFG, 'GRID_TP_MIN', 1.1))

            # Корректировка по ADX
            if adx >= 55:
                adx_mult = 1.35    # сильный тренд → TP выше на 35%
            elif adx >= 45:
                adx_mult = 1.20    # хороший тренд → TP выше на 20%
            elif adx >= 35:
                adx_mult = 1.10    # умеренный тренд → TP чуть выше
            elif adx >= 25:
                adx_mult = 1.00    # слабый тренд → базовый TP
            else:
                adx_mult = 0.90    # очень слабый → TP ниже, выходим быстрее

            # Корректировка по RSI
            if rsi <= 45:
                rsi_mult = 1.15    # перепродан → отскок будет сильным
            elif rsi <= 55:
                rsi_mult = 1.08    # нейтральный → небольшой буст
            elif rsi <= 65:
                rsi_mult = 1.00    # умеренный → без изменений
            elif rsi <= 72:
                rsi_mult = 0.90    # перекуплен → выходим раньше
            else:
                rsi_mult = 0.80    # сильно перекуплен → быстрый выход

            # История монеты: если монета раньше давала хороший TP
            sym_bonus = 1.0
            if symbol:
                sym_trades=[t for t in self._data.get("trades",[])
                            if t.get("symbol")==symbol and t.get("outcome")=="profit"]
                if len(sym_trades) >= 2:
                    avg_sym_pnl = sum(t.get("pnl_pct",0) for t in sym_trades) / len(sym_trades)
                    if avg_sym_pnl > 1.5:   sym_bonus = 1.10  # монета даёт хороший TP
                    elif avg_sym_pnl > 1.0: sym_bonus = 1.05

            smart_tp = base_tp * adx_mult * rsi_mult * sym_bonus
            # Ограничиваем диапазоном 0.8% — 2.5%
            smart_tp = max(0.8, min(2.5, smart_tp))
            return round(smart_tp, 3)
        except Exception as _stp_ex:
            log(f"⚠️ [brain smart_tp] {_stp_ex}")
            return float(getattr(CFG, 'GRID_TP_MIN', 1.1))

    def get_symbol_recovery_rate(self, symbol: str) -> float:
        """[FIX-v184-3] Процент восстановления монеты после просадки.
        Используется для решения: открывать ли усредняющий 3й ордер.
        """
        try:
            sym_trades=[t for t in self._data.get("trades",[]) if t.get("symbol")==symbol]
            if len(sym_trades) < 2:
                return 0.5  # нет данных → нейтральный 50%
            wins=sum(1 for t in sym_trades if t.get("outcome")=="profit")
            return wins / len(sym_trades)
        except Exception:
            return 0.5

    def is_good_hour_for_trading(self, hour: int) -> bool:
        """[FIX-v168-2] Проверяет исторически — хороший ли сейчас час для торговли?
        Используется в _get_adaptive_sniper_tier() для умного выбора Tier."""
        bad_hours = self._data.get("bad_hours", [])
        if not bad_hours:
            return True     # нет данных — считаем OK
        return hour not in bad_hours

    def get_tier_wr(self, tier: int) -> float:
        """[FIX-v168-2] Возвращает Win Rate для указанного Tier (0.0 если нет данных)."""
        key = f"Tier_{tier}"
        stats = self._data.get("filter_stats", {}).get(key, {})
        trades = stats.get("trades", 0)
        if trades < 3:
            return 50.0     # нет данных — нейтральный WR
        return stats["wins"] / trades * 100.0


    # ── SMC Bot интеграция (v172) ─────────────────────────────────────
    def get_filter_health(self) -> dict:
        """[FIX-v190-4] Диагностика здоровья фильтров на основе истории торгов.

        Анализирует reject_reasons из bot_knowledge.json:
        - Если 'оборот' блокирует >50% сканов → Turnover слишком высокий
        - Если 'ADX' блокирует >30% → ADX_MIN слишком высокий
        - Если 'depth' блокирует >30% → DEPTH слишком высокий
        Возвращает рекомендации по каждому фильтру.
        """
        try:
            rj = self._data.get("reject_reasons", {})
            total_scans = max(int(self._data.get("total_scans", 1)), 1)
            health = {}

            # Turnover — главный блокировщик (оборот)
            turn_blocks = int(rj.get("оборот", 0))
            turn_rate   = turn_blocks / total_scans
            if turn_rate > 50:   health["turnover"] = ("critical",  "снизить в 2×")
            elif turn_rate > 30: health["turnover"] = ("warning",   "снизить на 30%")
            elif turn_rate > 15: health["turnover"] = ("ok",        "нормально")
            else:                health["turnover"] = ("good",      "отлично")

            # ADX
            adx_blocks = int(rj.get("ADX", 0)) + int(rj.get("adx", 0))
            adx_rate   = adx_blocks / total_scans
            if adx_rate > 20:    health["adx"] = ("warning", "снизить ADX_MIN")
            else:                health["adx"] = ("ok",      "нормально")

            # [FIX-v227-2] RSI_MIN диагностика.
            # При медвежьем рынке RSI монет = 25-35, RSI_MIN=35 → весь рынок заблокирован.
            # Мозг раньше не видел этот блок. Теперь: если rsi<RSI_MIN блокирует >20% сканов → снижаем.
            rsi_min_blocks = int(rj.get("rsi", 0))  # "RSI=30<35" → tag="RSI" → key="rsi"
            rsi_min_rate = rsi_min_blocks / total_scans
            _cur_rsi_min = float(getattr(CFG, 'SCANNER_RSI_MIN', 35.0))
            if rsi_min_rate > 30:
                health["rsi_min"] = ("critical", f"RSI_MIN={_cur_rsi_min:.0f} блокирует {rsi_min_rate:.0f}×/скан → снизить")
            elif rsi_min_rate > 15:
                health["rsi_min"] = ("warning", f"RSI_MIN={_cur_rsi_min:.0f} снизить")
            else:
                health["rsi_min"] = ("ok", f"RSI_MIN={_cur_rsi_min:.0f} нормально")

            # Depth
            dep_blocks = int(rj.get("depth", 0))
            dep_rate   = dep_blocks / total_scans
            if dep_rate > 20:    health["depth"] = ("warning", "снизить DEPTH")
            else:                health["depth"] = ("ok",      "нормально")

            # [FIX-v226-6] Анализ EMA блоков — сколько раз EMA фильтр блокировал входы.
            # Эти данные показывают: нужен ли bypass (streak уже включил его при >=60).
            ema1h_blocks = int(rj.get("EMA1H↓", 0)) + int(rj.get("ema1h", 0)) + \
                           int(rj.get("нисходящий_тренд", 0)) + int(rj.get("EMA15m↓", 0))
            ema1h_rate = ema1h_blocks / total_scans
            if ema1h_rate > 30: health["ema1h"] = ("critical", f"EMA1H блокирует {ema1h_rate:.0f}×/скан")
            elif ema1h_rate > 10: health["ema1h"] = ("warning", f"EMA1H блокирует {ema1h_rate:.0f}×/скан")
            else: health["ema1h"] = ("ok", "нормально")

            # passes_trend (внутренние блоки)
            ptf_blocks = int(rj.get("15m_ema_cascade_prebuy", 0)) + \
                         int(rj.get("downtrend", 0))
            ptf_rate = ptf_blocks / total_scans
            if ptf_rate > 20: health["passes_trend"] = ("critical", f"тренд-фильтр {ptf_rate:.0f}×/скан")
            else: health["passes_trend"] = ("ok", "нормально")

            health["_rates"] = {
                "turnover_per_scan": round(turn_rate,1),
                "adx_per_scan":      round(adx_rate,1),
                "depth_per_scan":    round(dep_rate,1),
                "ema1h_per_scan":    round(ema1h_rate,1),
                "ptf_per_scan":      round(ptf_rate,1),
            }
            return health
        except Exception as _fh_ex:
            log(f"⚠️ [filter_health] {_fh_ex}")
            return {}

    def get_recommended_mode(self, current_mode: str,
                              btc_trend: str = "normal",
                              funding_signal: str = "normal",
                              volume_anomalies: int = 0) -> tuple:
        """[FIX-v189-1] Мозг рекомендует режим торговли на основе статистики.

        Анализирует:
        - WR последних 10 сделок
        - Средний ADX при прибыльных сделках
        - Плохие часы суток
        - Внешние сигналы: BTC тренд, фандинг, объём

        Возвращает: (режим, причина)
        """
        try:
            trades = self._data.get("trades", [])
            if len(trades) < 5:
                # Мало данных → SMART (умеренный риск)
                return "SMART", f"мало данных ({len(trades)}<5) → осторожный режим"

            # [FIX-v226-2] Минимум для смены режима — 15 сделок.
            # Проблема: при 5-10 сделках статистика ненадёжна.
            # 1 убыток из 3 = WR=33% → раньше сразу SAFE. Это неверно.
            # Математика: при n=10 сделках ±1σ WR = ±16%. При n=15 — ±13%.
            # При n<15: возвращаем текущий режим (без изменений).
            _min_for_switch = 15
            if len(trades) < _min_for_switch:
                return current_mode, f"накопление данных ({len(trades)}/{_min_for_switch}) → режим сохранён"

            # Берём последние 10 сделок (или меньше если нет)
            recent = trades[-10:]
            wins   = sum(1 for t in recent if t.get("outcome") == "profit")
            wr     = wins / len(recent) * 100
            avg_adx = sum(float(t.get("adx", 0)) for t in recent) / len(recent)
            avg_pnl = sum(float(t.get("pnl_usdt", 0)) for t in recent)

            # ADX прибыльных сделок
            profit_adx = [float(t.get("adx", 0)) for t in recent if t.get("outcome") == "profit"]
            avg_profit_adx = sum(profit_adx) / len(profit_adx) if profit_adx else 0

            # Текущий час
            hour = datetime.now().hour
            is_bad_hour = not self.is_good_hour_for_trading(hour)

            # ── Логика переключения ───────────────────────────────────────
            # AGGRESSIVE: рынок горячий, мы выигрываем
            if (wr >= 70 and avg_adx >= 45 and
                    not is_bad_hour and
                    funding_signal not in ("avoid", "caution") and
                    btc_trend != "bearish" and
                    volume_anomalies >= 3):
                return "AGGRESSIVE", (f"WR={wr:.0f}% ADX={avg_adx:.0f} "
                                      f"volume×{volume_anomalies} → горячий рынок")

            # SNIPER: хороший WR + сильный тренд
            if (wr >= 60 and avg_profit_adx >= 50 and
                    not is_bad_hour and
                    funding_signal not in ("avoid",) and
                    btc_trend not in ("bearish",)):
                return "SNIPER", (f"WR={wr:.0f}% profit_ADX={avg_profit_adx:.0f} "
                                  f"→ сильный тренд, точечный вход")

            # SAFE: плохая полоса, нужно остановить потери
            if (wr <= 30 or
                    (wr <= 40 and avg_pnl < -0.3) or
                    is_bad_hour or
                    funding_signal == "avoid" or
                    btc_trend == "bearish"):
                reasons = []
                if wr <= 30:         reasons.append(f"WR={wr:.0f}%")
                if is_bad_hour:      reasons.append(f"плохой час {hour}:00")
                if funding_signal == "avoid": reasons.append("фандинг перегрет")
                if btc_trend == "bearish":    reasons.append("BTC медведь")
                return "SAFE", "осторожно: " + ", ".join(reasons)

            # SMART: стандартный режим по умолчанию
            return "SMART", (f"WR={wr:.0f}% ADX={avg_adx:.0f} → "
                             f"умеренный режим")

        except Exception as _rm_ex:
            log(f"⚠️ [brain mode] {_rm_ex}")
            return current_mode, "ошибка анализа → режим сохранён"

    def get_smc_signal(self, symbol: str):
        """[FIX-v172-2] Читаем сигнал от SMC Bot из smc_signals.json.
        Возвращает dict сигнала если свежий и для нужной монеты, иначе None."""
        try:
            signals_file = os.path.join(BASE_DIR, "smc_signals.json")
            if not os.path.exists(signals_file):
                return None
            # Файл должен быть свежим (не старше 10 минут)
            if time.time() - os.path.getmtime(signals_file) > 600:
                return None
            with open(signals_file, "r", encoding="utf-8") as _f:
                data = json.load(_f)
            now = time.time()
            for sig in data.get("signals", []):
                if (sig.get("symbol") == symbol and
                        sig.get("valid_until", 0) > now):
                    return sig
        except Exception as _smc_ex:
            log(f"⚠️ [SMC reader] {_smc_ex}")
        return None

    def log_smc_context(self, symbol: str, smc_signal, trade_result=None):
        """[FIX-v172-2] Записываем контекст SMC сигнала в мозг.
        Второй слой обучения: мозг учится и на своих фильтрах и на SMC."""
        try:
            smc_log = self._data.setdefault("smc_log", [])
            entry = {
                "ts":          time.time(),
                "datetime":    datetime.now().isoformat(),  # [FIX-v321-BUG2] было datetime.datetime.now() — импорт "from datetime import datetime" делает datetime уже классом, не модулем; .datetime у него нет → AttributeError каждый раз, log_smc_context() падал в except и НИ РАЗУ не записывал контекст SMC-сигнала в мозг (подтверждено логом: "type object 'datetime.datetime' has no attribute 'datetime'")
                "symbol":      symbol,
                "had_signal":  smc_signal is not None,
                "smc_score":   smc_signal.get("score", 0) if smc_signal else 0,
                "structure":   smc_signal.get("structure_dir","?") if smc_signal else "?",
                "result":      trade_result,
            }
            smc_log.append(entry)
            self._data["smc_log"] = smc_log[-200:]
            if len(smc_log) >= 10:
                self._analyze_smc_patterns()
            self._save()
        except Exception as _e:
            log(f"⚠️ [smc_context] {_e}")

    def _analyze_smc_patterns(self):
        """[FIX-v172-2] Анализ: при каком SMC score WR лучший."""
        try:
            smc_log = self._data.get("smc_log", [])
            closed  = [e for e in smc_log if e.get("result") in ("profit","loss")]
            if len(closed) < 5:
                return
            score_stats = {}
            for e in closed:
                sc = str(e.get("smc_score", 0))
                st = score_stats.setdefault(sc, {"trades":0,"wins":0})
                st["trades"] += 1
                if e.get("result") == "profit":
                    st["wins"] += 1
            best_score = 0
            insights = ["[SMC] WR по score SMC бота:"]
            for sc, st in sorted(score_stats.items()):
                if st["trades"] >= 2:
                    wr = st["wins"]/st["trades"]*100
                    insights.append(f"  Score {sc}/5: WR={wr:.0f}% ({st['trades']} сделок)")
                    if wr >= 60:
                        best_score = max(best_score, int(sc))
            if best_score > 0:
                self._data["smc_best_score"] = best_score
                insights.append(f"  → Лучший порог: score≥{best_score}/5")
            self._data["smc_insights"] = insights
            for ins in insights: log(f"💡 {ins}")
        except Exception as _e:
            log(f"⚠️ [smc_analyze] {_e}")

    def log_manual_change(self, param: str, value, source: str = "TG"):
        self._data["manual_changes"].append({
            "ts": datetime.now().isoformat(),
            "param": param, "value": value, "source": source,
        })
        self._data["manual_changes"] = self._data["manual_changes"][-100:]
        self._save()

    def get_tg_report(self) -> str:
        trades = self._data["trades"]
        total = len(trades)
        # [FIX-v230-2] Добавлены: режим, фильтры, RSI_MIN, bad_hours, уверенность.
        # Ранее /knowledge не показывал текущее состояние фильтров и мозга.
        wins = sum(1 for t in trades if t["outcome"] == "profit")
        losses = sum(1 for t in trades if t["outcome"] == "loss")
        wr = wins / total * 100 if total > 0 else 0.0
        total_pnl = sum(t["pnl_usdt"] for t in trades)
        hs = self._data["hour_stats"]
        best_h = sorted(hs.items(), key=lambda x: x[1]["pnl"], reverse=True)[:3]
        last_ins = self._data["insights"][-1]["insights"] if self._data["insights"] else []
        probs = self._data["problems"][-3:]
        _bad_h = self._data.get("bad_hours", [])
        _lc = self._data.get("learned_cfg", {})
        _conf = "🔴 низкая" if total < 10 else "🟡 средняя" if total < 30 else "🟢 высокая"
        _adx = float(_lc.get("SCANNER_ADX_MIN", getattr(CFG, "SCANNER_ADX_MIN", 25.0)))
        _rsi_min = float(_lc.get("SCANNER_RSI_MIN", getattr(CFG, "SCANNER_RSI_MIN", 35.0)))
        _rsi_max = float(_lc.get("SCANNER_RSI_MAX", getattr(CFG, "SCANNER_RSI_MAX", 65.0)))
        _turn = float(getattr(CFG, "SCANNER_MIN_TURNOVER_SCAN", 500000.0))
        _relaxed = bool(getattr(CFG, "_filter_relaxed_by_brain", False))
        _mode = str(getattr(CFG, "TRADING_MODE", "SMART"))
        msg = (
            f"📚 БАЗА ЗНАНИЙ БОТА\n{'='*28}\n"
            f"🎯 Режим: {_mode} | {total} сделок | WR: {wr:.0f}%\n"
            f"Победы: {wins} ✅ | Убытки: {losses} ❌\n"
            f"Итого: {total_pnl:+.4f} USDT\n"
            f"Уверенность: {_conf}\n"
            f"{'─'*22}\n"
            f"📊 Активные фильтры (мозг):\n"
            f"  ADX_MIN: {_adx:.0f} | RSI: {_rsi_min:.0f}-{_rsi_max:.0f}\n"
            f"  Оборот скан: {_turn/1000:.0f}k\n"
            f"  Ослабление: {'✅ ДА' if _relaxed else '❌ нет'}\n"
            f"{'─'*22}\n"
        )
        if _bad_h:
            msg += f"🚫 Плохих часов: {sorted(_bad_h)}\n{'─'*22}\n"
        if total == 0:
            msg += "⚠️ База пуста. Нужны сделки для анализа."
            return msg
        if best_h:
            msg += "🕐 Лучшее время:\n"
            for h, s in best_h:
                msg += f"  {h}:00  WR={s['wins']}/{s['trades']} {s['pnl']:+.3f}\n"
        if last_ins:
            msg += "💡 Инсайты:\n"
            for ins in last_ins[:4]:
                msg += f"  {ins}\n"
        if probs:
            msg += "⚠️ Последние убытки:\n"
            for p in probs:
                msg += f"  {p['symbol']}: {p['pnl_usdt']:+.4f}\n  ↳ {p['analysis'][:50]}\n"
        msg += f"⚠️ Нужно {max(0,30-total)} сделок до высокой уверенности"
        return msg


class Engine:
    def __init__(self):
        # ── FIX #2: client создаётся здесь, а не на уровне модуля ──────
        global client
        api_placeholders = {"", "ВСТАВЬ_BYBIT_API_KEY_СЮДА", "YOUR_KEY_HERE", "ВСТАВЬ_СВОЙ_КЛЮЧ"}
        secret_placeholders = {"", "ВСТАВЬ_BYBIT_API_SECRET_СЮДА", "YOUR_SECRET_HERE", "ВСТАВЬ_СВОЙ_СЕКРЕТ"}
        if CFG.API_KEY in api_placeholders or CFG.API_SECRET in secret_placeholders:
            raise ValueError("Заполни реальные Bybit API_KEY/API_SECRET в Config перед запуском бота.")
        # [FIX-v160-2] Явный recv_window=20000ms даёт устойчивость к clock skew (по умолчанию 5000ms).
        # Если сервер немного отстаёт по NTP — запрос всё равно принимается биржей.
        client = HTTP(api_key=CFG.API_KEY, api_secret=CFG.API_SECRET, testnet=CFG.TESTNET, recv_window=20000)
        self.symbol: str = CFG.START_SYMBOL
        self.base: str = self._base_from_symbol(self.symbol)
        # Compatibility aliases (some helper blocks use these names)
        self.api = self
        self.tg = TG
        self.log = logging.getLogger('spotbot')
        if not self.log.handlers:
            _h = logging.StreamHandler()
            _h.setFormatter(logging.Formatter('%(asctime)s | %(levelname)s | %(message)s'))
            self.log.addHandler(_h)
            self.log.setLevel(logging.INFO)
        # Ensure minimal order size for Bybit
        if CFG.USDT_PER_ORDER < CFG.MIN_USDT_PER_ORDER:
            CFG.USDT_PER_ORDER = CFG.MIN_USDT_PER_ORDER
        self.filters: Optional[SymbolFilters] = None
        self.only_sell: bool = False
        self.downtrend_hits: int = 0
        self.dead_coin_hits: int = 0
        self._dead_coin_cache_val: bool = False     # [FIX-13A] кэш результата check_dead_coin
        self._dead_coin_cache_reason: str = ""     # [FIX-13A] кэш причины
        self._dead_coin_cache_ts: float = 0.0      # [FIX-13A] timestamp последней проверки
        self._dead_coin_block_since: float = 0.0   # [FIX-13B] когда началась dead_coin блокировка
        self._dc_force_switch_pending: bool = False # [FIX-13B] флаг принудительного переключения
        self.dead_market_hits: int = 0
        self.buy_blocked: bool = False
        self.buy_block_reasons: List[str] = []
        self.manual_only_sell: bool = False  # принудительный ONLY-SELL от команды
        # last scanner result (used by /scan + /resume /switch BEST)
        self.last_scan_best: Optional[str] = None
        self.last_scan_score: float = 0.0
        self.dump_cooldown_until: float = 0.0
        self._last_dump_candle_id: str = ""      # [FIX-v187-3] деdup DUMP 1H свечи
