    def _record_reject(self, tag: str, detail: str = "", symbol: Optional[str] = None):
        try:
            sym = str(symbol or self.symbol or "?")
            key = str(tag or "unknown").strip() or "unknown"
            self._reject_stats[key] += 1
            # [FIX-v300-BUG] Копим отдельно и в часовой счётчик (сбрасывается в
            # report_hourly_if_needed) — self._reject_stats выше по-прежнему копится за всю
            # сессию для No-trade diagnostics, это не трогаем.
            self._hour_reject_stats[key] += 1
            if sym not in self._reject_by_symbol:
                self._reject_by_symbol[sym] = Counter()
            self._reject_by_symbol[sym][key] += 1
            stamp = f"{int(time.time())}:{sym}:{key}"
            self._reject_recent[stamp] = detail or key
            while len(self._reject_recent) > 120:
                self._reject_recent.popitem(last=False)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_record_reject] {_sw_ex}')
    def _top_reject_summary(self, per_symbol: bool = False) -> str:
        try:
            src = self._reject_by_symbol.get(self.symbol, Counter()) if per_symbol else self._reject_stats
            if not src:
                return "нет"
            top_n = int(getattr(CFG, 'REJECT_SUMMARY_TOP_N', 5) or 5)
            return " | ".join(f"{k}:{v}" for k, v in src.most_common(top_n))
        except Exception:
            return "нет"
    def _top_reject_summary_hourly(self) -> str:
        """[FIX-v300-BUG] Версия _top_reject_summary() для часового отчёта: читает
        self._hour_reject_stats (сбрасывается каждый час), а не self._reject_stats
        (копится за всю сессию) — иначе "Часовой отчёт" много часов подряд показывал
        одни и те же цифры, накопленные когда-то раньше."""
        try:
            src = self._hour_reject_stats
            if not src:
                return "нет"
            top_n = int(getattr(CFG, 'REJECT_SUMMARY_TOP_N', 5) or 5)
            return " | ".join(f"{k}:{v}" for k, v in src.most_common(top_n))
        except Exception:
            return "нет"
    def _register_grid_reject(self, reason: str, symbol: Optional[str] = None):
        sym = str(symbol or self.symbol or "?")
        self._last_grid_skip_reason = str(reason or "")
        self._record_reject('grid_skip', reason, sym)
        self._record_reject(f"grid::{(reason or 'unknown').split(':')[0]}", reason, sym)
        cnt = int(self._grid_reject_streak_by_symbol.get(sym, 0) or 0) + 1
        self._grid_reject_streak_by_symbol[sym] = cnt
        if cnt >= int(getattr(CFG, 'GRID_REJECT_COOLDOWN_AFTER_N', 4) or 4):
            self._symbol_grid_cooldown_until[sym] = time.time() + float(getattr(CFG, 'SYMBOL_REJECT_COOLDOWN_SEC', 20 * 60) or 1200)
            self._record_reject('symbol_cooldown', f'{sym} cooldown after grid rejects={cnt}', sym)
    def _clear_grid_reject_streak(self, symbol: Optional[str] = None):
        sym = str(symbol or self.symbol or "?")
        self._grid_reject_streak_by_symbol[sym] = 0
    def _symbol_cooldown_left(self, symbol: Optional[str] = None) -> int:
        sym = str(symbol or self.symbol or "?")
        until = float(self._symbol_grid_cooldown_until.get(sym, 0.0) or 0.0)
        return max(0, int(until - time.time()))
    def _market_mode_name(self) -> str:
        try:
            if now := float(getattr(self, 'dump_cooldown_until', 0.0) or 0.0):
                if time.time() < now:
                    return 'DUMP_PAUSE'
            if time.time() < float(getattr(self, 'whipsaw_block_until', 0.0) or 0.0):
                return 'WHIPSAW'
            if time.time() < float(getattr(self, 'low_volume_until', 0.0) or 0.0):
                return 'LOW_VOLUME'
            if getattr(self, 'buy_blocked', False):
                return 'WAIT'
            profile = str(getattr(self, 'market_profile', 'NORMAL') or 'NORMAL')
            # market_profile can only be NORMAL or SCALP; map to mode names used in EMA/spread logic
            if profile == 'SCALP':
                return 'SCALP'
            # IMPULSE is detected dynamically from is_strong_impulse()
            try:
                if self.is_strong_impulse():
                    return 'IMPULSE'
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                pass  # intentionally silent: {_sw_ex}
            return 'NORMAL'
        except Exception:
            return 'NORMAL'
    def _effective_max_price_above_ema_pct(self) -> float:
        relax = 0.15 * float(getattr(self, '_no_trade_relax_step', 0) or 0)
        mode = self._market_mode_name()
        if mode == 'SCALP':
            base = float(getattr(CFG, 'EMA_DIST_SCALP_MAX_PCT', 0.55) or 0.55)
        elif mode == 'IMPULSE':
            base = float(getattr(CFG, 'EMA_DIST_IMPULSE_MAX_PCT', 1.20) or 1.20)
        elif mode == 'NORMAL':
            base = float(getattr(CFG, 'EMA_DIST_NORMAL_MAX_PCT', 0.85) or 0.85)
        else:
            base = float(getattr(CFG, 'MAX_PRICE_ABOVE_EMA_FAST_PCT', 0.35) or 0.35)
        base = max(base, float(getattr(CFG, 'MAX_PRICE_ABOVE_EMA_FAST_PCT', base) or base)) + relax
        return round(base * float(self._activity_profile().get('ema_mult', 1.0) or 1.0), 4)
    def _effective_max_spread_pct(self) -> float:
        relax = 0.05 * float(getattr(self, '_no_trade_relax_step', 0) or 0)
        mode = self._market_mode_name()
        if mode == 'SCALP':
            base = float(getattr(CFG, 'MAX_SPREAD_PCT_SCALP', 0.25) or 0.25)
        elif mode == 'IMPULSE':
            base = float(getattr(CFG, 'MAX_SPREAD_PCT_IMPULSE', 0.45) or 0.45)
        else:
            base = float(getattr(CFG, 'MAX_SPREAD_PCT_NORMAL', 0.35) or 0.35)
        base = max(base, float(getattr(CFG, 'MAX_SPREAD_PCT', base) or base)) + relax
        return round(base * float(self._activity_profile().get('spread_mult', 1.0) or 1.0), 4)
    def _apply_no_trade_relaxation(self):
        try:
            mins = float(getattr(CFG, 'NO_TRADE_RELAX_AFTER_MIN', 45) or 45)
            steps_max = int(getattr(CFG, 'NO_TRADE_RELAX_MAX_STEPS', 2) or 2)
            delta_min = (time.time() - float(getattr(self, '_last_trade_ts', time.time()) or time.time())) / 60.0
            step = int(delta_min // max(mins, 1.0))
            self._no_trade_relax_step = max(0, min(step, steps_max))
        except Exception:
            self._no_trade_relax_step = 0
    def _no_trade_diagnostic(self) -> str:
        reasons = self._top_reject_summary(per_symbol=False)
        market_mode = self._market_mode_name()
        if getattr(self, 'buy_blocked', False):
            core = 'filters too strict' if reasons not in ('', 'нет') else 'market truly bad'
        else:
            core = 'filters too strict' if reasons not in ('', 'нет') else 'market unclear'
        if getattr(self, '_idle_scan_reject_streak', 0) >= int(getattr(CFG, 'IDLE_SCAN_ROTATE_AFTER_REJECTS', 3) or 3):
            core += ' | idle-switch bias active'
        return f"{core} | market={market_mode} | rejects={reasons}"
    def _set_stage(self, stage: str, **meta):
        try:
            self._stage = str(stage or 'UNKNOWN')
            self._stage_meta = {k: v for k, v in (meta or {}).items() if v not in (None, '', [])}
            self._stage_ts = time.time()
            if hasattr(self, '_hour_stage_counts'):
                self._hour_stage_counts[self._stage] += 1
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_set_stage] {_sw_ex}')  # [FIX-v151-1]
    def _fmt_stage(self) -> str:
        try:
            meta = getattr(self, '_stage_meta', {}) or {}
            if not meta:
                return str(getattr(self, '_stage', 'UNKNOWN'))
            tail = ", ".join(f"{k}={v}" for k, v in list(meta.items())[:4])
            return f"{getattr(self, '_stage', 'UNKNOWN')} ({tail})"
        except Exception:
            return str(getattr(self, '_stage', 'UNKNOWN'))
    def _activity_profile(self) -> Dict[str, Any]:
        p = getattr(CFG, '_TRADE_ACTIVITY_PROFILE', None)
        if isinstance(p, dict) and p:
            return p
        apply_trade_activity_mode(getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced'))
        return getattr(CFG, '_TRADE_ACTIVITY_PROFILE', {}) or {}
    # [FIX-BUG17] _get_activity_profile удалён — мёртвый alias,
    # нигде не вызывался. Используй self._activity_profile() напрямую.
    def _entry_threshold(self) -> float:
        mode = str(getattr(CFG, "TRADE_ACTIVITY_MODE", "balanced")).lower()
        if mode == "conservative":
            return float(getattr(CFG, "ENTRY_THRESHOLD_CONSERVATIVE", 5.0) or 5.0)
        if mode == "active":
            return float(getattr(CFG, "ENTRY_THRESHOLD_ACTIVE", 2.5) or 2.5)
        return float(getattr(CFG, "ENTRY_THRESHOLD_BALANCED", 3.5) or 3.5)
    def _score_decision(self, base_score: float, penalties: Dict[str, float], bonuses: Dict[str, float], hard_block: str = "") -> Tuple[bool, str, float, float, str]:
        threshold = float(self._entry_threshold())
        total = float(base_score) + sum(float(v) for v in bonuses.values()) - sum(float(v) for v in penalties.values())
        if hard_block:
            return False, hard_block, round(total, 3), threshold, hard_block
        main_penalty = ''
        if penalties:
            main_penalty = max(penalties.items(), key=lambda kv: float(kv[1]))[0]
        main_bonus = ''
        if bonuses:
            main_bonus = max(bonuses.items(), key=lambda kv: float(kv[1]))[0]
        if total >= threshold:
            return True, f"entry score ok: {total:.2f}>={threshold:.2f}", round(total, 3), threshold, (main_bonus or 'score_ok')
        return False, f"entry score low: {total:.2f}<{threshold:.2f}", round(total, 3), threshold, (main_penalty or 'score_low')
    def _slog(self, title: str, **kv):
        try:
            if not bool(getattr(CFG, 'STRUCTURED_LOGS_ENABLE', True)):
                return
            title_s = str(title or '').upper()
            reason = kv.pop('reason', '')
            code_error = kv.pop('code_error', '')
            market_reject = kv.pop('market_reject', '')
            ordered = {}
            if reason:
                ordered['reason'] = reason
            if code_error:
                ordered['code_error'] = code_error
            if market_reject:
                ordered['market_reject'] = market_reject
            for k, v in kv.items():
                if v not in (None, '', []):
                    ordered[k] = v
            payload = ' | '.join(f"{k}={v}" for k, v in ordered.items())
            log(f"📌 {title_s}" + (f" | {payload}" if payload else ''))
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_slog] {_sw_ex}')  # [FIX-v151-1]
    def _note_grid_attempt(self, built: bool, reason: str = ""):
        try:
            self._hour_grid_attempts += 1
            if built:
                self._hour_grid_built += 1
            else:
                self._hour_grid_skipped += 1
                if reason:
                    self._record_reject('grid_skip_structured', reason)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_note_grid_attempt] {_sw_ex}')
    def _candidate_tradeability_score(self, d: Dict[str, Any]) -> float:
        try:
            c = d.get('checks', {}) or {}
            m = d.get('metrics', {}) or {}
            score = 0.0
            if c.get('ema15m', (False,))[0]: score += 1.3
            if c.get('ema1h', (False,))[0]: score += 0.9
            if c.get('vol', (False,))[0]: score += 1.1
            if c.get('pullback', (False,))[0]: score += 1.2
            if c.get('adx', (False,))[0]: score += 0.8
            if c.get('rsi', (False,))[0]: score += 0.5
            pb = float(d.get('pullback', 0.0) or 0.0)
            if 0.08 <= pb <= 1.60:
                score += 0.8
            elif pb > 4.5:
                score -= 0.6
            pump2h = float(d.get('pump2h', 0.0) or 0.0)
            if pump2h > 7.5: score -= 0.8
            elif pump2h > 4.5: score -= 0.3
            regime = str(m.get('regime', '') or '').lower()
            mode = str(getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced')).lower()
            if regime == 'impulse':
                score += 0.45
                if mode == 'active': score += 0.25
            elif regime == 'flat':
                score -= 0.35
                if mode == 'conservative': score -= 0.25
            if float(m.get('spread_pct', 0.0) or 0.0) > float(getattr(CFG, 'SCANNER_MAX_SPREAD_SCAN_PCT', 0.5) or 0.5) * 0.8:
                score -= 0.4
            return round(max(0.0, score), 4)
        except Exception:
            return 0.0
    def _simulate_entry_decision(self, symbol: str, price_hint: float = 0.0) -> Tuple[bool, str]:
        cur_sym, cur_base, cur_filters = self.symbol, self.base, self.filters
        try:
            if not bool(getattr(CFG, 'DIAG_SIMULATE_ENTRIES', True)):
                return True, 'disabled'
            now_ts = time.time()
            if (now_ts - float(getattr(self, '_diag_sim_hour_ts', now_ts) or now_ts)) >= 3600:
                self._diag_sim_hour_ts = now_ts
                self._hour_simulated_entries = 0
            max_per_hour = int(getattr(CFG, 'DIAG_SIMULATE_MAX_PER_HOUR', 20) or 20)
            if self._hour_simulated_entries >= max_per_hour:
                return False, 'simulate limit reached'
            self.symbol = symbol
            self.base = self._base_from_symbol(symbol)
            self.filters = self.get_filters() or cur_filters
            ok, reason = self.prebuy_entry_guard(buy_price=float(price_hint or 0.0) or None)
            self._hour_simulated_entries += 1
            return bool(ok), str(reason)
        except Exception as e:
            return False, f'sim_error: {e}'
        finally:
            self.symbol, self.base, self.filters = cur_sym, cur_base, cur_filters
    def _turnover_ladder(self) -> List[float]:
        """Adaptive turnover thresholds used by scanner / buy checks."""
        vals = [
            float(getattr(CFG, "AUTO_TURNOVER_BASE", CFG.MIN_24H_TURNOVER_USDT) or CFG.MIN_24H_TURNOVER_USDT),
            float(getattr(CFG, "AUTO_TURNOVER_STEP_1", CFG.MIN_24H_TURNOVER_USDT) or CFG.MIN_24H_TURNOVER_USDT),
            float(getattr(CFG, "AUTO_TURNOVER_STEP_2", CFG.MIN_24H_TURNOVER_USDT) or CFG.MIN_24H_TURNOVER_USDT),
            float(getattr(CFG, "AUTO_TURNOVER_STEP_3", CFG.MIN_24H_TURNOVER_USDT) or CFG.MIN_24H_TURNOVER_USDT),
        ]
        floor_min = float(getattr(CFG, "AUTO_TURNOVER_MIN", min(vals)) or min(vals))
        cleaned: List[float] = []
        for v in vals:
            vv = max(float(v), floor_min)
            if vv not in cleaned:
                cleaned.append(vv)
        cleaned.sort(reverse=True)
        return cleaned
    def _current_turnover_floor(self) -> float:
        if not bool(getattr(CFG, "AUTO_TURNOVER_ENABLE", True)):
            return float(CFG.MIN_24H_TURNOVER_USDT)
        # [FIX-v221-1] КРИТИЧНО: кэш _active_turnover_floor не синхронизировался с CFG.
        # Проблема: мозг снижает CFG.MIN_24H_TURNOVER_USDT (5M→2M), но сканер использовал
        # _active_turnover_floor из кэша (5M) → 0 монет из 120 при каждом скане.
        # _active_turnover_floor обновлялся только если found>0 — замкнутый круг.
        # Исправление: берём min(кэш, CFG) → принимаем наименьший (ослабленный) порог.
        cfg_floor = float(getattr(CFG, "AUTO_TURNOVER_BASE",
                          getattr(CFG, "MIN_24H_TURNOVER_USDT", 5_000_000.0)) or 5_000_000.0)
        cur = float(getattr(self, "_active_turnover_floor", 0.0) or 0.0)
        if cur > 0:
            # Синхронизируем: если мозг снизил CFG — принимаем новое меньшее значение
            synced = min(cur, cfg_floor)
            if synced < cur:
                self._active_turnover_floor = synced
            return synced
        return cfg_floor
    def _load_state(self):
        try:
            if not os.path.exists(STATE_FILE):
                return
            with open(STATE_FILE, 'r', encoding='utf-8') as f:
                st = json.load(f) or {}
            if st.get('day') != today_ymd():
                return
            self._daily_soft_applied = bool(st.get('daily_soft_applied', False))
            self._daily_hard_locked = bool(st.get('daily_hard_locked', False))
            self._daily_start_equity = float(st.get('daily_start_equity')) if st.get('daily_start_equity') is not None else None
            self._equity_now_cache = float(st.get('equity_now_cache', 0.0) or 0.0)
            self._equity_today_cache = float(st.get('equity_today_cache', 0.0) or 0.0)
            self._daily_soft_pause_until = float(st.get('daily_soft_pause_until', 0.0) or 0.0)
            self._daily_hard_pause_until = float(st.get('daily_hard_pause_until', 0.0) or 0.0)
            self._daily_stop_trigger_equity = float(st.get('daily_stop_trigger_equity', 0.0) or 0.0)
            # [FIX-v144-D3] Восстанавливаем dump cooldown при рестарте
            _saved_dump_cd = float(st.get('dump_cooldown_until', 0.0) or 0.0)
            if _saved_dump_cd > time.time():
                self.dump_cooldown_until = _saved_dump_cd
                log(f"⚠️ [FIX-v144-D3] dump_cooldown восстановлен: ещё {(_saved_dump_cd-time.time())/60:.1f} мин")
            # if SAFE/LOCK was reached earlier today, don't allow new BUY after restart
            if self._daily_hard_locked:
                self.only_sell = True
                self.paused = False
            elif self._daily_soft_applied:
                self.paused = True
        except Exception as e:
            log(f"⚠️ state load failed: {e}")

    def _save_state(self):
        try:
            st = {
                'day': today_ymd(),
                'daily_soft_applied': bool(self._daily_soft_applied),
                'daily_hard_locked': bool(self._daily_hard_locked),
                'daily_start_equity': self._daily_start_equity,
                'equity_now_cache': self._equity_now_cache,
                'equity_today_cache': self._equity_today_cache,
                'daily_soft_pause_until': self._daily_soft_pause_until,
                'daily_hard_pause_until': self._daily_hard_pause_until,
                'daily_stop_trigger_equity': self._daily_stop_trigger_equity,
                # [FIX-v144-D3] Сохраняем dump cooldown чтобы пережить рестарт
                'dump_cooldown_until': float(getattr(self, 'dump_cooldown_until', 0.0) or 0.0),
            }
            tmp_path = STATE_FILE + '.tmp'
            with open(tmp_path, 'w', encoding='utf-8') as f:
                json.dump(st, f, ensure_ascii=False)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, STATE_FILE)
        except Exception as e:
            log(f"⚠️ state save failed: {e}")
    # ---------- DAILY LOCK ----------
    def _recalc_equity(self, force: bool = False) -> float:
        """Пересчитать equity (USDT + base*price). Дёшево и стабильно для одного активного символа."""
        try:
            usdt = float(self.get_usdt_balance())
        except Exception:
            usdt = 0.0
        try:
            base_qty = float(self.get_base_balance())
        except Exception:
            base_qty = 0.0
        try:
            px = float(self.get_last_price(self.symbol) or 0.0)  # [FIX-v254-3]
        except Exception:
            px = 0.0
        equity_now = usdt + (base_qty * px if px > 0 else 0.0)
        # [FIX-v272-BUG5] ДЕТЕКТОР ПОПОЛНЕНИЯ — депозиты не считаются прибылью
        try:
            _prev_eq = float(getattr(self, '_equity_now_cache', equity_now) or equity_now)
            _in_pos = float(base_qty or 0.0) > 0.001
            _jump = equity_now - _prev_eq
            # Если не в позиции и баланс прыгнул > 5 USDT → это пополнение/конвертация
            if not _in_pos and _jump > 5.0 and self._daily_start_equity is not None:
                self._daily_start_equity = float(self._daily_start_equity) + _jump
                log(f"💰 [v272-deposit] Пополнение/конвертация +{_jump:.4f} USDT → baseline скорректирован")
                if TG.enabled:
                    TG.send(f"💰 Пополнение ~{_jump:.2f} USDT обнаружено. PnL не изменился.")
        except Exception as _dep_ex:
            log(f"⚠️ [deposit_detect] {_dep_ex}")
        self._equity_now_cache = float(equity_now)
        # если старт дня ещё не задан — задаём автоматически
        if self._daily_start_equity is None:
            self._daily_start_equity = float(equity_now)
        self._equity_today_cache = float(equity_now - float(self._daily_start_equity or 0.0))
        return float(equity_now)
    def _apply_daily_soft(self, text: str):
        if self._daily_soft_applied:
            return
        self._daily_soft_applied = True
        self._daily_mode_before = CFG.TRADING_MODE
        self.paused = True
        self._daily_soft_pause_until = time.time() + max(0, int(getattr(CFG, "DAILY_SOFT_PAUSE_MIN", 45))) * 60
        try:
            apply_mode("SAFE")
            CFG.TRADING_MODE = "SAFE"
        except Exception as e:
            log(f"⚠️ Daily SAFE mode apply error: {e}")
        self._save_state()
        if TG.enabled:
            mins = int(max(0, self._daily_soft_pause_until - time.time()) // 60)
            TG.send(f"🟦 Daily SAFE: {text}\nBUY пауза примерно на {mins} мин. После восстановления BUY снимется автоматически.")
    def _apply_daily_hard(self, text: str):
        if self._daily_hard_locked:
            return
        self._daily_hard_locked = True
        self.only_sell = True
        self.paused = False
        self._daily_hard_pause_until = time.time() + max(0, int(getattr(CFG, "DAILY_HARD_PAUSE_MIN", 45))) * 60
        self._daily_stop_trigger_equity = float(getattr(self, "_equity_today_cache", 0.0) or 0.0)
        try:
            self.cancel_all_open_orders()
        except Exception as e:
            log(f"⚠️ Daily STOP cancel_all_open_orders error: {e}")
        self._save_state()
        if TG.enabled:
            mins = int(max(0, self._daily_hard_pause_until - time.time()) // 60)
            TG.send(f"🛑 Daily STOP: {text}\nONLY-SELL примерно на {mins} мин. После восстановления BUY снимется автоматически.")
    def _daily_release_if_recovered(self):
        if not bool(getattr(CFG, "ENABLE_DAILY_LOCK", True)):
            return
        now_ts = time.time()
        eq_today = float(getattr(self, "_equity_today_cache", 0.0) or 0.0)
        realized_today = float(getattr(self.pnl, "day_realized", 0.0) or 0.0)
        if self._daily_soft_applied and self.paused and now_ts >= float(getattr(self, "_daily_soft_pause_until", 0.0) or 0.0):
            soft_release_eq = float(getattr(CFG, "DAILY_SOFT_RELEASE_EQ_USDT", 0.0))
            if realized_today >= soft_release_eq:  # [FIX-v265-1] от сделок, не equity
                self._daily_soft_applied = False
                self.paused = False
                self._daily_soft_pause_until = 0.0
                try:
                    # [FIX-v272-BUG7] сохраняем learned_cfg при снятии SAFE блока
                    _kd2 = getattr(getattr(self, 'knowledge', None), '_data', None)
                    apply_mode_with_brain(self._daily_mode_before, _kd2)
                except Exception as e:
                    log(f"⚠️ Daily SAFE release mode restore error: {e}")
                self._save_state()
                if TG.enabled:
                    TG.send(f"🟢 Daily SAFE снят: equity today {eq_today:+.4f} USDT восстановился.")
        if self._daily_hard_locked and now_ts >= float(getattr(self, "_daily_hard_pause_until", 0.0) or 0.0):
            hard_release_eq = float(getattr(CFG, "DAILY_HARD_RELEASE_EQ_USDT", 0.0))
            hard_release_realized = float(getattr(CFG, "DAILY_HARD_RELEASE_REALIZED_USDT", -0.15))
            if (not self.manual_only_sell) and self.pos.base_qty <= 0 and eq_today >= hard_release_eq and realized_today >= hard_release_realized:
                self._daily_hard_locked = False
                self.only_sell = False
                self._daily_hard_pause_until = 0.0
                self._daily_stop_trigger_equity = 0.0
                try:
                    # [FIX-v272-BUG7] сохраняем learned_cfg при снятии HARD блока
                    _kd3 = getattr(getattr(self, 'knowledge', None), '_data', None)
                    apply_mode_with_brain(self._daily_mode_before, _kd3)
                except Exception as e:
                    log(f"⚠️ Daily HARD release mode restore error: {e}")
                self._save_state()
                if TG.enabled:
                    TG.send(f"🟢 Daily STOP снят: equity today {eq_today:+.4f} USDT, realized today {realized_today:+.4f} USDT. BUY снова разрешены.")
    def _daily_equity_check(self):
        """Умный дневной контроль: триггерим защиту по equity, но подтверждаем realized/unrealized и снимаем блок после восстановления."""
        if not bool(getattr(CFG, "ENABLE_DAILY_LOCK", True)):
            return
        self._recalc_equity()
        self._daily_release_if_recovered()
        soft = float(getattr(CFG, "DAILY_SOFT_TARGET_USDT", 1.50))
        hard = float(getattr(CFG, "DAILY_HARD_TARGET_USDT", 3.00))
        stop_loss = float(getattr(CFG, "DAILY_STOP_LOSS_USDT", 3.0))
        eq_today = float(self._equity_today_cache)
        realized_today = float(getattr(self.pnl, "day_realized", 0.0) or 0.0)
        unreal_now = float(self._unrealized_now())
        stop_realized_confirm = -abs(stop_loss) * float(getattr(CFG, "DAILY_STOP_REALIZED_CONFIRM_RATIO", 0.20))
        stop_unreal_confirm = -abs(stop_loss) * float(getattr(CFG, "DAILY_STOP_UNREAL_CONFIRM_RATIO", 0.35))
        smart_stop = bool(getattr(CFG, "DAILY_SMART_STOP", True))
        stop_confirmed = (not smart_stop) or (realized_today <= stop_realized_confirm) or (unreal_now <= stop_unreal_confirm)
        # [FIX-v127-4] Добавлен счётчик подтверждения equity drop (3 итерации подряд).
        # Проблема: при 2с CHECK_DELAY и временном падении цены на 5% за 1 итерацию
        # equity_today падала ниже порога → daily_hard_stop срабатывал мгновенно,
        # хотя реальных убытков не было (цена восстанавливается за следующую итерацию).
        # Теперь: hard_stop требует 3 последовательных итерации с equity ниже порога.
        # Это добавляет ~6с задержки — достаточно для фильтрации шумовых дипов,
        # но не влияет на реальные убыточные ситуации.
        if (not self._daily_hard_locked) and (eq_today <= -abs(stop_loss)) and stop_confirmed:
            _eq_drop_hits = int(getattr(self, '_equity_drop_confirm_hits', 0)) + 1
            self._equity_drop_confirm_hits = _eq_drop_hits
            if _eq_drop_hits >= 3:  # 3 итерации подряд = ~6с подтверждение
                self._equity_drop_confirm_hits = 0
                self._apply_daily_hard(
                    f"Equity today {eq_today:+.4f} USDT ≤ -{abs(stop_loss):.2f}. "
                    f"Confirm: realized {realized_today:+.4f}, unrealized {unreal_now:+.4f}. "
                    f"(подтверждено 3 итерации)"
                )
                return
            # Ещё не подтверждено — не блокируем
        else:
            # Equity нормальная — сбрасываем счётчик
            self._equity_drop_confirm_hits = 0
        if (not self._daily_soft_applied) and (realized_today >= soft):
            self._apply_daily_soft(f"Прибыль за день {realized_today:+.4f} USDT ≥ {soft:.2f} (от сделок).")
        # [FIX-v38-10] Проверяем _daily_hard_locked ПОСЛЕ возможного вызова _apply_daily_soft выше.
        # Раньше: если eq_today >= hard сразу — оба блока выполнялись подряд за один тик:
        # _apply_daily_soft (режим SAFE) → _apply_daily_hard (режим ONLY-SELL) = двойное переключение.
        # Теперь: если soft уже применился → выходим, hard сработает на следующей итерации.
        if self._daily_soft_applied and not self._daily_hard_locked and realized_today < hard:
            return  # soft только что применился, ждём следующего тика для hard-проверки
        if (not self._daily_hard_locked) and (realized_today >= hard):
            # [FIX-v264-1] Дневная цель прибыли — ТОЛЬКО от закрытых сделок, не от пополнений/конвертаций
            self._apply_daily_hard(f"Прибыль за день {realized_today:+.4f} USDT ≥ {hard:.2f} (от сделок).")
            return
    def _daily_reset_if_needed(self):
        if not bool(getattr(CFG, "ENABLE_DAILY_LOCK", True)):
            return
        today = datetime.now(self._tz).date()
        if today != self._daily_date:
            self._daily_date = today
            self._daily_net_usdt = 0.0
            self._daily_soft_applied = False
            self._daily_hard_locked = False
            self._daily_soft_pause_until = 0.0
            self._daily_hard_pause_until = 0.0
            self._daily_stop_trigger_equity = 0.0
            self._symbol_round_trades = {}
            self._symbol_round_profit_trades = {}
            # [FIX-v144-P1] Сброс суточных PnL счётчиков при смене дня.
            # Ранее сбрасывались только в report_daily_if_needed (23:00).
            # Если бот работает через полночь — day_* содержали данные за несколько дней.
            try:
                self.pnl.day_realized = 0.0
                self.pnl.day_gross = 0.0
                self.pnl.day_fees = 0.0
                self.pnl.day_fee_buy = 0.0
                self.pnl.day_fee_sell = 0.0
                self.pnl.day_trades = 0
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [_daily_reset_if_needed] {_sw_ex}')  # [FIX-v151-1]
            # [FIX-10] Не сбрасываем only_sell если есть открытая позиция или manual режим
            # Но ВАЖНО: если был _daily_hard_locked → only_sell был True из-за него → сбрасываем
            if not self.manual_only_sell and self.pos.base_qty <= 0:
                self.only_sell = False
            self.paused = False
            # [FIX-v93-7] Сброс consecutive_losses при новом дне
            # Без этого: 2 убытка в конце дня → утром первый же убыток → смена монеты
            self._consecutive_losses = 0
            self._profit_streak = 0
            # [FIX-v128-2] Сброс счётчика подтверждения equity drop при смене дня.
            # Без этого: счётчик из конца предыдущего дня (1-2 попадания) переходит
            # на следующий день и ускоряет срабатывание daily_hard_stop утром.
            self._equity_drop_confirm_hits = 0
            # пересчитать equity и зафиксировать старт дня
            try:
                eq = self._recalc_equity(force=True)
                self._daily_start_equity = float(eq)
                self._equity_today_cache = 0.0
            except Exception:
                self._daily_start_equity = None
            try:
                # [FIX-v272-BUG7] apply_mode_with_brain — восстанавливает learned_cfg поверх дефолтов
                _kd = getattr(getattr(self, 'knowledge', None), '_data', None)
                apply_mode_with_brain(self._daily_mode_before, _kd)
            except Exception as _sw_ex:
                log(f'⚠️ [_daily_reset_if_needed] {_sw_ex}')
            # [v288-H5] AUTO_BALANCE_CAP: обновляем BALANCE_CAP из реального баланса раз в сутки
            # Проблема v287: BALANCE_CAP=25$ при реальном балансе $500 → торгуем на 3% (мизер!)
            if bool(getattr(CFG, 'AUTO_BALANCE_CAP', True)):
                try:
                    _auto_bal = self.get_usdt_balance()
                    if _auto_bal and float(_auto_bal) > 5.0:
                        _new_cap = round(float(_auto_bal) * 0.95, 2)  # 95% баланса как CAP
                        CFG.BALANCE_CAP_USDT = _new_cap
                        log(f"💰 [v288-H5] AUTO_BALANCE_CAP обновлён: {_new_cap:.2f}$ (баланс={_auto_bal:.2f}$)")
                except Exception as _abc_ex:
                    log(f"⚠️ [v288-H5] AUTO_BALANCE_CAP: {_abc_ex}")
            self._save_state()
            if TG.enabled:
                TG.send(f"🗓 Новый день ({self._daily_date}). Старт equity={self._daily_start_equity or 0.0:.4f} USDT. Лимиты сброшены. Режим: {CFG.TRADING_MODE}.")
    def _daily_on_sell(self, net_usdt: float):
        # оставляем локальный счётчик сделок только как справочную метрику
        if not bool(getattr(CFG, "ENABLE_DAILY_LOCK", True)):
            return
        self._daily_net_usdt += float(net_usdt or 0.0)
        # daily lock теперь считает по equity, поэтому здесь не блокируем
        self._save_state()
    def daily_status_text(self) -> str:
        if not bool(getattr(CFG, "ENABLE_DAILY_LOCK", True)):
            return "Daily lock: OFF"
        soft = float(getattr(CFG, "DAILY_SOFT_TARGET_USDT", 1.50))
        hard = float(getattr(CFG, "DAILY_HARD_TARGET_USDT", 3.00))
        sl = float(getattr(CFG, "DAILY_STOP_LOSS_USDT", 3.0))
        eq_today = float(getattr(self, "_equity_today_cache", 0.0) or 0.0)
        start_eq = float(getattr(self, "_daily_start_equity", 0.0) or 0.0)
        eq_now = float(getattr(self, "_equity_now_cache", 0.0) or 0.0)
        soft_left = max(0, int((float(getattr(self, "_daily_soft_pause_until", 0.0) or 0.0) - time.time()) // 60))
        hard_left = max(0, int((float(getattr(self, "_daily_hard_pause_until", 0.0) or 0.0) - time.time()) // 60))
        return (
            f"📅 Day {self._daily_date}\n"
            f"Equity: {eq_now:.4f} | Start: {start_eq:.4f} | Today: {eq_today:+.4f} USDT\n"
            f"Targets: +{soft:.2f}→SAFE(pause BUY) | +{hard:.2f}→ONLY-SELL | SL: -{abs(sl):.2f}→ONLY-SELL\n"
            f"Flags: soft={('YES' if self._daily_soft_applied else 'NO')}({soft_left}m) | hard={('YES' if self._daily_hard_locked else 'NO')}({hard_left}m)\n"
            f"Deals net (info): {self._daily_net_usdt:+.4f} USDT"
        )
    def _init_trades_csv(self):
        """[FIX-v144-P3] Создаёт CSV файл с заголовком если нет, ротирует если слишком большой."""
        try:
            csv_path = _cfg_path(CFG.TRADES_CSV)
            # Проверяем размер файла и ротируем если > MAX_CSV_SIZE_MB
            _max_mb = float(getattr(CFG, 'MAX_CSV_SIZE_MB', 5.0))
            if os.path.exists(csv_path) and _max_mb > 0:
                _size_mb = os.path.getsize(csv_path) / (1024 * 1024)
                if _size_mb >= _max_mb:
                    _archive = csv_path.replace('.csv', f'_{today_ymd()}.csv')
                    try:
                        os.rename(csv_path, _archive)
                        log(f"📦 [FIX-v144-P3] CSV ротация: {csv_path} → {_archive} ({_size_mb:.1f}MB)")
                        if TG.enabled:
                            TG.send_throttled('csv_rotated',
                                f"📦 CSV лог сделок заархивирован ({_size_mb:.1f}MB).\nНовый: {CFG.TRADES_CSV}",
                                cooldown_sec=86400)
                    except Exception as _re:
                        log(f"⚠️ CSV rotation error: {_re}")
            if not os.path.exists(csv_path):
                with open(csv_path, "w", newline="", encoding="utf-8") as f:
                    w = csv.writer(f)
                    w.writerow(["timestamp", "symbol", "side", "qty", "price", "gross", "fee", "net", "note"])
        except Exception as e:
            log(f"⚠️ CSV init error: {e}")
    def _csv_log(self, side: str, qty: float, price: float, gross: float, fee: float, net: float, note: str):
        try:
            with open(_cfg_path(CFG.TRADES_CSV), "a", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow([ts_str(), self.symbol, side, f"{qty:.10f}", f"{price:.10f}",
                            f"{gross:.6f}", f"{fee:.6f}", f"{net:.6f}", note])
        except Exception as e:
            log(f"⚠️ CSV write error: {e}")
    # ---------- Basics ----------
    @staticmethod
    def _base_from_symbol(sym: str) -> str:
        return sym.replace("USDT", "") if sym.endswith("USDT") else sym
    def auth_check_or_exit(self):
        try:
            call_with_retry(client.get_wallet_balance, accountType="UNIFIED", coin="USDT")
            call_with_retry(client.get_open_orders, category="spot", symbol=self.symbol)
        except Exception as e:
            log(f"🛑 AUTH ERROR: проверь API ключи/права. Детали: {e}")
            TG.send(f"🛑 AUTH ERROR: проверь API ключи/права.\n{e}")
            raise SystemExit(1)
    # ---------- Market / Filters ----------
    def bootstrap_position_from_wallet(self) -> bool:
        """If there is an existing spot position (non-USDT) in wallet, attach to it and switch to ONLY-SELL.
        This prevents 'forgotten position' after restart. Blacklisted symbols are allowed ONLY for selling out.
        """
        try:
            data = call_with_retry(client.get_wallet_balance, accountType="UNIFIED")
            lst = (data or {}).get("result", {}).get("list", []) or []
            if not lst:
                return False
            coins = lst[0].get("coin", []) or []
        except Exception:
            return False
        # find largest non-USDT holding by USDT value
        best_sym = None
        best_val = 0.0
        best_qty = 0.0
        # [FIX-25E] Минимум для bootstrap = DUST_USDT_THRESHOLD
        # Если остаток < порога пыли — не уходим в ONLY-SELL
        min_pos = float(getattr(CFG, "BOOTSTRAP_MIN_POS_USDT",
                                float(getattr(CFG, 'DUST_USDT_THRESHOLD', 3.5))))
        for c in coins:
            coin = (c.get("coin") or "").upper()
            if not coin or coin == "USDT":
                continue
            qty = float(c.get("walletBalance") or 0.0)
            if qty <= 0:
                continue
            sym = f"{coin}USDT"
            # [FIX-v140-1] Пропускаем фиат-валюты ДО API вызова — иначе EUR → EURUSDT →
            # ErrCode 10001 × 6 retry = 20 секунд потери при каждом старте.
            _FIAT_SKIP = {"EUR","GBP","USD","JPY","CNY","KRW","AED","RUB","BRL","CHF",
                          "SGD","HKD","MXN","CAD","AUD","NOK","SEK","INR","TRY","ZAR"}
            # [FIX-v152-2] Стейблкоины — добавляем явно. Они всегда около $1.00 →
            # нет движения → фильтры дадут случайные сигналы → убыточные сделки.
            _STABLE_SKIP = {"USDC","TUSD","BUSD","DAI","FDUSD","USDD","USDP","GUSD",
                            "SUSD","FRAX","LUSD","USDB","CELO","HUSD","CUSD","XIDR"}
            if coin in _FIAT_SKIP or coin in _STABLE_SKIP:
                log(f"[v140] bootstrap: пропускаем фиат/стейбл {coin}")
                continue
            # [FIX-v140-3] Проверяем VALID_SYMBOL_CACHE — если пара не существует на Bybit,
            # не тратим API retry на её запрос.
            if self._valid_symbol_cache_loaded and self._valid_symbol_cache:
                if sym not in self._valid_symbol_cache:
                    log(f"[v140] bootstrap: {sym} не в VALID_SYMBOL_CACHE — пропускаем")
                    continue
            # get price
            try:
                t = call_with_retry(client.get_tickers, category="spot", symbol=sym)
                tlist = (t or {}).get("result", {}).get("list", []) or []
                if not tlist:
                    continue
                last = float((tlist[0] or {}).get("lastPrice") or 0.0)
                if last <= 0:
                    continue
                val = qty * last
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [bootstrap_position_from_wallet] {_sw_ex}')
            if val > best_val:
                best_val = val
                best_sym = sym
                best_qty = qty
        if best_sym and best_val >= min_pos:
            self.symbol = best_sym
            self.base = self._base_from_symbol(best_sym)
            self.pos.base_qty = best_qty
            # [FIX-14A] Восстанавливаем entry_price из истории ордеров
            restored_entry = None
            try:
                hist = call_with_retry(client.get_order_history,
                                       category='spot', symbol=best_sym, limit=50)
                orders = (hist or {}).get('result', {}).get('list', []) or []
                # Ищем последние исполненные BUY ордера
                buy_fills = [
                    o for o in orders
                    if str(o.get('side','')).lower() == 'buy'
                    and str(o.get('orderStatus','')).lower() in ('filled','partialfilled')
                    and float(o.get('avgPrice') or 0.0) > 0
                ]
                if buy_fills:
                    # [FIX-v251-1] Средневзвешенная цена — только СВЕЖИЕ ордера (< 30 дней)
                    # И проверяем что цена близка к текущей (ratio 0.1x - 10x)
                    total_cost = 0.0
                    total_qty_filled = 0.0
                    _stale_skip = 0
                    import time as _t251
                    _now_ms = int(_t251.time() * 1000)
                    for o in buy_fills[:5]:  # последние 5 BUY
                        avg_p = float(o.get('avgPrice') or 0.0)
                        qty_f = float(o.get('cumExecQty') or o.get('qty') or 0.0)
                        # [FIX-v251-1] Фильтр по возрасту ордера (30 дней)
                        order_ts = int(o.get('createdTime') or o.get('updatedTime') or 0)
                        age_days = (_now_ms - order_ts) / 86400000 if order_ts > 0 else 999
                        # [FIX-v251-1] Фильтр по разумности цены vs текущая
                        price_ratio = avg_p / last if (avg_p > 0 and last > 0) else 999
                        if age_days > 30:
                            _stale_skip += 1
                            log(f"⚠️ [FIX-v251] BUY ордер {age_days:.0f} дней назад @ {avg_p:.6f} — пропускаем (слишком старый)")
                            continue
                        if price_ratio > 3.0 or price_ratio < 0.33:
                            _stale_skip += 1
                            log(f"⚠️ [FIX-v251] BUY ордер @ {avg_p:.6f} vs цена {last:.6f} (ratio={price_ratio:.2f}) — пропускаем (несоответствие)")
                            continue
                        if avg_p > 0 and qty_f > 0:
                            total_cost += avg_p * qty_f
                            total_qty_filled += qty_f
                    if total_qty_filled > 0:
                        restored_entry = total_cost / total_qty_filled
                        self.pos.entry_price = restored_entry
                        self.pos.entry_cost = restored_entry * best_qty
                        log(f"🧩 BOOTSTRAP: entry_price восстановлен = {restored_entry:.6f} (из {len(buy_fills[:5])-_stale_skip} BUY, пропущено {_stale_skip} старых/нерелевантных)")
                    else:
                        # [FIX-v251-1] Все ордера устарели или нерелевантны → используем текущую цену
                        restored_entry = last
                        self.pos.entry_price = last
                        self.pos.entry_cost = last * best_qty
                        log(f"🧩 BOOTSTRAP: entry_price = текущая цена {last:.6f} (не нашли валидных BUY ордеров)")
            except Exception as _be:
                log(f"⚠️ BOOTSTRAP: не удалось восстановить entry_price: {_be}")
            # [FIX-v251-3] Отменяем все старые ордера при bootstrap
            # Это предотвращает зависание старых SELL ордеров от прошлых сессий
            try:
                log(f"🧹 [FIX-v251-3] Bootstrap: отменяем все ордера {self.symbol} перед восстановлением")
                self.cancel_all_open_orders()
            except Exception as _can_ex:
                log(f"⚠️ [FIX-v251-3] cancel при bootstrap: {_can_ex}")
            # attach and go ONLY-SELL
            self.only_sell = True
            self.manual_only_sell = True
            # [FIX-v144-R2] Устанавливаем entry_time_ms при bootstrap.
            # Без этого time_stop никогда не сработает после рестарта:
            # условие `self.pos.entry_time_ms is not None` не выполняется → вечное удержание.
            if self.pos.entry_time_ms is None:
                self.pos.entry_time_ms = now_ms()
                log("🧩 BOOTSTRAP: entry_time_ms установлен = now (для time_stop защиты)")
            _entry_info = f' | entry~={restored_entry:.6f}' if restored_entry else ' | entry=неизвестен'
            log(f"🧩 BOOTSTRAP: found existing position {best_sym} value≈{best_val:.2f} USDT, qty={best_qty:.8f}{_entry_info}. ONLY-SELL enabled.")
            if TG.enabled:
                TG.send(
                    "🧩 BOOTSTRAP ПОЗИЦИИ\n"
                    f"Найдена позиция в кошельке: {best_sym}\n"
                    f"Оценка: ~{best_val:.2f} USDT\n"
                    + (f"Ср.цена входа~: {restored_entry:.6f}\n" if restored_entry else "Цена входа: неизвестна (рестарт)\n")
                    + "Режим: ONLY-SELL (покупки запрещены) до полного выхода."
                )
            return True
        return False
    def get_filters(self) -> SymbolFilters:
        data = call_with_retry(client.get_instruments_info, category="spot", symbol=self.symbol)
        lst = data.get("result", {}).get("list", []) or []
        if not lst:
            raise RuntimeError(f"instruments-info пусто для {self.symbol}")
        info = lst[0]
        price_filter = info.get("priceFilter", {}) or {}
        lot_filter = info.get("lotSizeFilter", {}) or {}
        tick_size = float(price_filter.get("tickSize") or 0.00001)
        if lot_filter.get("qtyStep") is not None:
            qty_step = float(lot_filter.get("qtyStep"))
        elif lot_filter.get("basePrecision") is not None:
            # Bybit иногда возвращает basePrecision как количество знаков (например 6),
            # а иногда как шаг (например "0.000001"). Поддерживаем оба варианта.
            bp_raw = lot_filter.get("basePrecision")
            try:
                bp_f = float(bp_raw)
                if 0 < bp_f < 1:
                    qty_step = bp_f
                else:
                    bp_i = int(float(bp_raw))
                    qty_step = float(Decimal("1") / (Decimal("10") ** bp_i))
            except Exception:
                qty_step = 0.01
        elif lot_filter.get("minOrderQty") is not None:
            qty_step = float(lot_filter.get("minOrderQty"))
        else:
            qty_step = 0.01
        min_qty = float(lot_filter.get("minOrderQty") or 0)
        min_amt = float(lot_filter.get("minOrderAmt") or 0)
        return SymbolFilters(tick_size=tick_size, qty_step=qty_step, min_qty=min_qty, min_amt=min_amt)
    def get_price(self) -> float:
        # Используем get_ticker() с TTL-кэшем (уменьшает нагрузку на API)
        t = self.get_ticker()
        try:
            return float(t.get("lastPrice") or 0.0)
        except Exception:
            return 0.0
    def get_ticker(self, symbol: Optional[str] = None) -> Dict:
        """Get ticker for symbol.
        Для текущего символа используем лёгкий кэш (TTL=1с) чтобы не бомбить API.
        Для других символов кэш не применяем.
        """
        sym = symbol or self.symbol
        now = time.time()
        if sym == self.symbol:
            try:
                if (now - float(getattr(self, "_ticker_cache_ts", 0.0)) < 1.0) and isinstance(getattr(self, "_ticker_cache", None), dict):
                    return dict(self._ticker_cache)
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [get_ticker] {_sw_ex}')  # [FIX-v152-3]
        data = call_with_retry(client.get_tickers, category="spot", symbol=sym)
        lst = data.get("result", {}).get("list", []) or []
        t = lst[0] if lst else {}
        if sym == self.symbol:
            self._ticker_cache = dict(t) if isinstance(t, dict) else {}
            self._ticker_cache_ts = now
        return t
    def _get_best_bid(self) -> float:
        """Return best bid price using orderbook, fallback to ticker."""
        try:
            ob = call_with_retry(client.get_orderbook, category="spot", symbol=self.symbol, limit=1)
            bids = (ob.get("result", {}) or {}).get("b", []) or []
            if bids:
                return float(bids[0][0])
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_get_best_bid] {_sw_ex}')
        try:
            t = self.get_ticker()
            return float(t.get("bid1Price") or t.get("lastPrice") or 0.0)
        except Exception:
            return 0.0
    def _get_base_free_locked_qty(self) -> float:
        """Get current base coin qty (free+locked) from wallet for self.symbol."""
        base = self._base_from_symbol(self.symbol)
        try:
            wb = call_with_retry(client.get_wallet_balance, accountType="UNIFIED", coin=base)
            lst = wb.get("result", {}).get("list", []) or []
            if not lst:
                return 0.0
            coins = lst[0].get("coin", []) or []
            for c in coins:
                if (c.get("coin") or "").upper() == base.upper():
                    # walletBalance = free + locked (общий баланс монеты)
                    wallet_bal = float(c.get("walletBalance") or 0.0)
                    return max(0.0, wallet_bal)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_get_base_free_locked_qty] {_sw_ex}')
        # fallback: use spot balances helper if exists
        try:
            bals = self.get_spot_balances()
            for c, q in bals.items():
                if c.upper() == base.upper():
                    return float(q)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_get_base_free_locked_qty] {_sw_ex}')
        return 0.0
    def get_closes(self, interval: str = "1", limit: int = 100, symbol: Optional[str] = None, interval_min: Optional[str] = None) -> List[float]:
        """Return closes for given interval (minutes). Accepts interval_min as alias."""
        if interval_min is not None:
            interval = str(interval_min)
        ohlc = self.get_ohlc(interval_min=interval, limit=limit, symbol=symbol)
        closes = ohlc.get("close", []) if isinstance(ohlc, dict) else []
        return [float(x) for x in closes]
    def get_kline_list(self, interval_min: str = "1", limit: int = 200, symbol: Optional[str] = None, interval: Optional[str] = None) -> List[list]:
        """Fetch raw kline rows from Bybit Unified API. Returns empty list on failure."""
        if interval is not None:
            interval_min = str(interval)
        sym = symbol or self.symbol
        try:
            r = call_with_retry(client.get_kline, category="spot", symbol=sym, interval=str(interval_min), limit=int(limit))
            lst = (r or {}).get("result", {}).get("list", []) or []
            # Bybit возвращает новые первыми — разворачиваем чтобы индекс [-1] = последняя свеча
            return list(reversed(lst))
        except Exception:
            return []
    def get_ohlc(self, interval_min: str = "1", limit: int = 200, symbol: Optional[str] = None, interval: Optional[str] = None) -> dict:
        """Return OHLC arrays as dict: open/high/low/close (oldest->newest)."""
        if interval is not None:
            interval_min = str(interval)
        kl = self.get_kline_list(interval_min=str(interval_min), limit=int(limit), symbol=symbol)
        o, h, l, c = [], [], [], []
        for row in kl:
            try:
                # Bybit kline: [startTime, open, high, low, close, volume, turnover]
                o.append(float(row[1]))
                h.append(float(row[2]))
                l.append(float(row[3]))
                c.append(float(row[4]))
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [get_ohlc] {_sw_ex}')  # [FIX-v152-3]
        return {"open": o, "high": h, "low": l, "close": c}
    def atr_pct(self, interval_min: str, period: int = 14, limit: int = 120) -> float:
        """ATR (Average True Range) as percent of last close."""
        ohlc = self.get_ohlc(interval_min=interval_min, limit=max(int(limit), int(period) + 2))
        highs = ohlc.get("high", [])
        lows = ohlc.get("low", [])
        closes = ohlc.get("close", [])
        if len(closes) < int(period) + 2:
            return 0.0
        trs: List[float] = []
        for i in range(1, len(closes)):
            h = float(highs[i]) if i < len(highs) else float(closes[i])
            lo = float(lows[i]) if i < len(lows) else float(closes[i])
            prev = float(closes[i - 1])
            tr = max(h - lo, abs(h - prev), abs(lo - prev))
            trs.append(tr)
        if len(trs) < int(period):
            return 0.0
        atr = sum(trs[-int(period):]) / float(period)
        last_close = float(closes[-1])
        return (atr / last_close) * 100.0 if last_close > 0 else 0.0
    def bb_width_pct(
        self,
        interval_min: str = "5",
        period: int = 20,
        k: float = 2.0,
        limit: int = 120,
        interval: Optional[str] = None,
        **_: Any,
    ) -> float:
        """Bollinger band width as percent of mid.
        Backward/forward compatible:
        - accepts interval_min or interval
        - ignores extra kwargs (so older call-sites won't crash)
        """
        if interval is not None:
            interval_min = str(interval)
        closes = self.get_closes(interval_min=interval_min, limit=max(int(limit), int(period) + 5))
        if len(closes) < int(period):
            return 0.0
        window = closes[-int(period):]
        m = sum(window) / float(period)
        if m <= 0:
            return 0.0
        var = sum((x - m) ** 2 for x in window) / float(period)
        sd = var ** 0.5
        upper = m + k * sd
        lower = m - k * sd
        return ((upper - lower) / m) * 100.0
    def range_pct(self, interval_min: Optional[str] = None, lookback: int = 60, interval: Optional[str] = None) -> float:
        interval_min = interval_min or getattr(CFG, "KLINE_INTERVAL_MIN", "5")
        if interval is not None:
            interval_min = str(interval)
        ohlc = self.get_ohlc(interval_min=interval_min, limit=int(lookback))
        closes = ohlc.get("close", [])
        highs = ohlc.get("high", [])
        lows = ohlc.get("low", [])
        if not closes:
            return 0.0
        hi = max(highs) if highs else max(closes)
        lo = min(lows) if lows else min(closes)
        mid = float(closes[-1])
        if mid <= 0:
            return 0.0
        return ((hi - lo) / mid) * 100.0
    def recent_change_pct(self, interval: str = "5") -> float:
        o = self.get_ohlc(interval_min=interval, limit=3)  # [FIX-8] был interval= → теперь явный interval_min=
        closes = o.get("close", [])
        if len(closes) < 2:
            return 0.0
        prev = float(closes[-2])
        last = float(closes[-1])
        if prev <= 0:
            return 0.0
        return (last - prev) / prev * 100.0
    def is_strong_impulse(self) -> bool:
        try:
            atr = float(self.atr_pct(interval_min="5", period=14, limit=60))
        except Exception:
            atr = 0.0
        try:
            chg = abs(float(self.recent_change_pct(interval="5")))
        except Exception:
            chg = 0.0
        return (atr >= float(getattr(CFG, "IMPULSE_ATR_PCT_5M", 0.60))) or (chg >= float(getattr(CFG, "IMPULSE_CANDLE_PCT_5M", 0.70)))
    # =============================
    # Flat/Scalp profile detection
    # =============================
    def detect_flat(self, tf_min: Optional[str] = None) -> bool:
        """Auto-detect sideways (flat) market.
        Uses: Range%, ATR%, Bollinger Band width%.
        Returns True => FLAT (prefer SCALP profile)
        """
        tf = str(tf_min or getattr(CFG, "FLAT_TF_MIN", "5"))
        lb = int(getattr(CFG, "FLAT_LOOKBACK", 60))
        try:
            r = float(self.range_pct(tf, lookback=lb))
        except Exception:
            r = 0.0
        try:
            atr = float(self.atr_pct(interval_min=tf, period=int(getattr(CFG, "FLAT_ATR_PERIOD", 14)), limit=max(120, lb + 10)))
        except Exception:
            atr = 0.0
        try:
            bb = float(self.bb_width_pct(interval_min=tf, period=int(getattr(CFG, "FLAT_BB_PERIOD", 20)), limit=max(120, lb + 20)))
        except Exception:
            bb = 0.0
        # [FIX-v35-3] используем CFG напрямую — getattr со старыми дефолтами (0.80/0.35/0.70)
        # перезатирал исправленные значения из Config (1.20/0.55/1.10)
        range_max = float(CFG.FLAT_RANGE_MAX_PCT)
        atr_max   = float(CFG.FLAT_ATR_MAX_PCT)
        bb_max    = float(CFG.FLAT_BB_WIDTH_MAX_PCT)
        # flat если хотя бы 2 из 3 условий выполнены
        hits = 0
        if r <= range_max:
            hits += 1
        if atr <= atr_max:
            hits += 1
        if bb <= bb_max:
            hits += 1
        return hits >= 2
    def effective_profile(self) -> str:
        """Return active profile name: 'scalp' or 'normal'.
        ✅ Кэш на уровне экземпляра с TTL=10с — убирает лишние get_ohlc вызовы
        (detect_flat() может делать до 3 API-запросов).
        """
        now = time.time()
        try:
            if (now - float(getattr(self, "_eff_profile_ts", 0.0)) < 10.0) and getattr(self, "_eff_profile_cache", None):
                return str(self._eff_profile_cache)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [effective_profile] {_sw_ex}')
        try:
            result = "scalp" if (bool(getattr(CFG, "USE_AUTO_PROFILE", True)) and self.detect_flat()) else "normal"
        except Exception:
            result = "normal"
        self._eff_profile_cache = result
        self._eff_profile_ts = now
        return result
    def effective_tp_minmax(self) -> Tuple[float, float]:
        profile = self.effective_profile()
        if profile == "scalp":
            return float(getattr(CFG, "SCALP_TP_MIN_PCT", CFG.TP_MIN_PCT)), float(getattr(CFG, "SCALP_TP_MAX_PCT", CFG.TP_MAX_PCT))
        # ✅ сильный импульс → берём TP больше (0.8–1.2%)
        if self.is_strong_impulse():
            return float(getattr(CFG, "IMPULSE_TP_MIN_PCT", 0.80)), float(getattr(CFG, "IMPULSE_TP_MAX_PCT", 1.20))
        return float(CFG.TP_MIN_PCT), float(CFG.TP_MAX_PCT)
    def effective_grid_step_percent(self) -> float:
        """Return adaptive grid step (%) for current market profile.
        Kept minimal and safe: always returns a finite float.
        """
        base = float(getattr(CFG, "GRID_STEP_PERCENT", 0.6))
        # profile-based default (SCALP tighter grid)
        try:
            profile = str(self.effective_profile()).lower()
        except Exception:
            profile = "normal"
        step = float(getattr(CFG, "SCALP_GRID_STEP_PCT", base)) if profile == "scalp" else base
        # Volatility adaptive step via ATR%
        if bool(getattr(CFG, "ADAPTIVE_GRID", True)):
            try:
                interval = str(getattr(CFG, "KLINE_INTERVAL_MIN", "5"))
                atr = float(self.atr_pct(interval, period=14, limit=120))
                mult = float(CFG.GRID_STEP_ATR_MULT)  # [FIX-v40] было getattr дефолт 1.0 ≠ CFG=1.20
                atr_step = atr * mult
                mn = base * float(getattr(CFG, "GRID_STEP_ATR_MULT_MIN", 0.7))
                mx = base * float(getattr(CFG, "GRID_STEP_ATR_MULT_MAX", 2.0))
                atr_step = max(mn, min(mx, atr_step))
                step = max(step, atr_step)
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [effective_grid_step_percent] {_sw_ex}')  # [FIX-v151-1]
        # Auto-widen step on dump
        try:
            if bool(getattr(CFG, "AUTO_STEP_ON_DUMP", True)) and bool(self.detect_dump()):
                dm = float(getattr(CFG, "DUMP_STEP_MULT", 1.6))
                dm = min(dm, float(getattr(CFG, "DUMP_STEP_MULT_MAX", 2.50)))  # применяем MAX-ограничитель
                step = max(step, base * dm)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [effective_grid_step_percent] {_sw_ex}')  # [FIX-v151-1]
        # Hard bounds (optional)
        step_min = float(getattr(CFG, "GRID_STEP_MIN_PCT", 0.15))
        step_max = float(CFG.GRID_STEP_MAX_PCT)  # [FIX-v40] было getattr дефолт 5.0 ≠ CFG=1.20
        step = max(step_min, min(step_max, step))
        return float(step)
    def effective_rebuild_threshold(self) -> float:
        """Adaptive rebuild threshold (%). Defaults to CFG.GRID_REBUILD_THRESHOLD.
        Returned value is always a finite float.
        """
        base = float(getattr(CFG, "GRID_REBUILD_THRESHOLD", 2.0))
        try:
            profile = str(self.effective_profile()).lower()
        except Exception:
            profile = "normal"
        thr = float(getattr(CFG, "SCALP_REBUILD_THRESHOLD", base)) if profile == "scalp" else base
        # Optional: slightly widen rebuild trigger during dumps to avoid thrashing
        try:
            if bool(getattr(CFG, "AUTO_REBUILD_WIDEN_ON_DUMP", True)) and bool(self.detect_dump()):
                thr = max(thr, base * float(getattr(CFG, "DUMP_REBUILD_MULT", 1.25)))
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [effective_rebuild_threshold] {_sw_ex}')
        # Hard bounds
        thr_min = float(getattr(CFG, "GRID_REBUILD_MIN_PCT", 0.25))
        thr_max = float(getattr(CFG, "GRID_REBUILD_MAX_PCT", 25.0))
        thr = max(thr_min, min(thr_max, thr))
        return float(thr)
    def __getattr__(self, name: str):
        """FIX #3: Убраны ложные fallback-и для методов которые уже существуют в классе.
        effective_profile/effective_grid_step_percent/effective_rebuild_threshold —
        реальные методы, __getattr__ для них не вызывается никогда.
        Оставлять их здесь было опасно: ошибка внутри метода → __getattr__
        перехватывал её и возвращал lambda вместо реального исключения.
        """
        raise AttributeError(f"{type(self).__name__!s} object has no attribute {name!r}")
    @staticmethod
    def ema(values: List[float], period: int) -> float:
        """EMA с прогревом через SMA первых period свечей."""
        if not values or period <= 1 or len(values) < period:
            return 0.0
        k = 2.0 / (period + 1.0)
        e = sum(values[:period]) / period
        for v in values[period:]:
            e = v * k + e * (1.0 - k)
        return e
    @staticmethod
    def ema_series(values: List[float], period: int) -> List[float]:
        """Возвращает полный список EMA (oldest→newest), нужен для slope-проверки."""
        if not values or period <= 1 or len(values) < period:
            return []
        k = 2.0 / (period + 1.0)
        e = sum(values[:period]) / period
        result: List[float] = [e]
        for v in values[period:]:
            e = v * k + e * (1.0 - k)
            result.append(e)
        return result
    def is_peak_candles(self) -> bool:
        """Защита от входа на пике: True если последние N свечей подряд зелёные.
        Не покупаем если рынок уже N баров идёт вверх без отката.
        """
        if not bool(getattr(CFG, "PEAK_PROTECTION", True)):
            return False
        n = int(getattr(CFG, "PEAK_GREEN_CANDLES", 5))  # [FIX-C] дефолт был 3 но CFG=5 → при сбое getattr снова блокировал тренды
        tf = str(getattr(CFG, "PEAK_CANDLE_TF", "5"))
        try:
            ohlc = self.get_ohlc(interval_min=tf, limit=n + 2)
            opens = ohlc.get("open", [])
            closes = ohlc.get("close", [])
            if len(closes) < n or len(opens) < n:
                return False
            # Проверяем последние n свечей (без текущей незакрытой — берём [-n-1:-1])
            relevant_o = opens[-n-1:-1] if len(opens) >= n+1 else opens[-n:]
            relevant_c = closes[-n-1:-1] if len(closes) >= n+1 else closes[-n:]
            if len(relevant_c) < n:
                return False
            return all(relevant_c[i] > relevant_o[i] for i in range(len(relevant_c)))
        except Exception:
            return False
    @staticmethod
    def _count_consecutive_green(opens: List[float], closes: List[float]) -> int:
        cnt = 0
        for o, c in zip(reversed(opens), reversed(closes)):
            if c > o:
                cnt += 1
            else:
                break
        return cnt
    def _orderbook_pressure_ratio(self, symbol: Optional[str] = None) -> float:
        sym = str(symbol or self.symbol)
        try:
            res = call_with_retry(client.get_orderbook, category="spot", symbol=sym, limit=int(getattr(CFG, "ORDERBOOK_DEPTH_LEVELS", 25)))
            ob = res.get("result", {}) or {}
            bids = ob.get("b") or []
            asks = ob.get("a") or []
            bid_notional = 0.0
            ask_notional = 0.0
            for p, q in bids:
                bid_notional += float(p) * float(q)
            for p, q in asks:
                ask_notional += float(p) * float(q)
            if ask_notional <= 0:
                return 1.0
            return float(bid_notional / ask_notional)
        except Exception:
            return 1.0
    def _ai_entry_score(self, market_price: float, ema_fast_1m: float, pb_pct: float, bounce_pct: float, ch5: float, ch15: float, green_cnt: int, pressure: float, last_candle_pct: float) -> Tuple[float, List[str]]:
        score = 0.0
        reasons: List[str] = []
        if ema_fast_1m > 0 and market_price >= ema_fast_1m:
            score += float(getattr(CFG, "AI_ENTRY_TREND_WEIGHT", 1.2))
            reasons.append("trend")
        if float(getattr(CFG, "MICRO_PULLBACK_MIN_PCT", 0.05)) <= pb_pct <= float(getattr(CFG, "MICRO_PULLBACK_MAX_PCT", 1.2)):
            score += float(getattr(CFG, "AI_ENTRY_PULLBACK_WEIGHT", 1.4))
            reasons.append("pullback")
        if float(getattr(CFG, "PREBUY_CONFIRM_MIN_BOUNCE_PCT", 0.03)) <= bounce_pct <= float(getattr(CFG, "PREBUY_CONFIRM_MAX_BOUNCE_PCT", 0.65)):
            score += 1.0
            reasons.append("bounce")
        if pressure >= float(getattr(CFG, "PREDUMP_MIN_PRESSURE", 0.92)):
            score += float(getattr(CFG, "AI_ENTRY_ORDERBOOK_WEIGHT", 1.0))
            reasons.append("pressure")
        if green_cnt <= max(1, int(getattr(CFG, "MAX_GREEN_1M_CANDLES", 2)) - 1):
            score += 0.8
        else:
            score -= 0.8
        if last_candle_pct <= float(getattr(CFG, "MAX_LAST_1M_CANDLE_PCT", 0.35)) * 0.7:
            score += 0.8
        else:
            score -= 0.6
        if ch5 <= float(getattr(CFG, "PREBUY_ANTI_CHASE_5M_MAX_PCT", 2.0)) * 0.6:
            score += 0.7
        else:
            score -= float(getattr(CFG, "AI_ENTRY_CHASE_PENALTY", 1.3)) * 0.5
        if ch15 <= float(getattr(CFG, "PREBUY_ANTI_CHASE_15M_MAX_PCT", 2.2)) * 0.7:
            score += 0.7
        else:
            score -= float(getattr(CFG, "AI_ENTRY_CHASE_PENALTY", 1.3))
        return score, reasons
    def _calc_atr_pct_from_ohlc(self, highs: List[float], lows: List[float], closes: List[float], period: int = 14) -> float:
        try:
            if len(closes) < period + 2 or len(highs) < len(closes) or len(lows) < len(closes) or float(closes[-1]) <= 0:
                return 0.0
            trs: List[float] = []
            for i in range(1, len(closes)):
                h = float(highs[i]); lo = float(lows[i]); prev = float(closes[i - 1])
                trs.append(max(h - lo, abs(h - prev), abs(lo - prev)))
            if len(trs) < period:
                return 0.0
            atr = sum(trs[-period:]) / float(period)
            return atr / float(closes[-1]) * 100.0 if float(closes[-1]) > 0 else 0.0
        except Exception:
            return 0.0
    def _calc_bb_width_pct(self, closes: List[float], period: int = 20) -> float:
        try:
            if len(closes) < period:
                return 0.0
            window = [float(x) for x in closes[-period:]]
            mid = sum(window) / float(period)
            if mid <= 0:
                return 0.0
            var = sum((x - mid) ** 2 for x in window) / float(period)
            sd = var ** 0.5
            upper = mid + 2.0 * sd
            lower = mid - 2.0 * sd
            return (upper - lower) / mid * 100.0
        except Exception:
            return 0.0
    def _adaptive_pullback_profile(self, market_price: float, ohlc_5m: Optional[Dict[str, List[float]]] = None) -> Tuple[float, float, bool, bool, str]:
        """Adaptive pullback bounds by trend strength and market state.
        v59 FIX#15: TTL-кэш 45с. Без кэша каждый BUY-attempt делал 2 некэшированных
        API-вызова (get_closes 15m + 60m) = +60 req/min → Bybit rate-limit 429.
        Returns: (pb_min, pb_max, require_confirm, require_green_confirm, profile_name)
        """
        pb_min = float(getattr(CFG, 'ADAPTIVE_PULLBACK_NORMAL_MIN_PCT', 0.20))  # v66: explicit fallback 0.20
        pb_max = float(getattr(CFG, 'ADAPTIVE_PULLBACK_NORMAL_MAX_PCT', CFG.MICRO_PULLBACK_MAX_PCT))
        require_confirm = bool(getattr(CFG, 'PREBUY_CONFIRM_AFTER_PULLBACK', True))
        require_green = bool(getattr(CFG, 'PREBUY_REQUIRE_GREEN_CONFIRM_CANDLE', True))
        profile = 'normal'
        if not bool(getattr(CFG, 'ADAPTIVE_PULLBACK_ENABLE', True)):
            return pb_min, pb_max, require_confirm, require_green, profile
        # v59 FIX#15: TTL cache — check BEFORE any API calls
        _pb_now = time.time()
        _pb_ttl = 45.0
        _pb_cached = getattr(self, '_adaptive_pb_cache', None)
        if (
            isinstance(_pb_cached, tuple)
            and len(_pb_cached) == 5
            and (_pb_now - float(getattr(self, '_adaptive_pb_cache_ts', 0.0))) < _pb_ttl
            and str(getattr(self, '_adaptive_pb_cache_sym', '')) == self.symbol
        ):
            return _pb_cached  # type: ignore[return-value]
        try:
            o5 = ohlc_5m or self.get_ohlc(interval_min='5', limit=40)
            c5 = [float(x) for x in (o5.get('close', []) or [])]
            h5 = [float(x) for x in (o5.get('high', []) or [])]
            l5 = [float(x) for x in (o5.get('low', []) or [])]
            atr5 = self._calc_atr_pct_from_ohlc(h5, l5, c5, period=14)
            bb5 = self._calc_bb_width_pct(c5, period=20)
            adx5 = self.calc_real_adx(h5, l5, c5, period=14) if len(c5) >= 40 else 0.0
            c15 = [float(x) for x in self.get_closes(interval='15', limit=80)]
            c1h = [float(x) for x in self.get_closes(interval='60', limit=80)]
            ema15_fast = self.ema(c15, int(getattr(CFG, 'SCANNER_EMA_15M_FAST', 9))) if len(c15) >= 25 else 0.0
            ema15_slow = self.ema(c15, int(getattr(CFG, 'SCANNER_EMA_15M_SLOW', 21))) if len(c15) >= 25 else 0.0
            ema1h_fast = self.ema(c1h, int(getattr(CFG, 'SCANNER_EMA_1H_FAST', 9))) if len(c1h) >= 25 else 0.0
            ema1h_slow = self.ema(c1h, int(getattr(CFG, 'SCANNER_EMA_1H_SLOW', 21))) if len(c1h) >= 25 else 0.0
            strong_trend = ema15_fast > ema15_slow > 0 and ema1h_fast > ema1h_slow > 0 and adx5 >= max(20.0, float(getattr(CFG, 'ADX_MIN', 23.0)))
            volatile = atr5 >= 1.0 or bb5 >= 3.5
            sleepy = atr5 > 0 and atr5 <= 0.25 and bb5 <= 0.80
            market_mode = self._market_mode_name()
            if market_mode == 'IMPULSE':
                pb_min = float(getattr(CFG, 'IMPULSE_MICRO_PULLBACK_MIN_PCT', 0.03) or 0.03)
                pb_max = max(pb_max, 1.50)
            elif market_mode == 'SCALP':
                pb_min = float(getattr(CFG, 'SCALP_MICRO_PULLBACK_MIN_PCT', 0.07) or 0.07)
            if strong_trend and not volatile:
                profile = 'strong'
                pb_min = float(getattr(CFG, 'ADAPTIVE_PULLBACK_STRONG_MIN_PCT', 0.03))
                pb_max = float(getattr(CFG, 'ADAPTIVE_PULLBACK_STRONG_MAX_PCT', 0.90))
                if bool(getattr(CFG, 'ADAPTIVE_PULLBACK_ALLOW_NO_PULLBACK_IN_STRONG_TREND', True)):
                    pb_min = min(pb_min, 0.03)
                if bool(getattr(CFG, 'ADAPTIVE_PULLBACK_SKIP_CONFIRM_IN_STRONG_TREND', True)):
                    require_confirm = False
                    require_green = False
            elif volatile or ema1h_fast <= ema1h_slow or (adx5 > 0 and adx5 < float(getattr(CFG, 'ADX_MIN', 23.0))):
                profile = 'weak'
                pb_min = float(getattr(CFG, 'WEAK_MICRO_PULLBACK_MIN_PCT', getattr(CFG, 'ADAPTIVE_PULLBACK_WEAK_MIN_PCT', 0.10)) or 0.10)  # v68: WEAK_MICRO → ADAPTIVE_WEAK chain
                pb_max = float(getattr(CFG, 'ADAPTIVE_PULLBACK_WEAK_MAX_PCT', 1.50))
                if volatile:
                    pb_max = min(pb_max, float(getattr(CFG, 'ADAPTIVE_PULLBACK_VOLATILE_MAX_PCT', 1.50)))
                require_confirm = True
                require_green = True
            elif sleepy:
                profile = 'sleepy'
                pb_min = float(getattr(CFG, 'ADAPTIVE_PULLBACK_SLEEPY_MIN_PCT', 0.02) or 0.02)  # v66: через CFG
                pb_max = min(pb_max, 0.70)
                require_confirm = False
                require_green = False
            pb_min = max(0.0, float(pb_min))
            pb_max = max(pb_min, float(pb_max))
            _pb_result: Tuple[float, float, bool, bool, str] = (pb_min, pb_max, require_confirm, require_green, profile)
            # v59 FIX#15: save to TTL cache
            self._adaptive_pb_cache = _pb_result
            self._adaptive_pb_cache_ts = _pb_now
            self._adaptive_pb_cache_sym = self.symbol
            return _pb_result
        except Exception:
            return pb_min, pb_max, require_confirm, require_green, profile
    def _is_strong_trend_context(self, ohlc_5m: Optional[Dict[str, List[float]]] = None) -> bool:
        try:
            o5 = ohlc_5m or self.get_ohlc(interval_min='5', limit=40)
            c5 = [float(x) for x in (o5.get('close', []) or [])]
            h5 = [float(x) for x in (o5.get('high', []) or [])]
            l5 = [float(x) for x in (o5.get('low', []) or [])]
            adx5 = self.calc_real_adx(h5, l5, c5, period=14) if len(c5) >= 25 else 0.0
            c15 = [float(x) for x in self.get_closes(interval='15', limit=80)]
            c1h = [float(x) for x in self.get_closes(interval='60', limit=80)]
            ema15_fast = self.ema(c15, int(getattr(CFG, 'SCANNER_EMA_15M_FAST', 9))) if len(c15) >= 25 else 0.0
            ema15_slow = self.ema(c15, int(getattr(CFG, 'SCANNER_EMA_15M_SLOW', 21))) if len(c15) >= 25 else 0.0
            ema1h_fast = self.ema(c1h, int(getattr(CFG, 'SCANNER_EMA_1H_FAST', 9))) if len(c1h) >= 25 else 0.0
            ema1h_slow = self.ema(c1h, int(getattr(CFG, 'SCANNER_EMA_1H_SLOW', 21))) if len(c1h) >= 25 else 0.0
            return bool(ema15_fast > ema15_slow > 0 and ema1h_fast > ema1h_slow > 0 and adx5 >= max(20.0, float(getattr(CFG, 'ADX_MIN', 23.0))))
        except Exception:
            return False
    def _fading_impulse_state(self, opens_1m: List[float], highs_1m: List[float], lows_1m: List[float], closes_1m: List[float]) -> Tuple[bool, str]:
        if not bool(getattr(CFG, 'FADING_IMPULSE_FILTER_ENABLE', True)):
            return False, ''
        try:
            lb = max(4, int(getattr(CFG, 'FADING_IMPULSE_LOOKBACK_1M', 6)))
            if len(highs_1m) < lb or len(lows_1m) < lb or len(closes_1m) < lb:
                return False, ''
            hs = highs_1m[-lb:]
            ls = lows_1m[-lb:]
            cs = closes_1m[-lb:]
            half = max(2, lb // 2)
            first_high = max(hs[:half]); second_high = max(hs[half:])
            first_low = min(ls[:half]); second_low = min(ls[half:])
            first_swing = (first_high - first_low) / first_low * 100.0 if first_low > 0 else 0.0
            second_swing = (second_high - second_low) / second_low * 100.0 if second_low > 0 else 0.0
            weak_ratio = float(getattr(CFG, 'FADING_IMPULSE_WEAK_RATIO', 0.72))
            min_swing = float(getattr(CFG, 'FADING_IMPULSE_MIN_SWING_PCT', 0.18))
            lower_highs = 0
            for i in range(1, len(hs)):
                if hs[i] < hs[i-1]:
                    lower_highs += 1
            if first_swing >= min_swing and second_swing > 0 and second_swing < first_swing * weak_ratio and lower_highs >= 2 and cs[-1] <= cs[-2]:
                return True, f'fading impulse: wave {second_swing:.2f}% < {first_swing:.2f}%'
            return False, ''
        except Exception:
            return False, ''
    def _late_entry_state(self, market_price: float, highs_1m: List[float], lows_1m: List[float], closes_5m: List[float]) -> Tuple[bool, str]:
        if not bool(getattr(CFG, 'LATE_ENTRY_FILTER_ENABLE', True)):
            return False, ''
        try:
            if len(highs_1m) < 4 or len(lows_1m) < 4:
                return False, ''
            recent_high = max(highs_1m[-4:])
            recent_low = min(lows_1m[-4:])
            dist_to_high = (recent_high - market_price) / recent_high * 100.0 if recent_high > 0 else 999.0
            wave_from_low = (market_price - recent_low) / recent_low * 100.0 if recent_low > 0 else 0.0
            lower_highs = 0
            hs = highs_1m[-4:]
            for i in range(1, len(hs)):
                if hs[i] < hs[i-1]:
                    lower_highs += 1
            if dist_to_high <= float(getattr(CFG, 'LATE_ENTRY_MAX_DIST_FROM_5M_HIGH_PCT', 0.25)) and wave_from_low >= float(getattr(CFG, 'LATE_ENTRY_MAX_RECENT_WAVE_FROM_LOW_PCT', 1.10)) and lower_highs >= int(getattr(CFG, 'LATE_ENTRY_MAX_1M_LOWER_HIGHS', 3)):
                return True, f'late-entry near local high: dist {dist_to_high:.2f}%'
            return False, ''
        except Exception:
            return False, ''
    def _impulse_alive_state(self, opens_1m: List[float], highs_1m: List[float], lows_1m: List[float], closes_1m: List[float], pressure: float) -> Tuple[bool, str]:
        if not bool(getattr(CFG, 'SMART_IMPULSE_ENTRY_ENABLE', True)):
            return True, ''
        try:
            if len(closes_1m) < 6 or len(opens_1m) < 6:
                return True, ''
            c = closes_1m[-6:]; o = opens_1m[-6:]
            green = sum(1 for a,b in zip(o,c) if b > a)
            last1h = 0.0
            try:
                last1h = float(self.recent_change_pct(interval='60') or 0.0)
            except Exception:
                last1h = 0.0
            up_bias = c[-1] >= c[-2] and c[-2] >= c[-3]
            weak_bids = pressure < float(getattr(CFG, 'SMART_IMPULSE_MIN_PRESSURE', 0.88))  # [FIX-v101-1]
            # [FIX-10A] если последняя 1m свеча красная — проверяем РАЗМЕР
            # Микро-красная (< 0.15%) при хорошем давлении покупателей не = мёртвый импульс
            _last_red_pct = ((c[-1] - o[-1]) / o[-1] * 100.0) if o[-1] > 0 else 0.0
            last_red = len(o) >= 1 and c[-1] < o[-1]
            _red_significant = _last_red_pct < -0.15  # значимая красная > 0.15%
            if last_red and green <= 2 and _red_significant:
                # [FIX-v190-PREBUY2] При streak>25 пропускаем impulse блок
                # [FIX-v297-BUG] Было: обращение к self._pb_relaxed/self._pb_streak, которые
                # являются ЛОКАЛЬНЫМИ переменными другого метода (prebuy_entry_guard) и никогда
                # не существуют в этой функции → гарантированный NameError, тихо гасившийся
                # общим except ниже как "impulse alive" (т.е. этот блок вообще не работал).
                _pb_streak = int(getattr(self, "_zero_scan_streak", 0))
                _pb_relaxed = _pb_streak > 10
                if _pb_relaxed:
                    log(f"⚡ [prebuy] streak={_pb_streak}>10 → impulse bypass (red candle)")
                else:
                    return False, f'impulse not alive: last 1m candle red ({_last_red_pct:.3f}%)'
            elif last_red and green <= 2 and not _red_significant and pressure < float(getattr(CFG, 'SMART_IMPULSE_MIN_PRESSURE', 0.88)):  # [FIX-v101-1]
                # Маленькая красная + слабые покупатели = тоже блок
                return False, f'impulse not alive: micro-red + weak pressure ({_last_red_pct:.3f}%, p={pressure:.2f})'
            if green <= 1 and c[-1] <= c[-2] and weak_bids:
                return False, f'impulse not alive: weak bids {pressure:.2f}'
            _min_1h = float(getattr(CFG, 'SMART_IMPULSE_MIN_LAST1H_PCT', -6.0))
            _max_1h = float(getattr(CFG, 'SMART_IMPULSE_MAX_LAST1H_PCT', 3.50))
            if last1h < _min_1h or last1h > _max_1h:
                # [FIX-v96-1] last1h блокируем только если структура тоже слабая.
                # Scanner уже одобрил монету через pb/EMA/ADX фильтры; если last1h
                # отрицательный из-за отката, но green/pressure/up_bias нормальные →
                # не блокируем жёстко (позволяем score-based decision в prebuy guard).
                if not up_bias or weak_bids or green <= 1:
                    return False, f'impulse not alive: last1h {last1h:.2f}%'
                # Структура нормальная — пропускаем, пусть prebuy guard решает
            if not up_bias and weak_bids:
                return False, 'impulse not alive: structure weak'
            return True, ''
        except Exception:
            return True, ''
    def _trend_break_state(self, market_price: float, highs_1m: List[float], lows_1m: List[float], closes_1m: List[float]) -> Tuple[bool, str]:
        if not bool(getattr(CFG, "TREND_BREAK_FILTER_ENABLE", True)):
            return False, ""
        try:
            n = max(3, int(getattr(CFG, "TREND_BREAK_LOWER_HIGHS", 3)))
            hs = highs_1m[-n:] if len(highs_1m) >= n else highs_1m
            lower_highs = sum(1 for i in range(1, len(hs)) if hs[i] < hs[i-1])
            if len(hs) >= n and lower_highs >= n - 1:
                return True, f"trend break: lower highs x{lower_highs+1}"
            if highs_1m:
                local_high = max(highs_1m[-max(4, n+1):])
                if local_high > 0:
                    drop_pct = (local_high - market_price) / local_high * 100.0
                    if drop_pct >= float(getattr(CFG, "TREND_BREAK_DROP_FROM_LOCAL_HIGH_PCT", 0.80)):
                        return True, f"trend break: drop from local high {drop_pct:.2f}%"
            if len(closes_1m) >= 7:
                prev_wave = abs(closes_1m[-4] - closes_1m[-7])
                last_wave = abs(closes_1m[-1] - closes_1m[-4])
                if prev_wave > 0 and last_wave < prev_wave * float(getattr(CFG, "TREND_BREAK_LAST_WAVE_WEAK_RATIO", 0.68)):
                    return True, f"trend break: last wave weak {last_wave/prev_wave:.2f}"
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_trend_break_state] {_sw_ex}')
        return False, ""
    def _post_buy_sell_guard(self, current_price: float, fill_qty: float) -> bool:
        if not bool(getattr(CFG, "GUARANTEED_SELL_AFTER_BUY_ENABLE", True)):
            return False
        retries = max(1, int(getattr(CFG, "GUARANTEED_SELL_AFTER_BUY_RETRIES", 6)))
        delay = float(getattr(CFG, "GUARANTEED_SELL_AFTER_BUY_RETRY_SEC", 2.0))
        # [FIX-v268-2] Перед проверкой SELL — ждём пока баланс base появится на бирже
        # NOTUSDT и другие монеты: после BUY fill баланс отображается с задержкой 2-5 сек
        _bal_wait = 0.0
        for _bw in range(10):  # до 10 попыток × 1.5 сек = 15 сек
            _bb = float(self.get_base_balance() or 0.0)
            if _bb >= float(fill_qty or 0.0) * 0.9:
                break  # баланс появился
            time.sleep(1.5)
            _bal_wait += 1.5
        if _bal_wait > 0:
            log(f"⏳ [v268-2] Ждали баланс base {_bal_wait:.0f}с перед SELL guard")
        for _ in range(retries):
            opens = self.get_open_orders()
            has_sell = False
            for o in opens or []:
                try:
                    if str(o.get("side", "")).lower() == "sell" and float(o.get("qty") or o.get("origQty") or o.get("leavesQty") or 0.0) > 0:
                        has_sell = True
                        break
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [_post_buy_sell_guard] {_sw_ex}')  # [FIX-v151-1]
            if has_sell:
                return True
            if self.safety_ensure_sell(current_price=current_price, open_orders=opens):
                return True
            time.sleep(delay)
        if bool(getattr(CFG, "GUARANTEED_SELL_FORCE_MARKET_ON_FAIL", True)):
            try:
                # [FIX-22] Перед аварийным выходом — ещё раз проверяем есть ли SELL ордера
                # TP1+TP2 могли уже встать, просто биржа медленно отвечала
                _final_opens = self.get_open_orders()
                _has_sell = any(str(o.get('side', '')).lower() == 'sell' for o in (_final_opens or []))
                if _has_sell:
                    log("ℹ️ [FIX-22] post-buy guard: SELL ордер найден при финальной проверке — аварийный выход отменён")
                    return True
                # [FIX-v105-3] Проверка цены перед аварийной продажей:
                # Если текущая цена >= 99.5% от entry — нет реального убытка, пробуем лимит вместо market.
                _entry_p = float(self.pos.entry_price or 0.0)
                _cur_p = float(current_price or 0.0)
                if _entry_p > 0 and _cur_p > 0:
                    _loss_pct = (_entry_p - _cur_p) / _entry_p * 100.0
                    if _loss_pct < 0.5:
                        # Нет убытка — пытаемся поставить лимитный SELL по текущей цене
                        log(f"ℹ️ [FIX-v105-3] post-buy guard: потеря {_loss_pct:.2f}% < 0.5% → пробуем лимитный SELL вместо аварийного")
                        if TG.enabled:
                            TG.send_throttled('guard_limit_sell',
                                f"⚠️ BUY без SELL guard: потеря {_loss_pct:.2f}% минимальна\n"
                                f"Пара: {self.symbol}\nПробую лимитный SELL вместо аварийного.", cooldown_sec=60)
                        bal = self.get_base_balance()
                        qty = min(float(fill_qty or 0.0), float(bal or 0.0))
                        if qty > 0:
                            _limit_ok = False
                            for _att in range(3):
                                # [FIX-v117-3] Лимитный SELL через place_tp_sell (TP выше entry)
                                # НЕ используем bid-0.05% — для монет с малым тиком это даёт цену НИЖЕ entry
                                if self.place_tp_sell(_cur_p, qty, note="(guard_limit_fallback)"):
                                    _limit_ok = True
                                    break
                                time.sleep(1.0)
                            if _limit_ok:
                                log("✅ [FIX-v105-3] Лимитный SELL поставлен — аварийная продажа отменена")
                                return True
                            log("⚠️ [FIX-v105-3] Лимитный SELL не удался → переходим к аварийному выходу")
                bal = self.get_base_balance()
                qty = min(float(fill_qty or 0.0), float(bal or 0.0))
                if qty > 0:
                    log("🚨 BUY without SELL → forced emergency exit")
                    # [FIX-v268-1] НЕ банить навсегда если убыток < 0.5% — это временный сбой биржи,
                    # а не плохая монета. Баним навсегда ТОЛЬКО при реальном убытке (монета упала).
                    _e_p = float(self.pos.entry_price or 0.0)
                    _c_p = float(current_price or 0.0)
                    _real_loss = ((_e_p - _c_p) / _e_p * 100.0) if (_e_p > 0 and _c_p > 0) else 0.0
                    if _real_loss >= 0.5:
                        # Реальный убыток → монета плохая → бан навсегда
                        self._add_to_permanent_emergency_blacklist(self.symbol, reason="post_buy_sell_guard_fail")
                    else:
                        # Сбой биржи без убытка → временная блокировка (не навсегда)
                        log(f"ℹ️ [v268-1] SELL guard fail без убытка ({_real_loss:.2f}%) → НЕ баним навсегда (сбой биржи)")
                        self._symbol_block_until[self.symbol] = time.time() + 3600  # бан на 1 час
                    # [FIX-v119-final] cancel перед аварийным выходом — убираем конкурирующие ордера
                    try:
                        self.cancel_all_open_orders()
                        time.sleep(0.3)  # [FIX-v120-6] убран inline import time
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [_post_buy_sell_guard] {_sw_ex}')  # [FIX-v151-1]
                    return bool(self.market_sell_emergency(qty, reason="post_buy_sell_guard_fail"))
            except Exception as e:
                log(f"⚠️ post-buy sell guard error: {e}")
        return False
    def _wait_sell_coverage_after_buy(self, required_qty: float, current_price: Optional[float] = None) -> bool:
        """After a BUY fill, verify that SELL protection really exists on the book.
        Returns True only when open SELL qty covers the held base position.
        """
        if self.filters is None:
            return False
        try:
            # [FIX-v303-BUG2] required_qty приходит как self.pos.base_qty — сумма СЫРЫХ
            # fill_qty из ордеров BUY, БЕЗ вычета комиссии (см. process_fills: "не запрашиваем
            # баланс с биржи — это убирает погрешность из-за асинхронного обновления баланса").
            # На Bybit Spot комиссия BUY по умолчанию списывается из ПОЛУЧЕННОГО актива (базовой
            # монеты), а не из USDT — то есть реальный баланс на бирже после покупки МЕНЬШЕ
            # required_qty примерно на FEE_RATE_PCT. place_tp_sell() уже это учитывает (сравнивает
            # с 0.95×реальный баланс, строка ~9642) — а эта функция сравнивала с required_qty
            # почти без допуска (2×qty_step), из-за чего условие ниже практически НИКОГДА не
            # выполнялось полностью и алерт "BUY без SELL после повторов. Аварийная защита"
            # срабатывал почти на КАЖДОМ заполнении сетки (см. ROUND7 — SAFEUSDT, 2/2 раза
            # за сессию), хотя защита по факту стояла (place_tp_sell параллельно рапортовал
            # "✅ покрыто"). Учитываем ожидаемое списание комиссии, чтобы порог был достижим.
            _fee_frac = float(getattr(CFG, 'FEE_RATE_PCT', 0.10)) / 100.0
            need_qty = floor_to_step(float(required_qty or 0.0) * (1.0 - _fee_frac), float(self.filters.qty_step or 0.0))
        except Exception:
            need_qty = float(required_qty or 0.0)
        retries = max(1, int(getattr(CFG, 'ORDER_CONFIRM_RETRIES', 12) or 12))
        delay = float(getattr(CFG, 'ORDER_CONFIRM_DELAY_SEC', 1.0) or 1.0)
        for _ in range(retries):
            try:
                opens = self.get_open_orders()
            except Exception:
                opens = []
            try:
                sell_qty = floor_to_step(self._sum_open_sell_qty(opens), float(self.filters.qty_step or 0.0))
            except Exception:
                sell_qty = 0.0
            if sell_qty >= max(0.0, need_qty - float(self.filters.qty_step or 0.0) * 2.0):
                return True
            # try to actively restore protection if missing / not enough
            try:
                self.safety_ensure_sell(current_price=current_price, open_orders=opens)
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [_wait_sell_coverage_after_buy] {_sw_ex}')  # [FIX-v153-FINAL]
            time.sleep(delay)
        return False
    def prebuy_entry_guard(self, buy_price: Optional[float] = None) -> Tuple[bool, str]:
        """Финальный decision-engine guard: hard blocks only for real danger, otherwise score-based."""
        # [FIX-v190-PREBUY] Ослабляем guard при длинной серии пустых сканов
        _pb_streak = int(getattr(self,"_zero_scan_streak",0))
        # [FIX-v191-2] Снижаем пороги — логи показали streak=21 не проходил!
        _pb_disabled = _pb_streak > 30  # было 50 — слишком высоко
        _pb_relaxed  = _pb_streak > 10  # было 25 — слишком высоко

        # [v213-BASE] При streak>40 — базовый режим через чтение графика
        if _pb_streak > 40:
            _bm_ok, _bm_reason, _bm_chart = self._check_base_mode_entry(
                price=float(buy_price or 0.0))
            if _bm_ok:
                _pb_disabled = True
                log(f"🟢 [v213-BASE] Вход: {_bm_reason}")
                if TG.enabled:
                    # [FIX-v312] Было "\\n" вместо настоящего переноса строки "\n" — см. ту же
                    # правку выше для ADX-дедлока.
                    TG.send(
                        f"🟢 <b>Базовый режим</b>\n"
                        f"Streak={_pb_streak} → упрощённый вход\n"
                        f"График: {_bm_chart.get('trend','?')} "
                        f"score={_bm_chart.get('score',0):.1f}\n"
                        f"[{_bm_chart.get('reason','')}]"
                    )
            else:
                log(f"🔴 [v213-BASE] Блок: {_bm_reason}")
        activity_mode = str(getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced')).lower()
        market_mode = self._market_mode_name()
        self._set_stage('PREBUY_GUARD_ENTER', symbol=self.symbol, mode=market_mode, activity=activity_mode)
        try:
            now = time.time()
            strong_ctx = False
            hard_reason = ""
            penalties: Dict[str, float] = {}
            bonuses: Dict[str, float] = {'base': 1.5}
            pressure = 1.0
            ch5 = 0.0
            ch15 = 0.0
            pb_pct = 0.0
            bounce_pct = 0.0
            dist_above = 0.0
            ai_score = 0.0
            scanner_score_bonus = max(0.0, min(2.5, float(getattr(self, 'current_score', 0.0) or 0.0) * 0.18))
            tradeability_bonus = max(0.0, min(1.5, float(getattr(self, '_last_selected_tradeability', 0.0) or 0.0) * 0.8))
            bonuses['scanner_score'] = scanner_score_bonus
            bonuses['tradeability'] = tradeability_bonus
            cd = int(getattr(CFG, "ENTRY_COOLDOWN_AFTER_SELL_SEC", 5 * 60))
            last_sell_ts = float(getattr(self, "_last_sell_fill_ts", 0.0))
            if cd > 0 and last_sell_ts > 0 and (now - last_sell_ts) < cd:
                left = int(cd - (now - last_sell_ts))
                reason = f"cooldown after SELL {left}s"
                self._last_prebuy_reason = reason
                self._record_reject('cooldown', reason)
                return False, reason
            ohlc_1m = self.get_ohlc(interval_min="1", limit=30)
            opens_1m = [float(x) for x in (ohlc_1m.get("open", []) or [])]
            highs_1m = [float(x) for x in (ohlc_1m.get("high", []) or [])]
            lows_1m = [float(x) for x in (ohlc_1m.get("low", []) or [])]
            closes_1m = [float(x) for x in (ohlc_1m.get("close", []) or [])]
            if len(closes_1m) < 12 or len(opens_1m) < 12 or len(highs_1m) < 12 or len(lows_1m) < 12:
                reason = "1m data gap / not enough candles"
                if bool(getattr(CFG, "PREBUY_BLOCK_ON_DATA_GAP", True)):
                    self._last_prebuy_reason = reason
                    self._record_reject('data_gap_1m', reason)
                    return False, reason
                return True, reason
            opens_c = opens_1m[:-1]
            highs_c = highs_1m[:-1]
            lows_c = lows_1m[:-1]
            closes_c = closes_1m[:-1]
            market_price = float(buy_price or closes_c[-1])
            ohlc_5m = self.get_ohlc(interval_min="5", limit=8)
            closes_5m = [float(x) for x in (ohlc_5m.get("close", []) or [])]
            if len(closes_5m) >= 2 and closes_5m[-2] > 0:
                ch5 = (closes_5m[-1] - closes_5m[-2]) / closes_5m[-2] * 100.0
            if len(closes_5m) >= 4 and closes_5m[-4] > 0:
                ch15 = (closes_5m[-1] - closes_5m[-4]) / closes_5m[-4] * 100.0
            pressure = self._orderbook_pressure_ratio()
            strong_ctx = self._is_strong_trend_context(ohlc_5m)
            # [FIX-v139-E] Real-time 1H EMA check перед BUY — критическая защита.
            # Scanner проверяет 1H тренд в момент скана, но до первого BUY может пройти время.
            # CC/ONDO: цена упала ниже EMA7(1H) пока шла подготовка к входу.
            # Здесь проверяем EMA9<EMA21 на 1H прямо перед размещением ордера.
            try:
                _pg_closes_1h = self.get_closes(interval="60", limit=40)
                if _pg_closes_1h and len(_pg_closes_1h) >= 25:
                    _pg_ema9_1h  = self.ema(_pg_closes_1h, 9)
                    _pg_ema21_1h = self.ema(_pg_closes_1h, 21)
                    _pg_ema7_1h  = self.ema(_pg_closes_1h, 7)
                    _pg_cur      = float(_pg_closes_1h[-1])
                    # [FIX-v212-2] EMA 1H bypass при streak>25
                    # При 120+ пустых сканах и ADX=10 — рынок боковой, EMA не работает
                    _ema_streak=int(getattr(self,'_zero_scan_streak',0))
                    _ema_bypass= _ema_streak > 25  # при 25+ сканах игнорируем EMA 1H
                    # Блок 1: EMA9(1H) < EMA21(1H) — медвежий кросс на 1H
                    if not _ema_bypass and _pg_ema9_1h > 0 and _pg_ema21_1h > 0 and _pg_ema9_1h < _pg_ema21_1h * 1.0002:
                        reason = f"[FIX-v139-E] 1H EMA9({_pg_ema9_1h:.5f})<EMA21({_pg_ema21_1h:.5f}) — нисходящий тренд 1H"
                        self._last_prebuy_reason = reason
                        self._record_reject("1h_ema_cross", reason)
                        return False, reason
                    elif _ema_bypass and _pg_ema9_1h > 0 and _pg_ema21_1h > 0 and _pg_ema9_1h < _pg_ema21_1h * 1.0002:
                        log(f"⚡ [v212] EMA1H bypass: streak={_ema_streak}>25")
                    # Блок 2: Цена ниже EMA7(1H)
                    if not _ema_bypass and _pg_ema7_1h > 0 and _pg_cur < _pg_ema7_1h * 1.001:
                        reason = f"[FIX-v139-E] Цена({_pg_cur:.5f})<EMA7_1H({_pg_ema7_1h:.5f}) — цена под EMA7 на 1H"
                        self._last_prebuy_reason = reason
                        self._record_reject("1h_ema7_price", reason)
                        return False, reason
            except Exception as _crit_ex:  # [v145-silent]
                log(f'⚠️ [prebuy_entry_guard] {_crit_ex}')
            # [FIX-v141-5] Проверка медвежьего EMA каскада 15m прямо перед BUY.
            # Между сканом и BUY может пройти несколько минут — 15m ЕМА успевает
            # сформировать каскад. Сканер уже отработал, trend_filter мог быть в кэше.
            # Это последний рубеж защиты от медвежьего разворота перед входом.
            try:
                _pg_ohlc_15m = self.get_ohlc(interval_min="15", limit=35)
                _pg_closes_15m = _pg_ohlc_15m.get("close", []) if _pg_ohlc_15m else []
                if _pg_closes_15m and len(_pg_closes_15m) >= 30:
                    _pg_ema7_15m  = self.ema(_pg_closes_15m, 7)
                    _pg_ema14_15m = self.ema(_pg_closes_15m, 14)
                    _pg_ema28_15m = self.ema(_pg_closes_15m, 28)
                    if _pg_ema7_15m > 0 and _pg_ema14_15m > 0 and _pg_ema28_15m > 0:
                        if _pg_ema7_15m < _pg_ema14_15m:  # начало медвежьего каскада
                            # [FIX-v224-D] BUG-D: EMA каскад не ослаблялся при длинном streak.
                            # При streak > 100 (>1.5ч без монет) рынок боковой — строгий блок
                            # убивает 100% попыток. При streak > 100 допускаем вход если
                            # разница EMA7 и EMA14 минимальна (< 0.05% — почти горизонт).
                            _ema_diff_pct = abs(_pg_ema7_15m - _pg_ema14_15m) / _pg_ema14_15m * 100.0
                            _streak_now = int(getattr(self, '_zero_scan_streak', 0))
                            _bypass_cascade = (
                                _streak_now >= 100 and
                                _ema_diff_pct < 0.05  # EMA7 ≈ EMA14 — почти горизонтальный
                            )
                            if not _bypass_cascade:
                                reason = (
                                    f"[FIX-v141-5] 15m медвежий EMA каскад перед BUY: "
                                    f"EMA7={_pg_ema7_15m:.5f}<EMA14={_pg_ema14_15m:.5f} → блок"
                                )
                                self._last_prebuy_reason = reason
                                self._record_reject("15m_ema_cascade_prebuy", reason)
                                return False, reason
                            else:
                                log(f"⚡ [v224-D] EMA каскад bypass: streak={_streak_now} diff={_ema_diff_pct:.4f}%<0.05%")
            except Exception as _crit_ex:  # [v145-silent]
                log(f'⚠️ [prebuy_entry_guard] {_crit_ex}')
            if strong_ctx:
                bonuses['strong_ctx'] = 0.9
            if pressure >= 1.03:
                bonuses['pressure'] = 0.7
            elif pressure < 0.92:
                penalties['pressure'] = 0.9
            ema_fast_period = int(getattr(CFG, "PREBUY_EMA_FAST_1M", 9))
            ema_fast_1m = self.ema(closes_c, ema_fast_period)
            if ema_fast_1m > 0:
                dist_above = (market_price - ema_fast_1m) / ema_fast_1m * 100.0
                ema_limit = float(self._effective_max_price_above_ema_pct())
                if dist_above <= ema_limit:
                    bonuses['ema_dist_ok'] = 0.8
                else:
                    over = max(0.0, dist_above - ema_limit)
                    penalties['ema_dist'] = min(2.1, over * (1.2 if not strong_ctx else 0.8) + 0.4)
                    if dist_above > ema_limit * (1.8 if strong_ctx else 1.5):  # v62 P1: было 2.2/2.0 → слишком мягко
                        hard_reason = f"price too high above EMAfast: {dist_above:.3f}%"
            last_o = opens_c[-1]
            last_c = closes_c[-1]
            last_candle_pct = ((last_c - last_o) / last_o * 100.0) if last_o > 0 else 0.0
            # [FIX-v212-1] candle too large bypass при streak>15
            _candle_streak=int(getattr(self,'_zero_scan_streak',0))
            _candle_limit=float(CFG.MAX_LAST_1M_CANDLE_PCT) * (1.30 if strong_ctx else 1.10)
            if last_candle_pct > _candle_limit and _candle_streak <= 15:
                hard_reason = hard_reason or f"last 1m candle too large: {last_candle_pct:.3f}%"
            elif last_candle_pct > _candle_limit * 3.0:  # экстремальный памп — всегда блокируем
                hard_reason = hard_reason or f"last 1m candle EXTREME: {last_candle_pct:.3f}%"
            elif last_candle_pct > float(CFG.MAX_LAST_1M_CANDLE_PCT):
                penalties['last_1m_size'] = 0.8
            else:
                bonuses['last_1m_size_ok'] = 0.2
            green_cnt = self._count_consecutive_green(opens_c[-6:], closes_c[-6:])
            green_hard = int(getattr(CFG, 'GREEN_1M_HARD_BLOCK', 3) or 3)  # v68: fallback синхронизирован с CFG=3
            green_soft_limit = int(getattr(CFG, 'GREEN_1M_SOFT_LIMIT', 2) or 2)
            # [FIX-10A] last candle red — hard block только при значимом падении
            # Раньше ЛЮБАЯ красная свеча (-0.038%) = hard block → пропускали хорошие входы.
            # Теперь: < -MIN_RED_HARD_PCT = hard block, < 0 = штраф.
            _red_hard_pct = float(getattr(CFG, 'MIN_RED_CANDLE_HARD_PCT', 0.30) or 0.30)
            _red_hard_pct_strong = _red_hard_pct * 1.5 if strong_ctx else _red_hard_pct
            if last_candle_pct < -_red_hard_pct_strong:
                hard_reason = hard_reason or f"last candle red (impulse dead): {last_candle_pct:.3f}%"
            elif last_candle_pct < 0:
                # Малая красная свеча — штраф пропорционально размеру
                penalties['last_candle_red_soft'] = min(1.2, abs(last_candle_pct) / _red_hard_pct * 0.8)
            if green_cnt >= green_hard:
                hard_reason = hard_reason or f"too many green 1m candles: {green_cnt}"
            elif green_cnt >= green_soft_limit:
                penalties['green_candles'] = 0.85 + max(0.0, green_cnt - green_soft_limit) * 0.35
            if bool(getattr(CFG, "REQUIRE_MICRO_PULLBACK", True)):
                lb = max(3, int(getattr(CFG, "MICRO_PULLBACK_LOOKBACK_1M", 6)))
                recent_high = max(highs_c[-lb:]) if len(highs_c) >= lb else max(highs_c)
                recent_low = min(lows_c[-lb:]) if len(lows_c) >= lb else min(lows_c)
                pb_min, pb_max, require_confirm, require_green_confirm, pb_profile = self._adaptive_pullback_profile(market_price, ohlc_5m=ohlc_5m)
                # v62 P3: убран soften-override weak pullback (он сбрасывал pb_min до 0.05)
                # pb_min теперь полностью управляется CFG.ADAPTIVE_PULLBACK_WEAK_MIN_PCT = 0.10
                if pb_profile == 'weak':
                    pb_max = max(pb_max, 1.25 if activity_mode == 'active' else 1.05)
                if recent_high > 0:
                    pb_pct = (recent_high - market_price) / recent_high * 100.0
                    ema_small_ctx = bool(ema_fast_1m > 0 and dist_above <= max(0.08, ema_limit * 0.45))
                    if pb_pct < pb_min:
                        miss_pen = max(0.45, (pb_min - pb_pct) * 4.5)  # v62 P3: усилен штраф за отсутствие отката
                        if ema_small_ctx:
                            miss_pen *= 0.45
                            bonuses['ema_pullback_link'] = 0.35
                        penalties['micro_pullback_missing'] = miss_pen
                    elif pb_pct > pb_max:
                        penalties['pullback_deep'] = min(1.25, (pb_pct - pb_max) * 1.2 + 0.20)
                    else:
                        bonuses['pullback_ok'] = 1.0
                if require_confirm and recent_low > 0:
                    bounce_pct = (market_price - recent_low) / recent_low * 100.0
                    bmin = float(CFG.PREBUY_CONFIRM_MIN_BOUNCE_PCT)
                    bmax = float(CFG.PREBUY_CONFIRM_MAX_BOUNCE_PCT) * (1.20 if strong_ctx else 1.0)
                    # v59 FIX#9: в ACTIVE режиме soft_ctx=True — штрафы вдвое меньше, green confirm пропускается
                    _act_soft = strong_ctx or str(getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced')).lower() == 'active'
                    _penalty_mult = 0.5 if _act_soft else 1.0
                    if bounce_pct < bmin:
                        penalties['bounce_weak'] = max(0.08, (bmin - bounce_pct) * 4.0) * _penalty_mult
                    elif bounce_pct > bmax:
                        penalties['bounce_too_large'] = min(1.2, (bounce_pct - bmax) * 1.6 + 0.25) * _penalty_mult
                    else:
                        bonuses['bounce_ok'] = 0.45
                    # v59 FIX#9: green confirm только когда НЕ active И НЕ strong_ctx
                    if require_green_confirm and last_c <= last_o and not _act_soft:
                        penalties['confirm_green_missing'] = 0.35
            chase5 = float(CFG.PREBUY_ANTI_CHASE_5M_MAX_PCT) * (1.20 if strong_ctx else 1.0)
            chase15 = float(CFG.PREBUY_ANTI_CHASE_15M_MAX_PCT) * (1.15 if strong_ctx else 1.0)
            if ch5 > chase5:
                penalties['chase_5m'] = min(1.6, (ch5 - chase5) * 1.0 + 0.45)
            else:
                bonuses['chase_5m_ok'] = 0.25
            if ch15 > chase15:
                penalties['chase_15m'] = min(1.8, (ch15 - chase15) * 0.8 + 0.55)
            if bool(getattr(CFG, "PREDUMP_FILTER_ENABLE", True)):
                red1_pct = max(0.0, (last_o - last_c) / last_o * 100.0) if last_o > 0 and last_c < last_o else 0.0
                drop2_pct = 0.0
                if len(closes_c) >= 3 and closes_c[-3] > 0:
                    drop2_pct = max(0.0, (closes_c[-3] - closes_c[-1]) / closes_c[-3] * 100.0)
                if red1_pct >= float(getattr(CFG, "PREDUMP_LAST1_RED_PCT", 0.45)) * 1.35:
                    hard_reason = hard_reason or f"pre-dump red 1m candle: {red1_pct:.3f}%"
                elif red1_pct > 0:
                    penalties['predump_red1'] = min(1.4, red1_pct * 1.3)
                if drop2_pct >= float(getattr(CFG, "PREDUMP_LAST2_DROP_PCT", 0.55)) * 1.35:
                    hard_reason = hard_reason or f"pre-dump 2m weakness: {drop2_pct:.3f}%"
                elif drop2_pct > 0:
                    penalties['predump_2m'] = min(1.2, drop2_pct * 1.0)
            trend_break_bad, trend_break_reason = self._trend_break_state(market_price, highs_c, lows_c, closes_c)
            if trend_break_bad:
                penalties['trend_break'] = 0.75 if not strong_ctx else 0.35
                # v62 P4: drop from local high = жёсткий блок всегда (не только без strong_ctx)
                if 'drop from local high' in str(trend_break_reason).lower():
                    hard_reason = hard_reason or trend_break_reason
            fading_bad, fading_reason = self._fading_impulse_state(opens_c, highs_c, lows_c, closes_c)
            if fading_bad:
                penalties['fading_impulse'] = 0.85 if not strong_ctx else 0.35
            late_bad, late_reason = self._late_entry_state(market_price, highs_c, lows_c, closes_5m)
            if late_bad:
                penalties['late_entry'] = 0.95 if not strong_ctx else 0.45
            alive_ok, alive_reason = self._impulse_alive_state(opens_c, highs_c, lows_c, closes_c, pressure)
            if not alive_ok:
                # v62 P5: impulse dead = жёсткий блок (не только штраф)
                # Исключение: strong_ctx может компенсировать слабый импульс
                if strong_ctx:
                    penalties['impulse_not_alive'] = 0.65  # смягчён в сильном тренде
                else:
                    hard_reason = hard_reason or f"impulse not alive: {alive_reason}"
            if bool(getattr(CFG, "AI_ENTRY_ENABLE", True)):
                ai_score, _ai_reasons = self._ai_entry_score(market_price, ema_fast_1m, pb_pct, bounce_pct, ch5, ch15, green_cnt, pressure, last_candle_pct)
                bonuses['ai'] = max(0.0, ai_score) * 0.22
                # Keep AI as soft influence only, not a hard blocker
                if ai_score < float(getattr(CFG, 'AI_ENTRY_MIN_SCORE', 4.0) or 4.0):
                    penalties['ai_low'] = max(0.0, (float(getattr(CFG, 'AI_ENTRY_MIN_SCORE', 4.0) or 4.0) - ai_score) * 0.35)
            if market_mode in ('WAIT', 'LOW_VOLUME', 'WHIPSAW'):
                penalties['market_mode'] = 0.9 if activity_mode != 'active' else 0.45
            if market_mode == 'IMPULSE':
                bonuses['market_mode_impulse'] = 0.35
            ok, reason, entry_score, threshold, main_reason = self._score_decision(0.0, penalties, bonuses, hard_reason)
            detail = f"entry={entry_score:.2f}/{threshold:.2f} | main={main_reason or 'n/a'} | ai={ai_score:.2f} | pressure={pressure:.2f} | pb={pb_pct:.3f}% | dist={dist_above:.3f}% | green={green_cnt}"
            if ok:
                self._last_prebuy_reason = "ok | " + detail
                self._set_stage('PREBUY_GUARD_OK', symbol=self.symbol, activity=activity_mode, score=f"{entry_score:.2f}/{threshold:.2f}")
                if bool(getattr(CFG, 'ENTRY_SCORE_LOG_ENABLE', True)):
                    self._slog('ENTRY_SCORE', symbol=self.symbol, reason=detail, activity=activity_mode, mode=market_mode)
                return True, "ok"
            self._last_prebuy_reason = reason + ' | ' + detail
            self._record_reject('prebuy', self._last_prebuy_reason)
            head = (main_reason or reason).split(':')[0].strip().replace(' ', '_')
            self._record_reject(f'prebuy::{head}', self._last_prebuy_reason)
            self._set_stage('PREBUY_GUARD_REJECT', symbol=self.symbol, reason=(main_reason or reason)[:80], activity=activity_mode, score=f"{entry_score:.2f}/{threshold:.2f}")
            self._slog('PREBUY_GUARD_REJECT', symbol=self.symbol, reason=self._last_prebuy_reason, activity=activity_mode, mode=market_mode)
            return False, self._last_prebuy_reason
        except Exception as e:
            log(f"⚠️ guard code error: {e}")
            reason = f"guard code error: {e}"
            self._last_prebuy_reason = reason
            self._record_reject('guard_code_error', reason)
            self._set_stage('PREBUY_GUARD_CODE_ERROR', symbol=self.symbol, reason=str(e)[:80], activity=activity_mode)
            self._slog('guard_code_error', symbol=self.symbol, reason=reason, code_error=str(e)[:120], activity=activity_mode)
            if bool(getattr(CFG, "PREBUY_FAILSAFE_BLOCK_ON_ERROR", True)):
                return False, reason
            return True, "guard error -> allow"
    def dynamic_order_count(self) -> int:
        """Динамическое число BUY ордеров по ATR% и TRADE_ACTIVITY_MODE."""
        # [FIX-v298-BUG] Было max(1, ...) в трёх местах этого метода — стратегия построена
        # на СТРОГО >=2 ордерах (усреднение), а build_grid() полагается на то, что этот метод
        # уже не даёт 1. Раньше это подстраховывалось только downstream floor'ом в build_grid
        # (v291-1), но здесь сам метод мог вернуть 1 при 'conservative'/малом ORDER_COUNT —
        # несогласованность каждый раз, когда результат читался НЕ через build_grid.
        cap = max(2, min(3, int(self._activity_profile().get('order_count_cap', CFG.ORDER_COUNT) or CFG.ORDER_COUNT)))
        if not bool(getattr(CFG, 'DYNAMIC_ORDERS', False)):
            return max(2, min(cap, int(CFG.ORDER_COUNT)))
        try:
            atr = float(self.atr_pct(interval_min=str(CFG.KLINE_INTERVAL_MIN), period=14, limit=60))
        except Exception:
            atr = 0.0
        high_atr = float(getattr(CFG, 'DYNAMIC_ORDERS_HIGH_ATR', 0.65))
        base = 3 if atr >= high_atr else 2
        mode = str(getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced')).lower()
        if mode == 'conservative':
            base = min(base, 2)
        elif mode == 'active' and atr >= high_atr * 0.8:
            base = 3
        return max(2, min(cap, base))  # [FIX-v298-BUG] было max(1, ...)
    @staticmethod
    def calc_real_adx(highs: List[float], lows: List[float], closes: List[float], period: int = 14) -> float:
        """
        Настоящий ADX по методу Wilder.
        TR → ATR → +DM / -DM → +DI / -DI → DX → ADX (сглаженный).
        Возвращает 0.0 если данных недостаточно.
        """
        n = len(closes)
        if n < period * 2 + 2 or len(highs) < n or len(lows) < n:
            return 0.0
        tr_list: List[float] = []
        pdm_list: List[float] = []
        ndm_list: List[float] = []
        for i in range(1, n):
            h, l, pc = highs[i], lows[i], closes[i - 1]
            tr = max(h - l, abs(h - pc), abs(l - pc))
            up_move = highs[i] - highs[i - 1]
            dn_move = lows[i - 1] - lows[i]
            pdm = up_move if (up_move > dn_move and up_move > 0) else 0.0
            ndm = dn_move if (dn_move > up_move and dn_move > 0) else 0.0
            tr_list.append(tr)
            pdm_list.append(pdm)
            ndm_list.append(ndm)
        def wilder_smooth(data: List[float], p: int) -> List[float]:
            if len(data) < p:
                return []
            s = sum(data[:p])
            result = [s]
            for v in data[p:]:
                s = s - (s / p) + v
                result.append(s)
            return result
        atr_s = wilder_smooth(tr_list, period)
        apdm_s = wilder_smooth(pdm_list, period)
        andm_s = wilder_smooth(ndm_list, period)
        if not atr_s:
            return 0.0
        dx_list: List[float] = []
        for i in range(len(atr_s)):
            if atr_s[i] == 0:
                continue
            pdi = 100.0 * apdm_s[i] / atr_s[i]
            ndi = 100.0 * andm_s[i] / atr_s[i]
            denom = pdi + ndi
            if denom == 0:
                continue
            dx_list.append(100.0 * abs(pdi - ndi) / denom)
        if len(dx_list) < period:
            return 0.0
        adx = sum(dx_list[:period]) / period
        for dx in dx_list[period:]:
            adx = (adx * (period - 1) + dx) / period
        return adx
    @staticmethod
    def calc_rsi_wilder(closes: List[float], period: int = 14) -> float:
        """
        RSI по методу Wilder (стандарт).
        Возвращает 50.0 если данных недостаточно.
        """
        if len(closes) < period + 2:
            return 50.0
        gains: List[float] = []
        losses: List[float] = []
        for i in range(1, len(closes)):
            diff = closes[i] - closes[i - 1]
            gains.append(max(diff, 0.0))
            losses.append(max(-diff, 0.0))
        # Первое среднее — простое (прогрев)
        avg_gain = sum(gains[:period]) / period
        avg_loss = sum(losses[:period]) / period
        # Wilder smoothing
        for i in range(period, len(gains)):
            avg_gain = (avg_gain * (period - 1) + gains[i]) / period
            avg_loss = (avg_loss * (period - 1) + losses[i]) / period
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
    def get_change24h_pct(self, symbol: Optional[str] = None) -> float:
        """24h change percent for current symbol. Returns 0.0 if unavailable."""
        try:
            sym = symbol or self.symbol
            r = call_with_retry(client.get_tickers, category="spot", symbol=sym)
            lst = (r or {}).get("result", {}).get("list", []) or []
            if not lst:
                return 0.0
            t = lst[0]
            # Bybit Unified: price24hPcnt like "0.0123" => 1.23%
            v = t.get("price24hPcnt")
            if v is None:
                return 0.0
            return float(v) * 100.0
        except Exception:
            return 0.0
    def passes_trend_filters(self, symbol: Optional[str] = None) -> bool:
        """
        Расширенный трендовый фильтр + [v217] большие монеты.
        """
        _sym = str(symbol or self.symbol or "").upper()

        # [v217-LARGE-COIN] BTC/ETH/BNB/SOL только при балансе ≥1000 USDT
        # [FIX-v238-1] Убраны SOL/LTC/BCH — они выбираются SMC при малом балансе
        _large = ("BTCUSDT","ETHUSDT","BNBUSDT","AVAXUSDT","DOTUSDT","MATICUSDT","ATOMUSDT")
        if _sym in _large:
            _min_lc = float(getattr(CFG,'LARGE_COIN_MIN_BALANCE_USDT',100.0))  # [FIX-v238-1b] 1000→100 USDT
            try:
                _lc_bal = float(self.get_usdt_balance() or 0.0)
                if _lc_bal < _min_lc:
                    return False
            except Exception:
                pass

        if not CFG.USE_TREND_FILTER:
            return True
        # [FIX-v35-2] TTL-кэш 30с: passes_trend_filters вызывается каждые 2с,
        # без кэша = 90-150 API запросов/мин → rate-limit 429 Bybit.
        _sym = symbol or self.symbol
        _now_tf = time.time()
        try:
            _ttl = float(getattr(CFG, 'TREND_CACHE_TTL_SEC', 10.0))  # [FIX-v141-1] было 30с
            _price_reset_pct = float(getattr(CFG, 'TREND_CACHE_PRICE_RESET_PCT', 0.3))
            _cache_ok = (
                _sym == self.symbol
                and (_now_tf - float(getattr(self, "_trend_cache_ts", 0.0)) < _ttl)
                and getattr(self, "_trend_cache_val", None) is not None
            )
            # [FIX-v141-1] Инвалидация кэша по движению цены: если цена изменилась
            # более чем на TREND_CACHE_PRICE_RESET_PCT% от момента кэширования — сброс.
            if _cache_ok and _price_reset_pct > 0:
                _cached_price = float(getattr(self, "_trend_cache_price", 0.0) or 0.0)
                if _cached_price > 0:
                    try:
                        _cur_px = float(self.get_price() or 0.0)
                        if _cur_px > 0 and abs(_cur_px - _cached_price) / _cached_price * 100.0 > _price_reset_pct:
                            _cache_ok = False  # цена изменилась → принудительный пересчёт
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [passes_trend_filters] {_sw_ex}')
            if _cache_ok:
                return bool(self._trend_cache_val)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [passes_trend_filters] {_sw_ex}')
        # ── Таймфрейм 5m: ОДИН запрос OHLC для всех 5m-фильтров ────────
        limit_5m = max(CFG.EMA_SLOW * 4, 300)
        ohlc_5m = self.get_ohlc(interval_min=CFG.KLINE_INTERVAL_MIN, limit=limit_5m, symbol=symbol)
        closes_5m = ohlc_5m.get("close", [])
        highs_5m  = ohlc_5m.get("high", [])
        lows_5m   = ohlc_5m.get("low", [])
        if len(closes_5m) < CFG.EMA_SLOW + max(10, CFG.EMA_SLOPE_BARS + 2):
            return True
        fast = self.ema(closes_5m, CFG.EMA_FAST)
        slow = self.ema(closes_5m, CFG.EMA_SLOW)
        last_price_5m = closes_5m[-1]
        if fast <= 0 or slow <= 0:
            return True
        # [FIX-v225-5] streak bypass для 5m фильтров.
        # При streak>=60 бот уже искал монеты >15 мин безуспешно — ослабляем 5m блоки.
        # Также: сбрасываем trend_cache при ПЕРВОМ входе в bypass zone (streak==60).
        _ptf_streak_5m = int(getattr(self, '_zero_scan_streak', 0))
        _5m_bypass = _ptf_streak_5m >= 60
        if _5m_bypass and (_ptf_streak_5m == 60 or _ptf_streak_5m % 10 == 0):  # [FIX-v238-4]
            # Первый раз входим в bypass — сбрасываем кэш чтобы следующий вызов пересчитал
            try:
                self._trend_cache_ts = 0.0
                self._trend_cache_val = None
            except Exception: pass
        # 1) Не берём явный даунтренд (fast < slow)
        if fast < slow:
            if _5m_bypass:
                # При bypass: допускаем если разница < 0.15% (боковик)
                _5m_diff = (slow - fast) / slow * 100.0
                if _5m_diff >= 0.15:
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception: pass
                    return False
                log(f"⚡ [v225-5] 5m EMA bypass: fast<slow diff={_5m_diff:.4f}%<0.15% streak={_ptf_streak_5m}")
            else:
                if _sym == self.symbol:
                    try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                    except Exception as _crit_ex:
                        log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                return False
        # 2) Цена должна быть выше EMA_SLOW
        if CFG.TREND_REQUIRE_PRICE_ABOVE_EMA and last_price_5m <= slow:
            if _5m_bypass:
                # При bypass: допускаем если цена выше fast EMA (менее строгий критерий)
                if last_price_5m <= fast:
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception: pass
                    return False
                log(f"⚡ [v225-5] Цена>fast bypass: streak={_ptf_streak_5m}")
            else:
                if _sym == self.symbol:
                    try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                    except Exception as _crit_ex:
                        log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                return False
        # 3) EMA_SLOW должна расти последние N баров (slope)
        n = max(1, int(CFG.EMA_SLOPE_BARS))
        if len(closes_5m) >= CFG.EMA_SLOW + n + 5:
            prev_slow = self.ema(closes_5m[:-n], CFG.EMA_SLOW)
            if prev_slow > 0 and slow <= prev_slow:
                if _5m_bypass:
                    log(f"⚡ [v225-5] EMA slope bypass: streak={_ptf_streak_5m}")
                else:
                    if _sym == self.symbol:
                        try:
                            self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception as _crit_ex:
                            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                    return False
        # ── 4) 1H EMA28 направлена вверх ───────────────────────────────
        try:
            closes_1h = self.get_closes(interval="60", limit=200, symbol=symbol)
            # [FIX-v225-2] Bypass жёстких 1H EMA блоков при длинном streak.
            # КОРНЕВАЯ ПРОБЛЕМА: при ночном медвежьем рынке EMA9(1H) < EMA21(1H) ВСЕГДА.
            # Мозг снижает ADX/RSI/turnover но НЕ МОЖЕТ ослабить этот фильтр.
            # Результат: 0 сделок за 12 часов даже при streak=190+.
            # Исправление: при streak >= 60 ослабляем жёсткие 1H EMA блоки:
            # - EMA9 < EMA21 → допускаем если разница < 0.3% (почти горизонталь)
            # - Цена < EMA7*1.001 → допускаем если цена выше EMA7 (убираем 0.1% буфер)
            _ptf_streak = int(getattr(self, '_zero_scan_streak', 0))
            _ptf_ema_bypass = _ptf_streak >= 60  # 60 пустых сканов = ~15 мин
            if len(closes_1h) >= 40:
                ema28_1h_series = self.ema_series(closes_1h, 28)
                if len(ema28_1h_series) >= 4:
                    tail = ema28_1h_series[-3:]
                    ema28_1h_rising = all(tail[i] < tail[i + 1] for i in range(len(tail) - 1))
                    if not ema28_1h_rising:
                        if len(closes_1h) >= 25:
                            ema9_1h = self.ema(closes_1h, 9)
                            ema21_1h = self.ema(closes_1h, 21)
                            if ema9_1h < ema21_1h:
                                if _ptf_ema_bypass:
                                    log(f"⚡ [v225-2] 1H EMA bypass streak={_ptf_streak}: EMA9<EMA21 но продолжаем")
                                else:
                                    log(f"⛔ [FIX-16A] 1H тренд вниз: EMA9={ema9_1h:.6f} < EMA21={ema21_1h:.6f} → блок")
                                    if _sym == self.symbol:
                                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                                        except Exception as _crit_ex: log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                                    return False
                        log(f"⚠️ 1H EMA28 не растёт (EMA9>EMA21, только лог)")
                    if closes_1h[-1] <= ema28_1h_series[-1] and not ema28_1h_rising:
                        if not _ptf_ema_bypass:
                            log(f"⛔ [FIX-16A] Цена {closes_1h[-1]:.6f} ниже 1H EMA28={ema28_1h_series[-1]:.6f} → блок")
                            if _sym == self.symbol:
                                try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                                except Exception as _crit_ex: log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                            return False
                    if len(closes_1h) >= 25:
                        _ema9_audit = self.ema(closes_1h, 9)
                        _ema21_audit = self.ema(closes_1h, 21)
                        if _ema9_audit > 0 and _ema21_audit > 0 and _ema9_audit < _ema21_audit * 1.0002:
                            if _ptf_ema_bypass:
                                # При bypass: допускаем если разница < 0.3%
                                _diff_pct = (_ema21_audit - _ema9_audit) / _ema21_audit * 100.0
                                if _diff_pct >= 0.3:
                                    log(f"⛔ [v225-2] 1H EMA9 diff={_diff_pct:.3f}%>=0.3% — слишком сильный даунтренд")
                                    if _sym == self.symbol:
                                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                                        except Exception as _crit_ex: log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                                    return False
                                log(f"⚡ [v225-2] EMA9<EMA21 bypass: diff={_diff_pct:.3f}%<0.3% streak={_ptf_streak}")
                            else:
                                log(f"⛔ [FIX-v139-B] 1H EMA9={_ema9_audit:.6f} < EMA21={_ema21_audit:.6f} → тренд вниз")
                                if _sym == self.symbol:
                                    try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                                    except Exception as _crit_ex: log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                                return False
                        if len(closes_1h) >= 9:
                            _ema7_1h_tf = self.ema(closes_1h, 7)
                            _cur_1h_close = float(closes_1h[-1])
                            if _ema7_1h_tf > 0 and _cur_1h_close < _ema7_1h_tf * 1.001:
                                if _ptf_ema_bypass and _cur_1h_close >= _ema7_1h_tf:
                                    # При bypass убираем 0.1% буфер — достаточно что цена выше EMA7
                                    log(f"⚡ [v225-2] EMA7(1H) буфер bypass: цена выше EMA7 streak={_ptf_streak}")
                                else:
                                    log(f"⛔ [FIX-v139-A] Цена({_cur_1h_close:.6f})<EMA7_1H({_ema7_1h_tf:.6f})×1.001 → блок")
                                    if _sym == self.symbol:
                                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                                        except Exception as _crit_ex: log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                                    return False
        except Exception as _crit_ex:
            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
        # ── 5) ADX > ADX_MIN — сила тренда ─────────────────────────────
        # [FIX-v141-2] ADX переведён с 5m на 1H данные — унификация с scan_market_top.
        # Ранее: ADX(5m) в trend_filter vs ADX(1H) в сканере — один порог для разных ТФ.
        # Теперь оба уровня используют ADX(1H) → сравнение корректное.
        # 1H OHLC уже загружены для EMA28 выше — дополнительных запросов нет.
        try:
            # [FIX-v191-1] ГЛАВНЫЙ БАГ: использовать SCANNER_ADX_MIN (ослабляемый)
            # а не CFG.ADX_MIN (фиксированный по режиму)!
            # Иначе: auto-relaxation снижает SCANNER_ADX_MIN до 14,
            # но FIX-v141-2 всё равно блокирует по CFG.ADX_MIN=22 → 0 торгов!
            adx_min_val = float(getattr(CFG,'SCANNER_ADX_MIN',
                                getattr(CFG,'ADX_MIN',20.0)))
            # Используем 1H данные (closes_1h, highs_1h, lows_1h) уже загруженные в секции 4)
            _tf1h_for_adx = self.get_ohlc(interval_min="60", limit=50, symbol=symbol)
            _h1h = _tf1h_for_adx.get("high", [])
            _l1h = _tf1h_for_adx.get("low", [])
            _c1h = _tf1h_for_adx.get("close", [])
            adx_period_tf = 14
            if (len(_c1h) >= adx_period_tf * 2 + 5
                    and len(_h1h) >= adx_period_tf * 2 + 5
                    and len(_l1h) >= adx_period_tf * 2 + 5):
                adx_val_1h = self.calc_real_adx(_h1h, _l1h, _c1h, period=adx_period_tf)
                # [FIX-v170-1] Сохраняем для BotKnowledge — иначе log_trade_entry получает ADX=0!
                if adx_val_1h > 0:
                    self._ptf_last_adx = adx_val_1h
                if adx_val_1h > 0 and adx_val_1h < adx_min_val:
                    log(f"⛔ [FIX-v141-2] ADX(1H)={adx_val_1h:.1f}<{adx_min_val:.1f} → слабый тренд, блок")
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception as _crit_ex:  # [v145-silent]
                            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                    return False
        except Exception as _crit_ex:  # [v145-silent]
            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
        # ── 6) RSI не перекуплен — используем 15m данные ──────────────
        # [FIX-v141-3] RSI переведён с 5m на 15m — унификация с scan_market_top.
        # Ранее: RSI(5m) в trend_filter vs RSI(15m) в сканере → несоответствие.
        # Теперь оба уровня используют RSI(15m).
        try:
            # [FIX-v191-4] Использовать SCANNER_RSI_MAX (ослабляемый мозгом)
            # а не CFG.RSI_OVERBOUGHT (фиксированный по режиму)!
            rsi_max = float(getattr(CFG,'SCANNER_RSI_MAX',
                            getattr(CFG,'RSI_OVERBOUGHT',65.0)))
            _closes_15m_rsi = self.get_closes(interval="15", limit=30, symbol=symbol)
            if _closes_15m_rsi and len(_closes_15m_rsi) >= 16:
                rsi_val_15m = self.calc_rsi_wilder(_closes_15m_rsi, period=14)
                # [FIX-v170-1] Сохраняем для BotKnowledge — иначе log_trade_entry получает RSI=0!
                if rsi_val_15m > 0:
                    self._ptf_last_rsi = rsi_val_15m
                if rsi_val_15m >= rsi_max:
                    log(f"⛔ [FIX-v141-3] RSI(15m)={rsi_val_15m:.1f}>={rsi_max:.1f} → перекуплен, блок")
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception as _crit_ex:  # [v145-silent]
                            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                    return False
                # [FIX-v142-3] RSI нижняя граница — синхронизация со сканером.
                # Сканер блокирует RSI < SCANNER_RSI_MIN (медвежий RSI), но trend_filter не делал этого.
                # Монета с RSI=25 (перепродана/медвежий сигнал) пройдёт trend_filter.
                _rsi_min_tf = float(getattr(CFG, 'SCANNER_RSI_MIN', 35.0))
                if _rsi_min_tf > 0 and rsi_val_15m > 0 and rsi_val_15m < _rsi_min_tf:
                    log(f"⛔ [FIX-v142-3] RSI(15m)={rsi_val_15m:.1f}<{_rsi_min_tf:.1f} → медвежий RSI, блок")
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception as _crit_ex:  # [v145-silent]
                            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                    return False
            else:
                # Fallback на 5m RSI если 15m данных не хватает
                rsi_val = self.calc_rsi_wilder(closes_5m, period=14)
                if rsi_val >= rsi_max:
                    if _sym == self.symbol:
                        try: self._trend_cache_val = False; self._trend_cache_ts = _now_tf
                        except Exception as _crit_ex:  # [v145-silent]
                            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
                    return False
        except Exception as _crit_ex:  # [v145-silent]
            log(f'⚠️ [passes_trend_filters] {_crit_ex}')
        # [FIX-v35-2] сохраняем результат в кэш только для текущего символа
        if _sym == self.symbol:
            try:
                self._trend_cache_val = True
                self._trend_cache_ts = _now_tf
                # [FIX-v141-1] Сохраняем текущую цену для инвалидации кэша по движению
                try:
                    self._trend_cache_price = float(self.get_price() or 0.0)
                except Exception:
                    self._trend_cache_price = 0.0
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [passes_trend_filters] {_sw_ex}')
        # [FIX-v170-1] Передаём реальные ADX/RSI в log_trade_entry через self атрибуты.
        # Ключевой баг v169: _last_adx_val/_last_rsi_val никогда не устанавливались →
        # BotKnowledge записывал ADX=0/RSI=0 для всех сделок → анализ был бесполезен!
        # Теперь: passes_trend_filters сохраняет _ptf_last_adx/rsi → process_fills читает.
        try:
            self._last_adx_val = float(getattr(self, '_ptf_last_adx', 0.0) or 0.0)
            self._last_rsi_val = float(getattr(self, '_ptf_last_rsi', 0.0) or 0.0)
        except Exception as _ptf_ex:  # [FIX-v170-4]
            log(f"⚠️ [passes_trend_filters] ptf_last transfer: {_ptf_ex}")
        return True
    def is_downtrend(self) -> bool:
        """Backward-compat alias."""
        return not self.passes_trend_filters()
    # ---------- Balances ----------
    def get_coin_balance(self, coin: str) -> float:
        data = call_with_retry(client.get_wallet_balance, accountType="UNIFIED", coin=coin)
        lst = data.get("result", {}).get("list", []) or []
        if not lst:
            return 0.0
        coins = lst[0].get("coin", []) or []
        for c in coins:
            if c.get("coin") == coin:
                # [FIX-v174-1] Bybit возвращает '' вместо '0' для монет с нулевым балансом.
                # float('') вызывает ValueError → спам ошибок в логе.
                # Исправление: заменяем пустую строку на '0' перед float().
                try:
                    wb = c.get("walletBalance")
                    if wb is not None:
                        wb_str = str(wb).strip()
                        return float(wb_str) if wb_str else 0.0
                except Exception as _sw_ex:
                    log(f'⚠️ [get_coin_balance] {_sw_ex}')
                for key in ("availableBalance", "availableToWithdraw", "free"):
                    val = c.get(key)
                    if val is not None:
                        try:
                            val_str = str(val).strip()
                            return float(val_str) if val_str else 0.0
                        except Exception as _sw_ex:
                            log(f'⚠️ [get_coin_balance] {_sw_ex}')
                return 0.0
        return 0.0
    def get_last_price(self, symbol: Optional[str] = None) -> float:
        """Get last price for symbol (self.symbol if None). Backward-compat alias."""
        if symbol and symbol != self.symbol:
            try:
                t = self.get_ticker(symbol=symbol)
                return float(t.get("lastPrice") or 0.0)
            except Exception:
                return 0.0
        return self.get_price()
    def get_spot_balances(self) -> dict:
        """Fallback helper: return {coin: qty} dict from UNIFIED wallet."""
        result: dict = {}
        try:
            data = call_with_retry(client.get_wallet_balance, accountType="UNIFIED")
            lst = (data or {}).get("result", {}).get("list", []) or []
            if lst:
                for c in lst[0].get("coin", []) or []:
                    coin = (c.get("coin") or "").upper()
                    qty = float(c.get("walletBalance") or 0.0)
                    if coin and qty > 0:
                        result[coin] = qty
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [get_spot_balances] {_sw_ex}')
        return result
    def get_usdt_balance(self) -> float:
        return self.get_coin_balance("USDT")
    def get_base_balance(self) -> float:
        return self.get_coin_balance(self.base)

    def _auto_resume_after_idle(self):
        """[FIX-v272-3] Авто-возобновление скана при простое без позиции.
        Защита от зависания после ошибки когда бот перестаёт искать монеты."""
        try:
            _has_pos = (self.pos.base_qty or 0) > 0
            if _has_pos:
                return
            if self.manual_only_sell and not self._daily_hard_locked and not self._daily_soft_applied:
                _idle = time.time() - float(getattr(self, '_last_trade_ts', 0) or 0)
                if _idle > 300:
                    log("🔄 [v272-3] Авто-возобновление: нет позиции 5+ мин → снимаю only_sell")
                    self.manual_only_sell = False
                    if TG.enabled:
                        TG.send("🔄 Авто-возобновление торговли (простой без позиции)")
        except Exception as _ar_ex:
            log(f"⚠️ [_auto_resume] {_ar_ex}")

    def _mark_smc_signal_closed(self):
        """[FIX-v270-1] Помечает SMC сигнал по текущей монете как закрытый.
        Без этого smc_bot держит паузу скана пока valid_until не истечёт (10 мин),
        думая что мы ещё в позиции. Сбрасываем чтобы SMC сразу возобновил скан."""
        try:
            _sf = os.path.join(BASE_DIR, "smc_signals.json")
            if not os.path.exists(_sf):
                return
            with open(_sf, 'r', encoding='utf-8') as _f:
                _sd = json.load(_f)
            if not isinstance(_sd, dict):
                return
            _changed = False
            for _s in (_sd.get("signals") or []):
                if isinstance(_s, dict) and _s.get("symbol") == self.symbol:
                    # [FIX-v272-BUG4] убрана проверка v170_trade_result — закрываем
                    # SMC сигнал при ЛЮБОМ выходе из монеты (TP, SL, dump, time_stop)
                    _s["v170_trade_result"] = "closed_by_v272"
                    _s["valid_until"] = 0
                    _changed = True
            if _changed:
                with open(_sf, 'w', encoding='utf-8') as _f:
                    json.dump(_sd, _f, ensure_ascii=False, indent=2)
                log(f"📝 [v270-1] SMC сигнал {self.symbol} закрыт → SMC возобновит скан")
        except Exception as _mc_ex:
            log(f"⚠️ [_mark_smc_signal_closed] {_mc_ex}")

    def remainder_value_usdt(self, current_price: Optional[float] = None) -> float:
        try:
            px = float(current_price if current_price is not None else (self.get_last_price(self.symbol) or 0.0))
        except Exception:
            px = 0.0
        try:
            qty = float(self.get_base_balance() or 0.0)
        except Exception:
            qty = float(getattr(self.pos, 'base_qty', 0.0) or 0.0)
        return max(0.0, qty * max(px, 0.0))
    def remainder_below_exchange_min(self, current_price: Optional[float] = None) -> bool:
        if self.filters is None:
            return False
        try:
            bal_qty = floor_to_step(float(self.get_base_balance() or 0.0), float(self.filters.qty_step or 0.0))
        except Exception:
            bal_qty = floor_to_step(float(getattr(self.pos, 'base_qty', 0.0) or 0.0), float(self.filters.qty_step or 0.0))
        if bal_qty <= 0:
            return False
        min_qty = float(getattr(self.filters, 'min_qty', 0.0) or 0.0)
        if bal_qty < max(min_qty, float(getattr(self.filters, 'qty_step', 0.0) or 0.0)):
            return False
        v = self.remainder_value_usdt(current_price)
        # [FIX-v98] remainder_below_exchange_min = qty < min_qty ИЛИ value < min_amt
        # Bybit ErrCode 170140 применяется к SELL тоже — проверяем обе границы
        dust = float(getattr(CFG, 'DUST_USDT_THRESHOLD', 3.5) or 3.5)
        if v < dust:
            return True  # пыль по стоимости
        # Проверяем min_amt биржи (для SELL тоже!)
        min_amt = float(getattr(self.filters, 'min_amt', 0.0) or 0.0)
        if min_amt > 0 and v < min_amt:
            return True  # стоимость ниже биржевого минимума → нельзя продать
        return False
    def has_live_remainder(self, current_price: Optional[float] = None) -> bool:
        if self.filters is None:
            return False
        try:
            bal_qty = floor_to_step(float(self.get_base_balance() or 0.0), float(self.filters.qty_step or 0.0))
        except Exception:
            bal_qty = floor_to_step(float(getattr(self.pos, 'base_qty', 0.0) or 0.0), float(self.filters.qty_step or 0.0))
        if bal_qty <= 0:
            return False
        min_qty = float(getattr(self.filters, 'min_qty', 0.0) or 0.0)
        if bal_qty < max(min_qty, float(getattr(self.filters, 'qty_step', 0.0) or 0.0)):
            return False
        v = self.remainder_value_usdt(current_price)
        # [FIX-30E] Remainder живой если qty > min_qty на бирже
        # Используем DUST_USDT_THRESHOLD только как нижнюю границу пыли
        live_min = float(getattr(CFG, 'DUST_USDT_THRESHOLD', 3.5) or 3.5)
        return v >= live_min
    def remainder_open_sell_ok(self, open_orders: Optional[List[Dict]] = None, current_price: Optional[float] = None) -> bool:
        if self.filters is None:
            return False
        opens = open_orders if isinstance(open_orders, list) else self.get_open_orders()
        sell_qty = floor_to_step(self._sum_open_sell_qty(opens), self.filters.qty_step)
        try:
            bal_qty = floor_to_step(float(self.get_base_balance() or 0.0), self.filters.qty_step)
        except Exception:
            bal_qty = floor_to_step(float(getattr(self.pos, 'base_qty', 0.0) or 0.0), self.filters.qty_step)
        if bal_qty <= 0:
            return False
        px = float(current_price if current_price is not None else (self.get_last_price(self.symbol) or 0.0))
        # [FIX-v98] Проверяем qty И min_amt для SELL остатка
        _rem_min_amt = float(getattr(self.filters, 'min_amt', 0.0) or 0.0)
        _rem_value = float(bal_qty * px)
        if bal_qty < self.filters.min_qty or (_rem_min_amt > 0 and _rem_value < _rem_min_amt):
            self._remainder_below_min_mode = True
            self._remainder_last_value_usdt = _rem_value
            return True  # ниже биржевого минимума — считаем "ok" (не спамим попытками)
        return sell_qty >= max(0.0, bal_qty - self.filters.qty_step * 2)
    def ensure_sell_for_remainder(self, current_price: Optional[float] = None) -> bool:
        if self.remainder_below_exchange_min(current_price):
            self._remainder_below_min_mode = True
            self._remainder_last_value_usdt = self.remainder_value_usdt(current_price)
            _dust_val = self._remainder_last_value_usdt
            _min_amt = float(getattr(self.filters, 'min_amt', 0.0) or 0.0) if self.filters else 0.0
            _threshold = max(float(getattr(CFG, 'SELL_MIN_USDT', 1.5) or 1.5), _min_amt)
            log(f"ℹ️ [v98] Остаток {_dust_val:.4f} USDT < {_threshold:.4f} USDT (min_amt={_min_amt:.4f}) — продать невозможно, сбрасываем ONLY-SELL")
            # [FIX-27A] Пыль нельзя продать → выходим из ONLY-SELL чтобы бот продолжил торговать
            if bool(getattr(self, 'manual_only_sell', False)) is False:  # только если не ручной режим
                self.only_sell = False
                self._remainder_mode = False
                self._remainder_since_ts = 0.0
                self.pos = PositionState()  # сбрасываем позицию
                self._averaging_active = False  # [FIX-v184-4] сброс при закрытии
                self.grid_prices = []
                self.grid_buy_ids = []
                if TG.enabled:
                    TG.send(f"🧹 Пыль {_dust_val:.4f} USDT ({self.symbol}) — слишком мала для продажи. Продолжаю торговать.")
            return True
        if not self.has_live_remainder(current_price):
            return False
        opens = self.get_open_orders()
        if self.remainder_open_sell_ok(opens, current_price):
            return True
        try:
            self.cancel_open_sell_orders()
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [ensure_sell_for_remainder] {_sw_ex}')  # [FIX-v151-1]
        ok = self.safety_ensure_sell(current_price=current_price, open_orders=[])
        self._remainder_last_guard_ts = time.time()
        return bool(ok)
    def finalize_trade_only_when_flat(self, current_price: Optional[float] = None) -> bool:
        try:
            px = float(current_price if current_price is not None else (self.get_last_price(self.symbol) or 0.0))
        except Exception:
            px = 0.0
        # 1) full live remainder blocks finalize
        if self.has_live_remainder(px):
            self._remainder_mode = True
            self._remainder_below_min_mode = False
            if not self._remainder_since_ts:
                self._remainder_since_ts = time.time()
            self._remainder_last_value_usdt = self.remainder_value_usdt(px)
            # [FIX-TAIL-B] Timeout защита: если remainder висит дольше порога
            # без SELL ордера — принудительно чистим чтобы не зависать вечно.
            # Watchdog из FIX-BUG9A должен был поставить SELL — если не смог,
            # значит монета не продаётся (spread, делистинг, ошибка API).
            _rem_timeout = float(getattr(CFG, 'REMAINDER_FORCE_CLEAR_SEC', 600) or 600)
            _rem_elapsed = time.time() - float(getattr(self, '_remainder_since_ts', time.time()) or time.time())
            if _rem_elapsed > _rem_timeout:
                try:
                    _rem_sell_ok = self.remainder_open_sell_ok(None, px)
                    if not _rem_sell_ok:
                        log(f"⚠️ [TAIL-B] Remainder timeout {_rem_elapsed:.0f}s без SELL — принудительная очистка")
                        if TG.enabled:
                            TG.send_throttled('remainder_timeout',
                                f"⚠️ Remainder {self.symbol} висит {_rem_elapsed/60:.1f} мин без SELL ордера.\n"
                                f"Принудительно сбрасываю состояние. Проверь баланс!",
                                cooldown_sec=300, only_on_change=True)
                        self._remainder_mode = False
                        self._remainder_since_ts = 0.0
                        self._remainder_last_guard_ts = 0.0
                        self.pos = PositionState()
                        return True  # финализируем несмотря на остаток
                except Exception as _tb:
                    log(f"⚠️ [TAIL-B] timeout check error: {_tb}")
            return False
        # 1.5) below-exchange-min remainder is tracked separately and does not trigger SELL spam
        if self.remainder_below_exchange_min(px):
            self._remainder_mode = False
            self._remainder_below_min_mode = True
            self._remainder_last_value_usdt = self.remainder_value_usdt(px)
        else:
            self._remainder_below_min_mode = False
        # 2) do not finalize while active SELL protection still exists for non-dust amount
        try:
            opens = self.get_open_orders()
        except Exception:
            opens = []
        try:
            sell_qty = floor_to_step(self._sum_open_sell_qty(opens), float(getattr(self.filters, 'qty_step', 0.0) or 0.0)) if self.filters else 0.0
        except Exception:
            sell_qty = 0.0
        # [FIX-26] порог для sell_qty проверки = DUST_USDT_THRESHOLD
        if sell_qty > 0 and px > 0 and (sell_qty * px) > float(getattr(CFG, 'DUST_USDT_THRESHOLD', 3.5) or 3.5):
            self._remainder_mode = True
            if not self._remainder_since_ts:
                self._remainder_since_ts = time.time()
            return False
        self._remainder_mode = False
        self._remainder_below_min_mode = False
        self._remainder_since_ts = 0.0
        self._remainder_last_guard_ts = 0.0
        self._remainder_last_value_usdt = 0.0
        self.pnl.position_remaining_qty = 0.0
        self.pnl.position_remaining_cost = 0.0
        self.pos = PositionState()
        return True
    # ---------- Orders ----------
    def get_open_orders(self, symbol: Optional[str] = None) -> List[Dict]:
        # [FIX-BUG9B] принимает явный symbol для отмены ордеров старой монеты
        sym = str(symbol or self.symbol)
        res = call_with_retry(client.get_open_orders, category="spot", symbol=sym)
        return res.get("result", {}).get("list", []) or []
    def _sum_open_sell_qty(self, open_orders: List[Dict]) -> float:
        """Sum qty of open SELL limit orders (best-effort parsing)."""
        total = 0.0
        for o in open_orders or []:
            try:
                if str(o.get("side", "")).lower() != "sell":
                    continue
                q = o.get("qty") or o.get("origQty") or o.get("leavesQty") or o.get("qtyRemaining")
                total += float(q or 0.0)
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                pass  # intentionally silent: {_sw_ex}
        return total
    def cancel_all_open_orders(self, symbol: Optional[str] = None):
        # [FIX-BUG9B] принимает явный symbol — позволяет отменять ордера
        # старой монеты ДО смены self.symbol в do_switch()
        sym = str(symbol or self.symbol)
        log("🧹 Clearing open orders...")
        try:
            opens = self.get_open_orders(symbol=sym)
            for o in opens:
                oid = o.get("orderId")
                if oid:
                    try:
                        call_with_retry(client.cancel_order, category="spot", symbol=sym, orderId=oid)
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [cancel_all_open_orders] {_sw_ex}')  # [FIX-v151-1]
            log("🧹 Orders cleared")
        except Exception as e:
            log(f"⚠️ cancel_all_open_orders error: {e}")
    def cancel_open_sell_orders(self):
        """Cancel only open SELL orders and keep BUY grid intact."""
        try:
            opens = self.get_open_orders()
            for o in opens:
                try:
                    if str(o.get("side", "")).lower() != "sell":
                        continue
                    oid = o.get("orderId")
                    if oid:
                        call_with_retry(client.cancel_order, category="spot", symbol=self.symbol, orderId=oid)
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [cancel_open_sell_orders] {_sw_ex}')  # [FIX-v154]
            return True
        except Exception as e:
            log(f"⚠️ cancel_open_sell_orders error: {e}")
            return False
    def cancel_order(self, order_id: str):
        try:
            call_with_retry(client.cancel_order, category="spot", symbol=self.symbol, orderId=order_id)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [cancel_order] {_sw_ex}')  # [FIX-v151-1]
    # ---------- TP logic ----------
    def _sell_meets_min_amt(self, qty: float, price: float) -> bool:
        """Проверяет что SELL ордер удовлетворяет минимальной сумме Bybit.
        ErrCode 170140 = Order value exceeded lower limit — применяется к SELL тоже!
        """
        if self.filters is None:
            return False
        f = self.filters
        if qty < f.min_qty:
            return False
        # min_amt = minOrderAmt из Bybit API — реальный минимум суммы ордера
        if f.min_amt > 0 and (qty * price) < f.min_amt:
            return False
        return True

    def _place_limit_sell_qty_price(self, qty: float, price: float, note: str = "") -> bool:
        """Place a GTC limit SELL order.
        Returns True on success, False on failure.
        [FIX-v129-1] Also stores last placed orderId in self._last_limit_sell_oid
        so callers (rotation_exit, sideways_switch) can add it to _emergency_sell_ids
        when _record_emergency_exit_pnl was already called before the fill.
        """
        self._last_limit_sell_oid: str = ""  # reset each call
        self._set_stage('ORDER_PREPARE_SELL', symbol=self.symbol, price=f'{float(price or 0.0):.8f}')
        if self.filters is None:
            return False
        f = self.filters
        qty = floor_to_step(float(qty or 0.0), f.qty_step)
        price = ceil_to_step(float(price or 0.0), f.tick_size)
        if qty <= 0 or price <= 0:
            return False
        try:
            # [FIX-v98] Bybit ErrCode 170140 = Order value too LOW — применяется к SELL тоже!
            # FIX-30 был НЕВЕРНЫМ: "min_amt только для BUY" — это не так.
            # На фото: NEARUSDT qty=1.80, price=1.264 = 2.27 USDT < 5 USDT min_amt → 170140 x6 ретраев.
            # Восстанавливаем обе проверки: qty >= min_qty И qty*price >= min_amt.
            if qty < f.min_qty:
                log(f"ℹ️ SELL skipped: qty={qty:.6f} < min_qty={f.min_qty:.6f} [{note}]")
                return False
            if f.min_amt > 0 and (qty * price) < f.min_amt:
                log(f"ℹ️ SELL skipped: value={qty*price:.4f} USDT < min_amt={f.min_amt:.4f} USDT [{note}]")
                return False
            if bool(getattr(CFG, 'DRY_RUN_ONLY', False)):
                log(f"🧪 DRY RUN SELL @ {fmt_by_step_ceil(price,f.tick_size)} | qty={fmt_by_step(qty,f.qty_step)} {note}")
                self._set_stage('ORDER_SENT_SELL_DRY', symbol=self.symbol)
                return True
            # [FIX-v297-BUG] orderLinkId — фиксируем ДО retry-цикла, чтобы повторная отправка
            # при таймауте не создала дублирующий SELL (см. new_order_link_id()).
            _link_id = new_order_link_id("sell")
            _resp = call_with_retry(
                client.place_order,
                category="spot",
                symbol=self.symbol,
                side="Sell",
                orderType="Limit",
                timeInForce="GTC",
                qty=fmt_by_step(qty, f.qty_step),
                price=fmt_by_step_ceil(price, f.tick_size),
                orderLinkId=_link_id
            )
            # [FIX-v129-1] Сохраняем orderId чтобы rotation_exit/sideways_switch могли
            # добавить его в _emergency_sell_ids, предотвращая двойной счёт PnL.
            try:
                _oid = (_resp or {}).get("result", {}).get("orderId", "")
                self._last_limit_sell_oid = str(_oid) if _oid else ""
            except Exception:
                self._last_limit_sell_oid = ""
            self._set_stage('ORDER_SENT_SELL', symbol=self.symbol, price=fmt_by_step_ceil(price,f.tick_size), qty=fmt_by_step(qty,f.qty_step))
            log(f"🔴 SELL placed @ {fmt_by_step_ceil(price,f.tick_size)} | qty={fmt_by_step(qty,f.qty_step)} [{note}]")
            return True
        except Exception as e:
            log(f"⚠️ ERROR SELL {note}: {e}")
            return False
    def calc_smart_tp_pct(self) -> float:
        if CFG.MANUAL_TP_PCT is not None:
            return float(CFG.MANUAL_TP_PCT)
        try:
            atr_pct = float(self.atr_pct(interval_min="5", period=14, limit=120) or 0.0)
        except Exception:
            atr_pct = 0.0
        try:
            impulse_pct = abs(float(self.recent_change_pct(interval="5") or 0.0))
        except Exception:
            impulse_pct = 0.0
        try:
            turnover = float((self.get_ticker() or {}).get("turnover24h") or 0.0)
        except Exception:
            turnover = 0.0
        base = float(self.compute_tp_pct())

        # [FIX-v235-1] ATR + ADX DYNAMIC TP — следует за движением монеты.
        # Проблема: фиксированный TP=1% упускал движения на 2-5%.
        # При росте на +2%: бот закрывался на +1%, остальное упускалось.
        # Решение: TP = max(min_tp, ATR × ATR_TP_MULT) + ADX надбавка.
        #
        # Таблица TP по режиму рынка:
        # Тихий   (ADX<15): TP= 0.6-0.9%  trail_start=0.5% trail_dist=0.25%
        # Активный(ADX15-30):TP=0.9-1.8%  trail_start=0.8% trail_dist=0.40%
        # Сильный (ADX>30):  TP=1.8-3.5%  trail_start=1.2% trail_dist=0.60%
        # Импульс (ADX>45):  TP=2.5-5.0%  trail_start=1.8% trail_dist=0.80%
        try:
            _adx_now = float(getattr(self, '_ptf_last_adx', 0.0) or 0.0)
            if _adx_now <= 0:
                _adx_now = float(getattr(CFG, 'SCANNER_ADX_MIN', 20.0))

            # Динамический TP на основе ATR монеты
            _atr_tp_mult = float(getattr(CFG, 'ATR_TP_MULT', 2.5))
            _tp_min = float(getattr(CFG, 'DYNAMIC_TP_MIN_PCT', 0.60))
            _tp_max_dyn = float(getattr(CFG, 'DYNAMIC_TP_MAX_PCT', 5.0))

            if atr_pct > 0:
                _atr_based_tp = atr_pct * _atr_tp_mult
                _atr_based_tp = max(_tp_min, min(_tp_max_dyn, _atr_based_tp))
            else:
                _atr_based_tp = base

            # ADX надбавка: чем сильнее тренд — тем дальше держим
            if _adx_now < 15:
                # [FIX-v236] Тихий рынок ADX<15: TP_MIN=0.90% (не 0.60%).
                # Причина: при SL=1.2% и TP=0.60-0.75% → WR_BEP=71.8% — недостижимо.
                # При TP=0.90%: net=0.70%, WR_BEP=66.7% — всё равно строгий, но реальный.
                # На тихом рынке бот всё равно мало торгует (ADX<15 фильтруется сканером).
                _adx_tp = max(1.40, min(1.80, _atr_based_tp))  # [v290-2] было max(0.95,...): чистый TP при 0.95%=0.75%<SL_net=1.00% = УБЫТОК!
                _new_trail_start = 0.50
                _new_trail_dist  = 0.25
            elif _adx_now < 30:
                # Активный рынок
                _adx_tp = max(1.40, min(1.80, _atr_based_tp))  # [v290-2] было max(0.80,...): ADX<30 теперь min TP=1.40%
                _new_trail_start = 0.80
                _new_trail_dist  = 0.40
            elif _adx_now < 45:
                # Сильный тренд — держим дольше
                _adx_tp = max(1.50, min(3.50, _atr_based_tp * 1.3))
                _new_trail_start = 1.20
                _new_trail_dist  = 0.60
            else:
                # Импульс — максимальная цель
                _adx_tp = max(2.00, min(5.00, _atr_based_tp * 1.8))
                _new_trail_start = 1.80
                _new_trail_dist  = 0.80

            # Обновляем trailing параметры под текущий ADX
            _old_trail_s = float(getattr(CFG, 'TRAIL_START_PCT', 0.7))
            _old_trail_d = float(getattr(CFG, 'TRAIL_DISTANCE_PCT', 0.5))
            if abs(_new_trail_start - _old_trail_s) > 0.05:
                CFG.TRAIL_START_PCT    = _new_trail_start
                CFG.TRAIL_DISTANCE_PCT = _new_trail_dist
                log(f"📈 [v235] Trailing обновлён: start={_new_trail_start:.2f}% dist={_new_trail_dist:.2f}% (ADX={_adx_now:.0f})")

            # Финальный TP: взвешенное среднее base + dynamic
            tp = base * 0.3 + _adx_tp * 0.7
            log(f"📊 [v235] Dynamic TP: ATR={atr_pct:.3f}% ADX={_adx_now:.0f} → TP={tp:.3f}% (atr_based={_atr_based_tp:.3f}%)")
        except Exception as _dtp_ex:
            log(f"⚠️ [v235 dynamic_tp] {_dtp_ex}")
            tp = base

        tp += max(0.0, atr_pct) * float(getattr(CFG, "SMART_TP_ATR_MULT", 0.35))
        if impulse_pct >= float(getattr(CFG, "IMPULSE_CANDLE_PCT_5M", 0.70)):
            tp += float(getattr(CFG, "SMART_TP_IMPULSE_BOOST", 0.12))
        if 0 < turnover < float(getattr(CFG, "SMART_TP_LIQ_THRESHOLD", 5_000_000.0)):
            tp -= float(getattr(CFG, "SMART_TP_LOW_LIQ_PENALTY", 0.10))
        # [FIX-v184-3] Мозг корректирует TP на основе ADX + RSI + истории монеты
        try:
            _brain_adx = float(getattr(self, '_ptf_last_adx', 0.0) or 0.0)
            _brain_rsi = float(getattr(self, '_ptf_last_rsi', 0.0) or 0.0)
            if _brain_adx >= 20.0 and _brain_rsi >= 20.0:
                _brain_tp = self.knowledge.get_smart_tp(_brain_adx, _brain_rsi, self.symbol)
                _tp_before_brain = tp
                tp = tp * 0.4 + _brain_tp * 0.6
                # [v290-3] Запрет снижать TP ниже минимума через brain корректировку
                # Проблема: brain_tp=0.80% + наш tp=1.40% → результат=1.04% — НИЖЕ МИНИМУМА!
                _brain_tp_min = float(getattr(CFG, 'STOP_LOSS_PCT', 0.80)) + 0.60
                _brain_tp_min = max(1.40, _brain_tp_min)
                if tp < _brain_tp_min:
                    log(f"🛡️ [v290-3] brain_tp снизил TP {_tp_before_brain:.3f}→{tp:.3f}% — поднят до {_brain_tp_min:.2f}% (min guard)")
                    tp = _brain_tp_min
                else:
                    log(f"🧠 [v184] Smart TP: ADX={_brain_adx:.0f} RSI={_brain_rsi:.0f} → TP={tp:.3f}%")
        except Exception as _btp_ex:
            log(f"⚠️ [brain_tp] {_btp_ex}")

        # [v216-BOOST-TP] confidence_boost увеличивает TP на 10-15%
        # Когда мозг уверен (base+smc, base+fund) → держим позицию дольше
        try:
            _conf_bot_tp = str(self.knowledge._data.get("_last_signal_bot","none"))
            _tp_boost = 1.0
            if "smc" in _conf_bot_tp and "fund" in _conf_bot_tp:
                _tp_boost = 1.15   # максимальная уверенность → TP +15%
            elif "smc" in _conf_bot_tp:
                _tp_boost = 1.10   # совпало с SMC → TP +10%
            elif "fund" in _conf_bot_tp:
                _tp_boost = 1.08   # совпало с funding → TP +8%
            elif _conf_bot_tp == "base":
                _tp_boost = 0.95   # базовый режим → TP -5% (выходим быстрее)
            if abs(_tp_boost - 1.0) > 0.01:
                _tp_before = tp
                tp = tp * _tp_boost
                log(f"🚀 [v216] TP boost×{_tp_boost:.2f}: {_tp_before:.3f}%→{tp:.3f}% conf={_conf_bot_tp}")
        except Exception as _tp_boost_ex:
            log(f"⚠️ [tp_boost] {_tp_boost_ex}")

        tp = max(float(getattr(CFG, "TP1_PCT", 1.20)), min(tp, float(CFG.TP_MAX_PCT)))
        # [v290-2] АБСОЛЮТНЫЙ МИНИМУМ TP — финальный зажим с учётом комиссии
        # Формула: TP_gross_min = SL_gross + 0.40% (0.20% комиссия×2 + 0.20% запас)
        # При SL=0.80%: TP_gross_min = 0.80+0.40 = 1.20% → чистый TP=1.00% = SL_net (безубыток)
        # Для реальной прибыли нужно TP_gross_min = SL+0.60% = 1.40% → R:R=1:1.20
        _tp_absolute_min = float(getattr(CFG, 'STOP_LOSS_PCT', 0.80)) + 0.60  # SL + 0.20комиссия*2 + 0.20запас
        _tp_absolute_min = max(1.40, _tp_absolute_min)  # не менее 1.40% в любом случае
        if tp < _tp_absolute_min:
            log(f"⚠️ [v290-2] TP={tp:.3f}% < мин={_tp_absolute_min:.2f}% → поднят до минимума (R:R защита)")
            tp = _tp_absolute_min
        return float(tp)
    def _classify_symbol_profile(self, symbol: Optional[str] = None) -> str:
        sym = str(symbol or self.symbol or "").upper()
        base = sym.replace("USDT", "")
        if base in {"SOL", "AVAX", "LINK", "SUI", "APT"}:
            return "sol"
        if base in {"XRP", "ADA", "TRX", "XLM", "DOGE"}:
            return "xrp"
        meme_keys = ("PEPE", "BONK", "WIF", "FLOKI", "SHIB", "MEME", "DOGS", "BOME", "TURBO", "BRETT", "NEIRO", "MOG", "PONKE")
        if any(k in base for k in meme_keys):
            return "meme"
        return "default"
    def _adaptive_tp_profile(self) -> tuple[float, float]:
        base_tp = float(self.calc_smart_tp_pct())
        profile = self._classify_symbol_profile()
        if not bool(getattr(CFG, "AUTO_TP_PROFILE_ENABLE", True)):
            tp1_pct = min(float(getattr(CFG, "TP1_PCT", 0.80)), base_tp)
            tp2_pct = max(float(getattr(CFG, "TP2_PCT", 1.10)), base_tp)
            return tp1_pct, tp2_pct
        if profile == "sol":
            factor = float(getattr(CFG, "TP_PROFILE_SOL_FACTOR", 1.05))
            tp1_pct = max(0.85, base_tp * 0.92 * factor)
            tp2_pct = max(1.20, base_tp * 1.18 * factor)
        elif profile == "xrp":
            factor = float(getattr(CFG, "TP_PROFILE_XRP_FACTOR", 0.90))
            tp1_pct = max(0.60, base_tp * 0.82 * factor)
            tp2_pct = max(0.92, base_tp * 0.96 * factor)
        elif profile == "meme":
            factor = float(getattr(CFG, "TP_PROFILE_MEME_FACTOR", 1.12))
            tp1_pct = max(0.72, base_tp * 0.88 * factor)
            tp2_pct = max(1.35, base_tp * 1.30 * factor)
        else:
            tp1_pct = min(float(getattr(CFG, "TP1_PCT", 0.80)), base_tp)
            tp2_pct = max(float(getattr(CFG, "TP2_PCT", 1.10)), base_tp)
        tp1_pct = max(0.55, min(tp1_pct, 1.20))
        tp2_pct = max(tp1_pct + 0.15, min(tp2_pct, float(CFG.TP_MAX_PCT) + 0.35))

        # [v217-P3] confidence_boost применяется к TP2 тоже
        # При высокой уверенности держим TP2 дальше → больше прибыль
        try:
            _conf_tp2 = str(self.knowledge._data.get("_last_signal_bot","none"))
            _tp2_boost = 1.0
            if "smc" in _conf_tp2 and "fund" in _conf_tp2:
                _tp2_boost = 1.20   # max уверенность → TP2 +20%
            elif "smc" in _conf_tp2:
                _tp2_boost = 1.12   # SMC +12%
            elif "fund" in _conf_tp2:
                _tp2_boost = 1.08   # funding +8%
            elif _conf_tp2 == "base":
                _tp2_boost = 0.95   # базовый → TP2 ближе (-5%)
            if abs(_tp2_boost - 1.0) > 0.01:
                _tp2_before = tp2_pct
                tp2_pct = tp2_pct * _tp2_boost
                # TP2 всегда больше TP1 + 0.10%
                tp2_pct = max(tp1_pct + 0.10, tp2_pct)
                # Не выше максимума + 0.5%
                tp2_pct = min(tp2_pct, float(CFG.TP_MAX_PCT) + 0.5)
                log(f"🚀 [v217-P3] TP2 boost×{_tp2_boost:.2f}: {_tp2_before:.3f}%→{tp2_pct:.3f}% conf={_conf_tp2}")
        except Exception as _tp2ex:
            log(f"⚠️ [tp2_boost] {_tp2ex}")

        return float(tp1_pct), float(tp2_pct)
    def _pro_target_prices(self, entry_price: float) -> tuple[float, float]:
        f = self.filters
        if f is None:
            return entry_price, entry_price
        # [FIX-v251-2] Санитарная проверка entry_price vs текущая цена
        # Если entry в 5+ раз отличается от рынка → используем текущую цену
        try:
            _cur_p = float(self.get_price() or 0.0)
            if _cur_p > 0 and entry_price > 0:
                _ratio_check = entry_price / _cur_p
                if _ratio_check > 5.0 or _ratio_check < 0.2:
                    log(f"⚠️ [FIX-v251-2] entry_price={entry_price:.6f} vs рынок={_cur_p:.6f} (ratio={_ratio_check:.2f}) — заменяем на рыночную цену")
                    entry_price = _cur_p
                    self.pos.entry_price = _cur_p  # исправляем и в позиции
        except Exception: pass
        tp1_pct, tp2_pct = self._adaptive_tp_profile()
        # [FIX-v273-6] Закладываем комиссию полного круга в TP-цель, чтобы tp1_pct был ЧИСТОЙ прибылью.
        # Без этого: TP +1.5% даёт реально +1.3% после комиссии (BUY 0.1% + SELL 0.1% = 0.2%).
        # С этим: TP-цена выставляется на +1.5%+0.2% = +1.7%, чистыми получаем заданные 1.5%.
        _fee_round_pct = float(getattr(CFG, 'FEE_RATE_PCT', 0.10)) * 2.0  # BUY + SELL
        _tp1_with_fee = tp1_pct + _fee_round_pct
        _tp2_with_fee = tp2_pct + _fee_round_pct
        tp1_price = ceil_to_step(entry_price * (1 + _tp1_with_fee / 100.0), f.tick_size)
        tp2_price = ceil_to_step(entry_price * (1 + _tp2_with_fee / 100.0), f.tick_size)
        # [FIX-v117-5] Защита от TP=entry для монет с малым тиком (PEPE/SHIB)
        # Если ceil(entry*1.0085) = entry (слишком малый тик) — поднимаем минимум на 1 тик
        if f.tick_size > 0:
            if tp1_price <= entry_price:
                tp1_price = ceil_to_step(entry_price + f.tick_size, f.tick_size)
            if tp2_price <= tp1_price:
                tp2_price = ceil_to_step(tp1_price + f.tick_size, f.tick_size)
        return tp1_price, tp2_price
    def _ensure_partial_tp_structure(self) -> bool:
        if not bool(getattr(CFG, "ENABLE_PRO_TP", True)):
            return False
        if self.filters is None or self.pos.entry_price is None or self.pos.base_qty <= 0:
            return False
        f = self.filters
        bal_base = float(self.get_base_balance() or 0.0)
        _pos_qty = float(self.pos.base_qty or 0.0)
        # [FIX-v100] Используем ТОЛЬКО реальный баланс биржи (bal_base).
        # Старый max(bal_base, pos.base_qty) приводил к ErrCode 170131:
        # если pos.base_qty > реального баланса (stale), qty_total завышался,
        # TP1 блокировал больше монет чем есть → для TP2 ничего не оставалось.
        # bal_base = walletBalance = истина. pos.base_qty = наш учёт (может запаздывать).
        # Если bal_base = 0 но pos_qty > 0 — биржа ещё не обновилась, ждём.
        if bal_base <= 0 and _pos_qty > 0:
            time.sleep(0.5)
            bal_base = float(self.get_base_balance() or 0.0)
        qty_total = floor_to_step(bal_base if bal_base > 0 else _pos_qty, f.qty_step)
        if qty_total <= 0:
            return False
        opens = self.get_open_orders()
        open_sell_qty = floor_to_step(self._sum_open_sell_qty(opens), f.qty_step)
        tp1_target_qty = floor_to_step(qty_total * float(getattr(CFG, "TP1_SIZE", 0.70)), f.qty_step)
        if open_sell_qty > 0:
            # [FIX-18] Если TP1 уже активен — проверяем что его qty соответствует
            # новому total (при добавлении BUY ордеров из сетки qty_total растёт).
            # Если разница > 2 шага — пересчитываем TP1 на актуальное кол-во.
            # [FIX-31A] Правильное определение mismatch:
            # Пересчёт нужен ТОЛЬКО если баланс существенно вырос (новый BUY)
            # НЕ триггерить когда стоят TP1+TP2 (open_sell_qty = 100% = нормально)
            # Условие: open_sell_qty покрывает < 85% qty_total (значит BUY добавил монет)
            _tp_coverage = open_sell_qty / qty_total if qty_total > 0 else 1.0
            _qty_mismatch = (tp1_target_qty > 0
                             and _tp_coverage < 0.85  # SELL покрывает < 85% → нужен пересчёт
                             and not self.pos.tp1_done
                             and not self.pos.tp2_order_active  # TP2 активен → НЕ трогаем!
                             and not self.pos.be_activated
                             and not self.pos.trailing_active
            )
            if _qty_mismatch and self.pos.tp1_order_active:
                # BUY добавил монет — нужно пересчитать TP1+TP2
                log(f"🔄 [FIX-31A] TP пересчёт: coverage={_tp_coverage:.1%} < 85% (total={qty_total:.4f})")
                self.cancel_open_sell_orders()
                opens = self.get_open_orders()
                open_sell_qty = floor_to_step(self._sum_open_sell_qty(opens), f.qty_step)
                self.pos.tp1_order_active = False
                self.pos.tp2_order_active = False  # сбрасываем оба
            elif self.pos.tp1_done or self.pos.be_activated or self.pos.be_order_active:
                return True
            elif self.pos.tp2_order_active:
                # [FIX-31C] TP2 активен — значит TP1+TP2 оба стоят, не трогаем
                return True
            elif self.pos.tp1_order_active and not self.pos.tp2_order_active:
                # [FIX-21] TP1 стоит но TP2 нет — добавляем TP2 на остаток
                _tp1_pr, _tp2_pr = self._pro_target_prices(float(self.pos.entry_price))
                _tp2_q = floor_to_step(qty_total - open_sell_qty, f.qty_step)
                # [FIX-v98] Проверяем qty И min_amt для TP2 gap fill
                if self._sell_meets_min_amt(_tp2_q, _tp2_pr):
                    if self._place_limit_sell_qty_price(_tp2_q, _tp2_pr, note="(TP2 добавлен)"):
                        self.pos.tp2_order_active = True
                        log(f"🔵 [v98] TP2 добавлен: {fmt_by_step(_tp2_q,f.qty_step)} @ {fmt_by_step_ceil(_tp2_pr,f.tick_size)}")
                elif _tp2_q >= f.min_qty:
                    # tp2 qty ок но value < min_amt — объединяем с TP1
                    log(f"ℹ️ [v98] TP2 gap value={_tp2_q*_tp2_pr:.4f} < min_amt — объединяем с TP1")
                    self.cancel_open_sell_orders()
                    time.sleep(0.3)
                    _full_q = floor_to_step(qty_total, f.qty_step)
                    if self._sell_meets_min_amt(_full_q, _tp2_pr):
                        if self._place_limit_sell_qty_price(_full_q, _tp2_pr, note="(full merged TP)"):
                            self.pos.tp1_order_active = True
                            self.pos.tp2_order_active = True
                return True
            elif self.pos.tp1_order_active:
                return True
            elif tp1_target_qty > 0 and open_sell_qty < qty_total and abs(open_sell_qty - tp1_target_qty) <= max(f.qty_step * 2, f.min_qty):
                # Infer TP1-sized order after restart.
                self.pos.tp1_order_active = True
                return True
            elif open_sell_qty > 0:
                # Legacy full-size SELL blocks TP1/TP2 structure -> replace SELL only.
                self.cancel_open_sell_orders()
                opens = self.get_open_orders()
                open_sell_qty = floor_to_step(self._sum_open_sell_qty(opens), f.qty_step)
                if open_sell_qty > 0:
                    return True
        tp1_price, tp2_price = self._pro_target_prices(float(self.pos.entry_price))
        tp1_qty = tp1_target_qty
        tp2_qty = floor_to_step(qty_total - tp1_qty, f.qty_step)

        # [FIX-v98] Проверяем что оба ордера удовлетворяют min_amt Bybit.
        # ErrCode 170140 = Order value too LOW — применяется к SELL тоже!
        # Если tp2 value < min_amt (например NEAR: 30% * 7.5 USDT = 2.25 USDT < 5 USDT min):
        #   → объединяем всё в один ордер по цене TP1 (выгоднее для пользователя).
        # Когда накопится больше монет (2-й/3-й BUY fill), recalc даст достаточную сумму.
        _tp1_meets = self._sell_meets_min_amt(tp1_qty, tp1_price)
        _tp2_meets = tp2_qty > 0 and self._sell_meets_min_amt(tp2_qty, tp2_price)

        if not _tp1_meets:
            # TP1 тоже мала — ставим весь баланс одним ордером по TP2 цене
            full_qty = floor_to_step(qty_total, f.qty_step)
            if self._sell_meets_min_amt(full_qty, tp2_price):
                if self._place_limit_sell_qty_price(full_qty, tp2_price, note="(full TP — tp1<min_amt)"):
                    self.pos.tp1_order_active = True
                    self.pos.tp2_order_active = True
                    self.pos.be_order_active = False
                    log(f"🔵 [v98] Весь баланс одним TP: {fmt_by_step(full_qty,f.qty_step)} @ {fmt_by_step_ceil(tp2_price,f.tick_size)}")
                    return True
            return False

        if _tp1_meets and _tp2_meets:
            # Оба TP проходят min_amt — ставим оба
            ok1 = self._place_limit_sell_qty_price(tp1_qty, tp1_price, note="(TP1 70%)")
            if ok1:
                self.pos.tp1_order_active = True
                self.pos.tp2_order_active = False
                self.pos.be_order_active = False
                # [FIX-v100] После TP1 re-читаем реальный свободный баланс для TP2.
                # Bybit сразу блокирует tp1_qty монет, доступных для TP2 становится меньше.
                # Если использовать tp2_qty из расчёта (total-tp1), получим 170131
                # когда bal_base был немного завышен (стандартная ситуация).
                time.sleep(0.3)
                try:
                    _free_for_tp2 = floor_to_step(float(self.get_base_balance() or 0.0), f.qty_step)
                except Exception:
                    _free_for_tp2 = tp2_qty
                # Используем фактически свободный баланс для TP2
                _tp2_qty_actual = min(tp2_qty, _free_for_tp2)
                if _tp2_qty_actual < f.min_qty:
                    _tp2_qty_actual = _free_for_tp2  # всё что осталось
                ok2 = False
                if self._sell_meets_min_amt(_tp2_qty_actual, tp2_price):
                    ok2 = self._place_limit_sell_qty_price(_tp2_qty_actual, tp2_price, note="(TP2 30%)")
                if ok2:
                    self.pos.tp2_order_active = True
                    log(f"✅ [v100] TP1+TP2 выставлены: TP1={fmt_by_step_ceil(tp1_price,f.tick_size)} qty={fmt_by_step(tp1_qty,f.qty_step)} | TP2={fmt_by_step_ceil(tp2_price,f.tick_size)} qty={fmt_by_step(_tp2_qty_actual,f.qty_step)}")
                else:
                    log(f"⚠️ [v100] TP2 не вышел — отменяю TP1 и ставлю весь баланс одним ордером")
                    self.cancel_open_sell_orders()
                    time.sleep(0.8)  # ждём подтверждения отмены
                    _all_free = floor_to_step(float(self.get_base_balance() or 0.0), f.qty_step)
                    if _all_free < f.min_qty:
                        _all_free = qty_total
                    if self._sell_meets_min_amt(_all_free, tp1_price):
                        if self._place_limit_sell_qty_price(_all_free, tp1_price, note="(full TP fallback)"):
                            self.pos.tp1_order_active = True
                            self.pos.tp2_order_active = True
                            log(f"✅ [v100] Весь баланс одним TP: {fmt_by_step(_all_free,f.qty_step)} @ {fmt_by_step_ceil(tp1_price,f.tick_size)}")
                return True
            return False

        # tp2 < min_amt но tp1 ок: объединяем всё в один ордер по TP1 цене
        # (не теряем 30%, просто продаём всё по той же выгодной цене TP1)
        full_qty = floor_to_step(qty_total, f.qty_step)
        if self._sell_meets_min_amt(full_qty, tp1_price):
            if self._place_limit_sell_qty_price(full_qty, tp1_price, note="(full TP — tp2<min_amt)"):
                self.pos.tp1_order_active = True
                self.pos.tp2_order_active = True  # считаем оба выставленными (один ордер = 100%)
                self.pos.be_order_active = False
                log(f"🔵 [v98] TP2 < min_amt → весь баланс по TP1: {fmt_by_step(full_qty,f.qty_step)} @ {fmt_by_step_ceil(tp1_price,f.tick_size)}")
                return True
        return False
    def _manage_protective_exit(self, current_price: float):
        if not bool(getattr(CFG, "ENABLE_PRO_TP", True)):
            return
        if self.filters is None or self.pos.entry_price is None or self.pos.base_qty <= 0:
            return
        f = self.filters
        entry = float(self.pos.entry_price)
        pnl_pct = (float(current_price) - entry) / entry * 100.0 if entry > 0 else 0.0
        bal_base = floor_to_step(self.get_base_balance(), f.qty_step)
        if bal_base <= 0:
            return
        opens = self.get_open_orders()
        open_sell_qty = floor_to_step(self._sum_open_sell_qty(opens), f.qty_step)
        remaining = floor_to_step(max(bal_base - open_sell_qty, 0.0), f.qty_step)

        # [FIX-v99-3] tp1_done проверяем ДО "remaining <= 0: return".
        # BUG: cancel_open_sell_orders() асинхронна — биржа не успела обработать,
        # open_sell_qty > 0 → remaining=0 → старый код делал return, TP2 не восстанавливался.
        # Теперь: при tp1_done проверяем bal_base напрямую, игнорируем open_sell_qty.
        if self.pos.tp1_done:
            _tp2_base = max(entry, float(current_price or 0.0))
            _, tp2_price_ref = self._pro_target_prices(_tp2_base)
            if tp2_price_ref <= float(current_price or 0.0):
                tp2_price_ref = ceil_to_step(float(current_price or entry) * 1.005, f.tick_size)
            # Проверяем: не покрыт ли уже весь баланс SELL ордерами
            _tp1_done_coverage = open_sell_qty / bal_base if bal_base > 0 else 1.0
            if _tp1_done_coverage < 0.97 and bal_base >= f.min_qty:
                # Есть непокрытые монеты — ставим TP2 на весь остаток
                _tp2_qty = bal_base
                if self._sell_meets_min_amt(_tp2_qty, tp2_price_ref):
                    if open_sell_qty > 0:
                        # Отменяем незакрытые ордера (старый TP2 если cancel не прошёл)
                        self.cancel_open_sell_orders()
                        time.sleep(0.3)
                        _tp2_qty = floor_to_step(float(self.get_base_balance() or 0.0), f.qty_step)
                    if _tp2_qty >= f.min_qty:
                        if self._place_limit_sell_qty_price(_tp2_qty, tp2_price_ref, note="(TP2 restore)"):
                            self.pos.tp2_order_active = True
                            self.pos.be_order_active = False
                            log(f"🔵 [v99] TP2 восстановлен: {fmt_by_step(_tp2_qty,f.qty_step)} @ {fmt_by_step_ceil(tp2_price_ref,f.tick_size)}")
                else:
                    log(f"ℹ️ [v99] TP2 restore: value={_tp2_qty*tp2_price_ref:.4f} < min_amt — watchdog исправит")

        if remaining <= 0:
            return
        if bool(getattr(CFG, "ENABLE_BE", True)) and self.pos.tp1_done and (not self.pos.be_activated) and pnl_pct >= float(getattr(CFG, "BE_TRIGGER_PCT", 0.50)):
            # BE: переставляем остаток выше цены входа (гарантируем безубыток)
            # [FIX-v98] Используем bal_base (реальный баланс), не remaining
            _be_qty = bal_base
            if _be_qty < f.min_qty:
                _be_qty = remaining if remaining >= f.min_qty else bal_base
            be_price = ceil_to_step(entry * (1 + float(getattr(CFG, "BE_OFFSET_PCT", 0.05)) / 100.0), f.tick_size)
            self.cancel_open_sell_orders()
            # Проверяем min_amt для BE ордера
            if self._sell_meets_min_amt(_be_qty, be_price):
                if self._place_limit_sell_qty_price(_be_qty, be_price, note="(BE)"):
                    self.pos.be_activated = True
                    self.pos.be_order_active = True
                    self.pos.tp2_order_active = False
            else:
                log(f"ℹ️ [v98] BE: value={_be_qty*be_price:.4f} < min_amt — пропускаем BE, TP2 остаётся")
        if bool(getattr(CFG, "ENABLE_SMART_TRAIL", True)) and self.pos.tp1_done and pnl_pct >= float(getattr(CFG, "TRAIL_START_PCT", 0.6)):
            peak = max(float(self.pos.peak_price or 0.0), float(current_price))
            self.pos.peak_price = peak
            trail_dist = float(getattr(CFG, "TRAIL_DISTANCE_PCT", 0.4))
            trail_price = peak * (1 - trail_dist / 100.0)
            floor_price = entry * (1 + float(getattr(CFG, "BE_OFFSET_PCT", 0.05)) / 100.0)
            desired = ceil_to_step(max(trail_price, floor_price), f.tick_size)
            open_sell_prices = []
            for o in opens:
                if str(o.get("side", "")).lower() == "sell":
                    try:
                        open_sell_prices.append(float(o.get("price") or 0.0))
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [_manage_protective_exit] {_sw_ex}')
            cur_open_price = max(open_sell_prices) if open_sell_prices else 0.0
            if desired > cur_open_price + f.tick_size / 2:
                self.cancel_open_sell_orders()
                # [FIX-20] trailing управляет только остатком (не всем балансом)
                # [FIX-v98] Trailing: используем реальный баланс, не remaining
                _trail_qty = bal_base if bal_base >= f.min_qty else remaining
                if not self._sell_meets_min_amt(_trail_qty, desired):
                    _trail_qty = bal_base  # fallback
                if self._place_limit_sell_qty_price(_trail_qty, desired, note="(smart trail)"):
                    self.pos.trailing_active = True
                    self.pos.be_order_active = False
                    self.pos.tp2_order_active = True
        # [FIX-v142-4] Trailing БЕЗ tp1_done при высоком профите.
        # Если монета прыгнула через TP1 и он не исполнился, но профит уже большой —
        # трейлинг не запускался. Монета разворачивается и прибыль теряется.
        # Решение: если pnl_pct >= TRAIL_START_PCT * TRAIL_NO_TP1_MULTIPLIER
        # И tp1_done=False → запускаем trailing для защиты прибыли.
        elif (bool(getattr(CFG, "ENABLE_SMART_TRAIL", True))
              and not self.pos.tp1_done
              and entry > 0
              and self.pos.base_qty > 0):
            _no_tp1_mult = float(getattr(CFG, 'TRAIL_NO_TP1_MULTIPLIER', 2.0))
            _trail_start = float(getattr(CFG, "TRAIL_START_PCT", 0.6))
            if pnl_pct >= _trail_start * _no_tp1_mult:
                try:
                    peak = max(float(self.pos.peak_price or 0.0), float(current_price))
                    self.pos.peak_price = peak
                    trail_dist = float(getattr(CFG, "TRAIL_DISTANCE_PCT", 0.4))
                    trail_price = peak * (1 - trail_dist / 100.0)
                    floor_price = entry * (1 + float(getattr(CFG, "BE_OFFSET_PCT", 0.05)) / 100.0)
                    desired_no_tp1 = ceil_to_step(max(trail_price, floor_price), f.tick_size)
                    _open_sell_px_no_tp1 = []
                    for o in opens:
                        if str(o.get("side", "")).lower() == "sell":
                            try: _open_sell_px_no_tp1.append(float(o.get("price") or 0.0))
                            except (ValueError, TypeError) as _px_ex:  # [FIX-v159-1]
                                log(f"⚠️ [_manage_protective_exit] price cast: {_px_ex}")
                    _cur_sell_px = max(_open_sell_px_no_tp1) if _open_sell_px_no_tp1 else 0.0
                    if desired_no_tp1 > _cur_sell_px + f.tick_size / 2:
                        self.cancel_open_sell_orders()
                        _trail_no_tp1_qty = bal_base if bal_base >= f.min_qty else remaining
                        if self._sell_meets_min_amt(_trail_no_tp1_qty, desired_no_tp1):
                            if self._place_limit_sell_qty_price(_trail_no_tp1_qty, desired_no_tp1, note="(trail no-tp1)"):
                                self.pos.trailing_active = True
                                log(f"📈 [FIX-v142-4] Trailing без tp1_done: pnl={pnl_pct:.2f}% >= {_trail_start*_no_tp1_mult:.2f}% → trail @ {desired_no_tp1:.6f}")
                except Exception as _nt_ex:
                    log(f"⚠️ [v142-4] trail no-tp1 error: {_nt_ex}")

        # ─── [FIX-v106-1] Динамический TP2 ──────────────────────────────────
        # Если монета растёт быстро (>DYN_TP_GROWTH_2M_PCT за 2 мин) — поднимаем TP2
        if (bool(getattr(CFG, 'DYN_TP_ENABLE', True))
                and not self.pos.tp1_done  # только до срабатывания TP1
                and entry > 0
                and pnl_pct > 0):
            try:
                _dtp_max_raises = int(getattr(CFG, 'DYN_TP_MAX_RAISES', 3))
                _dtp_raises = int(getattr(self, '_dyn_tp_raises', 0))
                if _dtp_raises < _dtp_max_raises:
                    # Смотрим рост за последние 2 минуты (4 свечи × 30с ≈ 2 мин)
                    try:
                        _ohlc_2m = self.get_ohlc(interval_min="1", limit=5, symbol=self.symbol)
                        _cls_2m = _ohlc_2m.get("close", [])
                    except Exception:
                        _cls_2m = []
                    if len(_cls_2m) >= 3 and _cls_2m[-3] > 0:
                        _growth_2m = (_cls_2m[-1] - _cls_2m[-3]) / _cls_2m[-3] * 100.0
                        _dtp_thresh = float(getattr(CFG, 'DYN_TP_GROWTH_2M_PCT', 0.5))
                        if _growth_2m >= _dtp_thresh:
                            # Поднимаем TP2 — сначала отменяем текущие SELL
                            _boost = float(getattr(CFG, 'DYN_TP_BOOST_PCT', 0.3))
                            open_sell_prices_dtp = []
                            for _o in opens:
                                if str(_o.get('side', '')).lower() == 'sell':
                                    try:
                                        open_sell_prices_dtp.append(float(_o.get('price') or 0.0))
                                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                                        log(f'⚠️ [_manage_protective_exit] {_sw_ex}')
                            _cur_tp_price = max(open_sell_prices_dtp) if open_sell_prices_dtp else 0.0
                            if _cur_tp_price > 0:
                                _new_tp = ceil_to_step(_cur_tp_price * (1 + _boost / 100.0), f.tick_size)
                                self.cancel_open_sell_orders()
                                time.sleep(0.2)
                                _dtp_qty = floor_to_step(self.get_base_balance(), f.qty_step)
                                if _dtp_qty >= f.min_qty and self._sell_meets_min_amt(_dtp_qty, _new_tp):
                                    if self._place_limit_sell_qty_price(_dtp_qty, _new_tp, note="(dyn_tp)"):
                                        self._dyn_tp_raises = _dtp_raises + 1
                                        log(f"📈 [v106] DYN_TP: рост {_growth_2m:.2f}%≥{_dtp_thresh}% → TP2 поднят "
                                            f"{_cur_tp_price:.6f}→{_new_tp:.6f} (подъём #{self._dyn_tp_raises})")
                                        if TG.enabled:
                                            TG.send_throttled('dyn_tp',
                                                f"📈 Динамический TP2 [{self.symbol}]\n"
                                                f"Рост 2м: {_growth_2m:.2f}% → TP2: {_new_tp:.6f}\n"
                                                f"Подъём #{self._dyn_tp_raises}/{_dtp_max_raises}",
                                                cooldown_sec=120)
            except Exception as _dtp_ex:
                log(f"⚠️ [v106] dyn_tp error: {_dtp_ex}")

        # ─── [FIX-v106-2] Trailing BE после TP1 ─────────────────────────────
        # Сразу при TP1_done двигаем BE вверх по мере роста цены
        if (bool(getattr(CFG, 'BE_AUTO_ON_TP1', True))
                and self.pos.tp1_done
                and entry > 0
                and pnl_pct > 0):
            try:
                _be_step = float(getattr(CFG, 'BE_TRAIL_STEP_PCT', 0.15))
                _be_trail_peak = float(getattr(self, '_be_trail_peak', 0.0) or 0.0)
                if float(current_price) > _be_trail_peak:
                    self._be_trail_peak = float(current_price)
                    _be_trail_peak = float(current_price)
                # Целевая цена BE: entry + 0.05% (минимальный плюс)
                _be_floor = ceil_to_step(entry * 1.0005, f.tick_size)
                # Трейлим: BE = текущий пик − BE_TRAIL_STEP_PCT (но не ниже entry+)
                _be_trail_target = ceil_to_step(
                    max(_be_floor, _be_trail_peak * (1 - _be_step / 100.0)), f.tick_size)
                # Проверяем текущий SELL ордер
                open_sell_prices_be = [float(_o.get('price') or 0.0)
                                       for _o in opens
                                       if str(_o.get('side', '')).lower() == 'sell']
                _cur_be_price = min(open_sell_prices_be) if open_sell_prices_be else 0.0
                # Поднимаем BE только вверх и только если разница существенная
                if _be_trail_target > _cur_be_price + f.tick_size * 2:
                    self.cancel_open_sell_orders()
                    time.sleep(0.2)
                    _be_qty = floor_to_step(self.get_base_balance(), f.qty_step)
                    if _be_qty >= f.min_qty and self._sell_meets_min_amt(_be_qty, _be_trail_target):
                        if self._place_limit_sell_qty_price(_be_qty, _be_trail_target, note="(be_trail)"):
                            self.pos.be_activated = True
                            self.pos.be_order_active = True
                            log(f"🔒 [v106] BE trail: {_cur_be_price:.6f}→{_be_trail_target:.6f} "
                                f"(пик={_be_trail_peak:.6f})")
            except Exception as _be_ex:
                log(f"⚠️ [v106] be_trail error: {_be_ex}")

    def safety_ensure_sell(self, current_price: Optional[float] = None, open_orders: Optional[List[Dict]] = None) -> bool:
        """Ensure there is a protective SELL order when base position exists.
        Prefers PRO TP structure; otherwise falls back to a full-size TP order.
        """
        try:
            if self.filters is None:
                return False
            f = self.filters
            bal_base = floor_to_step(self.get_base_balance(), f.qty_step)
            pos_qty = floor_to_step(float(self.pos.base_qty or 0.0), f.qty_step)
            qty_total = floor_to_step(min(bal_base, pos_qty if pos_qty > 0 else bal_base), f.qty_step)
            if qty_total <= 0:
                return False
            opens = open_orders if isinstance(open_orders, list) else self.get_open_orders()
            for o in opens or []:
                try:
                    if str(o.get("side", "")).lower() == "sell":
                        q = float(o.get("qty") or o.get("origQty") or o.get("leavesQty") or 0.0)
                        if q > 0:
                            return True
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [safety_ensure_sell] {_sw_ex}')
            if bool(getattr(CFG, "ENABLE_PRO_TP", True)) and self.pos.entry_price and qty_total > 0:
                if self._ensure_partial_tp_structure():
                    return True
            # [FIX-12C] если entry_price=None — _ensure_partial_tp_structure пропущена,
            # продолжаем к fallback SELL по текущей цене+TP%
            if current_price is None or float(current_price or 0.0) <= 0:
                current_price = float(self.get_last_price(self.symbol) or 0.0)
            entry = float(self.pos.entry_price or 0.0)
            # [FIX-12C] если entry_price=None/0 — используем current_price как базу для SELL
            # Раньше ref_price=0 → SELL не ставился → монета без защиты
            if entry > 0:
                ref_price = max(entry, float(current_price or 0.0))
            elif float(current_price or 0.0) > 0:
                ref_price = float(current_price)
            else:
                try:
                    ref_price = float(self.get_last_price(self.symbol) or 0.0)
                except Exception:
                    ref_price = 0.0
            if ref_price <= 0:
                return False
            tp_pct = float(self.calc_smart_tp_pct() if bool(getattr(CFG, "ENABLE_PRO_TP", True)) else self.compute_tp_pct())
            sell_price = ceil_to_step(ref_price * (1.0 + tp_pct / 100.0), f.tick_size)
            # [FIX-v117-4] Гарантируем что SELL цена > entry минимум на 1 тик
            # PEPE: ref=0.000004, sell=ceil(0.000004*1.0085/0.000001)*0.000001=0.000004 (=entry!)
            # SELL по цене entry = немедленное исполнение или отказ Bybit → SELL не вставал часами
            _entry_for_check = float(self.pos.entry_price or ref_price or 0.0)
            if f.tick_size > 0 and sell_price <= _entry_for_check:
                sell_price = ceil_to_step(_entry_for_check + f.tick_size, f.tick_size)
                log(f"⚠️ [v117] safety SELL: цена={sell_price:.8f} поднята (entry={_entry_for_check:.8f})")
            # [FIX-v98] safety_ensure_sell: проверяем qty И min_amt
            # ErrCode 170140 применяется к SELL тоже — qty*price >= min_amt обязательно
            if not self._sell_meets_min_amt(qty_total, sell_price):
                self._remainder_below_min_mode = True
                self._remainder_last_value_usdt = float(qty_total * sell_price)
                log(f"ℹ️ [v98] safety SELL skipped: qty={qty_total:.6f} value={qty_total*sell_price:.4f} USDT (min_qty={f.min_qty:.6f} min_amt={f.min_amt:.4f})")
                return False
            return self._place_limit_sell_qty_price(qty_total, sell_price, note="(safety ensure sell)")
        except Exception as e:
            log(f"⚠️ safety_ensure_sell error: {e}")
            return False
    def compute_tp_pct(self) -> float:
        if CFG.MANUAL_TP_PCT is not None:
            return float(CFG.MANUAL_TP_PCT)
        t = self.get_ticker()
        # amplitude proxy — используем отдельные имена чтобы не путать с TP-процентами
        price_hi = float(t.get("highPrice24h") or 0.0)
        price_lo = float(t.get("lowPrice24h") or 0.0)
        amp = 0.0
        if price_hi > 0 and price_lo > 0:
            amp = (price_hi - price_lo) / price_lo * 100.0
        tp_lo, tp_hi = self.effective_tp_minmax()
        return tp_hi if amp >= CFG.TP_VOL_THRESHOLD_24H else tp_lo
    # ---------- Place Orders ----------
    def _available_usdt_for_order(self) -> float:
        """[FIX-v143-P2] Доступный USDT с учётом резерва И текущей экспозиции."""
        usdt = self.get_usdt_balance()
        reserve = max(0.0, usdt * (CFG.RESERVE_USDT_PCT / 100.0))
        avail = max(0.0, usdt - reserve)
        cap = min(CFG.BALANCE_CAP_USDT, usdt)
        avail = min(avail, cap)
        # [FIX-v143-P2] Учитываем текущую экспозицию — не превышаем MAX_EXPOSURE
        try:
            _cur_expo = self._current_exposure_usdt()
            # [FIX-v318-BUG] MAX_EXPOSURE_USDT=22.5 — фиксированное число в долларах,
            # НЕ зависящее от реального баланса (в отличие от MAX_SINGLE_COIN_EXPOSURE_PCT,
            # который считается в % от баланса и поэтому сам масштабируется). Значение явно
            # подобрано под баланс ~$25-45 (типичный для вас на момент, когда писался этот
            # код) и с тех пор никогда не пересчитывалось. Если баланс вырастет (например,
            # по совету из ROUND17/18 — $150-200 для комфортной работы формул TP1/TP2) — этот
            # хардкод продолжит жёстко резать позицию на $22.5 суммарно, независимо от того,
            # сколько реально на счету, то есть большая часть депозита просто не будет
            # использоваться ботом. При вашем ТЕКУЩЕМ балансе (~$23-30) это ничего не меняет:
            # % от баланса (MAX_SINGLE_COIN_EXPOSURE_PCT=60%) и так меньше 22.5, то есть
            # реально ограничивающим уже был процент, а не эта константа. Меняем строгий
            # потолок на "не меньше, чем позволяет процент от баланса" — при малом балансе
            # ничего не меняется (см. выше), при более крупном — экспозиция растёт вместе с
            # реальными деньгами на счету, как и было задумано MAX_SINGLE_COIN_EXPOSURE_PCT.
            _max_expo_fixed = float(getattr(CFG, 'MAX_EXPOSURE_USDT', 22.5))
            _max_expo_pct = usdt * float(getattr(CFG, 'MAX_SINGLE_COIN_EXPOSURE_PCT', 60.0)) / 100.0
            _max_expo = max(_max_expo_fixed, _max_expo_pct)
            _expo_room = max(0.0, _max_expo - _cur_expo)
            avail = min(avail, _expo_room)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_available_usdt_for_order] {_sw_ex}')  # [FIX-v154]
        return max(0.0, avail)

    def _dynamic_usdt_per_order(self) -> float:
        """[FIX-v143-P1] + [v217-BALANCE] Авто-размер ордера по балансу.
        
        Ступени баланса (если TRADE_AMOUNT_USDT=0):
          <50 USDT  → 5% баланса  (мин 1 USDT)
          50-200    → 7% баланса
          200-500   → 6% баланса
          500-1000  → 5% баланса
          ≥1000     → 4% баланса  (диверсификация)
        """
        try:
            # [FIX-v221-3] Один вызов get_usdt_balance() вместо двух.
            # Ранее: _bal использовал get_usdt_balance() и ниже _real_bal снова
            # вызывал get_usdt_balance() → 2 API запроса на каждое построение сетки.
            _real_bal = float(self.get_usdt_balance() or 0.0)
            _bal = _real_bal + self._current_exposure_usdt()
            _max_pct = float(getattr(CFG, 'MAX_SINGLE_COIN_EXPOSURE_PCT', 60.0))
            # [FIX-v298-BUG] Было max(1, ...) — если CFG.ORDER_COUNT где-то временно равен 1
            # (напр. через AOS_ORDERS_UNDER_50 с дефолтом 1 ниже), бюджет на ордер делился на 1
            # (то есть удваивался), а build_grid() всё равно строит МИНИМУМ 2 ордера (v291-1) —
            # итог: 2 ордера по удвоенному размеру = скрытое превышение запланированной
            # экспозиции. Пол поднят до 2, синхронно со стратегией "строго 2 ордера".
            _n_orders = max(2, int(getattr(CFG, 'ORDER_COUNT', 2)))
            _dynamic = (_bal * _max_pct / 100.0) / _n_orders
            _min_order = float(getattr(CFG, 'MIN_USDT_PER_ORDER', 5.0))
            _cfg_max = float(getattr(CFG, 'USDT_PER_ORDER', 7.5))
            # [FIX-v264-2] АВТО-РАСПРЕДЕЛЕНИЕ БАЛАНСА (настройки в CFG.AOS_*)
            if bool(getattr(CFG, 'AUTO_ORDER_SIZING', False)) and _real_bal > 0:
                # [FIX-v298-BUG] AOS_ORDERS_UNDER_50 фолбэк был 1 (несогласован с реальным
                # дефолтом в Config, который =2) — при балансе <50 USDT (самый частый случай
                # в этом файле, все примеры про депозит $25) это давало _n=1, откуда:
                # (а) _per_order считался как budget/1 — вдвое больше положенного, И
                # (б) CFG.ORDER_COUNT = min(2, 1) = 1 ниже — гарантированный обход стратегии
                # "строго 2 ордера для усреднения". Фолбэки всех ступеней подняты до 2.
                if   _real_bal < 50:
                    _pct = float(getattr(CFG, 'AOS_PCT_UNDER_50', 0.40))
                    _n = int(getattr(CFG, 'AOS_ORDERS_UNDER_50', 2))
                elif _real_bal < 200:
                    _pct = float(getattr(CFG, 'AOS_PCT_50_200', 0.45))
                    _n = int(getattr(CFG, 'AOS_ORDERS_50_200', 2))
                elif _real_bal < 500:
                    _pct = float(getattr(CFG, 'AOS_PCT_200_500', 0.50))
                    _n = int(getattr(CFG, 'AOS_ORDERS_OVER_200', 2))
                elif _real_bal < 1000:
                    _pct = float(getattr(CFG, 'AOS_PCT_500_1000', 0.45))
                    _n = int(getattr(CFG, 'AOS_ORDERS_OVER_200', 2))
                else:
                    _pct = float(getattr(CFG, 'AOS_PCT_OVER_1000', 0.40))
                    _n = int(getattr(CFG, 'AOS_ORDERS_OVER_200', 2))
                # [FIX-v298-BUG] Флор >=2 ДО использования _n в делении на строке ниже —
                # раньше _n мог быть 1 (см. выше), а деление на _n происходит до guard'а
                # ORDER_COUNT, так что старый min(2,...) guard не защищал сайзинг вообще.
                _n = max(2, _n)
                # Обновляем кол-во ордеров под баланс
                # [v287-3+v298] строго 2: сохранён исходный потолок max=2 (стратегия не
                # рассчитана на 3+ ордера здесь) И добавлен пол >=2 (см. правку _n выше).
                CFG.ORDER_COUNT = max(2, min(2, int(_n)))
                _per_order = max(_min_order, round(_real_bal * _pct / _n, 2))
                log(f"💡 [v264-2] Авто-размер: баланс {_real_bal:.1f}×{_pct:.0%}÷{_n} ордеров = {_per_order:.2f} USDT/ордер")
                return _per_order
            # [v217-BALANCE] При нулевом TRADE_AMOUNT — авто-пропорция
            if _cfg_max <= 0 and _real_bal > 0:
                if   _real_bal < 50:    _pct = 0.05
                elif _real_bal < 200:   _pct = 0.07
                elif _real_bal < 500:   _pct = 0.06
                elif _real_bal < 1000:  _pct = 0.05
                else:                   _pct = 0.04
                _auto = max(1.0, round(_real_bal * _pct / _n_orders, 2))
                log(f"💡 [v217] Авто-размер: {_real_bal:.1f}×{_pct:.0%}÷{_n_orders}={_auto:.2f}USDT")
                return _auto
            return max(_min_order, min(_cfg_max, _dynamic))
        except Exception:
            return float(getattr(CFG, 'USDT_PER_ORDER', 7.5))
    def _current_exposure_usdt(self) -> float:
        """Текущая экспозиция: entry_cost (позиция) + сумма BUY лимиток (price*qty)."""
        expo = 0.0
        try:
            expo += float(self.pos.entry_cost or 0.0)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_current_exposure_usdt] {_sw_ex}')
        try:
            for o in self.get_open_orders():
                if str(o.get("side", "")).upper() == "BUY":
                    try:
                        p = float(o.get("price") or 0.0)
                        q = float(o.get("qty") or o.get("origQty") or 0.0)
                        if p > 0 and q > 0:
                            expo += p * q
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [_current_exposure_usdt] {_sw_ex}')
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_current_exposure_usdt] {_sw_ex}')
        return float(expo)
    def total_exposure_usdt(self) -> float:
        """Compatibility alias for exposure checks used by older/newer branches."""
        try:
            return float(self._current_exposure_usdt())
        except Exception:
            # [FIX-v297-BUG] Было `return 0.0` — fail-OPEN: при сбое эта функция врала, что
            # экспозиция нулевая, и вызывающий код (например _allow_buy_now) мог разрешить
            # новую покупку при реально высокой занятой экспозиции. _current_exposure_usdt()
            # сама по себе уже защищена try/except на каждом шаге и практически никогда не
            # бросает исключение — но если это всё же случится, безопаснее вернуть
            # MAX_EXPOSURE_USDT (то есть "экспозиция полная") и запретить новую покупку,
            # чем соврать, что экспозиции нет.
            log('⚠️ [total_exposure_usdt] ошибка расчёта экспозиции — считаем экспозицию полной (fail-closed)')
            return float(getattr(CFG, 'MAX_EXPOSURE_USDT', 22.5))
    def _exposure_allows_new_buy(self, add_usdt: float) -> bool:
        max_expo = float(getattr(CFG, "MAX_EXPOSURE_USDT", 22.5))
        try:
            cur = self._current_exposure_usdt()
        except Exception:
            cur = 0.0
        return (cur + float(add_usdt)) <= (max_expo + 1e-9)
    def _confirm_order_present(self, symbol: str, order_id: str, retries: int = 6, delay: float = 0.6) -> bool:
        """Проверка, что ордер действительно принят биржей.
        Сначала ищем в open orders, затем в order history.
        Возвращает True/False (без исключений).
        """
        if not order_id:
            return False
        for _ in range(max(1, retries)):
            try:
                r1 = call_with_retry(client.get_open_orders, category="spot", symbol=symbol, limit=50)
                if isinstance(r1, dict) and str(r1.get("retCode", 0)) == "0":
                    lst = (((r1.get("result") or {}).get("list")) or [])
                    for o in lst:
                        if str(o.get("orderId", "")) == str(order_id):
                            return True
                r2 = call_with_retry(client.get_order_history, category="spot", symbol=symbol, limit=50)
                if isinstance(r2, dict) and str(r2.get("retCode", 0)) == "0":
                    lst2 = (((r2.get("result") or {}).get("list")) or [])
                    for o in lst2:
                        if str(o.get("orderId", "")) == str(order_id):
                            return True
            except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                log(f'⚠️ [_confirm_order_present] {_sw_ex}')  # [FIX-v153-FINAL]
            time.sleep(delay)
        return False
    def _unrealized_now(self, last_price: Optional[float] = None) -> float:
        """Текущий нереализованный PnL по позиции (без учёта будущей комиссии SELL)."""
        try:
            if self.pos.base_qty and self.pos.entry_price:
                px = float(last_price) if last_price is not None else float(self.get_last_price(self.symbol))
                return (px - float(self.pos.entry_price)) * float(self.pos.base_qty)
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [_unrealized_now] {_sw_ex}')  # [FIX-v154]
        return 0.0
    def place_limit_buy(self, price: float, usdt_amount_target: float, _guard_already_passed: bool = False) -> Optional[str]:
        activity = getattr(CFG, 'TRADE_ACTIVITY_MODE', 'balanced')
        self._set_stage('ORDER_PREPARE_BUY', symbol=self.symbol, price=f'{float(price or 0.0):.8f}', activity=activity)
        blocked_sym, blocked_reason = self._symbol_is_blocked_for_buy(self.symbol)
        if blocked_sym:
            log(f"⛔ BUY skipped for {self.symbol}: {blocked_reason}")
            return None
        if self.filters is None:
            return None
        f = self.filters
        price_r = floor_to_step(price, f.tick_size)
        if price_r <= 0:
            return None
        # ── [1] Проверка позиции перед покупкой ──────────────────
        # Если уже держим позицию >= MAX_EXPOSURE — новый BUY запрещён.
        # Grid-стратегия допускает несколько ордеров, поэтому проверяем
        # не "есть ли позиция вообще", а "не превышен ли лимит экспозиции".
        try:
            cur_exposure = self._current_exposure_usdt()
        except Exception:
            cur_exposure = 0.0
        max_expo = float(getattr(CFG, "MAX_EXPOSURE_USDT", 22.5))
        if cur_exposure >= max_expo:
            log(f"⛔ BUY пропущен: позиция {cur_exposure:.2f} USDT >= max {max_expo:.2f} USDT")
            return None
        available_usdt = self._available_usdt_for_order()
        if available_usdt <= 0:
            return None
        # adapt order size to available usdt, but keep <= target
        usdt_amount = min(usdt_amount_target, available_usdt)
        if usdt_amount < CFG.MIN_USDT_PER_ORDER:
            return None
        # ── [2] Проверка спреда перед покупкой ──────────────────
        try:
            _t = self.get_ticker()
            _bid = float(_t.get("bid1Price") or 0.0)
            _ask = float(_t.get("ask1Price") or 0.0)
            _last = float(_t.get("lastPrice") or 0.0)
            if _bid > 0 and _ask > 0 and _last > 0:
                _spread = (_ask - _bid) / _last * 100.0
                if _spread > CFG.MAX_SPREAD_PCT:
                    log(f"⛔ BUY пропущен: спред {_spread:.3f}% > {CFG.MAX_SPREAD_PCT}%")
                    return None
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [place_limit_buy] {_sw_ex}')
        # ── [3] Проверка объёма перед покупкой ───────────────────  [FIX-v35-1]
        # Используем тот же тикер _t что получили выше — не делаем второй запрос
        try:
            _tv = float(_t.get("turnover24h") or 0.0)
            _turn_floor = float(self._current_turnover_floor())
            if _tv > 0 and _tv < _turn_floor:
                log(f"⛔ BUY пропущен: объём {_tv:.0f} USDT < min {_turn_floor:.0f}")
                return None
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [place_limit_buy] {_sw_ex}')
        # max exposure guard (позиция + BUY ордера)
        if not self._exposure_allows_new_buy(usdt_amount):
            if TG.enabled:
                TG.send_throttled("max_exposure", f"⛔ Max exposure reached: запрет BUY. cur~{self._current_exposure_usdt():.2f} + add~{usdt_amount:.2f} > {float(getattr(CFG,'MAX_EXPOSURE_USDT',22.5)):.2f} USDT", cooldown_sec=120, only_on_change=True)
            return None
        qty = usdt_amount / price_r
        qty_r = floor_to_step(qty, f.qty_step)
        if f.min_qty > 0 and qty_r < f.min_qty:
            qty_r = floor_to_step(f.min_qty, f.qty_step)
        notional = qty_r * price_r
        if f.min_amt > 0 and notional < f.min_amt:
            qty_need = f.min_amt / price_r
            qty_r = floor_to_step(qty_need, f.qty_step)
        # Recompute notional after min_qty/min_amt adjustments
        notional = qty_r * price_r
        # Ensure we still have enough USDT after rounding up to meet exchange mins
        if notional > available_usdt + 1e-9:
            return None
        # If rounding caused notional to stay below min_amt, skip (avoid rejected orders)
        if f.min_amt > 0 and notional < f.min_amt - 1e-9:
            return None
        if qty_r <= 0:
            return None
        # [FIX-BUG11] пропускаем повторный вызов guard если он уже выполнен в build_grid
        if not _guard_already_passed:
            ok_guard, guard_reason = self.prebuy_entry_guard(buy_price=price_r)
            if not ok_guard:
                log(f"⛔ BUY пропущен final pre-buy guard: {guard_reason}")
                if TG.enabled:
                    TG.send_throttled("prebuy_guard", f"⛔ BUY пропущен final pre-buy guard\nПара: {self.symbol}\nПричина: {guard_reason}", cooldown_sec=90, only_on_change=True)
                return None
        try:
            # [FIX-v297-BUG] orderLinkId — см. new_order_link_id(): защита от дублирующего
            # BUY-ордера, если retry в call_with_retry сработает после таймаута ответа биржи.
            _link_id = new_order_link_id("buy")
            resp = call_with_retry(
                client.place_order,
                category="spot",
                symbol=self.symbol,
                side="Buy",
                orderType="Limit",
                timeInForce="GTC",
                qty=fmt_by_step(qty_r, f.qty_step),
                price=fmt_by_step(price_r, f.tick_size),
                orderLinkId=_link_id
            )
            self._set_stage('ORDER_SUBMIT_ENTER', symbol=self.symbol, price=fmt_by_step(price_r, f.tick_size), usdt=f'{float(usdt_amount):.2f}', activity=activity)
            oid = resp.get("result", {}).get("orderId")
            # verify order appears on exchange (with retries). If still not confirmed — НЕ дублируем BUY,
            # возвращаем oid и продолжаем мониторить, чтобы не было двойных покупок.
            if not oid:
                log(f"⚠️ BUY: no orderId in response: {resp}")
                if TG.enabled and CFG.TG_SEND_TRADES:
                    TG.send("⚠️ BUY: биржа не вернула orderId (возможен отказ).")
                return None
            retries = int(getattr(CFG, "ORDER_CONFIRM_RETRIES", 12))  # [FIX-v117-audit] дефолт 6→12
            delay = float(getattr(CFG, "ORDER_CONFIRM_DELAY_SEC", 1.0))  # [FIX-v117-audit] дефолт 0.7→1.0
            ok_present = self._confirm_order_present(self.symbol, oid, retries=retries, delay=delay)
            if not ok_present:
                log(f"⚠️ BUY not confirmed (will monitor anyway). oid={oid} resp={resp}")
                if TG.enabled and CFG.TG_SEND_TRADES:
                    TG.send_throttled("buy_not_confirmed", f"⚠️ BUY НЕ подтвержден биржей (orderId {oid}). Я НЕ дублирую BUY, продолжу мониторить.", cooldown_sec=90, only_on_change=True)
            self._set_stage('ORDER_SUBMIT_OK', symbol=self.symbol, oid=str(oid)[:18], activity=activity)
            log(f"🟢 BUY placed @ {fmt_by_step(price_r, f.tick_size)} | ~{usdt_amount:.4f} USDT | oid={oid}")
            if TG.enabled:
                TG.send(f"🟢 BUY выставлен (oid={oid})\nПара: {self.symbol}\nЦена: {fmt_by_step(price_r,f.tick_size)}\nСумма: ~{usdt_amount:.4f} USDT")
            return oid
        except Exception as e:
            self._set_stage('ORDER_SUBMIT_FAIL', symbol=self.symbol, reason='api/place_order', activity=activity)
            log(f"⚠️ ERROR BUY: {e}")
            return None
    def place_tp_sell(self, buy_price: float, filled_qty: float, note: str = "") -> bool:
        """PRO TP: после каждого BUY fill ставит TP1(70%)+TP2(30%) от ВСЕЙ текущей позиции.
        [FIX-29G] Логика: отменяем старые SELL → ставим новые на total_qty.
        Это гарантирует что хвостов нет и оба TP всегда покрывают весь баланс."""
        if self.filters is None:
            return False
        _t0 = time.time()
        while True:
            try:
                bal_chk = self.get_base_balance()
            except Exception:
                bal_chk = 0.0
            if bal_chk > 0 or time.time() - _t0 > 8.0:  # [v219-FIX-SELL] 3→8с
                break
            time.sleep(0.4)
        if bool(getattr(CFG, "ENABLE_PRO_TP", True)):
            ok = self._ensure_partial_tp_structure()
            if ok and TG.enabled and CFG.TG_SEND_TRADES and self.pos.entry_price:
                tp1_price, tp2_price = self._pro_target_prices(float(self.pos.entry_price))
                _tp1_on = bool(getattr(self.pos, 'tp1_order_active', False))
                _tp2_on = bool(getattr(self.pos, 'tp2_order_active', False))
                f_ts = self.filters.tick_size
                # [FIX-v110-1] Реально считаем SELL ордера на бирже — не доверяем флагам
                try:
                    _open_sells = [o for o in (self.get_open_orders() or [])
                                   if str(o.get('side', '')).lower() == 'sell']
                    _n_sells = len(_open_sells)
                    _sell_qty = sum(float(o.get('qty') or o.get('leavesQty') or 0.0)
                                   for o in _open_sells)
                except Exception:
                    _n_sells = 1 if (_tp1_on or _tp2_on) else 0
                    _sell_qty = 0.0
                _bal = float(self.get_base_balance() or 0.0)
                _covered = _sell_qty >= _bal * 0.95 if _bal > 0 else False
                if _n_sells >= 2:
                    _tp2_pct = 100 - int(float(getattr(CFG, "TP1_SIZE", 0.7)) * 100)
                    _tp2_line = "TP2: " + fmt_by_step_ceil(tp2_price, f_ts) + " (остаток " + str(_tp2_pct) + "%)\n📌 Оба ордера выставлены"
                elif _n_sells == 1 and _tp1_on and _tp2_on:
                    _tp2_line = "⚠️ TP2 объединён с TP1 (мин.сумма биржи)\n📌 Один ордер @ TP1 цене = 100% покрыто"
                elif _tp2_on:
                    _tp2_pct = 100 - int(float(getattr(CFG, "TP1_SIZE", 0.7)) * 100)
                    _tp2_line = "TP2: " + fmt_by_step_ceil(tp2_price, f_ts) + " (остаток " + str(_tp2_pct) + "%)\n📌 Оба ордера выставлены"
                else:
                    _tp2_line = "TP2: " + fmt_by_step_ceil(tp2_price, f_ts) + " (watchdog выставит)"
                _prot = "✅ покрыто" if _covered else "⚠️ частично"
                _tp1_pct = int(float(getattr(CFG, "TP1_SIZE", 0.7)) * 100)
                TG.send("🔴 PRO TP active\n"
                        "TP1: " + fmt_by_step_ceil(tp1_price, f_ts) + " (" + str(_tp1_pct) + "%)\n"
                        + _tp2_line + "\n"
                        "Защита: " + _prot)
            return ok
        if self.filters is None:
            return False
        f = self.filters
        qty = floor_to_step(min(self.get_base_balance(), filled_qty), f.qty_step)
        if qty <= 0:
            return False
        tp_pct = self.compute_tp_pct()
        base_price_for_tp = self.pos.entry_price if (self.pos.entry_price and self.pos.entry_price > 0) else buy_price
        sell_price = ceil_to_step(base_price_for_tp * (1 + tp_pct / 100.0), f.tick_size)
        return self._place_limit_sell_qty_price(qty, sell_price, note=note)
    # ---------- Dead coin / spread / volume ----------
    def check_dead_coin(self) -> Tuple[bool, str]:
        """Return (is_bad, reason). Multi-factor dead-coin test with soft hysteresis.
        [FIX-13A] Результат кэшируется на DEAD_COIN_CHECK_INTERVAL_SEC (30с).
        Ticker (1с) проверяется всегда — это быстро и кэшируется отдельно.
        Тяжёлые вызовы (orderbook depth, ohlc) — только раз в 30с.
        """
        now_dc = time.time()
        _dc_interval = float(getattr(CFG, 'DEAD_COIN_CHECK_INTERVAL_SEC', 30.0) or 30.0)
        # Быстрая проверка ticker (уже кэширован на 1с) — всегда
        t = self.get_ticker()
        last = float(t.get("lastPrice") or 0.0)
        bid = float(t.get("bid1Price") or 0.0)
        ask = float(t.get("ask1Price") or 0.0)
        turnover = float(t.get("turnover24h") or 0.0)
        if last <= 0:
            return True, "нет цены"
        if bid <= 0 or ask <= 0:
            return True, f"нет стакана (bid={bid}, ask={ask})"
        spread_pct = (ask - bid) / last * 100.0
        spread_limit = float(self._effective_max_spread_pct())
        reasons = []
        bad_score = 0
        if spread_pct > spread_limit:
            bad_score += 2
            reasons.append(f"спред {spread_pct:.2f}% > {spread_limit:.2f}%")
        elif spread_pct > spread_limit * 0.9:
            bad_score += 1
            reasons.append(f"спред близко к лимиту {spread_pct:.2f}%")
        if turnover > 0 and turnover < CFG.MIN_24H_TURNOVER_USDT:
            bad_score += 1
            reasons.append(f"оборот24h {turnover:.0f} < {CFG.MIN_24H_TURNOVER_USDT:.0f}")
        # [FIX-13A] Тяжёлые проверки (orderbook + ohlc) — только раз в _dc_interval
        if (now_dc - float(getattr(self, '_dead_coin_cache_ts', 0.0) or 0.0)) < _dc_interval:
            # Кэш ещё актуален — используем прежний результат тяжёлых проверок
            # но ticker-часть (spread/turnover) уже пересчитана выше
            _cached_bad = bool(getattr(self, '_dead_coin_cache_val', False))
            _cached_reason = str(getattr(self, '_dead_coin_cache_reason', '') or '')
            # Если spread уже плохой — сразу возвращаем True без тяжёлых проверок
            if bad_score >= 2:
                return True, '; '.join(reasons)
            # Иначе возвращаем кэшированный результат (включая depth/ohlc)
            if _cached_bad:
                reasons.append(f'(cached) {_cached_reason}')
                return True, '; '.join(reasons)
            return False, ''
        # Полная проверка (раз в _dc_interval) — выполняем тяжёлые вызовы
        try:
            mid_price = (bid + ask) / 2.0 if (bid > 0 and ask > 0) else last
            depth = float(self._orderbook_depth_usdt(self.symbol, mid_price) or 0.0)
            min_depth = float(getattr(CFG, 'MIN_ORDERBOOK_DEPTH_USDT', 5000.0) or 5000.0)
            if min_depth > 0 and depth < min_depth:
                bad_score += 1
                reasons.append(f"depth {depth:.0f} < {min_depth:.0f}")
        except Exception:
            depth = 0.0
        try:
            ohlc = self.get_ohlc(interval_min='1', limit=8)
            highs = [float(x) for x in (ohlc.get('high', []) or [])][-6:]
            lows = [float(x) for x in (ohlc.get('low', []) or [])][-6:]
            if highs and lows and min(lows) > 0:
                live_range = (max(highs) - min(lows)) / min(lows) * 100.0
                if live_range < 0.18:
                    bad_score += 1
                    reasons.append(f"1m range {live_range:.2f}% too flat")
        except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
            log(f'⚠️ [check_dead_coin] {_sw_ex}')  # [FIX-v152-3]
        result_bad = (bad_score >= 2)
        result_reason = '; '.join(reasons)
        # Сохраняем в кэш
        self._dead_coin_cache_val = result_bad
        self._dead_coin_cache_reason = result_reason
        self._dead_coin_cache_ts = now_dc
        return result_bad, result_reason
    # ---------- Smart dump stop ----------
    def is_dead_coin(self) -> bool:
        bad, _reason = self.check_dead_coin()
        return bool(bad)
    def is_dead_market(self) -> bool:
        # Dead-market = слабая волатильность/ликвидность по скору сканера
        thr = getattr(CFG, 'DEAD_MARKET_SCORE_THRESHOLD', 0.0)
        return (thr > 0.0) and (self.current_score < thr)
    def should_add_averaging_order(self, current_price: float) -> bool:
        """[FIX-v184-4] Мозг решает: открывать ли 3-й усредняющий ордер при просадке.

        Логика:
        - Цена упала от входа на -0.5% до -1.5% (не слишком мало, не слишком много)
        - RSI перепродан (<= 38) → отскок вероятен
        - Объём 30м растёт → покупатели заходят
        - EMA9 > EMA21 на 1H → общий тренд всё ещё вверх
        - Мозг знает историю монеты: восстанавливалась ли она раньше
        """
        try:
            # Условие 1: нет позиции — незачем усреднять
            _ep = float(self.pos.entry_price or 0)
            if _ep <= 0 or current_price <= 0:
                return False

            # Условие 2: просадка в диапазоне -0.5% до -1.8%
            _loss_pct = (_ep - current_price) / _ep * 100.0
            if _loss_pct < 0.5 or _loss_pct > 1.8:
                return False

            # Условие 3: у нас УЖЕ есть ордера в сетке (нет смысла если сетка пустая)
            _open_orders = int(getattr(self, '_last_open_orders_count', 0))
            if _open_orders == 0:
                return False

            # Условие 4: RSI 15m — перепродан (вероятен отскок)
            try:
                _rsi_data = call_with_retry(client.get_kline, category="spot",
                                             symbol=self.symbol, interval="15", limit=20)
                _rsi_lst = _rsi_data.get("result",{}).get("list",[]) or []
                if len(_rsi_lst) >= 14:
                    _closes_rsi = [float(_rsi_lst[i][4]) for i in range(len(_rsi_lst)-1,-1,-1)]
                    _gains=[max(0,_closes_rsi[i]-_closes_rsi[i-1]) for i in range(1,15)]
                    _losses=[max(0,_closes_rsi[i-1]-_closes_rsi[i]) for i in range(1,15)]
                    _ag=sum(_gains)/14; _al=sum(_losses)/14
                    _rsi_15m = 100-(100/(1+_ag/_al)) if _al>0 else 50.0
                    if _rsi_15m > 40.0:
                        return False  # не перепродан → отскок неочевиден
            except Exception:
                return False  # нет данных → не рискуем

            # Условие 5: EMA тренд на 1H — EMA9 > EMA21 (тренд вверх)
            try:
                _ema_data = call_with_retry(client.get_kline, category="spot",
                                             symbol=self.symbol, interval="60", limit=25)
                _ema_lst = _ema_data.get("result",{}).get("list",[]) or []
                if len(_ema_lst) >= 22:
                    _ema_closes=[float(_ema_lst[i][4]) for i in range(len(_ema_lst)-1,-1,-1)]
                    _ema9 =sum(_ema_closes[-9:])/9
                    _ema21=sum(_ema_closes[-21:])/21
                    if _ema9 < _ema21:
                        return False  # нисходящий тренд → не усредняем
            except Exception:
                return False

            # Условие 6: мозг знает историю монеты
            _recovery = self.knowledge.get_symbol_recovery_rate(self.symbol)
            if _recovery < 0.55:
                return False  # монета редко восстанавливается → не рискуем

            # Все условия пройдены → усредняем
            log(f"🧠 [v184] Усреднение одобрено: loss={_loss_pct:.2f}% RSI={_rsi_15m:.0f} recovery={_recovery:.0%}")
            return True

        except Exception as _avg_ex:
            log(f"⚠️ [should_avg] {_avg_ex}")
            return False

    def detect_dump(self) -> bool:
        """Определяет резкий дамп по последней завершённой 5m-свече + кумулятивное падение.
        Кэш на уровне экземпляра (self._dump_cache_val/self._dump_cache_ts) с TTL=1с.
        Это безопасно при do_switch/soft_restart: кэш сбрасывается вместе со state.
        """
        if not CFG.ENABLE_SMART_DUMP_STOP:
            return False
        now = time.time()
        # 1-секундный кэш на уровне экземпляра
        if (now - float(getattr(self, "_dump_cache_ts", 0.0)) < 1.0) and (getattr(self, "_dump_cache_val", None) is not None):
            return bool(self._dump_cache_val)
        try:
            _cum_bars = int(getattr(CFG, 'DUMP_CUMULATIVE_BARS', 3))
            res = call_with_retry(client.get_kline, category="spot", symbol=self.symbol, interval="5", limit=max(3, _cum_bars + 1))
            lst = res.get("result", {}).get("list", []) or []
            # Bybit: newest first → lst[0] = текущая свеча
            if len(lst) < 2:
                self._dump_cache_val = False
                self._dump_cache_ts = now
                return False
            # [FIX-v103-1] Проверяем ОБЕ свечи: завершённую И текущую
            cur = lst[1]; o = float(cur[1]); c = float(cur[4])
            if o <= 0 or c <= 0:
                self._dump_cache_val = False; self._dump_cache_ts = now; return False
            drop_pct = (o - c) / o * 100.0
            result = drop_pct >= CFG.DUMP_5M_PCT
            if not result and len(lst) >= 1:
                try:
                    live = lst[0]; lo = float(live[1]); lc = float(live[4])
                    if lo > 0 and lc > 0 and (lo-lc)/lo*100.0 >= CFG.DUMP_5M_PCT * 0.75:
                        result = True
                        log(f"⚡ [v103] Live-свеча дамп: {(lo-lc)/lo*100:.2f}%")
                except Exception as _crit_ex:  # [v145-silent]
                    log(f'⚠️ [detect_dump] {_crit_ex}')
            # [FIX-v142-2] Кумулятивный дамп: медленное падение за N свечей.
            # Если монета падает по -0.4%/свеча, ни одна свеча не триггерит dump_exit,
            # но суммарное падение за 3 свечи = -1.2% — это тоже дамп.
            if not result and len(lst) >= _cum_bars + 1:
                try:
                    _cum_factor = float(getattr(CFG, 'DUMP_CUMULATIVE_FACTOR', 1.3))
                    # Берём N завершённых свечей (от lst[1] до lst[N])
                    _closes = [float(lst[i][4]) for i in range(1, _cum_bars + 1) if len(lst[i]) > 4]
                    _opens_c = [float(lst[i][1]) for i in range(1, _cum_bars + 1) if len(lst[i]) > 4]
                    if len(_closes) >= 2 and _closes[-1] > 0 and _opens_c[0] > 0:
                        # Падение от открытия первой до закрытия последней из N свечей
                        _cum_drop = (_opens_c[-1] - _closes[0]) / _opens_c[-1] * 100.0
                        if _cum_drop >= CFG.DUMP_5M_PCT * _cum_factor:
                            result = True
                            log(f"⚡ [FIX-v142-2] Кумулятивный дамп {_cum_bars} свечей: {_cum_drop:.2f}%>={CFG.DUMP_5M_PCT*_cum_factor:.2f}%")
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [detect_dump] {_sw_ex}')
            self._dump_cache_val = result; self._dump_cache_ts = now
            # [FIX-v184-1] 1H dump с ДЕДУПЛИКАЦИЕЙ по timestamp свечи.
            # ПРОБЛЕМА БЫЛА: та же закрытая 1H свеча триггерила каждые 3 сек весь час
            # → cooldown постоянно сбрасывался → бот час не торговал (464 раза в логе!)
            # РЕШЕНИЕ: запоминаем timestamp свечи которая уже триггернула дамп
            # → одна свеча = один trigger → cooldown нормально истекает через 10 мин
            if not result and bool(getattr(CFG, 'DUMP_1H_ENABLE', True)):
                try:
                    _d1h_pct = float(getattr(CFG, 'DUMP_1H_PCT', 2.5))
                    _res1h = call_with_retry(client.get_kline, category="spot", symbol=self.symbol, interval="60", limit=2)
                    _lst1h = _res1h.get("result", {}).get("list", []) or []
                    if len(_lst1h) >= 2:
                        _1h_o   = float(_lst1h[1][1])
                        _1h_c   = float(_lst1h[1][4])
                        # Уникальный идентификатор закрытой свечи = её timestamp открытия
                        _candle_id = str(_lst1h[1][0])
                        _last_id   = str(getattr(self, '_last_dump_candle_id', ''))
                        if _1h_o > 0 and _1h_c > 0 and (_1h_o - _1h_c) / _1h_o * 100.0 >= _d1h_pct:
                            if _candle_id != _last_id:
                                # Новая свеча — дамп реальный
                                self._last_dump_candle_id = _candle_id
                                result = True
                                log(f"⚡ [FIX-v144-D1] 1H дамп: свеча упала {(_1h_o-_1h_c)/_1h_o*100:.2f}%>={_d1h_pct:.1f}%")
                            # else: та же свеча — уже учли, не повторяем
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [detect_dump] {_sw_ex}')
            # [FIX-v144-D2] Pump-and-dump паттерн: памп на 4H + падение за 1H.
            # Из графиков: ONDO/CC — памп +15% за несколько часов → вход → откат.
            if not result and bool(getattr(CFG, 'PUMP_DUMP_DETECT_ENABLE', True)):
                try:
                    _pd_pump_pct = float(getattr(CFG, 'PUMP_DUMP_4H_MIN_PCT', 15.0))
                    _pd_drop_pct = float(getattr(CFG, 'PUMP_DUMP_DROP_1H_PCT', 2.0))
                    # 4H изменение (памп)
                    _res4h = call_with_retry(client.get_kline, category="spot", symbol=self.symbol, interval="240", limit=3)
                    _lst4h = _res4h.get("result", {}).get("list", []) or []
                    if len(_lst4h) >= 2:
                        _4h_lo = min(float(r[3]) for r in _lst4h if len(r) > 3)
                        _4h_hi = max(float(r[2]) for r in _lst4h if len(r) > 3)
                        _4h_amp = (_4h_hi - _4h_lo) / _4h_lo * 100.0 if _4h_lo > 0 else 0.0
                        if _4h_amp >= _pd_pump_pct:
                            # Теперь проверяем последний 1H дроп
                            _res1h_pd = call_with_retry(client.get_kline, category="spot", symbol=self.symbol, interval="60", limit=2)
                            _lst1h_pd = _res1h_pd.get("result", {}).get("list", []) or []
                            if len(_lst1h_pd) >= 2:
                                _1h_hi_pd = float(_lst1h_pd[1][2]); _1h_cl_pd = float(_lst1h_pd[1][4])
                                if _1h_hi_pd > 0 and (_1h_hi_pd - _1h_cl_pd) / _1h_hi_pd * 100.0 >= _pd_drop_pct:
                                    result = True
                                    log(f"⚡ [FIX-v144-D2] Pump-dump: 4H памп={_4h_amp:.1f}% + 1H дроп={(_1h_hi_pd-_1h_cl_pd)/_1h_hi_pd*100:.2f}%")
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [detect_dump] {_sw_ex}')
            self._dump_cache_val = result; self._dump_cache_ts = now
            return bool(result)
        except Exception:
            self._dump_cache_val = False
            self._dump_cache_ts = now
            return False
    # ---------- Order history fills ----------
    @staticmethod
    def _trim_set(s: set, limit: int = 500) -> set:
        """[BUG-v130-5] Обрезает set до limit последних элементов. Унифицирован для всех persistent oid sets."""
        if len(s) > limit + 100:
            return set(list(s)[-limit:])
        return s

    def process_fills(self, current_price: float):
        hist = call_with_retry(client.get_order_history, category="spot", symbol=self.symbol, limit=200)  # [FIX-v35-5] было 50 → пропускало fill'ы при >50 ордеров между проверками
        orders = hist.get("result", {}).get("list", []) or []
        if len(orders) >= 200:
            log("⚠️ process_fills: история ордеров достигла лимита 200 — возможен пропуск fill'ов. Увеличь limit если нужно.")
        # FIX #3: processed_fills — OrderedDict с FIFO-удалением старых записей.
        # Старые ID удаляются первыми (popitem(last=False)) — это безопасно,
        # т.к. биржа не возвращает ордера старше лимита в API.
        _MAX_FILLS = 500
        while len(self.processed_fills) > _MAX_FILLS:
            self.processed_fills.popitem(last=False)  # удаляем самый старый
        # [BUG-v130-1/3] Persistent sets для BUY и SELL fill oids.
        # НЕ сбрасываются при processed_fills = OrderedDict() (в market_sell_emergency/do_switch).
        # Предотвращает повторную обработку fill'ов после сброса → ZEN x2 / CHIP x2 / двойной PnL.
        if not hasattr(self, '_processed_buy_oids'):
            self._processed_buy_oids: set = set()
        if not hasattr(self, '_processed_sell_oids'):
            self._processed_sell_oids: set = set()
        for o in orders:
            oid = o.get("orderId")
            status = o.get("orderStatus") or o.get("status")
            side = o.get("side")
            price_str = (o.get("avgPrice") or o.get("avgFillPrice") or o.get("price") or o.get("orderPrice"))
            qty_str = (o.get("cumExecQty") or o.get("execQty") or o.get("qty") or o.get("origQty"))
            created_ms = None
            for k in ("createdTime", "createdTimeMs", "createdAt", "createTime"):
                if o.get(k) is not None:
                    try:
                        created_ms = int(o.get(k))
                        break
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [process_fills] {_sw_ex}')
            if not oid or oid in self.processed_fills:
                continue
            # [BUG-v130-1] Проверяем persistent sets ДО processed_fills.
            # Если oid был обработан и processed_fills сброшен — persistent set блокирует повтор.
            _oid_str = str(oid)
            if _oid_str in getattr(self, '_processed_buy_oids', set()):
                self.processed_fills[oid] = True  # синхронизируем processed_fills
                continue
            if _oid_str in getattr(self, '_processed_sell_oids', set()):
                self.processed_fills[oid] = True
                continue
            if status not in ("Filled", "FILLED"):
                continue
            if created_ms is not None and created_ms < self.bot_start_ms:
                # старые ордера до запуска — помечаем и пропускаем
                self.processed_fills[oid] = True
                continue
            # ВАЖНО: не помечаем oid обработанным до валидации цены/кол-ва.
            try:
                fill_price = float(price_str or 0.0)
            except Exception:
                fill_price = 0.0
            try:
                fill_qty = float(qty_str or 0.0)
            except Exception:
                fill_qty = 0.0
            if fill_price <= 0 or fill_qty <= 0:
                continue
            # Помечаем oid обработанным ТОЛЬКО после успешной валидации
            self.processed_fills[oid] = True
            if side == "Buy":
                # [FIX-v122-2] КРИТИЧНО: не восстанавливаем позицию для перманентно забаненных монет.
                # Сценарий: CHIP забанен в 11:20, pos сброшен. Старые BUY ордера (выставленные ДО бана)
                # заполняются и process_fills восстанавливает pos → повторная аварийная продажа!
                # Решение: если монета в permanent_emergency_blacklist — немедленная продажа,
                # позицию НЕ восстанавливаем.
                if self.symbol in getattr(self, '_permanent_emergency_blacklist', set()):
                    log(f"🚫 [v122-2] BUY fill {oid} для ЗАБАНЕННОЙ монеты {self.symbol} — немедленная продажа, pos не восстанавливается")
                    self.processed_fills[oid] = True
                    # [FIX-v132-1] Добавляем в persistent set — иначе если processed_fills сбросится
                    # (market_sell_emergency делает это!), этот fill будет обработан повторно → ещё одна аварийная продажа.
                    _pb_oids_ban = getattr(self, '_processed_buy_oids', set())
                    _pb_oids_ban.add(str(oid))
                    self._processed_buy_oids = self._trim_set(_pb_oids_ban, 500)
                    try:
                        self.cancel_all_open_orders()
                        _sell_qty = float(fill_qty)
                        if _sell_qty > 0:
                            self.market_sell_emergency(_sell_qty, reason=f"banned_coin_buy_fill({self.symbol})")
                    except Exception as _bf_e:
                        log(f"⚠️ [v122-2] Ошибка продажи при fill забаненной монеты: {_bf_e}")
                    continue
                # [FIX-v122-4] Блокируем BUY fills поступившие после аварийного выхода.
                # Сценарий (ZEN x2, CHIP x2): stop_loss сбрасывает pos, но уже-заполненные
                # BUY ордера из order_history восстанавливают pos в следующей итерации →
                # повторный стоп-лосс / dump_exit. 90 секунд = достаточно для API sync.
                _emerg_ts = float(getattr(self, '_emergency_exit_ts', 0.0) or 0.0)
                if _emerg_ts > 0 and (time.time() - _emerg_ts) < 90.0:
                    log(f"⚠️ [v122-4] Пропуск BUY fill {oid} — произошёл {time.time()-_emerg_ts:.0f}с после аварийного выхода (guard активен 90с)")
                    # [FIX-v132-1] Добавляем в persistent set — иначе если processed_fills сбросится,
                    # этот fill будет обработан повторно в следующей итерации.
                    _pb_oids_eg = getattr(self, '_processed_buy_oids', set())
                    _pb_oids_eg.add(str(oid))
                    self._processed_buy_oids = self._trim_set(_pb_oids_eg, 500)
                    try:
                        self.cancel_all_open_orders()
                        _sell_qty = float(fill_qty)
                        if _sell_qty > 0:
                            _chk_val = _sell_qty * fill_price
                            if _chk_val >= float(getattr(CFG, 'SELL_MIN_USDT', 1.5)):
                                self.market_sell_emergency(_sell_qty, reason=f"post_emergency_buy_fill_guard")
                    except Exception as _eg_e:
                        log(f"⚠️ [v122-4] Ошибка guard продажи: {_eg_e}")
                    continue
                self._last_buy_fill_ts = time.time()
                # [FIX-v149-2] filled_orders_count при BUY fill
                try:
                    self.pos.filled_orders_count = int(getattr(self.pos, "filled_orders_count", 0)) + 1
                except Exception as _foc_ex:
                    log(f"⚠️ [process_fills] filled_orders_count: {_foc_ex}")  # [FIX-v150-1]
                # [BUG-v130-1] Добавляем oid в persistent set СРАЗУ — до обновления позиции.
                # Если processed_fills будет сброшен до следующего вызова process_fills,
                # этот set заблокирует повторную обработку того же BUY fill.
                _pb_oids = getattr(self, '_processed_buy_oids', set())
                _pb_oids.add(str(oid))
                self._processed_buy_oids = self._trim_set(_pb_oids, 500)  # [BUG-v130-5]
                # [FIX-v142-B2] Falling grid detector — защита от быстрого исполнения всей сетки.
                # Из графиков: бот выставлял B,B,B все три ордера в нисходящем тренде.
                # Если 2+ BUY fills исполнились за < FALLING_GRID_TIME_MIN минут →
                # цена быстро падает через всю сетку = тренд вниз → отмена и стоп.
                if bool(getattr(CFG, 'FALLING_GRID_ENABLE', True)):
                    try:
                        if not hasattr(self, '_grid_buy_fill_times'):
                            self._grid_buy_fill_times: list = []
                        self._grid_buy_fill_times.append(time.time())
                        # Оставляем только fills за последние 30 минут
                        _fg_window = 30.0 * 60
                        self._grid_buy_fill_times = [t for t in self._grid_buy_fill_times
                                                      if time.time() - t <= _fg_window]
                        _fg_min_fills = int(getattr(CFG, 'FALLING_GRID_MIN_FILLS', 2))
                        _fg_time_min = float(getattr(CFG, 'FALLING_GRID_TIME_MIN', 15.0))
                        if len(self._grid_buy_fill_times) >= _fg_min_fills:
                            # Время между первым и последним fill в окне
                            _fg_elapsed_min = (self._grid_buy_fill_times[-1] - self._grid_buy_fill_times[0]) / 60.0
                            if _fg_elapsed_min <= _fg_time_min and _fg_elapsed_min > 0:
                                _fg_msg = (
                                    f"⚡ [FIX-v142-B2] Falling grid! {len(self._grid_buy_fill_times)} BUY fills "
                                    f"за {_fg_elapsed_min:.1f}мин < {_fg_time_min:.0f}мин — цена падает через сетку. "
                                    f"Отменяю оставшиеся BUY ордера."
                                )
                                log(_fg_msg)
                                if TG.enabled:
                                    TG.send(_fg_msg)
                                # Отменяем все оставшиеся BUY ордера
                                try:
                                    _open_buys_fg = [o for o in self.get_open_orders()
                                                     if str(o.get('side', '')).lower() == 'buy']
                                    if _open_buys_fg:
                                        self.cancel_all_open_orders()
                                        log(f"🧹 [FIX-v142-B2] Отменены {len(_open_buys_fg)} BUY ордеров")
                                    self._grid_buy_fill_times = []  # сброс счётчика
                                    # Ставим cooldown 20 минут — не строить новую сетку
                                    self._grid_fail_backoff_until = time.time() + 1200.0
                                    # [FIX-v300-BUG] УДАЛЁН self.knowledge.log_trade_exit(...) здесь.
                                    # Было: этот блок вызывал log_trade_exit() с pnl, посчитанным по ТЕКУЩЕЙ
                                    # цене, хотя позиция в этот момент НЕ закрывается — оба ордера сетки
                                    # просто исполнились, и сразу после этого блока код пересобирает единый
                                    # TP на весь объём (After-all-fills SELL) и продолжает держать позицию.
                                    # log_trade_exit() — это метод "сделка реально закрыта", он обнуляет
                                    # self.knowledge._cur. Когда позиция ПОЗЖЕ закрывалась по-настоящему
                                    # (TP/dump_exit/time_stop), _cur был уже пуст → код создавал
                                    # "синтетический _cur" и логировал ВТОРОЙ, отдельный exit для той же
                                    # самой сделки. Итог: один реальный трейд считался в BotKnowledge
                                    # как ДВЕ сделки (часто обе "в убыток" по знаку) — удваивался урон по
                                    # винрейту, доверию к боту-сигналу (bot_trust падал вдвое быстрее) и
                                    # по решению о перманентном бане монеты. Подтверждено в логах 08.07:
                                    # SOMIUSDT записан как loss -0.0486 (falling_grid_cancelled) в 00:16:23,
                                    # затем ВТОРОЙ раз как loss -0.1462 (dump_exit) в 00:18:50 для той же
                                    # позиции — суммарно вдвое больше "выученного" убытка, чем было в
                                    # реальности. Позиция продолжает жить дальше без записи в мозг —
                                    # реальный exit_reason/pnl будет корректно записан один раз, когда
                                    # она действительно закроется (TP/SL/time_stop/dump_exit).
                                    log(f"📝 [v300] Falling grid: сетка полностью заполнена, позиция "
                                        f"ПРОДОЛЖАЕТ жить с пересобранным TP (в мозг не пишем — не exit)")
                                except Exception as _fg_cancel_ex:
                                    log(f"⚠️ [v142-B2] cancel error: {_fg_cancel_ex}")
                    except Exception as _fg_ex:
                        log(f"⚠️ [v142-B2] falling_grid error: {_fg_ex}")
                # update position — средневзвешенная цена входа
                # Используем fill_qty из ордера, не запрашиваем баланс с биржи —
                # это убирает погрешность из-за асинхронного обновления баланса
                new_cost = fill_price * fill_qty
                old_cost = self.pos.entry_cost
                old_qty  = self.pos.base_qty  # накопленное кол-во из предыдущих fill
                total_qty = old_qty + fill_qty
                self.pos.entry_cost = old_cost + new_cost
                self.pos.base_qty   = total_qty  # обновляем из fill, не из биржи
                if total_qty > 0:
                    self.pos.entry_price = self.pos.entry_cost / total_qty
                else:
                    self.pos.entry_price = fill_price
                if self.pos.entry_time_ms is None:
                    self.pos.entry_time_ms = now_ms()
                    # [FIX-v167-2] Записываем контекст входа в базу знаний
                    try:
                        _k_adx = float(getattr(self,"_last_adx_val",0) or 0)
                        _k_rsi = float(getattr(self,"_last_rsi_val",0) or 0)
                        if _k_adx <= 0: _k_adx = float(getattr(self,"_ptf_last_adx",0.0) or 0.0)  # [v295-1]
                        if _k_rsi <= 0: _k_rsi = float(getattr(self,"_ptf_last_rsi",0.0) or 0.0)  # [v295-1]
                        _k_score = float(getattr(self,"current_score",0) or 0)
                        _k_turn = float(CFG.MIN_24H_TURNOVER_USDT)
                        _k_stak = float(CFG.MIN_ORDERBOOK_DEPTH_USDT)
                        _k_tier = int(getattr(self,"_last_logged_tier",1))
                        # [v232-ADVISOR] Сохраняем текущие советы ботов → попадут в _cur трейда
                        try:
                            self.knowledge._data["_pending_bot_advisory"] = dict(getattr(self, '_bot_advisory', {}))
                        except Exception: pass
                        self._last_trade_ts = time.time()  # [FIX-v190-NOTRADE]
                        self._last_buy_ts = time.time()    # [FIX-v258-2] для TG hold >2ч
                        self.knowledge.log_trade_entry(
                            symbol=self.symbol,
                            entry_price=self.pos.entry_price,
                            adx=_k_adx, rsi=_k_rsi, score=_k_score,
                            turnover=_k_turn, tier=_k_tier,
                            mode=CFG.TRADING_MODE,
                            stakan=_k_stak)
                    except Exception as _ke: log(f"⚠️ [knowledge entry] {_ke}")
                if self.pos.peak_price is None or fill_price > self.pos.peak_price:
                    self.pos.peak_price = fill_price
                self.pos.trailing_active = False
                # fee estimate (buy)
                fee_buy = new_cost * (CFG.FEE_RATE_PCT / 100.0)
                self.pnl.fees_usdt += fee_buy
                self.pnl.fee_buy_usdt += fee_buy
                self.pnl.hour_fees += fee_buy
                self.pnl.day_fees += fee_buy
                self.pnl.day_fee_buy += fee_buy
                self._csv_log("BUY", fill_qty, fill_price, gross=-new_cost, fee=fee_buy, net=-new_cost - fee_buy, note="fill")
                if TG.enabled and CFG.TG_SEND_TRADES:
                    _tg_tp1_p, _tg_tp2_p = self._pro_target_prices(float(self.pos.entry_price)) if self.pos.entry_price else (0.0, 0.0)
                    TG.send(
                        f"✅ BUY исполнен\n"
                        f"Пара: {self.symbol}\n"
                        f"Цена: {fill_price:.6f}\n"
                        f"Кол-во: {fill_qty:.6f}\n"
                        f"Сумма: ~{new_cost:.4f} USDT\n"
                        f"Ср.цена входа: {self.pos.entry_price:.6f}\n"
                        f"Комиссия BUY~: {fee_buy:.4f} USDT\n"
                        + (f"→ TP1~: {_tg_tp1_p:.6f} | TP2~: {_tg_tp2_p:.6f}" if _tg_tp1_p > 0 else "")
                    )
                # [FIX-v103-3] Отложенная постановка SELL (после ВСЕХ BUY)
                self._last_buy_fill_ts = time.time()
                self._need_sell_rebuild = True
                self.pos.tp1_order_active = False
                self.pos.tp2_order_active = False
                self.pos.be_order_active = False
                # [v103] SELL ставится в after-all-fills блоке ниже
            # [FIX-v109-2] After-all-fills: одна постановка SELL после ВСЕХ BUY за один запрос.
            # Проблема старой логики: блок выполнялся для каждого BUY fill внутри цикла,
            # что могло приводить к повторным постановкам SELL при нескольких BUY fill'ах.
            # Новая логика: проверяем есть ли ещё необработанные BUY fill'ы впереди.
            # Только если их нет — ставим SELL один раз.
            if getattr(self, "_need_sell_rebuild", False) and side == "Buy":
                # [FIX-v120-3] orders.index(o) обёрнут в try/except.
                # PENGU/SAHARA BUG (v109→v119): ValueError → блок падал молча,
                # _need_sell_rebuild=True но oid уже в processed_fills →
                # SELL никогда не выставлялся повторно.
                # Fallback: index не нашёл → ставим SELL немедленно.
                try:
                    _cur_idx = orders.index(o)
                    _remaining_buy_fills = [
                        x for x in orders[_cur_idx + 1:]
                        if x.get("orderStatus") in ("Filled", "FILLED")
                        and x.get("side") == "Buy"
                        and x.get("orderId") not in self.processed_fills
                    ]
                except (ValueError, Exception):
                    log(f"⚠️ [v120] orders.index fallback для {oid} — SELL немедленно")
                    _remaining_buy_fills = []
                if not _remaining_buy_fills:
                    # Все BUY fill'ы обработаны — ставим SELL один раз
                    self._need_sell_rebuild = False
                    try:
                        time.sleep(0.4)
                        _ops = self.get_open_orders()
                        if any(str(x.get("side", "")).lower() == "sell" for x in _ops):
                            self.cancel_open_sell_orders()
                            time.sleep(0.2)
                        log(f"🔄 [v109] After-all-fills SELL: base={self.pos.base_qty:.4f}")
                    except Exception as _ae:
                        log(f"⚠️ [v109] {_ae}")
                    # [v219-FIX-SELL] 5 попыток → 10 попыток, задержка 1.5с
                    # Биржа иногда требует 8-12с для обновления баланса после BUY
                    _paf = False
                    for _paf_i in range(10):
                        # Ждём пока баланс появится
                        _bal_now = float(self.get_base_balance() or 0)
                        if _bal_now <= 0 and _paf_i < 6:
                            time.sleep(1.5)
                            continue
                        if self.place_tp_sell(fill_price, self.pos.base_qty, note="(after all BUY)"):
                            _paf = True
                            break
                        time.sleep(1.5)
                    if not _paf:
                        log("⚠️ [v109] SELL не поставился → guard")
                        if TG.enabled:
                            TG.send("⚠️ Не удалось подтвердить SELL после BUY. Усиленная защита.")
                        self._post_buy_sell_guard(fill_price, self.pos.base_qty or fill_qty)
                    elif not self._wait_sell_coverage_after_buy(self.pos.base_qty, current_price=fill_price):
                        if TG.enabled:
                            TG.send("🚨 BUY без SELL после повторов. Аварийная защита.")
            elif side == "Sell":
                # [FIX-v128-1] Проверяем: этот SELL fill — emergency IOC ордер?
                # Если да — PnL уже записан _record_emergency_exit_pnl() ДО продажи.
                # Пропускаем повторную запись PnL.
                _emerg_ids = getattr(self, '_emergency_sell_ids', set())
                if str(oid) in _emerg_ids:
                    log(f"ℹ️ [v128-1] Пропуск SELL fill {oid} — emergency IOC, PnL уже записан")
                    continue
                # [BUG-v130-3] Добавляем oid в persistent set СРАЗУ.
                # Предотвращает повторную обработку лимитных TP SELL после сброса processed_fills.
                # Это устраняет двойную запись PnL (SELL исполнен + FINAL SELL filled).
                _ps_oids = getattr(self, '_processed_sell_oids', set())
                _ps_oids.add(str(oid))
                self._processed_sell_oids = self._trim_set(_ps_oids, 500)  # [BUG-v130-5]
                self._last_sell_fill_ts = time.time()
                # ── Детальный расчёт PnL ───────────────────────────────────
                sell_value = fill_price * fill_qty
                fee_sell = sell_value * (CFG.FEE_RATE_PCT / 100.0)
                gross = 0.0
                net = -fee_sell
                note = "sell fill"
                entry_p = self.pos.entry_price
                # [FIX-17C] Если entry_price=None — пробуем восстановить из истории ордеров
                if (entry_p is None or entry_p <= 0) and fill_qty > 0:
                    try:
                        _hist = call_with_retry(client.get_order_history,
                                               category='spot', symbol=self.symbol, limit=20)
                        _orders = (_hist or {}).get('result', {}).get('list', []) or []
                        _buy_fills = [o for o in _orders
                                      if str(o.get('side','')).lower()=='buy'
                                      and str(o.get('orderStatus','')).lower() in ('filled','partialfilled')
                                      and float(o.get('avgPrice') or 0.0) > 0]
                        if _buy_fills:
                            _tc, _tq = 0.0, 0.0
                            for _o in _buy_fills[:5]:
                                _p = float(_o.get('avgPrice') or 0.0)
                                _q = float(_o.get('cumExecQty') or 0.0)
                                if _p > 0 and _q > 0:
                                    _tc += _p * _q; _tq += _q
                            if _tq > 0:
                                entry_p = _tc / _tq
                                self.pos.entry_price = entry_p
                                log(f"ℹ️ [FIX-17C] entry_price восстановлен для SELL: {entry_p:.6f}")
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [process_fills] {_sw_ex}')
                if entry_p is not None and entry_p > 0:
                    buy_cost = entry_p * fill_qty
                    fee_buy_this = buy_cost * (CFG.FEE_RATE_PCT / 100.0)
                    gross = (fill_price - entry_p) * fill_qty
                    net = gross - fee_sell - fee_buy_this
                    pct = gross / buy_cost * 100.0 if buy_cost > 0 else 0.0
                    # accumulated stats
                    self.pnl.gross_usdt += gross
                    self.pnl.realized_usdt += net
                    self.pnl.hour_realized += net
                    self.pnl.hour_gross += gross
                    self.pnl.day_realized += net
                    self._daily_on_sell(net)
                    self.pnl.day_gross += gross
                    self._last_trade_ts = time.time()
                else:
                    # [FIX-BUG5] entry_price неизвестен — считаем только fee-потери
                    pct = 0.0
                    fee_buy_this = 0.0
                    gross = 0.0
                    # Даже без entry_price: net = -fee_sell — учитываем в PnL и daily lock
                    self.pnl.realized_usdt += net        # net = -fee_sell
                    self.pnl.hour_realized += net
                    self.pnl.day_realized += net
                    self._daily_on_sell(net)             # [FIX-BUG5] дневной стоп теперь всегда знает об убытке
                    self._last_trade_ts = time.time()
                    log(f"⚠️ SELL fill без known entry_price: fee-only net={net:.4f} USDT (entry_price=None)")
                self.pnl.fees_usdt += fee_sell
                self.pnl.fee_sell_usdt += fee_sell
                self.pnl.hour_fees += fee_sell
                self.pnl.day_fees += fee_sell
                self.pnl.day_fee_sell += fee_sell
                self._csv_log("SELL", fill_qty, fill_price, gross=gross, fee=fee_sell, net=net, note=note)
                log(f"💰 SELL filled @ {fill_price:.6f} | qty={fill_qty:.6f} | gross~={gross:.4f} | net~={net:.4f} USDT")
                if TG.enabled and CFG.TG_SEND_TRADES:
                    sign = "🟢" if net >= 0 else "🔴"
                    total_trades = self.pnl.trades_count
                    total_net = self.pnl.realized_usdt
                    win_rate = (self.pnl.profitable_trades / total_trades * 100) if total_trades > 0 else 0.0
                    # [FIX-v269-1] Определяем кто продал: бот (по нашему ордеру) или вручную
                    _our_oids = (getattr(self, '_processed_sell_oids', set())
                                 | getattr(self, '_emergency_sell_ids', set()))
                    _our_last = str(getattr(self, '_last_limit_sell_oid', ''))
                    _is_ours = (str(oid) in _our_oids) or (str(oid) == _our_last) or note
                    _seller = "🤖 БОТ" if _is_ours else "👤 ВРУЧНУЮ"
                    # [FIX-v269-1] Точный процент прибыли/убытка от цены входа
                    _entry_p269 = float(self.pos.entry_price or 0.0)
                    _pct269 = ((fill_price - _entry_p269) / _entry_p269 * 100.0) if _entry_p269 > 0 else 0.0
                    TG.send(
                        f"{sign} SELL исполнен ({_seller})\n"
                        f"Пара: {self.symbol}\n"
                        f"Цена: {fill_price:.6f}\n"
                        f"Кол-во: {fill_qty:.6f}\n"
                        f"───────────────\n"
                        f"Gross PnL~:  {gross:+.4f} USDT ({_pct269:+.2f}%)\n"
                        f"Fees BUY~:  -{fee_buy_this:.4f} USDT\n"
                        f"Fees SELL~: -{fee_sell:.4f} USDT\n"
                        f"Net PnL~:    {net:+.4f} USDT\n"
                        f"───────────────\n"
                        f"Накопительно:\n"
                        f"Сделок: {total_trades} | Винрейт: {win_rate:.0f}%\n"
                        f"Net всего~: {total_net:+.4f} USDT\n"
                        f"Комиссии всего~: {self.pnl.fees_usdt:.4f} USDT"
                    )
                # ── Consecutive loss → автосмена монеты ───────────────────
                # [FIX-v157-1] Используем CONSECUTIVE_LOSS_SWITCH_MAX для смены монеты
                # (не путать с CONSECUTIVE_LOSS_MAX=3 который паузирует торговлю)
                max_losses = int(getattr(CFG, "CONSECUTIVE_LOSS_SWITCH_MAX", 2))
                if self._consecutive_losses >= max_losses and CFG.ENABLE_AUTO_SWITCH:
                    log(f"🔴 {max_losses} SELLа подряд в минус → запускаю смену монеты")
                    if TG.enabled:
                        TG.send(f"🔴 {max_losses} убыточных SELL подряд → ищу новую монету...")
                    self._consecutive_losses = 0
                    try:
                        cur_price = current_price
                        new_best, new_score = self.scan_market_top(confirmed_only=True)
                        if new_best and new_best != self.symbol and self.can_switch_safely(cur_price):
                            self.do_switch(new_best, new_score)
                            self._rebuild_after_switch()
                            if TG.enabled:
                                TG.send(f"🔁 Сменил монету на {new_best} (после {max_losses} минусов)")
                    except Exception as _ex:
                        log(f"⚠️ Consecutive loss switch error: {_ex}")
                # Profit rotation: после N прибыльных SELL-циклов на монете — перескан и смена (если безопасно)
                try:
                    max_profit_sells = int(getattr(CFG, "SWITCH_AFTER_PROFIT_SELLS", 0) or 0)
                    max_runtime_min = int(getattr(CFG, "MAX_SYMBOL_RUNTIME_MIN", 0) or 0)
                    runtime_trigger = False
                    if max_runtime_min > 0:
                        runtime_trigger = (time.time() - float(getattr(self, "_last_symbol_switch_ts", time.time()))) >= (max_runtime_min * 60)
                    trigger = False
                    if max_profit_sells > 0 and getattr(self, "_profit_sells_on_symbol", 0) >= max_profit_sells:
                        trigger = True
                    if runtime_trigger:
                        trigger = True
                    if trigger:
                        # минимум времени на монете (антипинг-понг) + правило "3 профита подряд — остаёмся"
                        min_hold = int(getattr(CFG, "MIN_SYMBOL_HOLD_MIN", 0) or 0)
                        held_sec = time.time() - float(getattr(self, "_symbol_enter_ts", getattr(self, "_last_symbol_switch_ts", time.time())))
                        if (min_hold > 0) and (held_sec < min_hold * 60):
                            # слишком рано после свитча/старта — пропускаем мягкую ротацию
                            pass
                        elif int(getattr(self, "_profit_streak", 0)) >= int(getattr(CFG, "STAY_IF_PROFIT_STREAK", 3)):
                            # монета даёт стабильный профит — остаёмся
                            pass
                        else:
                            # меняем монету только когда нет позиции и остаток не мешает
                            if self.pos.base_qty <= 0:
                                cur_price = current_price
                                new_best, new_score = self.scan_market_top(confirmed_only=True)
                                if new_best and new_best != self.symbol and self.can_switch_safely(cur_price):
                                    self._set_stage('SWITCH_EXECUTE', old=self.symbol, new=new_best, score=f'{new_score:.2f}')
                                    self.do_switch(new_best, new_score)
                                    self._last_switch_ts = time.time()
                                    self._idle_scan_reject_streak = 0
                                    self._rebuild_after_switch()
                                    if TG.enabled:
                                        TG.send(f"🔁 Rotation switch → {new_best} (profit_sells={getattr(self,'_profit_sells_on_symbol',0)}/{max_profit_sells})")
                except Exception as _ex:
                    log(f"⚠️ Profit rotation switch error: {_ex}")
                # After SELL: cancel any remaining open orders (BUY and orphan SELL) and rebuild
                try:
                    opens = self.get_open_orders()
                    # [FIX-13] отменяем ВСЕ оставшиеся BUY-ордера (лесенка)
                    # Оставшиеся SELL-ордера не отменяем: если был частичный fill нескольких BUY,
                    # может остаться ещё один SELL — пусть исполнится.
                    open_buys = [x for x in opens if x.get("side") == "Buy"]
                    for x in open_buys:
                        xid = x.get("orderId")
                        if xid:
                            self.cancel_order(xid)
                    if open_buys:
                        log("🧹 Extra BUY canceled after SELL fill")
                except Exception as e:
                    log(f"⚠️ Post-SELL cleanup error: {e}")
                # Tail-safe partial/final sell handling
                _min_step = float(getattr(self.filters, "qty_step", 0.0)) if self.filters else 0.0
                _prev_qty = float(self.pos.base_qty or 0.0)
                # [FIX-TAIL-A] если pos.base_qty=0 (сброшен до fill) —
                # получаем реальный баланс с биржи как базу для расчёта остатка
                if _prev_qty <= 0 and fill_qty > 0:
                    try:
                        _real_bal = float(self.get_base_balance() or 0.0)
                        _prev_qty = _real_bal + fill_qty  # восстанавливаем: до продажи было больше
                        log(f"ℹ️ [TAIL-A] pos.base_qty=0 перед SELL fill — восстановлено из баланса: prev~={_prev_qty:.6f}")
                    except Exception:
                        _prev_qty = fill_qty  # минимально: считаем что продали всё что было
                _remaining_qty = max(0.0, _prev_qty - fill_qty)
                # Синхронизируем с реальным балансом биржи для надёжности
                try:
                    _real_remaining = floor_to_step(float(self.get_base_balance() or 0.0),
                                                    float(getattr(self.filters, 'qty_step', 0.0) or 0.0))
                    if _real_remaining < _remaining_qty:  # биржа показывает меньше — доверяем ей
                        _remaining_qty = _real_remaining
                except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                    log(f'⚠️ [process_fills] {_sw_ex}')
                self.pos.base_qty = _remaining_qty
                if self.pos.entry_price is not None:
                    self.pos.entry_cost = float(self.pos.entry_price or 0.0) * _remaining_qty
                try:
                    tp1_ratio = float(getattr(CFG, "TP1_SIZE", 0.70))
                except Exception:
                    tp1_ratio = 0.70
                partial_close = False
                if _prev_qty > 0 and fill_qty < max(_prev_qty - _min_step, 0.0):
                    partial_close = True
                if _prev_qty > 0 and fill_qty >= (_prev_qty * tp1_ratio * 0.85):
                    self.pos.tp1_done = True
                    partial_close = True
                is_flat = not self.has_live_remainder(current_price)
                if is_flat:
                    # [FIX-v158-1] Если позиция полностью закрыта и TP1 был сделан → TP2 тоже исполнен.
                    # tp2_done — флаг для логов и будущих фич (полное закрытие позиции).
                    if self.pos.tp1_done:
                        self.pos.tp2_done = True
                    # [FIX-27C] Позиция полностью закрыта — отменяем незаполненные BUY
                    try:
                        _flat_buys = [o for o in self.get_open_orders()
                                      if str(o.get('side','')).lower() == 'buy']
                        if _flat_buys:
                            self.cancel_all_open_orders()
                            log(f"🧹 [FIX-27C] Позиция закрыта → отменены {len(_flat_buys)} незаполненных BUY")
                            if TG.enabled:
                                TG.send(f"🧹 Позиция {self.symbol} закрыта → отменены {len(_flat_buys)} BUY ордера из сетки")
                    except Exception as _fb_e:
                        log(f"⚠️ FIX-27C cancel buys error: {_fb_e}")
                if partial_close and not is_flat:
                    self._last_partial_close_ts = time.time()
                    self._last_partial_close_info = {
                        'qty_sold': float(fill_qty),
                        'price': float(fill_price),
                        'remainder_qty': float(self.pos.base_qty),
                        'remainder_value_usdt': float(self.remainder_value_usdt(current_price)),
                        'net': float(net),
                    }
                    self.pnl.realized_partial_usdt = float(net)  # [FIX-BUG2] только текущий partial, НЕ аккумулятор (realized_usdt уже накоплен выше)
                    self.pnl.position_remaining_qty = float(self.pos.base_qty)
                    self.pnl.position_remaining_cost = float(self.pos.entry_cost or 0.0)
                    self._remainder_last_value_usdt = float(self.remainder_value_usdt(current_price))
                    self._remainder_mode = True
                    if not self._remainder_since_ts:
                        self._remainder_since_ts = time.time()
                    try:
                        self.cancel_open_sell_orders()
                        # [FIX-v99-1] Ждём подтверждения отмены от биржи.
                        # Без паузы get_open_orders() в _manage_protective_exit
                        # ещё видит отменённый TP2 → remaining=0 → TP2 не восстанавливается.
                        time.sleep(0.5)
                    except Exception as _sw_ex:  # [FIX-v145-BARE-EXCEPT]
                        log(f'⚠️ [process_fills] {_sw_ex}')
                    try:
                        self._manage_protective_exit(current_price)
                        self._protective_exit_called_in_fill = True  # [FIX-BUG13]
                    except Exception as _pro_sell_ex:
                        log(f"⚠️ PRO exit refresh error: {_pro_sell_ex}")
                    self.ensure_sell_for_remainder(current_price)
                    if TG.enabled and CFG.TG_SEND_TRADES:
                        sign = "🟡"
                        TG.send(
                            f"{sign} TP1 SELL filled\n"
                            f"Пара: {self.symbol}\n"
                            f"Цена: {fill_price:.6f}\n"
                            f"Продано: {fill_qty:.6f}\n"
                            f"Net partial~: {net:+.4f} USDT\n"
                            f"Остаток: {self.pos.base_qty:.6f}\n"
                            f"Остаток value~: {self.remainder_value_usdt(current_price):.4f} USDT\n"
                            f"Remainder protection: active"
                        )
                else:
                    # final close only here
                    if self.finalize_trade_only_when_flat(current_price):
                        self.pnl.realized_final_usdt = float(net)  # [FIX-BUG2] только последний final, НЕ аккумулятор (realized_usdt уже накоплен выше)
                        self.pnl.position_remaining_qty = 0.0
                        self.pnl.position_remaining_cost = 0.0
                        self.pnl.trades_count += 1
                        self.pnl.hour_trades += 1
                        # [FIX-v177-1] Маркируем позицию: открыта по SMC или самостоятельно
                        # SMC бот и v177 обменяются через smc_signals.json
                        # [FIX-v182-4] убраны inline import os/json — используем глобальные (L1206-1207)
                        try:
                            _sf_mk = os.path.join(BASE_DIR, "smc_signals.json")
                            if os.path.exists(_sf_mk):
                                with open(_sf_mk,'r',encoding='utf-8') as _f_mk:
                                    _sd_mk = json.load(_f_mk)
                                _now_mk = time.time()
                                _opened_by_smc = False
                                for _s in (_sd_mk.get("signals") or []):
                                    if not isinstance(_s, dict):
                                        continue
                                    # [FIX-v180-2] valid_until может быть null в JSON
                                    # _s.get("valid_until",0) возвращает None если ключ есть но = null
                                    _s_valid = float(_s.get("valid_until") or 0)
                                    if (_s.get("symbol") == self.symbol and
                                            _s_valid > _now_mk):
                                        _s["consumed_by_v170"]   = True
                                        _s["v170_trade_result"]  = "opened_by_smc"
                                        _opened_by_smc = True
                                        break
                                if not _opened_by_smc:
                                    # Добавляем запись что открыли самостоятельно
                                    _sd_mk.setdefault("independent_trades",[]).append({
                                        "symbol": self.symbol,
                                        "ts":     _now_mk,
                                        "result": "opened_independent",
                                    })
                                with open(_sf_mk,'w',encoding='utf-8') as _f_mk:
                                    json.dump(_sd_mk, _f_mk, ensure_ascii=False, indent=2)
                                log(f"📝 [v177] Позиция {'по SMC' if _opened_by_smc else 'самостоятельно'}: {self.symbol}")
                        except Exception as _mk_ex:
                            log(f"⚠️ [mark_trade] {_mk_ex}")
                        self.pnl.day_trades += 1
                        if net >= 0:
                            self.pnl.profitable_trades += 1
                            self.pnl.hour_wins += 1    # [FIX-v144-STRUCT1]
                            self._consecutive_losses = 0
                            if net > 0:
                                self._profit_streak = int(getattr(self, "_profit_streak", 0)) + 1
                                self._profit_sells_on_symbol += 1
                                # [FIX-v100] Сбрасываем счётчик stop_loss при прибыльной сделке
                                _sl_key = f"_sl_count_{self.symbol}"
                                if getattr(self, _sl_key, 0) > 0:
                                    setattr(self, _sl_key, 0)
                            else:
                                self._profit_streak = 0
                            # [FIX-v168-3] Записываем ПРИБЫЛЬНЫЙ выход в базу знаний
                            # Раньше записывались только убытки (TIME_STOP)!
                            # Без этого WR в базе = всегда 0% → неверный анализ
                            try:
                                self.knowledge.log_trade_exit(
                                    exit_price=fill_price,
                                    pnl_usdt=net,
                                    exit_reason="TP_fill" if net > 0 else "BE_fill")
                                self._last_trade_ts = time.time()
                                # [FIX-v253-2] ИИ учится на победе
                                if net > 0 and getattr(self, 'ai_advisor', None):
                                    try:
                                        _win_t = {
                                            'symbol': self.symbol,
                                            'pnl_usdt': net,
                                            'adx': float(getattr(self, '_last_adx', 0) or 0),
                                            'rsi': float(getattr(self, '_last_rsi', 50) or 50),
                                            'hour': __import__('datetime').datetime.now().hour,
                                            'mode': str(getattr(CFG, 'TRADING_MODE', '?')),
                                        }
                                        self.ai_advisor.ai_explain_win(_win_t)
                                    except Exception: pass
                                # [FIX-v173-2] SMC контекст при TP
                                try:
                                    _smc_result = "profit" if net > 0 else "breakeven"
                                    _smc_sig_tp = self.knowledge.get_smc_signal(self.symbol)
                                    self.knowledge.log_smc_context(self.symbol, _smc_sig_tp, _smc_result)
                                except Exception as _sc_ex:
                                    log(f"⚠️ [smc_ctx TP] {_sc_ex}")
                                # Возврат в Tier 1 после прибыльной сделки
                                if bool(getattr(CFG, 'ADAPTIVE_SNIPER_RESTORE_ON_WIN', True)):
                                    self._restore_sniper_tier1()
                            except Exception as _kw:
                                log(f"⚠️ [knowledge TP exit] {_kw}")
                        else:
                            self.pnl.loss_trades += 1
                            self._consecutive_losses += 1
                            self._profit_streak = 0
                        try:
                            self._register_symbol_round(self.symbol, net)
                        except Exception as _rot_ex:
                            log(f"⚠️ Rotation round register error: {_rot_ex}")
                        if TG.enabled and CFG.TG_SEND_TRADES:
                            sign = "🟢" if net >= 0 else "🔴"
                            total_trades = self.pnl.trades_count
                            total_net = self.pnl.realized_usdt
                            win_rate = (self.pnl.profitable_trades / total_trades * 100) if total_trades > 0 else 0.0
                            TG.send(
                                f"{sign} FINAL SELL filled\n"
                                f"Пара: {self.symbol}\n"
                                f"Цена: {fill_price:.6f}\n"
                                f"Кол-во: {fill_qty:.6f}\n"
                                f"───────────────\n"
                                f"Gross PnL~:  {gross:+.4f} USDT ({pct:+.2f}%)\n"
                                f"Fees BUY~:  -{fee_buy_this:.4f} USDT\n"
                                f"Fees SELL~: -{fee_sell:.4f} USDT\n"
                                f"Net PnL~:    {net:+.4f} USDT\n"
                                f"───────────────\n"
                                f"Накопительно:\n"
                                f"Сделок: {total_trades} | Винрейт: {win_rate:.0f}%\n"
                                f"Net всего~: {total_net:+.4f} USDT\n"
                                f"Комиссии всего~: {self.pnl.fees_usdt:.4f} USDT"
                            )
                        # [FIX-v270-1] При ЛЮБОМ полном закрытии — освобождаем SMC (не только manual)
                        self._mark_smc_signal_closed()  # [FIX-v272-BUG4] единый вызов
                        if self.manual_only_sell and not self._daily_hard_locked:
                            log("ℹ️ Позиция закрыта — сбрасываю manual_only_sell, возобновляю BUY+SELL")
                            self.manual_only_sell = False
                            # [FIX-v272-BUG4] дубль убран — _mark_smc_signal_closed уже вызван выше
                            if TG.enabled:
                                TG.send("ℹ️ Позиция закрыта. ONLY-SELL снят — возобновляю торговлю (BUY+SELL).")
                        # [FIX-BUG6] build_grid убран из process_fills.
                        # Сетка строится в run() ПОСЛЕ update_modes — когда buy_blocked
                        # и only_sell уже актуальны. need_rebuild в run() покрывает этот случай.
                        # (если allow_buy=True и нет ордеров/позиции → need_rebuild=True → build_grid)
    # ---------- Scanner ----------
    # [FIX-v124-3] SCAN_CANDIDATES используется только как fallback при SCAN_USE_ALL_SPOT_USDT=False.
    # Убраны монеты которые уже находятся в BLACKLIST_SYMBOLS (APTUSDT, GALAUSDT, PEPEUSDT,
