        if txt == "/resume":
            # Resume trading; if /scan was done before, try to switch to last best symbol
            self.paused = False
            self.manual_only_sell = False
            # [FIX-v148-4] Сбрасываем consecutive loss pause при /resume.
            # Ранее: пауза не сбрасывалась → /resume не помогало если была пауза после потерь.
            try:
                _cl_was_paused = float(getattr(self,'_consecutive_loss_pause_until',0.0)) > time.time()
                self._consecutive_loss_pause_until = 0.0
                if _cl_was_paused:
                    log("ℹ️ [FIX-v148-4] /resume: сброшена пауза consecutive_loss")
            except Exception as _hc_ex:
                log(f'⚠️ [handle_command] {_hc_ex}')
            target = getattr(self, "last_scan_best", None)
            if target and target != self.symbol:
                cur_price = float(self.get_price() or 0.0)  # [FIX-v254-1]
